def apartments(m: int, a: List[int], b: List[int]) -> int:
    a.sort()
    b.sort()
    i = j = count = 0
    while i < len(a) and j < len(b):
        if abs(a[i] - b[j]) <= m:
            i += 1
            j += 1
            count += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return count

def ferris_wheel(people, limit):
    people.sort()
    left, right = 0, len(people) - 1
    gondolas = 0
    while left <= right:
        if left == right:
            gondolas += 1
            break
        if people[left] + people[right] <= limit:
            left += 1
        right -= 1
        gondolas += 1
    return gondolas

