def book_shop(prices: List[int], pages: List[int], budget: int) -> int:
    dp = [[0] * (budget + 1) for _ in range(len(prices) + 1)]
    for i in range(1, len(prices) + 1):
        for j in range(1, budget + 1):
            if prices[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - prices[i - 1]] + pages[i - 1])
    return dp[len(prices)][budget]

