def building_roads(n: int, connections: List[List[int]]) -> int:
    graph = [[] for _ in range(n)]
    for i in range(len(connections)):
        a, b = connections[i]
        graph[a].append(b)
        graph[b].append(a)
    visited = [False] * n
    def dfs(v: int) -> None:
        visited[v] = True
        for nb in graph[v]:
            if not visited[nb]:
                dfs(nb)
    count = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1
    return count - 1

def message_route(graph, start, end):
    visited = set()
    queue = [[start]]
    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node == end:
            return path
        visited.add(node)
        neighbors = graph.get(node, [])
        for neighbor in neighbors:
            if neighbor not in visited:
                queue.append(path + [neighbor])
    return None

