from collections import deque

def build_teams(n: int, edges: List[List[int]]) -> Optional[List[int]]:
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)
    team = [0] * n
    for start in range(n):
        if team[start] != 0:
            continue
        team[start] = 1
        q = deque([start])
        while q:
            node = q.popleft()
            for nb in graph[node]:
                if team[nb] == 0:
                    team[nb] = 2 if team[node] == 1 else 1
                    q.append(nb)
                elif team[nb] == team[node]:
                    return None
    return team

