def shortest_routes(graph: List[List[float]], start: int) -> List[float]:
    distances = [float('inf')] * len(graph)
    distances[start] = 0.0
    for _ in range(len(graph) - 1):
        for u in range(len(graph)):
            for v in range(len(graph[u])):
                if graph[u][v] != 0 and distances[u] + graph[u][v] < distances[v]:
                    distances[v] = distances[u] + graph[u][v]
    for u in range(len(graph)):
        for v in range(len(graph[u])):
            if graph[u][v] != 0 and distances[u] + graph[u][v] < distances[v]:
                raise Exception("Graph contains a negative-weight cycle")
    return distances

import heapq

def shortest_routes(n: int, edges: list, src: int, dest: int) -> int:
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))
    dist = [float('inf')] * n
    dist[src] = 0
    pq = [(0, src)]
    visited = [False] * n
    while pq:
        d, node = heapq.heappop(pq)
        if visited[node]:
            continue
        visited[node] = True
        for nb, w in graph[node]:
            if dist[node] + w < dist[nb]:
                dist[nb] = dist[node] + w
                heapq.heappush(pq, (dist[nb], nb))
    return -1 if dist[dest] == float('inf') else dist[dest]

