def find_median_sorted_arrays(nums1: List[int], nums2: List[int]) -> float:
    if len(nums1) > len(nums2):
        return find_median_sorted_arrays(nums2, nums1)
    x, y = len(nums1), len(nums2)
    start, end = 0, x
    while start <= end:
        partition_x = (start + end) // 2
        partition_y = (x + y + 1) // 2 - partition_x
        max_left_x = -math.inf if partition_x == 0 else nums1[partition_x - 1]
        min_right_x = math.inf if partition_x == x else nums1[partition_x]
        max_left_y = -math.inf if partition_y == 0 else nums2[partition_y - 1]
        min_right_y = math.inf if partition_y == y else nums2[partition_y]
        if max_left_x <= min_right_y and max_left_y <= min_right_x:
            if (x + y) % 2 == 0:
                return (max(max_left_x, max_left_y) + min(min_right_x, min_right_y)) / 2.0
            return max(max_left_x, max_left_y)
        if max_left_x > min_right_y:
            end = partition_x - 1
        else:
            start = partition_x + 1

def longest_palindromic_substring(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    dp = [[False] * n for _ in range(n)]
    max_length = 1
    start = 0
    for i in range(n - 1, -1, -1):
        dp[i][i] = True
        for j in range(i + 1, n):
            if s[i] == s[j] and (j - i == 1 or dp[i + 1][j - 1]):
                dp[i][j] = True
                cur_len = j - i + 1
                if cur_len > max_length or (cur_len == max_length and i < start):
                    max_length = cur_len
                    start = i
    return s[start:start + max_length]

def convert(s: str, num_rows: int) -> str:
    if num_rows <= 1 or num_rows >= len(s):
        return s
    n = len(s)
    result: list[str] = []
    for row in range(num_rows):
        idx = row
        step_down = 2 * (num_rows - row - 1)
        step_up = 2 * row
        toggle = False
        while idx < n:
            result.append(s[idx])
            if step_down == 0:
                idx += step_up
            elif step_up == 0:
                idx += step_down
            else:
                idx += step_up if toggle else step_down
                toggle = not toggle
    return ''.join(result)

def my_atoi(s: str) -> int:
    s = s.strip()
