def letter_combinations(digits: str) -> List[str]:
    phone_mapping = {
        "2": "abc",
        "3": "def",
        "4": "ghi",
        "5": "jkl",
        "6": "mno",
        "7": "pqrs",
        "8": "tuv",
        "9": "wxyz"
    }
    if len(digits) == 0:
        return []
    result: List[str] = []
    def backtrack(combination: str, next_digits: str) -> None:
        if len(next_digits) == 0:
            result.append(combination)
        else:
            letters = phone_mapping[next_digits[0]]
            for i in range(len(letters)):
                backtrack(combination + letters[i], next_digits[1:])
    backtrack("", digits)
    return result

