class ListNode:
    def __init__(self, val: int = 0, next: Optional['ListNode'] = None):
        self.val = val
        self.next = next

def merge_k_lists(lists: List[Optional[ListNode]]) -> Optional[ListNode]:
    min_heap = []
    for i in range(len(lists)):
        if lists[i]:
            min_heap.append({'val': lists[i].val, 'listIndex': i, 'node': lists[i]})
    dummy_head = ListNode(0)
    current = dummy_head
    min_heap.sort(key=lambda x: x['val'])
    while min_heap:
        smallest = min_heap.pop(0)
        current.next = smallest['node']
        current = current.next
        if smallest['node'].next:
            min_heap.append({
                'val': smallest['node'].next.val,
                'listIndex': smallest['listIndex'],
                'node': smallest['node'].next
            })
            min_heap.sort(key=lambda x: x['val'])
    return dummy_head.next

