def divide(dividend: int, divisor: int) -> int:
    if divisor == 0:
        raise Exception("Cannot divide by zero")
    sign = -1 if (dividend < 0) ^ (divisor < 0) else 1
    a = abs(dividend)
    b = abs(divisor)
    quotient = 0
    while a >= b:
        shift = 0
        while (b << shift) <= a:
            shift += 1
        a -= (b << (shift - 1))
        quotient += (1 << (shift - 1))
    quotient *= sign
    if quotient > 2**31 - 1:
        return 2**31 - 1
    elif quotient < -2**31:
        return -2**31
    return quotient

