def search_range(nums: List[int], target: int) -> List[int]:
    def binary_search(find_first: bool) -> int:
        left, right, result = 0, len(nums) - 1, -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                if find_first:
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result
    first = binary_search(True)
    last = binary_search(False)
    return [first, last]

