def group_anagrams(strs: List[str]) -> List[List[str]]:
    hash_table: dict[str, List[str]] = {}
    for s in strs:
        sorted_str = ''.join(sorted(s))
        if sorted_str not in hash_table:
            hash_table[sorted_str] = []
        hash_table[sorted_str].append(s)
    # sort each group lexicographically
    groups = [sorted(group) for group in hash_table.values()]
    # sort groups by their size (ascending)
    groups.sort(key=len)
