def solve_n_queens(n: int) -> List[List[str]]:
    result: List[List[str]] = []
    board: List[List[str]] = [['.' for _ in range(n)] for _ in range(n)]

    def is_safe(row: int, col: int) -> bool:
        for i in range(row):
            if board[i][col] == 'Q':
                return False
        i, j = row - 1, col - 1
        while i >= 0 and j >= 0:
            if board[i][j] == 'Q':
                return False
            i -= 1
            j -= 1
        i, j = row - 1, col + 1
        while i >= 0 and j < n:
            if board[i][j] == 'Q':
                return False
            i -= 1
            j += 1
        return True

    def backtrack(row: int) -> None:
        if row == n:
            solution = [''.join(r) for r in board]
            result.append(solution)
            return
        for col in range(n):
            if is_safe(row, col):
                board[row][col] = 'Q'
                backtrack(row + 1)
                board[row][col] = '.'

    backtrack(0)
    return result

