def largest_rectangle_area(heights: List[int]) -> int:
    stack: List[int] = []
    max_area = 0
    index = 0
    n = len(heights)
    while index < n:
        if not stack or heights[index] >= heights[stack[-1]]:
            stack.append(index)
            index += 1
        else:
            top_of_stack = stack.pop()
            width = index if not stack else index - stack[-1] - 1
            area = heights[top_of_stack] * width
            if area > max_area:
                max_area = area
    while stack:
        top_of_stack = stack.pop()
        width = index if not stack else index - stack[-1] - 1
        area = heights[top_of_stack] * width
        if area > max_area:
            max_area = area
    return max_area

