def generate_trees(n: int) -> List[Optional[Dict[str, Any]]]:
    def helper(start: int, end: int) -> List[Optional[Dict[str, Any]]]:
        if start > end:
            return [None]
        trees: List[Optional[Dict[str, Any]]] = []
        for i in range(start, end + 1):
            left_subtrees = helper(start, i - 1)
            right_subtrees = helper(i + 1, end)
            for left in left_subtrees:
                for right in right_subtrees:
                    trees.append({'val': i, 'left': left, 'right': right})
        return trees
    return helper(1, n)

def num_trees(n: int) -> int:
    dp = [0] * (n + 1)
    dp[0] = 1
    if n >= 1:
        dp[1] = 1
    for i in range(2, n + 1):
        for j in range(1, i + 1):
            dp[i] += dp[j - 1] * dp[i - j]
    return dp[n]

def is_valid_bst(root):
    def dfs(node, min_val, max_val):
        if node is None:
            return True
        if node.val <= min_val or node.val >= max_val:
            return False
        return dfs(node.left, min_val, node.val) and dfs(node.right, node.val, max_val)
    return dfs(root, float('-inf'), float('inf'))

def is_interleave(s1: str, s2: str, s3: str) -> bool:
    if len(s1) + len(s2) != len(s3):
        return False
    dp = [[False] * (len(s2) + 1) for _ in range(len(s1) + 1)]
    dp[0][0] = True
    for i in range(1, len(s2) + 1):
        dp[0][i] = dp[0][i - 1] and s2[i - 1] == s3[i - 1]
    for i in range(1, len(s1) + 1):
        dp[i][0] = dp[i - 1][0] and s1[i - 1] == s3[i - 1]
    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            dp[i][j] = (dp[i - 1][j] and s1[i - 1] == s3[i + j - 1]) or (dp[i][j - 1] and s2[j - 1] == s3[i + j - 1])
    return dp[len(s1)][len(s2)]

def recover_tree(root):
    first = second = prev = None
    def in_order(node):
        nonlocal first, second, prev
        if not node:
            return
        in_order(node.left)
        if prev and prev.val > node.val:
            if not first:
                first = prev
            second = node
        prev = node
        in_order(node.right)
    in_order(root)
    first.val, second.val = second.val, first.val

def is_same_tree(p, q):
    if p is None and q is None:
        return True
    if p is None or q is None:
        return False
    if p.val != q.val:
        return False
    return is_same_tree(p.left, q.left) and is_same_tree(p.right, q.right)

def is_symmetric(root):
    def is_mirror(t1, t2):
        if t1 is None and t2 is None:
            return True
        if t1 is None or t2 is None:
            return False
        return (t1.val == t2.val) and is_mirror(t1.right, t2.left) and is_mirror(t1.left, t2.right)
    if root is None:
        return True
    return is_mirror(root.left, root.right)

