def build_tree(preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
    inorder_map = {value: idx for idx, value in enumerate(inorder)}
    def recursive_build(pre_start: int, pre_end: int, in_start: int, in_end: int) -> Optional[TreeNode]:
        if pre_start > pre_end:
            return None
        root = TreeNode(preorder[pre_start])
        in_index = inorder_map[preorder[pre_start]]
        left_size = in_index - in_start
        root.left = recursive_build(pre_start + 1, pre_start + left_size, in_start, in_index - 1)
        root.right = recursive_build(pre_start + left_size + 1, pre_end, in_index + 1, in_end)
        return root
    return recursive_build(0, len(preorder) - 1, 0, len(inorder) - 1)

