def build_tree(inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
    inorder_index_map = {}
    for i, v in enumerate(inorder):
        inorder_index_map[v] = i

    def recursive_build_tree(inorder_start: int, inorder_end: int, postorder_start: int, postorder_end: int) -> Optional[TreeNode]:
        if inorder_start > inorder_end:
            return None
        root_val = postorder[postorder_end]
        root = TreeNode(root_val)
        inorder_root_index = inorder_index_map[root_val]
        left_subtree_size = inorder_root_index - inorder_start
        root.left = recursive_build_tree(inorder_start, inorder_root_index - 1, postorder_start, postorder_start + left_subtree_size - 1)
        root.right = recursive_build_tree(inorder_root_index + 1, inorder_end, postorder_start + left_subtree_size, postorder_end - 1)
        return root

    return recursive_build_tree(0, len(inorder) - 1, 0, len(postorder) - 1)

