def sorted_list_to_bst(head: Optional[ListNode]) -> Optional[TreeNode]:
    arr: List[int] = []
    while head:
        arr.append(head.val)
        head = head.next

    def helper(left: int, right: int) -> Optional[TreeNode]:
        if left > right:
            return None
        mid = (left + right) // 2
        node = TreeNode(arr[mid])
        node.left = helper(left, mid - 1)
        node.right = helper(mid + 1, right)
        return node

    return helper(0, len(arr) - 1)

def is_balanced(root):
    def check_balance(node):
        if node is None:
            return 0
        left_height = check_balance(node.left)
        right_height = check_balance(node.right)
        if left_height == -1 or right_height == -1 or abs(left_height - right_height) > 1:
            return -1
        return 1 + max(left_height, right_height)
    return check_balance(root) != -1

def min_depth(root):
    if not root:
        return 0
    queue = [(root, 1)]
    while queue:
        node, depth = queue.pop(0)
        if not node.left and not node.right:
            return depth
        if node.left:
            queue.append((node.left, depth + 1))
        if node.right:
            queue.append((node.right, depth + 1))

def has_path_sum(root, target_sum):
    if not root:
        return False
    if not root.left and not root.right and root.val == target_sum:
        return True
    return has_path_sum(root.left, target_sum - root.val) or has_path_sum(root.right, target_sum - root.val)

def connect(root):
    if not root:
        return None
    queue = [root]
    while queue:
        size = len(queue)
        for i in range(size):
            if i < size - 1:
                queue[i].next = queue[i + 1]
            else:
                queue[i].next = None
            if queue[i].left:
                queue.append(queue[i].left)
            if queue[i].right:
                queue.append(queue[i].right)
        queue = queue[size:]
    return root

from collections import deque

def connect(root):
    if not root:
        return None
    queue = deque([root])
    while queue:
        size = len(queue)
        for i in range(size):
            node = queue.popleft()
            if i < size - 1:
                node.next = queue[0]
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
    return root

