from collections import deque, defaultdict

def find_ladders(beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
    word_set = set(wordList)
    if endWord not in word_set:
        return []

    # Ensure beginWord is in the set for neighbor generation
    word_set.add(beginWord)

    # BFS to compute shortest distances and adjacency list
    distances: Dict[str, int] = {beginWord: 0}
    adjacency: Dict[str, List[str]] = defaultdict(list)
    q = deque([beginWord])
    word_len = len(beginWord)

    while q:
        current = q.popleft()
        cur_dist = distances[current]
        for i in range(word_len):
            for c in range(26):
                nxt = current[:i] + chr(97 + c) + current[i + 1 :]
                if nxt not in word_set:
                    continue
                # Build adjacency regardless of visitation status
                if distances.get(nxt, float('inf')) == cur_dist + 1:
                    adjacency[current].append(nxt)
                elif nxt not in distances:
                    distances[nxt] = cur_dist + 1
                    adjacency[current].append(nxt)
                    q.append(nxt)

    if endWord not in distances:
        return []

    # DFS to collect all shortest paths using adjacency and distances
    results: List[List[str]] = []
    path: List[str] = []

    def dfs(word: str) -> None:
        path.append(word)
        if word == endWord:
            results.append(path.copy())
        else:
            for nxt in adjacency.get(word, []):
                if distances.get(nxt, float('inf')) == distances[word] + 1:
                    dfs(nxt)
        path.pop()

    dfs(beginWord)
    return results

