from typing import List

def word_break(s: str, word_dict: List[str]) -> List[str]:
    word_set = set(word_dict)
    memo: dict[int, List[List[str]]] = {}

    def backtrack(start: int) -> List[List[str]]:
        if start == len(s):
            return [[]]
        if start in memo:
            return memo[start]
        result: List[List[str]] = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in word_set:
                for nxt in backtrack(end):
                    result.append([word] + nxt)
        memo[start] = result
        return result

    sentences = [' '.join(words) for words in backtrack(0)]
    # sort by number of words descending, then lexicographically descending
    sentences.sort(key=lambda x: (len(x.split()), x), reverse=True)
    return sentences

def has_cycle(head):
    slow = head
    fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

def detect_cycle(head):
    if not head or not head.next:
        return None
    slow = head
    fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            slow = head
            while slow is not fast:
                slow = slow.next
                fast = fast.next
            return slow
    return None

def lru_cache(capacity: int):
    cache = {}
    head = {'next': None, 'prev': None}
    tail = {'next': None, 'prev': None}
    head['next'] = tail
    tail['prev'] = head
    size = 0

    def remove(node):
        node['prev']['next'] = node['next']
        node['next']['prev'] = node['prev']

    def add(node):
        node['prev'] = tail['prev']
        node['next'] = tail
        tail['prev']['next'] = node
        tail['prev'] = node

    def inner(operation, key, value=None):
        nonlocal size
        if operation == 'get':
            if key in cache:
                node = cache[key]
                remove(node)
                add(node)
                return node['value']
            return -1
        elif operation == 'put':
            if key in cache:
                node = cache[key]
                node['value'] = value
                remove(node)
                add(node)
            else:
                node = {'key': key, 'value': value}
                cache[key] = node
                add(node)
                size += 1
                if size > capacity:
