def min_stack() -> SimpleNamespace:
    stack: List[int] = []
    min_stack: List[int] = []

    def push(x: int) -> None:
        stack.append(x)
        if not min_stack or x <= min_stack[-1]:
            min_stack.append(x)

    def pop() -> None:
        if stack:
            val = stack.pop()
            if val == min_stack[-1]:
                min_stack.pop()

    def top() -> int:
        return stack[-1]

    def get_min() -> int:
        return min_stack[-1]

    return SimpleNamespace(push=push, pop=pop, top=top, get_min=get_min)

