def get_intersection_node(head_a: Optional['ListNode'], head_b: Optional['ListNode']) -> Optional['ListNode']:
    length_a = 0
    temp_a = head_a
    while temp_a is not None:
        length_a += 1
        temp_a = temp_a.next
    length_b = 0
    temp_b = head_b
