        length_b += 1
        temp_b = temp_b.next
    diff = abs(length_a - length_b)
    if length_a > length_b:
        for _ in range(diff):
            head_a = head_a.next
    else:
        for _ in range(diff):
            head_b = head_b.next
    while head_a is not None and head_b is not None:
        if head_a is head_b:
            return head_a
        head_a = head_a.next
        head_b = head_b.next
    return None

