def maximum_gap(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return 0
    mn = min(nums)
    mx = max(nums)
    if mn == mx:
        return 0

    # Use n buckets (indices 0..n-1)
    bucket_min: List[Optional[int]] = [None] * n
    bucket_max: List[Optional[int]] = [None] * n

    for v in nums:
        idx = (v - mn) * (n - 1) // (mx - mn)
        if bucket_min[idx] is None:
            bucket_min[idx] = bucket_max[idx] = v
        else:
            if v < bucket_min[idx]:
                bucket_min[idx] = v
            if v > bucket_max[idx]:
                bucket_max[idx] = v

    prev_max: Optional[int] = None
    max_gap = 0
    for i in range(n):
        if bucket_min[i] is None:
            continue
        if prev_max is not None:
            gap = bucket_min[i] - prev_max
            if gap > max_gap:
                max_gap = gap
        prev_max = bucket_max[i]

    return max_gap

