def max_profit(k: int, prices: List[int]) -> int:
    n = len(prices)
    if n == 0 or k == 0:
        return 0

    # If transactions are effectively unlimited
    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            diff = prices[i] - prices[i - 1]
            if diff > 0:
                profit += diff
        return profit

    m = 2 * k + 1
    dp = [[float('-inf')] * m for _ in range(n)]

    # Base cases for day 0
    dp[0][0] = 0                     # no transaction, not holding
    dp[0][1] = -prices[0]            # first buy
    for j in range(2, m):
        if j % 2 == 0:
            dp[0][j] = 0            # even state: not holding, zero profit
        else:
            dp[0][j] = float('-inf')  # odd state beyond first buy is impossible

    # Fill DP table
    for i in range(1, n):
        dp[i][0] = 0
        for j in range(1, m):
            if j % 2 == 1:  # holding a stock
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] - prices[i])
            else:           # not holding a stock
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + prices[i])

    return dp[-1][2 * k]

