def fraction_to_decimal(numerator: int, denominator: int) -> str:
    if numerator == 0:
        return "0"
    sign = "-" if (numerator < 0) ^ (denominator < 0) else ""
    num = abs(numerator)
    den = abs(denominator)
    integer_part = num // den
    remainder = num % den
    if remainder == 0:
        return sign + str(integer_part)
    result = [sign + str(integer_part), "."]
    seen = {}
    fractional = []
    while remainder and remainder not in seen:
        seen[remainder] = len(fractional)
        remainder *= 10
        digit = remainder // den
        fractional.append(str(digit))
        remainder %= den
    if remainder == 0:
        result.append("".join(fractional))
    else:
        idx = seen[remainder]
        non_repeat = "".join(fractional[:idx])
        repeat = "".join(fractional[idx:])
        result.append(non_repeat + "(" + repeat + ")")
    return "".join(result)

