def shortest_palindrome(s: str) -> str:
    rev = s[::-1]
    combined = s + '#' + rev
    prefix_suffix_lengths = [0] * len(combined)
    prefix_length = 0
    for i in range(1, len(combined)):
        while prefix_length > 0 and combined[i] != combined[prefix_length]:
            prefix_length = prefix_suffix_lengths[prefix_length - 1]
        if combined[i] == combined[prefix_length]:
            prefix_length += 1
        prefix_suffix_lengths[i] = prefix_length
    max_length = prefix_suffix_lengths[-1]
    return rev[:len(s) - max_length] + s

