def find_words(board: List[List[str]], words: List[str]) -> List[str]:
    trie: dict = {}
    for word in words:
        node = trie
        for ch in word:
            node = node.setdefault(ch, {})
        node['end'] = True

    result = set()
    rows, cols = len(board), len(board[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def backtrack(r: int, c: int, node: dict, cur: str) -> None:
        if node.get('end'):
            result.add(cur)

        temp = board[r][c]
        board[r][c] = '#'

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nxt_char = board[nr][nc]
                if nxt_char in node:
                    backtrack(nr, nc, node[nxt_char], cur + nxt_char)

        board[r][c] = temp

    for i in range(rows):
        for j in range(cols):
            ch = board[i][j]
            if ch in trie:
                backtrack(i, j, trie[ch], ch)

    return sorted(result)

