        max_size = max(max_size, dp[i][0])
    for j in range(cols):
        dp[0][j] = 1 if matrix[0][j] == '1' else 0
        max_size = max(max_size, dp[0][j])
    for i in range(1, rows):
        for j in range(1, cols):
            if matrix[i][j] == '1':
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_size = max(max_size, dp[i][j])
    return max_size * max_size

def count_nodes(root):
    height = 0
    node = root
    while node:
        height += 1
        node = node.left
    if height == 0:
        return 0
    if height == 1:
        return 1
    left, right = 0, 2 ** (height - 1) - 1
    while left <= right:
        mid = (left + right) // 2
        node = root
        path = mid
        for i in range(height - 2, -1, -1):
            node = node.right if (path & (1 << i)) else node.left
        if node:
            left = mid + 1
        else:
            right = mid - 1
    return 2 ** (height - 1) - 1 + left

def calculate(s: str) -> int:
    sign = 1
    result = 0
    num = 0
    for i in range(len(s)):
        c = s[i]
        if c.isdigit():
            num = num * 10 + (ord(c) - ord('0'))
        elif c == '+' or c == '-':
            result += sign * num
            num = 0
            sign = 1 if c == '+' else -1
        elif c == ' ':
            continue
    result += sign * num
    return result

def calculate(s: str) -> int:
    stack: list[int] = []
    num = 0
    sign = '+'
    n = len(s)
    i = 0
    while i < n:
        ch = s[i]
        if ch.isdigit():
            num = num * 10 + int(ch)
        if ch in '+-*/' or i == n - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                prev = stack.pop()
                stack.append(int(prev / num))
            sign = ch
            num = 0
        i += 1
    return sum(stack)

def my_stack():
