        queue1.append(x)
    def pop():
        nonlocal queue1, queue2
        while len(queue1) > 1:
            queue2.append(queue1.pop(0))
        temp = queue1.pop(0)
        queue1, queue2 = queue2, queue1
        return temp
    def top():
        nonlocal queue1, queue2
        while len(queue1) > 1:
            queue2.append(queue1.pop(0))
        temp = queue1[0]
        queue2.append(queue1.pop(0))
        queue1, queue2 = queue2, queue1
        return temp
    def empty():
        return len(queue1) == 0
    return {'push': push, 'pop': pop, 'top': top, 'empty': empty}

