        return stack_oldest_on_top[-1]

    def empty() -> bool:
        return not stack_newest_on_top and not stack_oldest_on_top

    q = SimpleNamespace()
    q.stackNewestOnTop = stack_newest_on_top
    q.stackOldestOnTop = stack_oldest_on_top
    q.push = push
    q.pop = pop
    q.peek = peek
    q.empty = empty
