def diff_ways_to_compute(expression: str) -> List[int]:
    memo: dict[str, List[int]] = {}
    def compute(expr: str) -> List[int]:
        if expr in memo:
            return memo[expr]
        if expr.isdigit():
            memo[expr] = [int(expr)]
            return memo[expr]
        results: List[int] = []
        for i, ch in enumerate(expr):
            if ch in '+-*':
                left_vals = compute(expr[:i])
                right_vals = compute(expr[i+1:])
                for l in left_vals:
                    for r in right_vals:
                        if ch == '+':
                            results.append(l + r)
                        elif ch == '-':
                            results.append(l - r)
                        else:  # ch == '*'
                            results.append(l * r)
        memo[expr] = results
        return results
    return sorted(compute(expression))

