def add_operators(num: str, target: int) -> List[str]:
    result: List[str] = []

    def backtrack(index: int, path: str, value: int, prev: int) -> None:
        if index == len(num):
            if value == target:
                result.append(path)
            return
        for i in range(index, len(num)):
            if i != index and num[index] == '0':
                break
            cur_str = num[index:i + 1]
            cur = int(cur_str)
            if index == 0:
                backtrack(i + 1, cur_str, cur, cur)
            else:
                # multiply first to match expected ordering
                backtrack(i + 1, path + '*' + cur_str, value - prev + prev * cur, prev * cur)
                backtrack(i + 1, path + '+' + cur_str, value + cur, cur)
                backtrack(i + 1, path + '-' + cur_str, value - cur, -cur)

    backtrack(0, '', 0, 0)
    return result

class PeekingIterator:
    def __init__(self, iterator):
        self.iterator = iterator
        self.peeked = None
        self.has_peeked = False

    def peek(self):
        if not self.has_peeked:
            self.peeked = next(self.iterator)
            self.has_peeked = True
        return self.peeked

    def next(self):
        if self.has_peeked:
            val = self.peeked
            self.has_peeked = False
            return val
        return next(self.iterator)

    def hasNext(self):
        if self.has_peeked:
            return True
        try:
            self.peeked = next(self.iterator)
            self.has_peeked = True
            return True
        except StopIteration:
            return False

