def num_array(nums: List[int]) -> SimpleNamespace:
    tree = [0] * (4 * len(nums))
    n = len(nums)

    def build(node: int, left: int, right: int) -> None:
        if left == right:
            tree[node] = nums[left]
        else:
            mid = (left + right) // 2
            build(node * 2 + 1, left, mid)
            build(node * 2 + 2, mid + 1, right)
            tree[node] = tree[node * 2 + 1] + tree[node * 2 + 2]

    if n:
        build(0, 0, n - 1)

    def update(index: int, val: int) -> None:
        def _update(node: int, left: int, right: int) -> None:
            if left == right:
                tree[node] = val
            else:
                mid = (left + right) // 2
                if index <= mid:
                    _update(node * 2 + 1, left, mid)
                else:
                    _update(node * 2 + 2, mid + 1, right)
                tree[node] = tree[node * 2 + 1] + tree[node * 2 + 2]

        _update(0, 0, n - 1)

    def sum_range(left: int, right: int) -> int:
        def _query(node: int, l: int, r: int) -> int:
            if left <= l and r <= right:
                return tree[node]
            if r < left or l > right:
                return 0
            mid = (l + r) // 2
            return _query(node * 2 + 1, l, mid) + _query(node * 2 + 2, mid + 1, r)

        return _query(0, 0, n - 1)

    return SimpleNamespace(update=update, sum_range=sum_range)

