def find_min_height_trees(n: int, edges: List[List[int]]) -> List[int]:
    if n == 1:
        return [0]
    graph = [[] for _ in range(n)]
    degree = [0] * n
    for edge in edges:
        a, b = edge
        graph[a].append(b)
        graph[b].append(a)
        degree[a] += 1
        degree[b] += 1
    queue = deque()
    for i in range(n):
        if degree[i] == 1:
            queue.append(i)
    while n > 2:
        size = len(queue)
        n -= size
        for _ in range(size):
            node = queue.popleft()
            for neighbor in graph[node]:
                degree[neighbor] -= 1
                if degree[neighbor] == 1:
                    queue.append(neighbor)
    return list(queue)

def remove_duplicate_letters(s: str) -> str:
    count_map = {}
    for ch in s:
        count_map[ch] = count_map.get(ch, 0) + 1
    result_set = set()
    result = []
    for ch in s:
        count_map[ch] -= 1
        if ch in result_set:
            continue
        while result and result[-1] > ch and count_map[result[-1]] > 0:
            result_set.remove(result[-1])
            result.pop()
        result_set.add(ch)
