def rob(root):
    def dfs(node):
        if not node:
            return (0, 0)
        left = dfs(node.left)
        right = dfs(node.right)
        without = max(left[0], left[1]) + max(right[0], right[1])
        # if we rob this node, its children CANNOT be robbed -- use their "without" values
        with_node = node.val + left[1] + right[1]
        return (with_node, without)
    result = dfs(root)
    return max(result[0], result[1])

class NestedIterator:
    def __init__(self, nestedList):
        stack = list(reversed(nestedList))
        result = []
        while stack:
            current = stack.pop()
            if isinstance(current, list):
                stack.extend(reversed(current))
            else:
                result.append(current)
        self.flat_list = result
        self.index = 0

    def hasNext(self):
        return self.index < len(self.flat_list)

    def next(self):
        val = self.flat_list[self.index]
        self.index += 1
        return val

