def twitter():
    user_followings: Dict[int, Set[int]] = {}
    tweets: Dict[int, List[Tuple[int, int]]] = {}
    time = 0

    def post_tweet(user_id: int, tweet_id: int) -> None:
        nonlocal time
        tweets.setdefault(user_id, []).append((tweet_id, time))
        time += 1

    def get_news_feed(user_id: int) -> List[int]:
        heap: List[Tuple[int, int]] = []
        followees = user_followings.get(user_id, set()).copy()
        followees.add(user_id)
        for uid in followees:
            for tweet_id, ts in tweets.get(uid, [])[-10:][::-1]:
                heapq.heappush(heap, (ts, tweet_id))
                if len(heap) > 10:
                    heapq.heappop(heap)
        return [tweet_id for _, tweet_id in sorted(heap, reverse=True)]

    def follow(follower_id: int, followee_id: int) -> None:
        user_followings.setdefault(follower_id, set()).add(followee_id)

    def unfollow(follower_id: int, followee_id: int) -> None:
        s = user_followings.get(follower_id)
        if s:
            s.discard(followee_id)

    return {
        "post_tweet": post_tweet,
        "get_news_feed": get_news_feed,
        "follow": follow,
        "unfollow": unfollow,
    }

