        for i in range(1, n - length + 2):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j + 1):
                left = dp[i][k - 1] if k - 1 >= i else 0
                right = dp[k + 1][j] if k + 1 <= j else 0
                cost = k + (left if left > right else right)
                if cost < dp[i][j]:
                    dp[i][j] = cost
    return dp[1][n]

