        index_map[val] = len(elements)
        elements.append(val)
        return True

    def remove(val: int) -> bool:
        if val not in index_map:
            return False
        idx = index_map[val]
        last = elements[-1]
        elements[idx] = last
        index_map[last] = idx
        elements.pop()
        del index_map[val]
        return True

