def is_rectangle_cover(rectangles: List[List[int]]) -> bool:
    area = 0
    x1 = float('inf')
    y1 = float('inf')
    x2 = float('-inf')
    y2 = float('-inf')
    corners = set()
    for rect in rectangles:
        x, y, a, b = rect
        area += (a - x) * (b - y)
        x1 = min(x1, x)
        y1 = min(y1, y)
        x2 = max(x2, a)
        y2 = max(y2, b)
        points = [(x, y), (x, b), (a, y), (a, b)]
        for p in points:
            if p in corners:
                corners.remove(p)
            else:
                corners.add(p)
    if area != (x2 - x1) * (y2 - y1):
        return False
    expected_corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
    for corner in expected_corners:
        if corner not in corners:
            return False
    return len(corners) == 4

