def rotate_function(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    total = sum(nums)
    current = sum(i * num for i, num in enumerate(nums))
    max_val = current
    for k in range(1, n):
        current = current + total - n * nums[n - k]
        if current > max_val:
            max_val = current
    return max_val

