    for ch in s:
        if ch.isdigit():
            cur_num = cur_num * 10 + int(ch)
        elif 'a' <= ch <= 'z':
            cur_string += ch
        elif ch == '[':
            stack.append(cur_string)
            stack.append(cur_num)
            cur_string = ''
            cur_num = 0
        elif ch == ']':
            num = stack.pop()
            prev_string = stack.pop()
            cur_string = prev_string + cur_string * num
    return cur_string

