def calc_equation(equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
    graph: Dict[str, Dict[str, float]] = {}
    for i in range(len(equations)):
        dividend, divisor = equations[i]
        value = values[i]
        if dividend not in graph:
            graph[dividend] = {}
        if divisor not in graph:
            graph[divisor] = {}
        graph[dividend][divisor] = value
        graph[divisor][dividend] = 1 / value

    def dfs(start: str, end: str, visited: Set[str]) -> float:
        if start not in graph:
            return -1.0
        if start == end:
            return 1.0
        visited.add(start)
        result = -1.0
        for neighbor in graph[start]:
            if neighbor not in visited:
                temp_result = dfs(neighbor, end, visited)
                if temp_result != -1.0:
                    result = graph[start][neighbor] * temp_result
                    break
        visited.remove(start)
        return result

    result: List[float] = []
    for dividend, divisor in queries:
        result.append(dfs(dividend, divisor, set()))
    return result

