        for jump in (k - 1, k, k + 1):
            if jump <= 0:
                continue
            nxt = stone + jump
            if nxt in stone_set:
                if dfs(nxt, jump):
                    memo[key] = True
                    return True
        memo[key] = False
        return False
    return dfs(stones[0], 1)

