def to_hex(num: int) -> str:
    if num < 0:
        num += 2 ** 32
    result = ''
    while num > 0:
        remainder = num % 16
        if remainder < 10:
            result = str(remainder) + result
        else:
            result = chr(97 + remainder - 10) + result
        num //= 16
    if result == '':
        return '0'
    return result

def remove_k_digits(num: str, k: int) -> str:
    stack = []
    for i in range(len(num)):
        while stack and stack[-1] > num[i] and k > 0:
            stack.pop()
            k -= 1
        stack.append(num[i])
    while k > 0:
        stack.pop()
        k -= 1
    result = ''.join(stack).lstrip('0') or '0'
    return result

