def strong_password_checker(password: str) -> int:
    n = len(password)

    # count missing character types
    missing = 3
    if any(c.islower() for c in password):
        missing -= 1
    if any(c.isupper() for c in password):
        missing -= 1
    if any(c.isdigit() for c in password):
        missing -= 1

    # collect lengths of repeating sequences (len >= 3)
    repeats: List[int] = []
    i = 0
    while i < n:
        j = i
        while j < n and password[j] == password[i]:
            j += 1
        length = j - i
        if length >= 3:
            repeats.append(length)
        i = j

    if n < 6:
        # need insertions; they can also fix missing types
        return max(missing, 6 - n)

    if n <= 20:
        # replacements needed to break repeats
        replace = sum(l // 3 for l in repeats)
        return max(missing, replace)

    # n > 20: need deletions
    delete = n - 20

    # prioritize deletions on repeats to reduce replacements
    repeats.sort(key=lambda x: x % 3)  # mod 0 first, then 1, then 2
    for idx in range(len(repeats)):
        if delete == 0:
            break
        l = repeats[idx]
        if l < 3:
            continue
        # deletions needed to reduce one replacement for this sequence
        need = (l % 3) + 1
        del_cnt = min(need, delete)
        repeats[idx] -= del_cnt
        delete -= del_cnt

    # if deletions remain, apply them in groups of three
    if delete > 0:
        # each 3 deletions can reduce one replacement
        # we just reduce the lengths as much as possible
        for idx in range(len(repeats)):
            if delete == 0:
                break
            l = repeats[idx]
            if l < 3:
                continue
            # maximum deletions we can apply without making length < 3
            max_del = l - 2
            del_cnt = min(delete, max_del)
            repeats[idx] -= del_cnt
            delete -= del_cnt

    replace = sum(l // 3 for l in repeats if l >= 3)
    return (n - 20) + max(missing, replace)

