def pacific_atlantic(heights: List[List[int]]) -> List[List[int]]:
    rows = len(heights)
    cols = len(heights[0])
    pacific: Set[str] = set()
    atlantic: Set[str] = set()

    def dfs(r: int, c: int, ocean: Set[str]) -> None:
        key = f"{r},{c}"
        if r < 0 or r >= rows or c < 0 or c >= cols or key in ocean:
            return
        ocean.add(key)
        if r > 0 and heights[r - 1][c] >= heights[r][c]:
            dfs(r - 1, c, ocean)
        if r < rows - 1 and heights[r + 1][c] >= heights[r][c]:
            dfs(r + 1, c, ocean)
        if c > 0 and heights[r][c - 1] >= heights[r][c]:
            dfs(r, c - 1, ocean)
        if c < cols - 1 and heights[r][c + 1] >= heights[r][c]:
            dfs(r, c + 1, ocean)

    for i in range(rows):
        dfs(i, 0, pacific)
    for j in range(cols):
        dfs(0, j, pacific)
    for i in range(rows):
        dfs(i, cols - 1, atlantic)
    for j in range(cols):
        dfs(rows - 1, j, atlantic)

    result: List[List[int]] = []
    for cell in pacific:
        if cell in atlantic:
            r, c = map(int, cell.split(','))
            result.append([r, c])
    result.sort(key=lambda x: (x[0], x[1]))
    return result

