def find_maximum_xor(nums: List[int]) -> int:
    trie = {}
    for num in nums:
        node = trie
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]
    max_result = 0
    for num in nums:
        node = trie
        curr_result = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            opp = 1 - bit
            if opp in node:
                curr_result |= (1 << i)
                node = node[opp]
            else:
                node = node[bit]
        if curr_result > max_result:
            max_result = curr_result
    return max_result

