class Solution:
    def levelOrder(self, root):
        if not root:
            return []
        ans = []
        level = [root]
        while level:
            ans.append([n.val for n in level])
            nxt = []
            for n in level:
                nxt.extend(n.children)
            level = nxt
        return ans

