def min_mutation(start_gene: str, end_gene: str, bank: List[str]) -> int:
    valid_genes = set(bank)
    queue = [(start_gene, 0)]
    visited = {start_gene}
    while queue:
        current_gene, distance = queue.pop(0)
        if current_gene == end_gene:
            return distance
        for i in range(8):
            for nucleotide in ('A', 'C', 'G', 'T'):
                new_gene = current_gene[:i] + nucleotide + current_gene[i + 1:]
                if new_gene in valid_genes and new_gene not in visited:
                    queue.append((new_gene, distance + 1))
                    visited.add(new_gene)
    return -1

