def all_one():
    count_map = {}
    bucket_map = {}
    min_count = 1
    max_count = 1

    def inc(key: str):
        nonlocal min_count, max_count
        cnt = count_map.get(key, 0)
        new_cnt = cnt + 1
        count_map[key] = new_cnt
        if cnt:
            s = bucket_map.get(cnt)
            if s:
                s.discard(key)
                if not s:
                    del bucket_map[cnt]
                    if min_count == cnt:
                        min_count = new_cnt
        bucket_map.setdefault(new_cnt, set()).add(key)
        if max_count < new_cnt:
            max_count = new_cnt
        if min_count > new_cnt or cnt == 0:
            min_count = new_cnt

    def dec(key: str):
        nonlocal min_count, max_count
        cnt = count_map.get(key)
        if cnt is None:
            return
        s = bucket_map.get(cnt)
        if s:
            s.discard(key)
            if not s:
                del bucket_map[cnt]
                if max_count == cnt:
                    max_count = max(bucket_map) if bucket_map else 0
        if cnt == 1:
            del count_map[key]
        else:
            new_cnt = cnt - 1
            count_map[key] = new_cnt
            bucket_map.setdefault(new_cnt, set()).add(key)
        if bucket_map:
            min_count = min(bucket_map)
        else:
            min_count = 1
            max_count = 1

    def get_max_key() -> str:
        if not bucket_map:
            return ""
        s = bucket_map.get(max_count)
        return next(iter(s)) if s else ""

    def get_min_key() -> str:
        if not bucket_map:
            return ""
        s = bucket_map.get(min_count)
        return next(iter(s)) if s else ""

    return SimpleNamespace(inc=inc, dec=dec, get_max_key=get_max_key, get_min_key=get_min_key)

