def path_sum(root, target_sum):
    count = 0
    def dfs(node, current_sum):
        nonlocal count
        if node is None:
            return
        current_sum += node.val
        if current_sum == target_sum:
            count += 1
        dfs(node.left, current_sum)
        dfs(node.right, current_sum)
    def traverse(node):
        if node is None:
            return
        dfs(node, 0)
        traverse(node.left)
        traverse(node.right)
    traverse(root)
    return count

