def find_anagrams(s: str, p: str) -> List[int]:
    p_count = {}
    for ch in p:
        p_count[ch] = p_count.get(ch, 0) + 1

    result = []
    window_count = {}
    required_chars = len(p_count)
    formed_chars = 0
    left = 0
    p_len = len(p)

    for right in range(len(s)):
        character = s[right]
        if character in p_count:
            window_count[character] = window_count.get(character, 0) + 1
            if window_count[character] == p_count[character]:
                formed_chars += 1

        while right - left + 1 > p_len:
            left_char = s[left]
            if left_char in p_count:
                window_count[left_char] -= 1
                if window_count[left_char] < p_count[left_char]:
                    formed_chars -= 1
            left += 1

        if right - left + 1 == p_len and formed_chars == required_chars:
            result.append(left)

    return result

