def circular_array_loop(nums: List[int]) -> bool:
    n = len(nums)
    for i in range(n):
        slow = i
        fast = i
        direction = nums[i] > 0
        while True:
            slow = _find_next_index(nums, slow, direction)
            if slow == -1:
                break
            fast = _find_next_index(nums, fast, direction)
            if fast == -1:
                break
            fast = _find_next_index(nums, fast, direction)
            if fast == -1:
                break
            if slow == fast:
                break
        if slow != -1 and slow == fast:
            if _has_cycle(nums, slow, direction):
                return True
    return False

