def is_repeated_substring(s: str) -> bool:
    n = len(s)
    if n == 0:
        return False
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if s[i] == s[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length:
                length = lps[length - 1]
            else:
                i += 1
    longest = lps[-1]
    return longest != 0 and n % (n - longest) == 0

