def lfu_cache(capacity: int):
    from collections import OrderedDict
    key_map = {}
    freq_map = {}
    min_freq = 1

    def get(key: int) -> int:
        nonlocal min_freq
        if key not in key_map:
            return -1
        val, freq = key_map[key]
        freq_od = freq_map[freq]
        del freq_od[key]
        if not freq_od:
            del freq_map[freq]
            if min_freq == freq:
                min_freq += 1
        new_freq = freq + 1
        if new_freq not in freq_map:
            freq_map[new_freq] = OrderedDict()
        freq_map[new_freq][key] = None
        key_map[key] = (val, new_freq)
        return val

    def put(key: int, value: int) -> None:
        nonlocal min_freq
        if capacity == 0:
            return
        if key in key_map:
            _, freq = key_map[key]
            key_map[key] = (value, freq)
            get(key)
            return
        if len(key_map) >= capacity:
            lru_key, _ = freq_map[min_freq].popitem(last=False)
            del key_map[lru_key]
            if not freq_map[min_freq]:
                del freq_map[min_freq]
        min_freq = 1
        key_map[key] = (value, 1)
        if 1 not in freq_map:
            freq_map[1] = OrderedDict()
        freq_map[1][key] = None

    return get, put

