            if num < 0 or num > 255 or (len(part) > 1 and part[0] == '0'):
                return "Neither"
        return "IPv4"
    elif ':' in query_ip:
        parts = query_ip.split(':')
        if len(parts) != 8:
            return "Neither"
        for part in parts:
            if not part or len(part) > 4:
                return "Neither"
            if not all(c in "0123456789abcdefABCDEF" for c in part):
                return "Neither"
        return "IPv6"
    else:
        return "Neither"

