def can_i_win(max_choosable_integer: int, desired_total: int) -> bool:
    # If the total sum of all numbers is less than the desired total, it's impossible to reach it.
    total_sum = max_choosable_integer * (max_choosable_integer + 1) // 2
    if total_sum < desired_total:
        return False
    # If the desired total is zero or negative, the first player wins by default.
    if desired_total <= 0:
        return True

    memo: Dict[Tuple[int, int], bool] = {}

    def dp(mask: int, remaining: int) -> bool:
        if (mask, remaining) in memo:
            return memo[(mask, remaining)]

        for i in range(1, max_choosable_integer + 1):
            bit = 1 << (i - 1)
            if mask & bit:
                continue
            # If picking i reaches or exceeds the remaining total, current player wins.
            if i >= remaining:
                memo[(mask, remaining)] = True
                return True
            # Otherwise, see if the opponent loses after this move.
            if not dp(mask | bit, remaining - i):
                memo[(mask, remaining)] = True
                return True

        memo[(mask, remaining)] = False
        return False

    return dp(0, desired_total)

