def median_sliding_window(nums: List[int], k: int) -> List[float]:
    min_heap: List[int] = []
    max_heap: List[int] = []
    result: List[float] = []

    for i in range(len(nums)):
        if not max_heap or nums[i] < -max_heap[0]:
            max_heap.append(-nums[i])
            max_heap.sort()
        else:
            min_heap.append(nums[i])
            min_heap.sort()

        if len(max_heap) > len(min_heap) + 1:
            min_heap.append(-max_heap.pop(0))
            min_heap.sort()
        elif len(min_heap) > len(max_heap):
            max_heap.append(-min_heap.pop(0))
            max_heap.sort()

        if i >= k - 1:
            if k % 2 == 0:
                result.append((-max_heap[0] + min_heap[0]) / 2)
            else:
                result.append(-max_heap[0])

            out_val = nums[i - k + 1]
            if out_val <= -max_heap[0]:
                idx = max_heap.index(-out_val)
                del max_heap[idx]
                max_heap.sort()
            else:
                idx = min_heap.index(out_val)
                del min_heap[idx]
                min_heap.sort()

            if len(max_heap) > len(min_heap) + 1:
                min_heap.append(-max_heap.pop(0))
                min_heap.sort()
            elif len(min_heap) > len(max_heap):
                max_heap.append(-min_heap.pop(0))
                max_heap.sort()

    return result

