def smallest_good_base(n: str) -> str:
    num = int(n)
    max_k = int(math.log2(num))  # maximum possible length-1
    for k in range(max_k, 1, -1):
        low, high = 2, int(num ** (1.0 / k)) + 1
        while low <= high:
            mid = (low + high) // 2
            total = 0
            cur = 1
            for _ in range(k + 1):
                total += cur
                if total > num:
                    break
                cur *= mid
            if total == num:
                return str(mid)
            if total < num:
                low = mid + 1
            else:
                high = mid - 1
    return str(num - 1)

