import copy

def find_min_step(board: str, hand: str) -> int:
    def reduce_board(s: str) -> str:
        while True:
            i = 0
            new_s = []
            changed = False
            while i < len(s):
                j = i
                while j < len(s) and s[j] == s[i]:
                    j += 1
                if j - i >= 3:
                    changed = True
                else:
                    new_s.append(s[i:j])
                i = j
            if not changed:
                break
            s = "".join(new_s)
        return s

    hand_map: Dict[str, int] = Counter(hand)
    queue = deque()
    queue.append((board, hand_map))
    visited = set()
    steps = 0

    while queue:
        for _ in range(len(queue)):
            cur_board, cur_hand = queue.popleft()
            state_key = (cur_board, tuple(sorted(cur_hand.items())))
            if state_key in visited:
                continue
            visited.add(state_key)

            if not cur_board:
                return steps

            for color, cnt in list(cur_hand.items()):
                if cnt == 0:
                    continue
                for i in range(len(cur_board) + 1):
                    new_board = cur_board[:i] + color + cur_board[i:]
                    new_hand = copy.deepcopy(cur_hand)
                    new_hand[color] -= 1
                    reduced = reduce_board(new_board)
                    if not reduced:
                        return steps + 1
                    queue.append((reduced, new_hand))
        steps += 1

    return -1

