def find_subsequences(nums: List[int]) -> List[List[int]]:
    result = set()

    def backtrack(start: int, cur: List[int]) -> None:
        if len(cur) >= 2:
            result.add(tuple(cur))
        for i in range(start, len(nums)):
            if not cur or nums[i] >= cur[-1]:
                cur.append(nums[i])
                backtrack(i + 1, cur)
                cur.pop()

    backtrack(0, [])
    return sorted([list(t) for t in result])

