from collections import Counter

def find_pairs(nums: List[int], k: int) -> int:
    freq = Counter(nums)
    if k == 0:
        return sum(1 for count in freq.values() if count > 1)
    count = 0
    for num in freq:
        if num + k in freq:
            count += 1
    return count

