class Solution:
    def __init__(self):
        self.url_map = {}
        self.chars = string.ascii_letters + string.digits

    def encode(self, longUrl: str) -> str:
        while True:
            short_code = ''.join(random.choice(self.chars) for _ in range(6))
            if short_code not in self.url_map:
                break
        self.url_map[short_code] = longUrl
        return "http://tinyurl.com/" + short_code

    def decode(self, shortUrl: str) -> str:
        short_code = shortUrl.split('/')[-1]
        return self.url_map.get(short_code)

def single_non_duplicate(nums: list[int]) -> int:
    result = 0
    for i in range(len(nums)):
        result ^= nums[i]
    return result

def reverse_str(s: str, k: int) -> str:
    s = list(s)
    i = 0
    n = len(s)
    while i < n:
        left = i
        right = min(i + k - 1, n - 1)
        while left < right:
            s[left], s[right] = s[right], s[left]
            left += 1
            right -= 1
        i += 2 * k
    return ''.join(s)

