from collections import deque

def update_matrix(mat: List[List[int]]) -> List[List[int]]:
    result = [[0] * len(mat[0]) for _ in range(len(mat))]
    queue = deque()
    for i in range(len(mat)):
        for j in range(len(mat[0])):
            if mat[i][j] == 0:
                result[i][j] = 0
                queue.append((i, j))
            else:
                result[i][j] = -1
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        x0, y0 = queue.popleft()
        for dx, dy in directions:
            x = x0 + dx
            y = y0 + dy
            if 0 <= x < len(mat) and 0 <= y < len(mat[0]) and result[x][y] == -1:
                result[x][y] = result[x0][y0] + 1
                queue.append((x, y))
    return result

from typing import List, Dict, Tuple

def remove_boxes(boxes: List[int]) -> int:
    if not boxes:
        return 0
    memo: Dict[Tuple[int, int, int], int] = {}

    def dp(left: int, right: int, k: int) -> int:
        if left > right:
            return 0
        key = (left, right, k)
        if key in memo:
            return memo[key]
        # compress consecutive boxes of the same color at the left side
        while left < right and boxes[left] == boxes[left + 1]:
            left += 1
            k += 1
        if left == right:
            memo[key] = (k + 1) * (k + 1)
            return memo[key]

        # option 1: remove the group at left now
        max_points = (k + 1) * (k + 1) + dp(left + 1, right, 0)

        # option 2: merge with a later box of the same color
        for i in range(left + 1, right + 1):
            if boxes[i] == boxes[left]:
                points = dp(left + 1, i - 1, 0) + dp(i, right, k + 1)
                if points > max_points:
                    max_points = points

        memo[key] = max_points
        return max_points

    return dp(0, len(boxes) - 1, 0)

