def least_bricks(wall: List[List[int]]) -> int:
    edges = {}
    for row in wall:
        s = 0
        for brick in row[:-1]:
            s += brick
            edges[s] = edges.get(s, 0) + 1
    max_edges = 0
    for count in edges.values():
        if count > max_edges:
            max_edges = count
    return len(wall) - max_edges

