from typing import List, Optional

def logical_or(quad_tree1: List[Optional[List[int]]],
               quad_tree2: List[Optional[List[int]]]) -> List[Optional[List[int]]]:
    class Node:
        __slots__ = ('isLeaf', 'val', 'topLeft', 'topRight', 'bottomLeft', 'bottomRight')
        def __init__(self, is_leaf: bool, val: bool):
            self.isLeaf: bool = is_leaf
            self.val: bool = val
            self.topLeft: Optional['Node'] = None
            self.topRight: Optional['Node'] = None
            self.bottomLeft: Optional['Node'] = None
            self.bottomRight: Optional['Node'] = None

    def build(data: List[Optional[List[int]]]) -> Optional[Node]:
        if not data:
            return None
        it = iter(data)
        root_info = next(it)
        if root_info is None:
            return None
        root = Node(bool(root_info[0]), bool(root_info[1]))
        queue: List[Optional[Node]] = [root]
        while queue:
            node = queue.pop(0)
            if node is None or node.isLeaf:
                continue
            # need four children
            children = []
            for _ in range(4):
                try:
                    info = next(it)
                except StopIteration:
                    info = None
                if info is None:
                    child = None
                else:
                    child = Node(bool(info[0]), bool(info[1]))
                children.append(child)
                if child is not None:
                    queue.append(child)
            node.topLeft, node.topRight, node.bottomLeft, node.bottomRight = children
        return root

    def intersect(a: Optional[Node], b: Optional[Node]) -> Optional[Node]:
        if a is None:
            return b
        if b is None:
            return a
        if a.isLeaf:
            if a.val:
                return Node(True, True)
            else:
                return b
        if b.isLeaf:
            if b.val:
                return Node(True, True)
            else:
                return a
        tl = intersect(a.topLeft, b.topLeft)
        tr = intersect(a.topRight, b.topRight)
        bl = intersect(a.bottomLeft, b.bottomLeft)
        br = intersect(a.bottomRight, b.bottomRight)
        if (tl.isLeaf and tr.isLeaf and bl.isLeaf and br.isLeaf and
            tl.val == tr.val == bl.val == br.val):
            return Node(True, tl.val)
        n = Node(False, False)
        n.topLeft, n.topRight, n.bottomLeft, n.bottomRight = tl, tr, bl, br
        return n

    def serialize(root: Optional[Node]) -> List[Optional[List[int]]]:
        if root is None:
            return []
        res: List[Optional[List[int]]] = []
        q: List[Optional[Node]] = [root]
        while q:
            node = q.pop(0)
            if node is None:
                res.append(None)
                continue
            res.append([int(node.isLeaf), int(node.val)])
            if not node.isLeaf:
                q.extend([node.topLeft, node.topRight, node.bottomLeft, node.bottomRight])
        while res and res[-1] is None:
            res.pop()
        return res

    tree1 = build(quad_tree1)
    tree2 = build(quad_tree2)
    result = intersect(tree1, tree2)
    return serialize(result)

