def matrix_reshape(mat: List[List[int]], r: int, c: int) -> List[List[int]]:
    if len(mat) * len(mat[0]) != r * c:
        return mat
    reshaped_matrix: List[List[int]] = []
    current_row: List[int] = []
    column_index = 0
    for i in range(len(mat)):
        for j in range(len(mat[0])):
            current_row.append(mat[i][j])
            column_index += 1
            if column_index == c:
                reshaped_matrix.append(current_row)
                current_row = []
                column_index = 0
    return reshaped_matrix

def check_inclusion(s1: str, s2: str) -> bool:
    s1_map = {}
    for ch in s1:
        s1_map[ch] = s1_map.get(ch, 0) + 1
    left = 0
    right = 0
    matched = 0
    window_counts = {}
    while right < len(s2):
        character = s2[right]
        if character in s1_map:
            window_counts[character] = window_counts.get(character, 0) + 1
            if window_counts[character] == s1_map[character]:
                matched += 1
        if right - left + 1 == len(s1):
            if matched == len(s1_map):
                return True
            left_char = s2[left]
            if left_char in s1_map:
                if window_counts[left_char] == s1_map[left_char]:
                    matched -= 1
                window_counts[left_char] -= 1
            left += 1
        right += 1
    return False

def is_subtree(root, sub_root):
    def is_match(node1, node2):
        if not node1 and not node2:
            return True
        if not node1 or not node2:
            return False
        return node1.val == node2.val and is_match(node1.left, node2.left) and is_match(node1.right, node2.right)
    def dfs(node):
        if not node:
            return False
        if is_match(node, sub_root):
            return True
        return dfs(node.left) or dfs(node.right)
    return dfs(root)

