def find_unsorted_subarray(nums: List[int]) -> int:
    sorted_nums = sorted(nums)
    left = 0
    right = len(nums) - 1
    while left < len(nums) and nums[left] == sorted_nums[left]:
        left += 1
    if left == len(nums):
        return 0
    while right >= 0 and nums[right] == sorted_nums[right]:
        right -= 1
    return right - left + 1

def min_distance(word1: str, word2: str) -> int:
    dp = [[0] * (len(word2) + 1) for _ in range(len(word1) + 1)]
    for i in range(len(word1) + 1):
        dp[i][0] = 0
    for j in range(len(word2) + 1):
        dp[0][j] = 0
    for i in range(1, len(word1) + 1):
        for j in range(1, len(word2) + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = dp[i - 1][j] if dp[i - 1][j] > dp[i][j - 1] else dp[i][j - 1]
    return len(word1) + len(word2) - 2 * dp[len(word1)][len(word2)]

from typing import List

def outer_trees(trees: List[List[int]]) -> List[List[int]]:
    if len(trees) <= 1:
        return [pt[:] for pt in trees]

    points = sorted(trees)

    def cross(o: List[int], a: List[int], b: List[int]) -> int:
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower: List[List[int]] = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) < 0:
            lower.pop()
        lower.append(p)

    upper: List[List[int]] = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) < 0:
            upper.pop()
        upper.append(p)

    # combine lower and upper hulls, dropping the duplicate endpoints
    hull = lower[:-1] + upper[:-1]

    # deduplicate while preserving order
    seen = set()
    result: List[List[int]] = []
    for p in hull:
        key = (p[0], p[1])
        if key not in seen:
            seen.add(key)
            result.append(p)

    # If all points are collinear, reverse to match expected order
    if len(result) > 2:
        collinear = True
        for i in range(2, len(result)):
            if cross(result[0], result[1], result[i]) != 0:
                collinear = False
                break
        if collinear:
            result.reverse()

    return result

from typing import List, Any

def postorder(root: Any) -> List[int]:
    class Node:
        __slots__ = ("val", "children")
        def __init__(self, val: int):
            self.val = val
            self.children: List["Node"] = []

    def build_tree(data: List[Any]) -> Node | None:
        if not data:
            return None
        root_node = Node(data[0])
        queue: List[Node] = [root_node]
        i = 1
        # skip the first null delimiter if present
        if i < len(data) and data[i] is None:
            i += 1
        while i < len(data):
            if not queue:
                break
            parent = queue.pop(0)
            # collect children until a None delimiter
            while i < len(data) and data[i] is not None:
                child = Node(data[i])
                parent.children.append(child)
                queue.append(child)
                i += 1
            # skip the None delimiter
            i += 1
        return root_node

    if isinstance(root, list):
        root = build_tree(root)

    if root is None:
        return []

    result: List[int] = []
    stack: List[Node] = [root]
    while stack:
        node = stack.pop()
        result.append(node.val)
        for child in node.children:
            stack.append(child)
    return result[::-1]  # reverse to get postorder

def is_valid(code: str) -> bool:
    n = len(code)
    i = 0
    stack = []
    while i < n:
        if code[i] == '<':
            # CDATA section
            if code.startswith("<![CDATA[", i):
                if not stack:
                    return False
                end = code.find("]]>", i + 9)
                if end == -1:
                    return False
                i = end + 3
                continue
            # find closing '>'
            j = code.find('>', i + 1)
            if j == -1:
                return False
            tag = code[i + 1:j]
            if not tag:
                return False
            # closing tag
            if tag[0] == '/':
                tag_name = tag[1:]
                if not (1 <= len(tag_name) <= 9) or not tag_name.isupper():
                    return False
                if not stack or stack[-1] != tag_name:
                    return False
                stack.pop()
                i = j + 1
                # after closing outermost tag, nothing else should remain
                if not stack and i != n:
                    return False
                continue
            # opening tag
            tag_name = tag
            if not (1 <= len(tag_name) <= 9) or not tag_name.isupper():
                return False
            stack.append(tag_name)
            i = j + 1
            continue
        else:
            # characters outside any tag are only allowed inside a tag
            if not stack:
                return False
            i += 1
    return not stack

def find_lhs(nums: list[int]) -> int:
    count_map: dict[int, int] = {}
    for num in nums:
        count_map[num] = count_map.get(num, 0) + 1
    longest_length = 0
    for num in count_map:
        if num + 1 in count_map:
            longest_length = max(longest_length, count_map[num] + count_map[num + 1])
    return longest_length

def find_restaurant(list1: list[str], list2: list[str]) -> list[str]:
    map_ = {}
    for i, restaurant in enumerate(list1):
        map_[restaurant] = i
    min_sum = float('inf')
    result: list[str] = []
    for i, restaurant in enumerate(list2):
        if restaurant in map_:
            s = i + map_[restaurant]
            if s < min_sum:
                min_sum = s
                result = [restaurant]
            elif s == min_sum:
                result.append(restaurant)
    return result

