def triangle_number(nums: List[int]) -> int:
    nums.sort()
    count = 0
    for i in range(len(nums) - 1, 1, -1):
        left, right = 0, i - 1
        while left < right:
            if nums[left] + nums[right] > nums[i]:
                count += right - left
                right -= 1
            else:
                left += 1
    return count

def merge_trees(root1, root2):
    if not root1 and not root2:
        return None
    if not root1:
        return root2
    if not root2:
        return root1
    root1.val += root2.val
    root1.left = merge_trees(root1.left, root2.left)
    root1.right = merge_trees(root1.right, root2.right)
    return root1

def least_interval(tasks, n):
    frequency_map = {}
    for task in tasks:
        frequency_map[task] = frequency_map.get(task, 0) + 1
    max_frequency = 0
    for freq in frequency_map.values():
        if freq > max_frequency:
            max_frequency = freq
    max_frequency_count = 0
    for freq in frequency_map.values():
        if freq == max_frequency:
            max_frequency_count += 1
    intervals = (max_frequency - 1) * (n + 1) + max_frequency_count
    return max(intervals, len(tasks))

class MyCircularQueue:
    def __init__(self, k: int):
        self.queue = [None]*k
        self.head = 0
        self.tail = -1
        self.size = 0

    def enQueue(self, value: int) -> bool:
        if self.size == len(self.queue): return False
        self.tail = (self.tail+1) % len(self.queue)
        self.queue[self.tail] = value
        self.size += 1
        return True

    def deQueue(self) -> bool:
        if self.size == 0: return False
        self.head = (self.head+1) % len(self.queue)
        self.size -= 1
        return True

    def Front(self) -> int:
        return -1 if self.size == 0 else self.queue[self.head]

    def Rear(self) -> int:
        return -1 if self.size == 0 else self.queue[self.tail]

    def isEmpty(self) -> bool:
        return self.size == 0

    def isFull(self) -> bool:
        return self.size == len(self.queue)

from typing import Optional

def add_one_row(root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
    if depth == 1:
        new_node = TreeNode(val, left=root, right=None)
        return new_node
    def dfs(node: Optional[TreeNode], current_depth: int) -> None:
        if node is None:
            return
        if current_depth == depth - 1:
            new_left = TreeNode(val, left=node.left, right=None)
            new_right = TreeNode(val, left=None, right=node.right)
            node.left = new_left
            node.right = new_right
        else:
            dfs(node.left, current_depth + 1)
            dfs(node.right, current_depth + 1)
    dfs(root, 1)
    return root

