def k_inverse_pairs(n: int, k: int) -> int:
    MOD = 10**9 + 7
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][0] = 1
    for i in range(2, n + 1):
        for j in range(1, k + 1):
            limit = i - 1
            if limit > j:
                limit = j
            for p in range(limit + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - p]) % MOD
    return dp[n][k]

