import heapq

def schedule_course(courses: List[List[int]]) -> int:
    courses.sort(key=lambda x: x[1])
    time = 0
    max_heap = []
    for duration, last_day in courses:
        if time + duration <= last_day:
            time += duration
            heapq.heappush(max_heap, -duration)
        elif max_heap and -max_heap[0] > duration:
            time += duration + max_heap[0]
            heapq.heapreplace(max_heap, -duration)
    return len(max_heap)

import math

def judge_square_sum(c: int) -> bool:
    a = 0
    while a * a <= c:
        remaining = c - a * a
        b = math.sqrt(remaining)
        if b == int(b):
            return True
        a += 1
    return False

def average_of_levels(root):
    result = []
    queue = [root]
    while queue:
        sum_ = 0
        level_size = len(queue)
        for _ in range(level_size):
            node = queue.pop(0)
            sum_ += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(sum_ / level_size)
    return result

