def shopping_offers(price: List[int], special: List[List[int]], needs: List[int]) -> int:
    memo = {}
    def dfs(cur: List[int]) -> int:
        key = tuple(cur)
        if key in memo:
            return memo[key]
        min_cost = sum(cur[i] * price[i] for i in range(len(cur)))
        for offer in special:
            clone = cur[:]
            valid = True
            for i in range(len(cur)):
                clone[i] -= offer[i]
                if clone[i] < 0:
                    valid = False
                    break
            if valid:
                cost = offer[-1] + dfs(clone)
                if cost < min_cost:
                    min_cost = cost
        memo[key] = min_cost
        return min_cost
    return dfs(needs)

