def num_decodings(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    if n == 0:
        return 0

    # dp_prev2 = dp[i-2], dp_prev1 = dp[i-1]
    dp_prev2 = 1
    # dp for first character
    first = s[0]
    if first == '*':
        dp_prev1 = 9
    elif first == '0':
        dp_prev1 = 0
    else:
        dp_prev1 = 1

    for i in range(1, n):
        cur = 0
        c = s[i]
        p = s[i - 1]

        # single character decoding
        if c == '*':
            cur += dp_prev1 * 9
        elif c != '0':
            cur += dp_prev1

        # two-character decoding
        if p == '*':
            if c == '*':
                # 11-19 (9) and 21-26 (6)
                cur += dp_prev2 * 15
            else:
                # p can be 1 or 2
                if c <= '6':
                    cur += dp_prev2 * 2  # 1c and 2c
                else:
                    cur += dp_prev2 * 1  # only 1c
        elif p == '1':
            if c == '*':
                cur += dp_prev2 * 9
            else:
                cur += dp_prev2
        elif p == '2':
            if c == '*':
                cur += dp_prev2 * 6
            elif c <= '6':
                cur += dp_prev2

        cur %= MOD
        dp_prev2, dp_prev1 = dp_prev1, cur

    return dp_prev1 % MOD

import re

def solve_equation(equation: str) -> str:
    left, right = equation.split('=')

    def parse_side(side):
        x_coeff = 0
        const = 0
        terms = re.findall(r'[+-]?\d*x|[+-]?\d+', side)
        for term in terms:
            if term.endswith('x'):
                coeff_str = term[:-1]
                if coeff_str in ('', '+'):
                    x_coeff += 1
                elif coeff_str == '-':
                    x_coeff -= 1
                else:
                    x_coeff += int(coeff_str)
            else:
                const += int(term)
        return x_coeff, const

    left_x, left_c = parse_side(left)
    right_x, right_c = parse_side(right)
    x_coefficient = left_x - right_x
    constant = right_c - left_c
    if x_coefficient == 0:
        return "Infinite solutions" if constant == 0 else "No solution"
    return "x=" + str(constant // x_coefficient)

