def print_tree(root):
    height = get_height(root)
    width = (1 << height) - 1
    res = [[""] * width for _ in range(height)]
    from collections import deque
    queue = deque()
    queue.append((root, 0, 0, width - 1))
    while queue:
        node, level, start, end = queue.popleft()
        mid = (start + end) // 2
        res[level][mid] = str(node.val)
        if getattr(node, "left", None):
            queue.append((node.left, level + 1, start, mid - 1))
        if getattr(node, "right", None):
            queue.append((node.right, level + 1, mid + 1, end))
    return res

