def strange_printer(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            # start with printing s[i] separately then the rest
            dp[i][j] = dp[i + 1][j] + 1
            for k in range(i + 1, j + 1):
                if s[k] == s[i]:
                    # merge the print of s[i] with s[k]
                    left = dp[i + 1][k - 1] if k - 1 >= i + 1 else 0
                    dp[i][j] = min(dp[i][j], left + dp[k][j])
    return dp[0][n - 1]

