def construct_array(n: int, k: int) -> List[int]:
    result: List[int] = []
    # Append the initial increasing sequence up to n - k - 1
    for num in range(1, n - k):
        result.append(num)
    low, high = n - k, n
    # Alternate between low and high to create k distinct differences
    for i in range(k + 1):
        if i % 2 == 0:
            result.append(low)
            low += 1
        else:
            result.append(high)
            high -= 1
    return result

