def maximum_swap(num: int) -> int:
    digits: List[str] = list(str(num))
    # record the last position of each digit (0-9)
    last: List[int] = [-1] * 10
    for i, ch in enumerate(digits):
        last[int(ch)] = i

    for i, ch in enumerate(digits):
        cur = int(ch)
        # try to find a larger digit to swap with, starting from 9 down to cur+1
        for d in range(9, cur, -1):
            if last[d] > i:
                # perform swap
                digits[i], digits[last[d]] = digits[last[d]], digits[i]
                return int(''.join(digits))
    return num

