        self.map[key] = val
        node = self.trie
        for ch in key:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
            node['sum'] = node.get('sum', 0) + delta

    def sum(self, prefix: str) -> int:
        node = self.trie
        for ch in prefix:
            if ch not in node:
                return 0
            node = node[ch]
        return node.get('sum', 0)

