        if bytes_left == 0:
            if binary[0] == '0':
                continue
            elif binary[0] == '1' and binary[1] == '1' and binary[2] == '0':
                bytes_left = 1
            elif binary[0] == '1' and binary[1] == '1' and binary[2] == '1' and binary[3] == '0':
                bytes_left = 2
            elif binary[0] == '1' and binary[1] == '1' and binary[2] == '1' and binary[3] == '1' and binary[4] == '0':
