def max_number(nums1: List[int], nums2: List[int], k: int) -> List[int]:
    def pick_max(nums: List[int], k: int) -> List[int]:
        drop = len(nums) - k
        out: List[int] = []
        for num in nums:
            while out and drop and out[-1] < num:
                out.pop()
                drop -= 1
            out.append(num)
        return out[:k]

    def greater(a: List[int], b: List[int], a_index: int, b_index: int, max_len: int) -> bool:
        while a_index < len(a) and b_index < len(b):
            if a[a_index] != b[b_index]:
                return a[a_index] > b[b_index]
            a_index += 1
            b_index += 1
        return a_index < len(a)

    def merge(a: List[int], b: List[int]) -> List[int]:
        out: List[int] = []
        i = j = 0
        while i < len(a) or j < len(b):
            if j == len(b) or (i < len(a) and greater(a, b, i, j, len(a) - i)):
                out.append(a[i])
                i += 1
            else:
                out.append(b[j])
                j += 1
        return out

    max_res: List[int] = []
    for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
        candidate = merge(pick_max(nums1, i), pick_max(nums2, k - i))
        if greater(candidate, max_res, 0, 0, len(candidate)):
            max_res = candidate
    return max_res

