def shortest_path_length(graph: List[List[int]]) -> int:
    n = len(graph)
    all_nodes_visited = (1 << n) - 1
    queue = deque()
    visited = [[False] * (1 << n) for _ in range(n)]
    for i in range(n):
        queue.append((i, 1 << i, 0))
        visited[i][1 << i] = True
    while queue:
        node, bitmask, distance = queue.popleft()
        if bitmask == all_nodes_visited:
            return distance
        for neighbor in graph[node]:
            new_bitmask = bitmask | (1 << neighbor)
            if not visited[neighbor][new_bitmask]:
                queue.append((neighbor, new_bitmask, distance + 1))
                visited[neighbor][new_bitmask] = True

def is_n_straight_hand(hand, group_size):
    freq = {}
    for card in hand:
        if card in freq:
            freq[card] += 1
        else:
            freq[card] = 1

    keys = sorted(freq.keys())

    for key in keys:
        while freq.get(key, 0) > 0:
            for j in range(group_size):
                cur = key + j
                if freq.get(cur, 0) == 0:
                    return False
                freq[cur] -= 1
    return True

