def k_similarity(s1: str, s2: str) -> int:
    queue = deque()
    queue.append((s1, 0))
    visited = {s1}
    while queue:
        curr, swaps = queue.popleft()
        if curr == s2:
            return swaps
        n = len(curr)
        for i in range(n):
            if curr[i] != s2[i]:
                for j in range(i + 1, n):
                    if curr[j] == s2[i]:
                        nxt = _swap(curr, i, j)
                        if nxt not in visited:
                            visited.add(nxt)
                            queue.append((nxt, swaps + 1))
                break
    return -1

