def shortest_path_all_keys(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    keys = 0
    locks = 0
    queue = deque()
    visited = set()
    for i in range(rows):
        for j in range(cols):
            cell = grid[i][j]
            if cell == '@':
                queue.append((i, j, 0, 0))
                visited.add(f"{i},{j},0")
            elif 'a' <= cell <= 'f':
                keys += 1
            elif 'A' <= cell <= 'F':
                locks += 1
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        x, y, collected_keys, steps = queue.popleft()
        if collected_keys == (1 << keys) - 1:
            return steps
        for dx, dy in directions:
            nx = x + dx
            ny = y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                new_cell = grid[nx][ny]
                if 'a' <= new_cell <= 'f':
                    new_collected_keys = collected_keys | (1 << (ord(new_cell) - ord('a')))
                    state = f"{nx},{ny},{new_collected_keys}"
                    if state not in visited:
                        visited.add(state)
                        queue.append((nx, ny, new_collected_keys, steps + 1))
                elif 'A' <= new_cell <= 'F':
                    if collected_keys & (1 << (ord(new_cell) - ord('A'))):
                        state = f"{nx},{ny},{collected_keys}"
                        if state not in visited:
                            visited.add(state)
                            queue.append((nx, ny, collected_keys, steps + 1))
                else:
                    state = f"{nx},{ny},{collected_keys}"
                    if state not in visited:
                        visited.add(state)
                        queue.append((nx, ny, collected_keys, steps + 1))
    return -1

