    def next(self, num: int) -> int:
        while self.index < len(self.encoding):
            remaining = self.encoding[self.index]
            if num <= remaining:
                self.encoding[self.index] -= num
                return self.encoding[self.index+1]
            num -= remaining
            self.index += 2
        return -1

