def die_simulator(n: int, roll_max: List[int]) -> int:
    MOD = 10**9 + 7
    dp = [[[0] * 16 for _ in range(6)] for _ in range(n + 1)]
    for i in range(6):
        dp[1][i][1] = 1
    for i in range(2, n + 1):
        for j in range(6):
            for k in range(1, 16):
                for prev in range(6):
                    if prev != j:
                        dp[i][j][1] = (dp[i][j][1] + dp[i - 1][prev][k]) % MOD
                    elif k < roll_max[j]:
                        dp[i][j][k + 1] = (dp[i][j][k + 1] + dp[i - 1][prev][k]) % MOD
    res = 0
    for i in range(6):
        for j in range(1, 16):
            res = (res + dp[n][i][j]) % MOD
    return res

