def max_equal_freq(nums: List[int]) -> int:
    freq: Dict[int, int] = {}
    freq_cnt: Dict[int, int] = {}
    max_len = 0

    for i, num in enumerate(nums):
        prev = freq.get(num, 0)
        if prev:
            freq_cnt[prev] -= 1
            if freq_cnt[prev] == 0:
                del freq_cnt[prev]

        cur = prev + 1
        freq[num] = cur
        freq_cnt[cur] = freq_cnt.get(cur, 0) + 1

        total = i + 1
        distinct = len(freq)

        # current maximum frequency
        max_f = max(freq_cnt)
        cnt_max = freq_cnt[max_f]

        # check conditions
        # 1. all frequencies are 1
        if max_f == 1:
            max_len = total
        # 2. only one distinct number
        elif distinct == 1:
            max_len = total
        else:
            # 3. one number occurs once, others have same frequency
            if 1 in freq_cnt and freq_cnt[1] == 1:
                # after removing that single occurrence, remaining total should be max_f * cnt_max
                if max_f * cnt_max == total - 1:
                    max_len = total
            # 4. one number has frequency higher by one than the rest
            if cnt_max == 1 and (max_f - 1) in freq_cnt:
                cnt_prev = freq_cnt[max_f - 1]
                # removing one occurrence of the max_f number makes all frequencies equal to max_f-1
                if (max_f - 1) * (distinct - 1) + (max_f - 1) == total - 1:
                    max_len = total

    return max_len

