def kth_factor(n: int, k: int) -> int:
    import math
    small_factors = []
    large_factors = []
    limit = int(math.isqrt(n))
    for i in range(1, limit + 1):
        if n % i == 0:
            small_factors.append(i)
            other = n // i
            if other != i:
                large_factors.append(other)
    total = len(small_factors) + len(large_factors)
    if k > total:
        return -1
    if k <= len(small_factors):
        return small_factors[k - 1]
    # kth factor is in the large_factors list, which is in descending order
    idx = total - k
    return large_factors[idx]

