def min_number_of_semesters(n: int, relations: List[List[int]], k: int) -> int:
    graph = [[] for _ in range(n + 1)]
    indegree = [0] * (n + 1)
    for prev, nxt in relations:
        graph[prev].append(nxt)
        indegree[nxt] += 1

    queue = deque()
    for i in range(1, n + 1):
        if indegree[i] == 0:
            queue.append(i)

    visited = 0
    result = 0

    while queue:
        size = len(queue)
        dequeue_count = 0
        for _ in range(size):
            if dequeue_count >= k:
                break
            node = queue.popleft()
            visited += 1
            dequeue_count += 1
            for neighbor in graph[node]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)
        if dequeue_count > 0:
            result += 1

    return result

def num_submat(mat):
    m = len(mat)
    n = len(mat[0])
    height = [0] * n
    count = 0
    for i in range(m):
        for j in range(n):
            height[j] = height[j] + 1 if mat[i][j] == 1 else 0
        stack = []
        for j in range(n + 1):
            while stack and (j == n or height[j] < height[stack[-1]]):
                h = height[stack.pop()]
                w = j if not stack else j - stack[-1] - 1
                count += h * w
            stack.append(j)
    return count

