def closest_to_target(arr: List[int], target: int) -> int:
    """
    Returns the minimum possible absolute difference between `target` and the bitwise AND
    of any non‑empty contiguous subarray of `arr`.
    """
    best = float('inf')
    cur = set()  # possible AND values for subarrays ending at previous index

    for x in arr:
        nxt = {x}
        for v in cur:
            nxt.add(v & x)
        cur = nxt
        for v in cur:
            diff = v - target
            if diff < 0:
                diff = -diff
            if diff < best:
                best = diff
                if best == 0:  # early exit, cannot improve
                    return 0
    return best

