def find_redundant_connection(edges: List[List[int]]) -> List[int]:
    parent = list(range(len(edges) + 1))
    def find(node: int) -> int:
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]
    def union(node1: int, node2: int) -> bool:
        root1 = find(node1)
        root2 = find(node2)
        if root1 == root2:
            return False
        parent[root1] = root2
        return True
    for edge in edges:
        node1, node2 = edge[0], edge[1]
        if not union(node1, node2):
            return edge

def knight_probability(n: int, k: int, row: int, column: int) -> float:
    moves = [(-2, -1), (-1, -2), (1, -2), (2, -1), (-2, 1), (-1, 2), (1, 2), (2, 1)]
    memo = [[[-1.0 for _ in range(k + 1)] for _ in range(n)] for _ in range(n)]

    def calculate_probability(x: int, y: int, moves_left: int) -> float:
        if x < 0 or x >= n or y < 0 or y >= n:
            return 0.0
        if moves_left == 0:
            return 1.0
        if memo[x][y][moves_left] != -1.0:
            return memo[x][y][moves_left]
        prob = 0.0
        for dx, dy in moves:
            prob += calculate_probability(x + dx, y + dy, moves_left - 1) / 8.0
        memo[x][y][moves_left] = prob
        return prob

    return calculate_probability(row, column, k)

