def max_sum_of_three_subarrays(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]
    sum1 = [0] * (n - k + 1)
    for i in range(n - k + 1):
        sum1[i] = prefix_sum[i + k] - prefix_sum[i]
    sum2 = [0] * (n - 2 * k + 1)
    for i in range(n - 2 * k + 1):
        max_sum = -float('inf')
        for j in range(i + k, n - k + 1):
            max_sum = max(max_sum, sum1[i] + sum1[j])
        sum2[i] = max_sum
    max_sum = -float('inf')
    result: List[int] = []
    for i in range(n - 3 * k + 1):
        for j in range(i + k, n - 2 * k + 1):
            for m in range(j + k, n - k + 1):
                current_sum = sum1[i] + sum1[j] + sum1[m]
                if current_sum > max_sum:
                    max_sum = current_sum
                    result = [i, j, m]
                elif current_sum == max_sum:
                    if i < result[0] or (i == result[0] and j < result[1]) or (i == result[0] and j == result[1] and m < result[2]):
                        result = [i, j, m]
