def min_stickers(stickers: List[str], target: str) -> int:
    # convert stickers to count vectors
    sticker_counts = []
    for s in stickers:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        sticker_counts.append(cnt)

    # target count vector
    target_cnt = [0] * 26
    for ch in target:
        target_cnt[ord(ch) - 97] += 1

    # discard stickers that don't contribute to target
    useful = []
    for cnt in sticker_counts:
        if any(cnt[i] > 0 and target_cnt[i] > 0 for i in range(26)):
            useful.append(cnt)
    sticker_counts = useful

    @lru_cache(None)
    def dfs(rem: Tuple[int, ...]) -> int:
        if all(v == 0 for v in rem):
            return 0
        # pick a needed character to guide pruning
        for i in range(26):
            if rem[i] > 0:
                need_idx = i
                break
        best = float('inf')
        for cnt in sticker_counts:
            if cnt[need_idx] == 0:
                continue
            new_rem = list(rem)
            for j in range(26):
                if new_rem[j] > 0:
                    new_rem[j] = max(0, new_rem[j] - cnt[j])
            best = min(best, 1 + dfs(tuple(new_rem)))
        return best if best != float('inf') else -1

    return dfs(tuple(target_cnt))

