def my_linked_list():
    head = None
    tail = None
    size = 0

    def get_node(index):
        nonlocal head, tail, size
        if index <= size / 2:
            node = head
            for _ in range(index):
                node = node['next']
            return node
        else:
            node = tail
            for _ in range(size - index - 1):
                node = node['prev']
            return node

    def add_at_head(val):
        nonlocal head, tail, size
        new_node = {'val': val, 'next': None, 'prev': None}
        if head is None:
            head = new_node
            tail = new_node
        else:
            new_node['next'] = head
            head['prev'] = new_node
            head = new_node
        size += 1

    def add_at_tail(val):
        nonlocal head, tail, size
        new_node = {'val': val, 'next': None, 'prev': None}
        if tail is None:
            head = new_node
            tail = new_node
        else:
            new_node['prev'] = tail
            tail['next'] = new_node
            tail = new_node
        size += 1

    def add_at_index(index, val):
        nonlocal head, tail, size
        if index == 0:
            add_at_head(val)
        elif index == size:
            add_at_tail(val)
        elif index < 0 or index > size:
            return
        else:
            prev_node = get_node(index - 1)
            new_node = {'val': val, 'next': None, 'prev': None}
            new_node['next'] = prev_node['next']
            new_node['prev'] = prev_node
            prev_node['next']['prev'] = new_node
            prev_node['next'] = new_node
            size += 1

    def delete_at_index(index):
        nonlocal head, tail, size
        if index < 0 or index >= size:
            return
        if index == 0:
            if size == 1:
                head = None
                tail = None
            else:
                head = head['next']
                head['prev'] = None
        elif index == size - 1:
            tail = tail['prev']
            tail['next'] = None
        else:
            node = get_node(index)
            node['prev']['next'] = node['next']
            node['next']['prev'] = node['prev']
        size -= 1

    def get(index):
        nonlocal size
        if index < 0 or index >= size:
            return -1
        return get_node(index)['val']

    return SimpleNamespace(
        add_at_head=add_at_head,
        add_at_tail=add_at_tail,
        add_at_index=add_at_index,
        delete_at_index=delete_at_index,
        get=get
    )

