def smallest_distance_pair(nums: List[int], k: int) -> int:
    nums.sort()
    left = 0
    right = nums[-1] - nums[0]
    while left < right:
        mid = (left + right) // 2
        count = 0
        j = 0
        n = len(nums)
        for i in range(n):
            while j < n and nums[j] - nums[i] <= mid:
                j += 1
            count += j - i - 1
        if count < k:
            left = mid + 1
        else:
            right = mid
    return left

