def accounts_merge(accounts: List[List[str]]) -> List[List[str]]:
    parent: Dict[str, str] = {}
    name: Dict[str, str] = {}
    for account in accounts:
        for email in account[1:]:
            parent[email] = email
            name[email] = account[0]

    def find(email: str) -> str:
        if parent[email] == email:
            return email
        parent[email] = find(parent[email])
        return parent[email]

    def union(email1: str, email2: str) -> None:
        p1 = find(email1)
        p2 = find(email2)
        if p1 != p2:
            parent[p1] = p2

    for account in accounts:
        for i in range(1, len(account) - 1):
            union(account[i], account[i + 1])

    merged: Dict[str, List[str]] = {}
    for email in parent:
        root = find(email)
        merged.setdefault(root, []).append(email)

    result: List[List[str]] = []
    for root, emails in merged.items():
        emails.sort()
        result.append([name[root]] + emails)

    return result

