def count_of_atoms(formula: str) -> str:
    stack = [{}]
    i = 0
    n = len(formula)
    while i < n:
        ch = formula[i]
        if ch.isupper():
            name = ch
            i += 1
            while i < n and formula[i].islower():
                name += formula[i]
                i += 1
            count = 0
            while i < n and formula[i].isdigit():
                count = count * 10 + int(formula[i])
                i += 1
            if count == 0:
                count = 1
            stack[-1][name] = stack[-1].get(name, 0) + count
        elif ch == '(':
            stack.append({})
            i += 1
        elif ch == ')':
            i += 1
            count = 0
            while i < n and formula[i].isdigit():
                count = count * 10 + int(formula[i])
                i += 1
            if count == 0:
                count = 1
            temp = stack.pop()
            for name, cnt in temp.items():
                stack[-1][name] = stack[-1].get(name, 0) + cnt * count
        else:
            i += 1
    result = ''
    for name in sorted(stack[0].keys()):
        result += name
        cnt = stack[0][name]
        if cnt > 1:
            result += str(cnt)
    return result

