def cherry_pickup(grid: List[List[int]]) -> int:
    n = len(grid)
    INF_NEG = -10**9
    # dp[i1][i2] = max cherries when person1 at (i1, k-i1) and person2 at (i2, k-i2)
    dp = [[INF_NEG] * n for _ in range(n)]
    dp[0][0] = grid[0][0] if grid[0][0] != -1 else INF_NEG

    for k in range(1, 2 * n - 1):
        new_dp = [[INF_NEG] * n for _ in range(n)]
        i1_min = max(0, k - (n - 1))
        i1_max = min(n - 1, k)
        for i1 in range(i1_min, i1_max + 1):
            j1 = k - i1
            if j1 >= n or grid[i1][j1] == -1:
                continue
            i2_min = i1_min
            i2_max = i1_max
            for i2 in range(i2_min, i2_max + 1):
                j2 = k - i2
                if j2 >= n or grid[i2][j2] == -1:
                    continue
                best_prev = INF_NEG
                # four possible previous moves
                for di1 in (0, -1):
                    for di2 in (0, -1):
                        pi1 = i1 + di1
                        pi2 = i2 + di2
                        if pi1 < 0 or pi2 < 0:
                            continue
                        prev = dp[pi1][pi2]
                        if prev > best_prev:
                            best_prev = prev
                if best_prev == INF_NEG:
                    continue
                cur = best_prev
                if i1 == i2 and j1 == j2:
                    cur += grid[i1][j1]
                else:
                    cur += grid[i1][j1] + grid[i2][j2]
                new_dp[i1][i2] = cur
        dp = new_dp

    result = dp[n - 1][n - 1]
    return max(result, 0)

