def open_lock(deadends: List[str], target: str) -> int:
    dead = set(deadends)
    if '0000' in dead:
        return -1
    queue = deque([('0000', 0)])
    visited = {'0000'}
    while queue:
        state, turns = queue.popleft()
        if state == target:
            return turns
        for i in range(4):
            inc = (int(state[i]) + 1) % 10
            next_state = state[:i] + str(inc) + state[i+1:]
            if next_state not in dead and next_state not in visited:
                queue.append((next_state, turns + 1))
                visited.add(next_state)
            dec = (int(state[i]) - 1 + 10) % 10
            next_state = state[:i] + str(dec) + state[i+1:]
            if next_state not in dead and next_state not in visited:
                queue.append((next_state, turns + 1))
                visited.add(next_state)
    return -1

def crack_safe(n: int, k: int) -> str:
    """
    Returns a shortest string that contains every possible password of length n
    (digits in [0, k-1]) as a contiguous substring.
    """
    if n == 0:
        return ""
    total = k ** n
    mod = k ** (n - 1) if n > 1 else 1
    visited = [False] * total
    res: list[str] = []

    def dfs(node: int) -> None:
        for x in range(k):
            edge = node * k + x
            if not visited[edge]:
                visited[edge] = True
                dfs(edge % mod)
                res.append(str(x))

    dfs(0)
    return "".join(res) + "0" * (n - 1)

