def contain_virus(is_infected: List[List[int]]) -> int:
    m = len(is_infected)
    if m == 0:
        return 0
    n = len(is_infected[0])
    walls_built = 0

    while True:
        visited = [[False] * n for _ in range(m)]
        regions: List[List[tuple[int, int]]] = []
        frontiers: List[set[tuple[int, int]]] = []
        walls_needed: List[int] = []

        for i in range(m):
            for j in range(n):
                if is_infected[i][j] == 1 and not visited[i][j]:
                    region: List[tuple[int, int]] = []
                    frontier: set[tuple[int, int]] = set()
                    wall_cnt = 0
                    q = deque()
                    q.append((i, j))
                    visited[i][j] = True
                    while q:
                        x, y = q.popleft()
                        region.append((x, y))
                        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < m and 0 <= ny < n:
                                if is_infected[nx][ny] == 1 and not visited[nx][ny]:
                                    visited[nx][ny] = True
                                    q.append((nx, ny))
                                elif is_infected[nx][ny] == 0:
                                    wall_cnt += 1
                                    frontier.add((nx, ny))
                    regions.append(region)
                    frontiers.append(frontier)
                    walls_needed.append(wall_cnt)

        if not regions:
            break

        # choose region with largest frontier
        max_idx = max(range(len(frontiers)), key=lambda i: len(frontiers[i]))
        walls_built += walls_needed[max_idx]

        # quarantine the chosen region
        for x, y in regions[max_idx]:
            is_infected[x][y] = -1

        # spread virus from other regions
        for idx, region in enumerate(regions):
            if idx == max_idx:
                continue
            for x, y in region:
                for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and is_infected[nx][ny] == 0:
                        is_infected[nx][ny] = 1

    return walls_built

def is_palindrome(s: str, left: int, right: int) -> bool:
