def find_closest_palindrome(n: str) -> str:
    length = len(n)
    num = int(n)

    # Single digit edge case
    if length == 1:
        return str(num - 1)

    candidates = set()

    # Helper to create palindrome from a prefix string
    def make_pal(prefix: str) -> int:
        if length % 2 == 0:
            return int(prefix + prefix[::-1])
        else:
            return int(prefix + prefix[-2::-1])

    # Original prefix (including middle for odd length)
    prefix_len = (length + 1) // 2
    prefix = n[:prefix_len]
    prefix_int = int(prefix)

    # Generate palindromes by adjusting the prefix
    for delta in (-1, 0, 1):
        new_prefix = str(prefix_int + delta)
        # Ensure the new prefix has correct length (may shrink or grow)
        if len(new_prefix) != prefix_len:
            # When length changes, handle separately via edge candidates
            continue
        candidates.add(make_pal(new_prefix))

    # Edge candidates: 10^length + 1 (e.g., 100...001) and 10^(length-1) - 1 (e.g., 99...9)
    candidates.add(10 ** length + 1)
    candidates.add(10 ** (length - 1) - 1)

    # Remove the original number if present
    candidates.discard(num)

    # Find the closest palindrome
    best = None
    min_diff = float('inf')
    for cand in candidates:
        diff = abs(cand - num)
        if diff < min_diff or (diff == min_diff and cand < best):
            min_diff = diff
            best = cand

    return str(best)

