def shortest_completing_word(license_plate: str, words: List[str]) -> Optional[str]:
    license_map = {}
    for char in license_plate:
        if char.isalpha():
            lower_char = char.lower()
            license_map[lower_char] = license_map.get(lower_char, 0) + 1

    shortest_word = None
    shortest_length = float('inf')

    for word in words:
        word_map = {}
        for char in word:
            lower_char = char.lower()
            word_map[lower_char] = word_map.get(lower_char, 0) + 1

        is_completing_word = True
        for char, count in license_map.items():
            if word_map.get(char, 0) < count:
                is_completing_word = False
                break

        if is_completing_word and len(word) < shortest_length:
            shortest_word = word
            shortest_length = len(word)

    return shortest_word

def count_prime_set_bits(left: int, right: int) -> int:
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True
    count = 0
    for i in range(left, right + 1):
        set_bits = len(bin(i)[2:].split('1')) - 1
        if is_prime(set_bits):
            count += 1
    return count

