def intersection_size_two(intervals: List[List[int]]) -> int:
    # sort by right endpoint ascending, and by left endpoint descending for ties
    intervals.sort(key=lambda x: (x[1], -x[0]))
    selected: List[int] = []
    for l, r in intervals:
        # count how many of the last selected numbers fall inside the current interval
        cnt = 0
        if len(selected) >= 1 and selected[-1] >= l:
            cnt += 1
        if len(selected) >= 2 and selected[-2] >= l:
            cnt += 1

        if cnt >= 2:
            continue
        if cnt == 1:
            # need one more number, choose the rightmost possible that is not already selected
            new_num = r if selected[-1] != r else r - 1
            selected.append(new_num)
        else:  # cnt == 0
            # need two numbers, pick the two rightmost distinct numbers
            selected.append(r - 1)
            selected.append(r)
    return len(selected)

