def order_of_largest_plus_sign(n: int, mines: List[Tuple[int, int]]) -> int:
    grid = [[1] * n for _ in range(n)]
    for x, y in mines:
        grid[x][y] = 0
    max_order = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                order = 1
                while i - order >= 0 and i + order < n and j - order >= 0 and j + order < n:
                    if (grid[i - order][j] == 1 and
                        grid[i + order][j] == 1 and
                        grid[i][j - order] == 1 and
                        grid[i][j + order] == 1):
                        order += 1
                    else:
                        break
                max_order = max(max_order, order)
    return max_order

