def reorganize_string(s: str) -> str:
    char_frequency = {}
    for char in s:
        if char in char_frequency:
            char_frequency[char] += 1
        else:
            char_frequency[char] = 1

    max_heap = []
    for char, freq in char_frequency.items():
        max_heap.append([char, freq])
    max_heap.sort(key=lambda x: x[1], reverse=True)

    result = ""

    while max_heap:
        if result and result[-1] == max_heap[0][0]:
            if len(max_heap) == 1:
                return ""
            max_heap[0], max_heap[1] = max_heap[1], max_heap[0]

        char = max_heap[0][0]
        frequency = max_heap[0][1]
        result += char
        max_heap[0][1] -= 1
        if max_heap[0][1] == 0:
            del max_heap[0]
        if max_heap:
            max_heap.sort(key=lambda x: x[1], reverse=True)

    return result

