def pyramid_transition(bottom: str, allowed: List[str]) -> bool:
    mapping: Dict[str, List[str]] = {}
    for pattern in allowed:
        key = pattern[:2]
        mapping.setdefault(key, []).append(pattern[2])

    current_row = [bottom]

    while len(current_row[0]) > 1:
        next_row = []
        for row in current_row:
            possible = set()
            generate_next_rows(row, 0, "", possible, mapping)
            for nxt in possible:
                next_row.append(nxt)
        current_row = next_row
        if not current_row:
            return False
    return True

