from collections import Counter

def basic_calculator_iv(expression: str, evalvars: List[str], evalints: List[int]) -> List[str]:
    var_map: Dict[str, int] = {v: i for v, i in zip(evalvars, evalints)}

    def tokenize(s: str) -> List[str]:
        tokens: List[str] = []
        i = 0
        while i < len(s):
            if s[i] == ' ':
                i += 1
                continue
            if s[i] in "+-*()":
                tokens.append(s[i])
                i += 1
            elif s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:  # variable
                j = i
                while j < len(s) and s[j].isalpha():
                    j += 1
                tokens.append(s[i:j])
                i = j
        return tokens

    # polynomial represented as Counter mapping tuple of vars -> coefficient
    Poly = Counter[Tuple[str, ...]]

    def make_poly(token: str) -> Poly:
        if token.isdigit():
            return Counter({(): int(token)})
        if token in var_map:
            return Counter({(): var_map[token]})
        return Counter({(token,): 1})

    def add(p1: Poly, p2: Poly) -> Poly:
        res = Counter(p1)
        for k, v in p2.items():
            res[k] += v
        return Counter({k: v for k, v in res.items() if v != 0})

    def sub(p1: Poly, p2: Poly) -> Poly:
        res = Counter(p1)
        for k, v in p2.items():
            res[k] -= v
        return Counter({k: v for k, v in res.items() if v != 0})

    def mul(p1: Poly, p2: Poly) -> Poly:
        res: Counter[Tuple[str, ...]] = Counter()
        for vars1, coeff1 in p1.items():
            for vars2, coeff2 in p2.items():
                new_coeff = coeff1 * coeff2
                new_vars = tuple(sorted(vars1 + vars2))
                res[new_vars] += new_coeff
        return Counter({k: v for k, v in res.items() if v != 0})

    precedence = {'+': 1, '-': 1, '*': 2}
    tokens = tokenize(expression)

    values: List[Poly] = []
    ops: List[str] = []

    def apply_op():
        op = ops.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            values.append(add(left, right))
        elif op == '-':
            values.append(sub(left, right))
        else:  # '*'
            values.append(mul(left, right))

    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok == '(':
            ops.append(tok)
        elif tok == ')':
            while ops and ops[-1] != '(':
                apply_op()
            ops.pop()  # remove '('
        elif tok in '+-*':
            while ops and ops[-1] != '(' and precedence[ops[-1]] >= precedence[tok]:
                apply_op()
            ops.append(tok)
        else:
            values.append(make_poly(tok))
        i += 1

    while ops:
        apply_op()

    final_poly = values[0]

    # sort terms: degree descending, then lexicographically
    sorted_terms = sorted(
        final_poly.items(),
        key=lambda kv: (-len(kv[0]), kv[0])
    )

    result: List[str] = []
    for vars_tuple, coeff in sorted_terms:
        if coeff == 0:
            continue
        if not vars_tuple:
            result.append(str(coeff))
        else:
            result.append(str(coeff) + '*' + '*'.join(vars_tuple))
    return result

