def reaching_points(sx: int, sy: int, tx: int, ty: int) -> bool:
    if sx == tx and sy == ty:
        return True
    if sx > tx or sy > ty:
        return False

    while tx > sx and ty > sy:
        if tx == ty:
            break
        if tx > ty:
            tx %= ty
            if tx == 0:
                tx = ty
        else:
            ty %= tx
            if ty == 0:
                ty = tx

    if tx == sx and ty >= sy and (ty - sy) % sx == 0:
        return True
    if ty == sy and tx >= sx and (tx - sx) % sy == 0:
        return True
    return False
# TIME: O(log max(tx, ty)) SPACE: O(1)

