    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                global_inversions += 1
    local_inversions = 0
    for i in range(n - 1):
        if nums[i] > nums[i + 1]:
            local_inversions += 1
    return global_inversions == local_inversions

def min_diff_in_bst(root):
    min_diff = float('inf')
    prev_val = None
    def in_order(node):
        nonlocal min_diff, prev_val
        if node:
            in_order(node.left)
            if prev_val is not None:
                diff = node.val - prev_val
                if diff < min_diff:
                    min_diff = diff
            prev_val = node.val
            in_order(node.right)
    in_order(root)
    return min_diff

