def moves_to_make_chessboard(board: List[List[int]]) -> int:
    n = len(board)
    if n == 0:
        return 0

    # Helper to validate that all lines are either equal to first or its complement
    def validate(lines: List[List[int]]) -> int:
        first = lines[0]
        complement = [1 - x for x in first]
        cnt_first = 0
        for line in lines:
            if line == first:
                cnt_first += 1
            elif line == complement:
                continue
            else:
                return -1
        # For a valid chessboard, the count of the first pattern must be balanced
        if n % 2 == 0:
            if cnt_first != n // 2:
                return -1
        else:
            if cnt_first not in (n // 2, n // 2 + 1):
                return -1
        return cnt_first

    # Validate rows
    row_cnt_first = validate(board)
    if row_cnt_first == -1:
        return -1

    # Build columns
    cols = [[board[i][j] for i in range(n)] for j in range(n)]
    col_cnt_first = validate(cols)
    if col_cnt_first == -1:
        return -1

    # Helper to compute minimal swaps for either rows or columns
    def min_swaps(line_vals: List[int]) -> int:
        # line_vals holds the first element of each line (row or column)
        ones = sum(line_vals)
        # count mismatches with the ideal alternating pattern starting with 0
        mismatches = sum((line_vals[i] != (i % 2)) for i in range(n))

        if n % 2 == 0:
            # we can start with 0 or 1, choose the minimal swaps
            return min(mismatches, n - mismatches) // 2
        else:
            # For odd n, the pattern must start with the majority value
            if ones * 2 > n:  # more 1s than 0s, pattern should start with 1
                # mismatches currently count positions where we have 0 instead of 1 at even indices
                # we need mismatches to be even; if it's odd, use the other orientation
                if mismatches % 2 == 0:
                    return mismatches // 2
                else:
                    return (n - mismatches) // 2
            else:  # more 0s or equal, pattern should start with 0
                if mismatches % 2 == 0:
                    return mismatches // 2
                else:
                    return (n - mismatches) // 2

    # Row swaps: use first column values
    row_vals = [board[i][0] for i in range(n)]
    row_swaps = min_swaps(row_vals)

    # Column swaps: use first row values
    col_vals = board[0]
    col_swaps = min_swaps(col_vals)

    return row_swaps + col_swaps

