def preimage_size_fzf(k):
    def find_trailing_zeroes(x):
        count = 0
        i = 5
        while x // i >= 1:
            count += x // i
            i *= 5
        return count

    left = 0
    right = 5 * k
    while left < right:
        mid = (left + right) // 2
        if find_trailing_zeroes(mid) < k:
            left = mid + 1
        elif find_trailing_zeroes(mid) > k:
            right = mid
        else:
            right = mid

    if find_trailing_zeroes(left) == k:
        if find_trailing_zeroes(left + 4) == k:
            return 5
        else:
            return 1
    else:
        return 0

