def rotated_digits(n: int) -> int:
    count = 0
    for i in range(1, n + 1):
        is_good = False
        is_valid = True
        rotated = 0
        temp = i
        base = 1
        while temp > 0:
            digit = temp % 10
            if digit == 3 or digit == 4 or digit == 7:
                is_valid = False
                break
            if digit == 0:
                rotated_digit = 0
            elif digit == 1:
                rotated_digit = 1
            elif digit == 6:
                rotated_digit = 9
            elif digit == 8:
                rotated_digit = 8
            elif digit == 9:
                rotated_digit = 6
            else:
                rotated_digit = 9
            if rotated_digit != digit:
                is_good = True
            rotated += rotated_digit * base
            base *= 10
            temp //= 10
        if is_valid and is_good:
            count += 1
    return count

