def champagne_tower(poured: float, query_row: int, query_glass: int) -> float:
    champagne = [[0.0] * (query_row + 1) for _ in range(query_row + 1)]
    champagne[0][0] = poured
    for row in range(query_row):
        for glass in range(row + 1):
            if champagne[row][glass] > 1:
                excess = (champagne[row][glass] - 1) / 2
                champagne[row + 1][glass] += excess
                champagne[row + 1][glass + 1] += excess
                champagne[row][glass] = 1
    return min(1, champagne[query_row][query_glass])

