def max_increase_keeping_skyline(grid: List[List[int]]) -> int:
    n = len(grid)
    row_max = [0] * n
    col_max = [0] * n
    for i in range(n):
        for j in range(n):
            val = grid[i][j]
            if val > row_max[i]:
                row_max[i] = val
            if val > col_max[j]:
                col_max[j] = val
    total = 0
    for i in range(n):
        for j in range(n):
            total += min(row_max[i], col_max[j]) - grid[i][j]
    return total

