def split_array_same_average(nums: list[int]) -> bool:
    total_sum = 0
    for i in range(len(nums)):
        total_sum += nums[i]

    n = len(nums)
    for size in range(1, n):
        if (total_sum * size) % n == 0:
            target_sum = (total_sum * size) // n
            bitmask_limit = (1 << n) - 1
            for mask in range(bitmask_limit + 1):
                # count bits
                cnt = 0
                m = mask
                while m:
                    cnt += m & 1
                    m >>= 1
                if cnt == size:
                    subset_sum = 0
                    for j in range(n):
                        if mask & (1 << j):
                            subset_sum += nums[j]
                    if subset_sum == target_sum:
                        return True
    return False

