def min_swap(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    if n == 0:
        return 0
    # keep: min swaps to make sequences increasing up to i without swapping at i
    # swap: min swaps to make sequences increasing up to i with swapping at i
    keep, swap = 0, 1
    for i in range(1, n):
        new_keep = new_swap = float('inf')
        # Case 1: no swap at i, and previous state also no swap
        if nums1[i] > nums1[i - 1] and nums2[i] > nums2[i - 1]:
            new_keep = min(new_keep, keep)
            new_swap = min(new_swap, swap + 1)
        # Case 2: swap at i, previous state no swap
        if nums1[i] > nums2[i - 1] and nums2[i] > nums1[i - 1]:
            new_keep = min(new_keep, swap)
            new_swap = min(new_swap, keep + 1)
        keep, swap = new_keep, new_swap
    return min(keep, swap)

