    result: List[int] = []

    def dfs(node: int) -> bool:
        if color[node] == 2:
            return True
        if color[node] == 1:
            return False
        color[node] = 1
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        color[node] = 2
        return True

    for i in range(len(graph)):
        if dfs(i):
            result.append(i)
    return result

