def hit_bricks(grid: List[List[int]], hits: List[List[int]]) -> List[int]:
    m, n = len(grid), len(grid[0])
    size = m * n + 1  # extra node for the ceiling
    top = m * n

    parent = list(range(size))
    sz = [1] * size

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if sz[rx] < sz[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        sz[rx] += sz[ry]

    def top_size() -> int:
        return sz[find(top)]

    # copy grid and apply all hits
    cur = [row[:] for row in grid]
    for r, c in hits:
        if 0 <= r < m and 0 <= c < n:
            cur[r][c] = 0

    # initial unions
    for i in range(m):
        for j in range(n):
            if cur[i][j] == 1:
                idx = i * n + j
                if i == 0:
                    union(idx, top)
                if i > 0 and cur[i - 1][j] == 1:
                    union(idx, (i - 1) * n + j)
                if j > 0 and cur[i][j - 1] == 1:
                    union(idx, i * n + (j - 1))

    res = [0] * len(hits)

    for k in range(len(hits) - 1, -1, -1):
        r, c = hits[k]
        if not (0 <= r < m and 0 <= c < n):
            continue
        if grid[r][c] == 0:
            # original cell was empty; nothing falls
            continue
        before = top_size()
        cur[r][c] = 1
        idx = r * n + c
        if r == 0:
            union(idx, top)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and cur[nr][nc] == 1:
                union(idx, nr * n + nc)
        after = top_size()
        fallen = after - before - 1
        res[k] = fallen if fallen > 0 else 0

    return res
# TIME: O(m*n + len(hits) * α(m*n)) SPACE: O(m*n)

import math

def soup_servings(n: int) -> float:
    n = math.ceil(n / 25)
    if n >= 179:
        return 1.0
    memo = [[0.0] * (n + 1) for _ in range(n + 1)]
    def dfs(a: int, b: int) -> float:
        if a <= 0 and b <= 0:
            return 0.5
        if a <= 0:
            return 1.0
        if b <= 0:
            return 0.0
        if memo[a][b] != 0.0:
            return memo[a][b]
        memo[a][b] = 0.25 * (
            dfs(a - 4, b) +
            dfs(a - 3, b - 1) +
            dfs(a - 2, b - 2) +
            dfs(a - 1, b - 3)
        )
        return memo[a][b]
    return dfs(n, n)

