def expressive_words(s: str, words: List[str]) -> int:
    def is_stretchy(word: str) -> bool:
        i = j = 0
        n, m = len(s), len(word)
        while i < n and j < m:
            if s[i] != word[j]:
                return False
            # count consecutive chars in s
            cnt_s = 0
            while i + cnt_s < n and s[i + cnt_s] == s[i]:
                cnt_s += 1
            # count consecutive chars in word
            cnt_w = 0
            while j + cnt_w < m and word[j + cnt_w] == word[j]:
                cnt_w += 1
            if cnt_s < cnt_w:
                return False
            if cnt_s < 3 and cnt_s != cnt_w:
                return False
            i += cnt_s
            j += cnt_w
        return i == n and j == m

    count = 0
    for w in words:
        if is_stretchy(w):
            count += 1
    return count

