def ambiguous_coordinates(s: str) -> List[str]:
    inner = s[1:-1]
    n = len(inner)
    result: List[str] = []

    def generate(num: str) -> List[str]:
        """Return all valid representations of a numeric string."""
        if len(num) == 1:
            return [num]
        reps: List[str] = []
        # integer without decimal point (no leading zero)
        if not (num[0] == '0' and len(num) > 1):
            reps.append(num)
        # insert decimal point at each possible position
        for i in range(1, len(num)):
            left, right = num[:i], num[i:]
            # left part must not have leading zeros unless it is exactly "0"
            if left[0] == '0' and len(left) > 1:
                continue
            # right part must not end with zero
            if right[-1] == '0':
                continue
            reps.append(f"{left}.{right}")
        return reps

    for i in range(1, n):
        left_part, right_part = inner[:i], inner[i:]
        left_opts = generate(left_part)
        right_opts = generate(right_part)
        for l in left_opts:
            for r in right_opts:
                result.append(f"({l}, {r})")
    result.sort()
    return result

