def largest_sum_of_averages(nums: List[int], k: int) -> float:
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]

    dp = [[-float('inf')] * (k + 1) for _ in range(n)]

    for i in range(n):
        dp[i][1] = prefix_sum[i + 1] / (i + 1)

    for j in range(2, k + 1):
        for i in range(j - 1, n):
            for x in range(j - 2, i):
                avg = (prefix_sum[i + 1] - prefix_sum[x + 1]) / (i - x)
                dp[i][j] = max(dp[i][j], dp[x][j - 1] + avg)

    return dp[n - 1][k]

def racecar(target: int) -> int:
    queue = [[0, 1, 0]]
    visited = set()
    while queue:
        position, speed, steps = queue.pop(0)
        if position == target:
            return steps
        key = f"{position},{speed}"
        if key in visited:
            continue
        visited.add(key)
        queue.append([position + speed, speed * 2, steps + 1])
        if (speed > 0 and position + speed > target) or (speed < 0 and position + speed < target):
            queue.append([position, -1, steps + 1])

