def flip_game(fronts: List[int], backs: List[int]) -> int:
    same = set()
    for i in range(len(fronts)):
        if fronts[i] == backs[i]:
            same.add(fronts[i])
    res = float('inf')
    for i in range(len(fronts)):
        if fronts[i] not in same and fronts[i] < res:
            res = fronts[i]
        if backs[i] not in same and backs[i] < res:
            res = backs[i]
    return 0 if res == float('inf') else res

