def num_factored_binary_trees(arr: List[int]) -> int:
    MOD = 10**9 + 7
    arr.sort()
    dp = {}
    result = 0
    for i in range(len(arr)):
        dp[arr[i]] = 1
        for j in range(i):
            if arr[i] % arr[j] == 0:
                other = arr[i] // arr[j]
                if other in dp:
                    dp[arr[i]] = (dp[arr[i]] + dp[arr[j]] * dp[other]) % MOD
        result = (result + dp[arr[i]]) % MOD
    return result

