def num_friend_requests(ages: List[int]) -> int:
    # Count frequency of each age (ages are between 1 and 120 inclusive)
    max_age = 120
    freq = [0] * (max_age + 1)
    for age in ages:
        if 0 <= age <= max_age:
            freq[age] += 1

    total_requests = 0
    # Ages less than 15 cannot send any requests (since 0.5*age+7 >= age)
    for a in range(15, max_age + 1):
        if freq[a] == 0:
            continue
        lower = int(0.5 * a + 7) + 1  # smallest age that can receive a request from age a
        for b in range(lower, a + 1):
            if freq[b] == 0:
                continue
            if a == b:
                # ordered pairs where i != j
                total_requests += freq[a] * (freq[a] - 1)
            else:
                total_requests += freq[a] * freq[b]
    return total_requests

def shortest_to_char(s: str, c: str) -> list[int]:
    res = [float('inf')] * len(s)
    prev = -float('inf')
    for i in range(len(s)):
        if s[i] == c:
            prev = i
            res[i] = 0
        elif prev != -float('inf'):
            res[i] = min(res[i], i - prev)
    nxt = float('inf')
    for i in range(len(s) - 1, -1, -1):
        if s[i] == c:
            nxt = i
        elif nxt != float('inf'):
            res[i] = min(res[i], nxt - i)
    return res

