def max_profit_assignment(difficulty: List[int], profit: List[int], worker: List[int]) -> int:
    jobs = [(diff, profit[i]) for i, diff in enumerate(difficulty)]
    jobs.sort(key=lambda x: x[0])
    n = len(jobs)
    max_profit = [0] * n
    max_profit[0] = jobs[0][1]
    for i in range(1, n):
        max_profit[i] = max(max_profit[i - 1], jobs[i][1])
    total_profit = 0
    for w in worker:
        left, right = 0, n - 1
        while left < right:
            mid = (left + right + 1) // 2
            if jobs[mid][0] <= w:
                left = mid
            else:
                right = mid - 1
        if jobs[left][0] <= w:
            total_profit += max_profit[left]
    return total_profit

