def largest_island(grid: List[List[int]]) -> int:
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    island_index = 2
    island_sizes = {}

    def dfs(i: int, j: int, index: int) -> int:
        if i < 0 or i >= n or j < 0 or j >= n or grid[i][j] != 1:
            return 0
        grid[i][j] = index
        size = 1
        for dx, dy in directions:
            size += dfs(i + dx, j + dy, index)
        return size

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                island_sizes[island_index] = dfs(i, j, island_index)
                island_index += 1

    max_size = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                seen = set()
                size = 1
                for dx, dy in directions:
                    x = i + dx
                    y = j + dy
                    if 0 <= x < n and 0 <= y < n and grid[x][y] > 1 and grid[x][y] not in seen:
                        size += island_sizes[grid[x][y]]
                        seen.add(grid[x][y])
                if size > max_size:
                    max_size = size

    if max_size == 0:
        return max(island_sizes.values()) if island_sizes else 0
    return max_size

