def push_dominoes(dominoes: str) -> str:
    n = len(dominoes)
    result = ['.'] * n
    force = [0] * n
    f = 0
    for i in range(n):
        if dominoes[i] == 'R':
            f = n
        elif dominoes[i] == 'L':
            f = 0
        else:
            f = max(f - 1, 0)
        force[i] += f
    f = 0
    for i in range(n - 1, -1, -1):
        if dominoes[i] == 'L':
            f = n
        elif dominoes[i] == 'R':
            f = 0
        else:
            f = max(f - 1, 0)
        force[i] -= f
    for i in range(n):
        if force[i] > 0:
            result[i] = 'R'
        elif force[i] < 0:
            result[i] = 'L'
    return ''.join(result)

def new21_game(n: int, k: int, max_pts: int) -> float:
    # If Alice stops immediately or can never exceed n, probability is 1
    if k == 0 or n >= k + max_pts - 1:
        return 1.0

    dp = [0.0] * (n + 1)
    dp[0] = 1.0
    window_sum = 1.0  # sum of probabilities of the last `max_pts` states

    for i in range(1, n + 1):
        dp[i] = window_sum / max_pts
        if i < k:
            window_sum += dp[i]
        if i - max_pts >= 0:
            window_sum -= dp[i - max_pts]

    result = sum(dp[k : n + 1])
    return round(result, 5)

