def sum_of_distances_in_tree(n: int, edges: List[List[int]]) -> List[int]:
    graph: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    count: List[int] = [1] * n          # size of subtree rooted at each node
    answer: List[int] = [0] * n        # sum of distances from each node

    def dfs(node: int, parent: int) -> None:
        for child in graph[node]:
            if child == parent:
                continue
            dfs(child, node)
            count[node] += count[child]
            answer[node] += answer[child] + count[child]

    def dfs2(node: int, parent: int) -> None:
        for child in graph[node]:
            if child == parent:
                continue
            # move root from node to child
            answer[child] = answer[node] - count[child] + (n - count[child])
            dfs2(child, node)

    dfs(0, -1)
    dfs2(0, -1)
    return answer

