def num_similar_groups(strs: List[str]) -> int:
    parent = [i for i in range(len(strs))]

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_x] = root_y

    def is_similar(s1: str, s2: str) -> bool:
        count = 0
        for i in range(len(s1)):
            if s1[i] != s2[i]:
                count += 1
                if count > 2:
                    return False
        return count == 0 or count == 2

    n = len(strs)
