def is_magic_square(grid: List[List[int]], r: int, c: int) -> bool:
    if grid[r + 1][c + 1] != 5:
        return False
    if (grid[r][c] % 2 == 1 or grid[r][c + 2] % 2 == 1 or
        grid[r + 2][c] % 2 == 1 or grid[r + 2][c + 2] % 2 == 1):
        return False
    if (grid[r][c + 1] % 2 == 0 or grid[r + 1][c] % 2 == 0 or
        grid[r + 1][c + 2] % 2 == 0 or grid[r + 2][c + 1] % 2 == 0):
        return False
    seen = [False] * 10
    for i in range(r, r + 3):
        for j in range(c, c + 3):
            val = grid[i][j]
            if val < 1 or val > 9 or seen[val]:
                return False
            seen[val] = True
    s = grid[r][c] + grid[r][c + 1] + grid[r][c + 2]
    for i in range(r, r + 3):
        if grid[i][c] + grid[i][c + 1] + grid[i][c + 2] != s:
            return False
    for j in range(c, c + 3):
        if grid[r][j] + grid[r + 1][j] + grid[r + 2][j] != s:
            return False
    if grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2] != s:
        return False
    if grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c] != s:
        return False
    return True

