def split_into_fibonacci(num: str) -> List[int]:
    def is_fibonacci(arr: List[str]) -> bool:
        for i in range(2, len(arr)):
            if int(arr[i - 2]) + int(arr[i - 1]) != int(arr[i]):
                return False
        return True

    def backtrack(start: int, path: List[str]) -> Optional[List[str]]:
        if start == len(num) and len(path) >= 3 and is_fibonacci(path):
            return path
        for i in range(start, len(num)):
            if i > start and num[start] == '0':
                break
            curr = num[start:i + 1]
            if int(curr) > 2 ** 31 - 1:
                break
            result = backtrack(i + 1, path + [curr])
            if result:
                return result
        return None

    result = backtrack(0, [])
    return [int(x) for x in result] if result else []

