def backspace_compare(s: str, t: str) -> bool:
    i, j = len(s) - 1, len(t) - 1
    back_s = back_t = 0
    while i >= 0 or j >= 0:
        while i >= 0:
            if s[i] == '#':
                back_s += 1
                i -= 1
            elif back_s > 0:
                back_s -= 1
                i -= 1
            else:
                break
        while j >= 0:
            if t[j] == '#':
                back_t += 1
                j -= 1
            elif back_t > 0:
                back_t -= 1
                j -= 1
            else:
                break
        if i < 0 and j < 0:
            return True
        if i < 0 or j < 0:
            return False
        if s[i] != t[j]:
            return False
        i -= 1
        j -= 1
    return True

