def mirror_reflection(p: int, q: int) -> int:
    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    g = gcd(p, q)
    p //= g
    q //= g

    if p % 2 == 0 and q % 2 == 1:
        return 2
    if p % 2 == 1 and q % 2 == 1:
        return 1
    if p % 2 == 1 and q % 2 == 0:
        return 0
    return 0
# TIME: O(log(min(p,q))) SPACE: O(1)

