def subtree_with_all_deepest(root: Optional["TreeNode"]) -> Optional["TreeNode"]:
    def dfs(node: Optional["TreeNode"]) -> int:
        if not node:
            return 0
        return 1 + max(dfs(node.left), dfs(node.right))

    def find_lca(node: Optional["TreeNode"], depth: int) -> Optional["TreeNode"]:
        if not node:
            return None
        if depth == 0:
            return node
        left_depth = dfs(node.left)
        right_depth = dfs(node.right)
        if left_depth == right_depth:
            return node
        if left_depth > right_depth:
            return find_lca(node.left, depth - 1)
        return find_lca(node.right, depth - 1)

    max_depth = dfs(root)
    return find_lca(root, max_depth - 1)

