def distance_k(root, target, k):
    parent_map = {}
    def dfs(node, parent):
        if not node:
            return
        parent_map[node.val] = parent
        dfs(node.left, node)
        dfs(node.right, node)
    dfs(root, None)
    queue = deque([(target, 0)])
    visited = {target.val}
    result = []
    while queue:
        node, distance = queue.popleft()
        if distance == k:
            result.append(node.val)
        if distance > k:
            break
        neighbors = [node.left, node.right, parent_map.get(node.val)]
        for neighbor in neighbors:
            if neighbor and neighbor.val not in visited:
                visited.add(neighbor.val)
                queue.append((neighbor, distance + 1))
    return result

