def construct_from_pre_post(preorder, postorder):
    post_index_map = {value: i for i, value in enumerate(postorder)}
    def construct(pre_start, pre_end, post_start, post_end):
        if pre_start > pre_end:
            return None
        root = TreeNode(preorder[pre_start])
        if pre_start + 1 > pre_end:
            return root
        left_child_post_index = post_index_map[preorder[pre_start + 1]]
        left_subtree_size = left_child_post_index - post_start + 1
        root.left = construct(pre_start + 1, pre_start + left_subtree_size, post_start, left_child_post_index)
        root.right = construct(pre_start + left_subtree_size + 1, pre_end, left_child_post_index + 1, post_end - 1)
        return root
    return construct(0, len(preorder) - 1, 0, len(postorder) - 1)

