class FreqStack:
    def __init__(self):
        self.frequency_map = {}
        self.frequency_stacks = {}
        self.max_frequency = 0
    def push(self, x: int) -> None:
        self.frequency_map[x] = self.frequency_map.get(x, 0) + 1
        freq = self.frequency_map[x]
        self.max_frequency = max(self.max_frequency, freq)
        self.frequency_stacks.setdefault(freq, []).append(x)
    def pop(self) -> int:
        stack = self.frequency_stacks[self.max_frequency]
        result = stack.pop()
        self.frequency_map[result] -= 1
        if not stack:
            self.max_frequency -= 1
        return result

