def snakes_and_ladders(board: List[List[int]]) -> int:
    n = len(board)

    def cell_to_pos(cell: int) -> tuple[int, int]:
        """Convert 1‑based cell number to board coordinates (row, col)."""
        quot, rem = divmod(cell - 1, n)
        row = n - 1 - quot
        col = rem if quot % 2 == 0 else n - 1 - rem
        return row, col

    queue = deque([(1, 0)])          # (cell number, moves taken)
    visited = {1}

    while queue:
        cur, moves = queue.popleft()
        if cur == n * n:
            return moves
        for dice in range(1, 7):
            nxt = cur + dice
            if nxt > n * n:
                continue
            r, c = cell_to_pos(nxt)
            if board[r][c] != -1:
                nxt = board[r][c]
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, moves + 1))
    return -1

