def is_n_straight_hand(deck: List[int]) -> bool:
    count_map = {}
    for card in deck:
        if card in count_map:
            count_map[card] += 1
        else:
            count_map[card] = 1

    sorted_cards = sorted(count_map.keys())

    for card in sorted_cards:
        if count_map.get(card, 0) > 0:
            count = count_map[card]
            for j in range(card, card + count):
                if count_map.get(j, 0) < count:
                    return False
                count_map[j] -= count
    return True

