class TopVotedCandidate:
    def __init__(self, persons, times):
        self.times = times
        self.leaders = []
        counts = {}
        leader, max_count = -1, 0
        for p in persons:
            counts[p] = counts.get(p, 0) + 1
            if counts[p] >= max_count:
                max_count = counts[p]
                leader = p
            self.leaders.append(leader)
    def q(self, t: int) -> int:
        left, right = 0, len(self.times) - 1
        while left < right:
            mid = (left + right + 1) // 2
            if self.times[mid] <= t: left = mid
            else: right = mid - 1
        return self.leaders[left]

