def cat_mouse_game(graph: List[List[int]]) -> int:
    n = len(graph)
    # result[mouse][cat][turn] = 0 (draw), 1 (mouse wins), 2 (cat wins)
    result = [[[0, 0] for _ in range(n)] for _ in range(n)]
    # degree[mouse][cat][turn] = number of moves available from this state
    degree = [[[0, 0] for _ in range(n)] for _ in range(n)]

    for m in range(n):
        for c in range(n):
            degree[m][c][0] = len(graph[m])                     # mouse turn
            degree[m][c][1] = sum(1 for nxt in graph[c] if nxt != 0)  # cat cannot go to 0

    q = deque()
    # terminal states
    for m in range(n):
        for c in range(n):
            if m == 0:
                result[m][c][0] = result[m][c][1] = 1
                q.append((m, c, 0))
                q.append((m, c, 1))
            elif m == c:
                result[m][c][0] = result[m][c][1] = 2
                q.append((m, c, 0))
                q.append((m, c, 1))

    while q:
        mouse, cat, turn = q.popleft()
        cur_res = result[mouse][cat][turn]

        if turn == 0:  # current state was after mouse moved, so previous turn was cat
            prev_turn = 1
            for prev_cat in graph[cat]:
                if prev_cat == 0:
                    continue
                if result[mouse][prev_cat][prev_turn] != 0:
                    continue
                if cur_res == 2:  # cat can force a win
                    result[mouse][prev_cat][prev_turn] = 2
                    q.append((mouse, prev_cat, prev_turn))
                else:
                    degree[mouse][prev_cat][prev_turn] -= 1
                    if degree[mouse][prev_cat][prev_turn] == 0:
                        result[mouse][prev_cat][prev_turn] = 1
                        q.append((mouse, prev_cat, prev_turn))
        else:  # turn == 1, current state was after cat moved, previous turn was mouse
            prev_turn = 0
            for prev_mouse in graph[mouse]:
                if result[prev_mouse][cat][prev_turn] != 0:
                    continue
                if cur_res == 1:  # mouse can force a win
                    result[prev_mouse][cat][prev_turn] = 1
                    q.append((prev_mouse, cat, prev_turn))
                else:
                    degree[prev_mouse][cat][prev_turn] -= 1
                    if degree[prev_mouse][cat][prev_turn] == 0:
                        result[prev_mouse][cat][prev_turn] = 2
                        q.append((prev_mouse, cat, prev_turn))

    return result[1][2][0]  # start: mouse at 1, cat at 2, mouse's turn

