def min_malware_spread(graph: List[List[int]], initial: List[int]) -> int:
    n = len(graph)
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    for i in range(n):
        for j in range(n):
            if graph[i][j] == 1:
                union(i, j)

    group_size = {}
    for i in range(n):
        root = find(i)
        group_size[root] = group_size.get(root, 0) + 1

    infected_count = {}
    for node in initial:
        root = find(node)
        infected_count[root] = infected_count.get(root, 0) + 1

    min_size = float('inf')
    node_to_remove = -1
    for node in initial:
        root = find(node)
        if infected_count.get(root, 0) == 1:
            size = group_size[root]
            if size < min_size:
                min_size = size
                node_to_remove = node
            elif size == min_size and node < node_to_remove:
                node_to_remove = node

    if min_size == float('inf'):
        return min(initial)
    return node_to_remove

