def min_malware_spread(graph: List[List[int]], initial: List[int]) -> int:
    n = len(graph)
    # adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j, val in enumerate(graph[i]):
            if val:
                adj[i].append(j)

    infected_set = set(initial)
    best_node = min(initial)
    max_saved = -1

    for node in initial:
        visited = [False] * n
        stack = [node]
        visited[node] = True
        saved = 0

        while stack:
            cur = stack.pop()
            for nb in adj[cur]:
                if visited[nb]:
                    continue
                # stop traversal when reaching another initially infected node
                if nb in infected_set and nb != node:
                    continue
                visited[nb] = True
                stack.append(nb)
                saved += 1

        if saved > max_saved or (saved == max_saved and node < best_node):
            max_saved = saved
            best_node = node

    return best_node
