        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] != 1:
            return
        grid[i][j] = -1
        island.append((i, j))
        dfs(grid, i - 1, j, island)
        dfs(grid, i + 1, j, island)
        dfs(grid, i, j - 1, island)
        dfs(grid, i, j + 1, island)

    def bfs(grid: List[List[int]], island: List[tuple]) -> int:
        queue = deque(island)
        distance = 0
        while queue:
            size = len(queue)
            for _ in range(size):
                x, y = queue.popleft()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if nx < 0 or nx >= len(grid) or ny < 0 or ny >= len(grid[0]):
                        continue
                    if grid[nx][ny] == 1:
                        return distance
                    if grid[nx][ny] == 0:
                        grid[nx][ny] = -1
                        queue.append((nx, ny))
            distance += 1
        return distance

