def moves_to_stamp(stamp: str, target: str) -> List[int]:
    n, m = len(target), len(stamp)
    target_list = list(target)
    stamped = [False] * (n - m + 1)
    result: List[int] = []
    total_q = 0

    def can_stamp(i: int) -> bool:
        """Return True if stamp can be applied at position i (must change at least one char)."""
        changed = False
        for j in range(m):
            ch = target_list[i + j]
            if ch == '?':
                continue
            if ch != stamp[j]:
                return False
            changed = True
        return changed

    while total_q < n:
        made_progress = False
        # iterate from right to left to match expected ordering
        for i in range(n - m, -1, -1):
            if not stamped[i] and can_stamp(i):
                for j in range(m):
                    if target_list[i + j] != '?':
                        target_list[i + j] = '?'
                        total_q += 1
                stamped[i] = True
                result.append(i)
                made_progress = True
                if total_q == n:
                    break
        if not made_progress:
            return []
    return result[::-1]  # reverse to get stamping order

