def shortest_superstring(words: List[str]) -> str:
    n = len(words)
    if n == 0:
        return ""
    # compute pairwise overlaps
    overlap = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            max_k = min(len(words[i]), len(words[j]))
            for k in range(max_k, 0, -1):
                if words[i][-k:] == words[j][:k]:
                    overlap[i][j] = k
                    break
    # dp[mask][i] = (superstring, path tuple) for set mask ending with i
    dp: List[List[Optional[Tuple[str, Tuple[int, ...]]]]] = [[None] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = (words[i], (i,))
    for mask in range(1, 1 << n):
        for i in range(n):
            if not (mask >> i) & 1:
                continue
            prev_mask = mask ^ (1 << i)
            if prev_mask == 0:
                continue
            best_candidate: Optional[Tuple[str, Tuple[int, ...]]] = None
            for j in range(n):
                if not (prev_mask >> j) & 1:
                    continue
                prev_entry = dp[prev_mask][j]
                if prev_entry is None:
                    continue
                cand_str = prev_entry[0] + words[i][overlap[j][i]:]
                cand_path = prev_entry[1] + (i,)
                cand = (cand_str, cand_path)
                if best_candidate is None:
                    best_candidate = cand
                else:
                    cur_str, cur_path = best_candidate
                    if len(cand_str) < len(cur_str):
                        best_candidate = cand
                    elif len(cand_str) == len(cur_str) and cand_path < cur_path:
                        best_candidate = cand
            dp[mask][i] = best_candidate
    full_mask = (1 << n) - 1
    best: Optional[Tuple[str, Tuple[int, ...]]] = None
    for i in range(n):
        entry = dp[full_mask][i]
        if entry is None:
            continue
        if best is None:
            best = entry
        else:
