def remove_stones(stones: list[list[int]]) -> int:
    parent = [i for i in range(len(stones))]
    rank = [0] * len(stones)

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        rootx = find(x)
        rooty = find(y)
        if rootx == rooty:
            return
        if rank[rootx] < rank[rooty]:
            parent[rootx] = rooty
        elif rank[rootx] > rank[rooty]:
            parent[rooty] = rootx
        else:
            parent[rooty] = rootx
            rank[rootx] += 1

    n = len(stones)
    for i in range(n):
        for j in range(i + 1, n):
            if stones[i][0] == stones[j][0] or stones[i][1] == stones[j][1]:
                union(i, j)

    count = sum(1 for i in range(n) if parent[i] == i)
    return n - count

