def largest_component_size(nums: List[int]) -> int:
    def get_prime_factors(n: int) -> List[int]:
        factors: List[int] = []
        d = 2
        while d * d <= n:
            if n % d == 0:
                factors.append(d)
                while n % d == 0:
                    n //= d
            d += 1 if d == 2 else 2
        if n > 1:
            factors.append(n)
        return factors

    parent: List[int] = list(range(len(nums)))
    size: List[int] = [1] * len(nums)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]

    factor_to_index: Dict[int, int] = {}
    for i, num in enumerate(nums):
        for f in get_prime_factors(num):
            if f in factor_to_index:
                union(i, factor_to_index[f])
            else:
                factor_to_index[f] = i

    max_comp = 0
    for i in range(len(nums)):
        if parent[i] == i:  # root
            max_comp = max(max_comp, size[i])
    return max_comp
# TIME: O(N * sqrt(M)) SPACE: O(N + P)

