    n = len(strs)
    m = len(strs[0])
    delete_cnt = 0
    sorted_pair = [False] * (n - 1)  # sorted_pair[i] means strs[i] < strs[i+1] already determined

    for col in range(m):
        # Check if this column can be kept
        need_delete = False
        for i in range(n - 1):
            if not sorted_pair[i] and strs[i][col] > strs[i + 1][col]:
                need_delete = True
                break
