                new_grid[i * 3 + 2][j * 3 + 2] = 1
    count = 0
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(start_i: int, start_j: int) -> None:
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if 0 <= i < size and 0 <= j < size and new_grid[i][j] == 0:
                new_grid[i][j] = 1
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < size and 0 <= nj < size and new_grid[ni][nj] == 0:
                        stack.append((ni, nj))

    for i in range(size):
        for j in range(size):
            if new_grid[i][j] == 0:
                dfs(i, j)
                count += 1
    return count

