    vowel_map = {}
    for word in wordlist:
        lower_case_word = word.lower()
        if lower_case_word not in lower_case_map:
            lower_case_map[lower_case_word] = word
        vowel_ignored_word = (
            lower_case_word.replace('a', '*')
            .replace('e', '*')
            .replace('i', '*')
            .replace('o', '*')
            .replace('u', '*')
        )
        if vowel_ignored_word not in vowel_map:
            vowel_map[vowel_ignored_word] = word
    result = []
    for query in queries:
        if query in word_set:
            result.append(query)
        else:
            lower_case_query = query.lower()
            if lower_case_query in lower_case_map:
                result.append(lower_case_map[lower_case_query])
            else:
                vowel_ignored_query = (
                    lower_case_query.replace('a', '*')
                    .replace('e', '*')
                    .replace('i', '*')
                    .replace('o', '*')
                    .replace('u', '*')
                )
                if vowel_ignored_query in vowel_map:
                    result.append(vowel_map[vowel_ignored_query])
                else:
