def nums_same_consec_diff(n: int, k: int) -> List[int]:
    if n == 1:
        return list(range(10))

    result: List[int] = []

    def backtrack(cur: int, last: int, length: int) -> None:
        if length == n:
            result.append(cur)
            return
        low = last - k
        high = last + k
        # add candidates in increasing order
        if low >= 0:
            backtrack(cur * 10 + low, low, length + 1)
        if k != 0 and high <= 9:
            backtrack(cur * 10 + high, high, length + 1)

    for i in range(1, 10):
        backtrack(i, i, 1)

    return result

