def odd_even_jumps(arr: List[int]) -> int:
    n = len(arr)
    if n == 0:
        return 0
    next_higher = [-1] * n
    next_lower = [-1] * n

    # compute next higher jumps
    sorted_idx = sorted(range(n), key=lambda i: (arr[i], i))
    stack: List[int] = []
    for idx in sorted_idx:
        while stack and idx > stack[-1]:
            prev = stack.pop()
            next_higher[prev] = idx
        stack.append(idx)

    # compute next lower jumps
    sorted_idx = sorted(range(n), key=lambda i: (-arr[i], i))
    stack.clear()
    for idx in sorted_idx:
        while stack and idx > stack[-1]:
            prev = stack.pop()
            next_lower[prev] = idx
        stack.append(idx)

    higher = [False] * n
    lower = [False] * n
    higher[-1] = lower[-1] = True

    for i in range(n - 2, -1, -1):
        if next_higher[i] != -1:
            higher[i] = lower[next_higher[i]]
        if next_lower[i] != -1:
            lower[i] = higher[next_lower[i]]

    return sum(higher)

class TimeMap:
    def __init__(self):
        self.store = {}
    def set(self, key: str, value: str, timestamp: int) -> None:
        self.store.setdefault(key, []).append((timestamp, value))
    def get(self, key: str, timestamp: int) -> str:
        if key not in self.store: return ""
        arr = self.store[key]
        lo, hi = 0, len(arr) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid][0] <= timestamp: lo = mid + 1
            else: hi = mid - 1
        return arr[hi][1] if hi >= 0 else ""

