def unique_paths_iii(grid: List[List[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    total = 0
    start = end = None

    for i in range(rows):
        for j in range(cols):
            cell = grid[i][j]
            if cell != -1:
                total += 1
            if cell == 1:
                start = (i, j)
            elif cell == 2:
                end = (i, j)

    if start is None or end is None:
        return 0

    ans = 0
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(x: int, y: int, visited: int) -> None:
        nonlocal ans
        if (x, y) == end:
            if visited == total:
                ans += 1
            return

        # mark current as obstacle to avoid revisiting
        cur_val = grid[x][y]
        grid[x][y] = -1

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != -1:
                dfs(nx, ny, visited + 1)

        grid[x][y] = cur_val  # backtrack

    dfs(start[0], start[1], 1)
    return ans
# TIME: O(4^k) where k is the number of non‑obstacle squares SPACE: O(k) recursion depth where k ≤ 20

