        if a > 0 and not (len(result) >= 2 and result[-1] == result[-2] == "a"):
            result.append("a")
            a -= 1
        # otherwise try to place 'b' if it doesn't create three consecutive 'b's
        elif b > 0 and not (len(result) >= 2 and result[-1] == result[-2] == "b"):
            result.append("b")
            b -= 1
        # if both would create three in a row, place the remaining character (input guarantees this won't happen)
