def vertical_traversal(root):
    if not root:
        return []
    column_table = {}
    min_column = max_column = 0
    queue = deque([(root, 0)])
    while queue:
        size = len(queue)
        temp = {}
        for _ in range(size):
            node, column = queue.popleft()
            min_column = min(min_column, column)
            max_column = max(max_column, column)
            temp.setdefault(column, []).append(node.val)
            if node.left:
                queue.append((node.left, column - 1))
            if node.right:
                queue.append((node.right, column + 1))
        for column, vals in temp.items():
            column_table.setdefault(column, []).extend(sorted(vals))
    result = []
    for i in range(min_column, max_column + 1):
        result.append(column_table.get(i, []))
    return result

