    uniq = list(cnt.keys())

    # precompute which numbers can follow each other
    adj = {x: [] for x in uniq}
    for a in uniq:
        for b in uniq:
            if a == b and cnt[a] < 2:
                continue
            s = a + b
            r = int(math.isqrt(s))
            if r * r == s:
                adj[a].append(b)

    total = 0

    def backtrack(prev: int, remaining: int) -> None:
        nonlocal total
        if remaining == 0:
            total += 1
            return
        for nxt in adj[prev]:
            if cnt[nxt] > 0:
                cnt[nxt] -= 1
                backtrack(nxt, remaining - 1)
                cnt[nxt] += 1

    for start in uniq:
        cnt[start] -= 1
        backtrack(start, n - 1)
        cnt[start] += 1

    return total

