        return 0
    cols = len(board[0])
    rook_row = rook_col = -1
    for i in range(rows):
        for j in range(cols):
            if board[i][j] == 'R':
                rook_row, rook_col = i, j
                break
        if rook_row != -1:
            break
    if rook_row == -1:
        return 0
    count = 0
    # up
    for i in range(rook_row - 1, -1, -1):
        cell = board[i][rook_col]
        if cell == 'p':
            count += 1
            break
        if cell != '.':
            break
    # down
    for i in range(rook_row + 1, rows):
        cell = board[i][rook_col]
        if cell == 'p':
            count += 1
            break
        if cell != '.':
            break
    # left
    for j in range(rook_col - 1, -1, -1):
        cell = board[rook_row][j]
        if cell == 'p':
            count += 1
            break
        if cell != '.':
            break
    # right
    for j in range(rook_col + 1, cols):
        cell = board[rook_row][j]
        if cell == 'p':
            count += 1
            break
        if cell != '.':
            break
    return count

