def oranges_rotting(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    fresh_oranges = 0
    queue = deque()
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                fresh_oranges += 1
            elif grid[i][j] == 2:
                queue.append((i, j))
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    minutes = 0
    while queue and fresh_oranges > 0:
        minutes += 1
        size = len(queue)
        for _ in range(size):
            x0, y0 = queue.popleft()
            for dx, dy in directions:
                x = x0 + dx
                y = y0 + dy
                if 0 <= x < rows and 0 <= y < cols and grid[x][y] == 1:
                    grid[x][y] = 2
                    fresh_oranges -= 1
                    queue.append((x, y))
    if fresh_oranges > 0:
        return -1
    return minutes

