def merge_stones(stones: List[int], k: int) -> int:
    n = len(stones)
    # feasibility check
    if (n - 1) % (k - 1) != 0:
        return -1

    # prefix sums for quick range sum
    pref = [0] * (n + 1)
    for i, v in enumerate(stones):
        pref[i + 1] = pref[i] + v

    def range_sum(l: int, r: int) -> int:
        return pref[r + 1] - pref[l]

    INF = 10 ** 9
    # dp[i][j][m] = min cost to merge stones[i..j] into m piles (1 <= m <= k)
    dp = [[[INF] * (k + 1) for _ in range(n)] for __ in range(n)]
    for i in range(n):
        dp[i][i][1] = 0

    # length of interval
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            # compute dp[i][j][m] for m = 2..k
            for m in range(2, k + 1):
                # split into left part that can become 1 pile and right part that becomes m-1 piles
                for mid in range(i, j):
                    left_len = mid - i + 1
                    # left part must be mergeable into 1 pile
                    if (left_len - 1) % (k - 1) != 0:
                        continue
                    if dp[i][mid][1] == INF or dp[mid + 1][j][m - 1] == INF:
                        continue
                    dp[i][j][m] = min(dp[i][j][m],
                                      dp[i][mid][1] + dp[mid + 1][j][m - 1])
            # after we have k piles we can merge them into one pile (if allowed)
            if (length - 1) % (k - 1) == 0:
                if dp[i][j][k] < INF:
                    dp[i][j][1] = dp[i][j][k] + range_sum(i, j)

    ans = dp[0][n - 1][1]
    return ans if ans < INF else -1

