def longest_duplicate_substring(s: str) -> str:
    n = len(s)
    if n <= 1:
        return ""
    base = 256
    mod = (1 << 61) - 1

    def search(L: int) -> int:
        if L == 0:
            return 0
        power = pow(base, L, mod)
        cur = 0
        for i in range(L):
            cur = (cur * base + ord(s[i])) % mod
        seen = {cur: 0}
        for start in range(1, n - L + 1):
            cur = (cur * base - ord(s[start - 1]) * power + ord(s[start + L - 1])) % mod
            if cur in seen:
                prev = seen[cur]
                if s[prev:prev + L] == s[start:start + L]:
                    return start
            else:
                seen[cur] = start
        return -1

    left, right = 1, n - 1
    best_len = 0
    best_start = 0
    while left <= right:
        mid = (left + right) // 2
        idx = search(mid)
        if idx != -1:
            best_len = mid
            best_start = idx
            left = mid + 1
        else:
            right = mid - 1
    return s[best_start:best_start + best_len] if best_len else ""

