    def find(x: str) -> str:
        idx = ord(x) - ord('a')
        if parent[idx] != x:
            parent[idx] = find(parent[idx])
        return parent[idx]

    def union(x: str, y: str) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x > root_y:
            parent[ord(root_x) - ord('a')] = root_y
        else:
            parent[ord(root_y) - ord('a')] = root_x

