def num_submatrix_sum_target(matrix: List[List[int]], target: int) -> int:
    count = 0
    rows = len(matrix)
    cols = len(matrix[0])
    prefix_sum = [[0] * (cols + 1) for _ in range(rows + 1)]
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            prefix_sum[i][j] = (
                prefix_sum[i - 1][j]
                + prefix_sum[i][j - 1]
                - prefix_sum[i - 1][j - 1]
                + matrix[i - 1][j - 1]
            )
    for x1 in range(rows):
        for y1 in range(cols):
            for x2 in range(x1, rows):
                for y2 in range(y1, cols):
                    s = (
                        prefix_sum[x2 + 1][y2 + 1]
                        - prefix_sum[x2 + 1][y1]
                        - prefix_sum[x1][y2 + 1]
                        + prefix_sum[x1][y1]
                    )
                    if s == target:
                        count += 1
    return count

def num_tile_possibilities(tiles: str) -> int:
    count = 0
    frequency = {}
    for ch in tiles:
        if ch in frequency:
            frequency[ch] += 1
        else:
            frequency[ch] = 1
    def backtrack():
        nonlocal count
        for tile in frequency:
            if frequency[tile] > 0:
                count += 1
                frequency[tile] -= 1
                backtrack()
                frequency[tile] += 1
    backtrack()
    return count

def smallest_subsequence(s: str) -> str:
    seen = set()
    stack = []
    last_occurrence = {}
    for i in range(len(s)):
        last_occurrence[s[i]] = i
    for i in range(len(s)):
        if s[i] in seen:
            continue
        while stack and stack[-1] > s[i] and last_occurrence[stack[-1]] > i:
            seen.remove(stack.pop())
        stack.append(s[i])
        seen.add(s[i])
    return ''.join(stack)

