    for i in range(len(trips)):
        locations.append((trips[i][1], trips[i][0]))
        locations.append((trips[i][2], -trips[i][0]))
    locations.sort(key=lambda x: (x[0], x[1]))
    current = 0
    for _, delta in locations:
        current += delta
        if current > capacity:
            return False
    return True

def find_in_mountain_array(target, mountain_arr):
    # mountain_arr only exposes .get(index) and .length() (the real judge interface) --
    # NOT list indexing / len(), which the previous version incorrectly relied on
    left, right = 0, mountain_arr.length() - 1
    while left < right:
        mid = (left + right) // 2
        if mountain_arr.get(mid) < mountain_arr.get(mid + 1):
            left = mid + 1
        else:
            right = mid
    peak = left

    left, right = 0, peak
    while left <= right:
        mid = (left + right) // 2
        if mountain_arr.get(mid) == target:
            return mid
        elif mountain_arr.get(mid) < target:
            left = mid + 1
        else:
            right = mid - 1

    left, right = peak, mountain_arr.length() - 1
    while left <= right:
        mid = (left + right) // 2
        if mountain_arr.get(mid) == target:
            return mid
        elif mountain_arr.get(mid) < target:
            right = mid - 1
        else:
            left = mid + 1

    return -1

