def brace_expansion_ii(expression: str) -> List[str]:
    n = len(expression)

    def parse(i: int) -> (set, int):
        # Parse a sequence of factors concatenated together until a closing brace or comma.
        cur = {""}
        while i < n and expression[i] not in ('}', ','):
            if expression[i] == '{':
                sub, i = parse_brace(i)
            else:
                sub = {expression[i]}
                i += 1
            cur = {a + b for a in cur for b in sub}
        return cur, i

    def parse_brace(i: int) -> (set, int):
        # i points to '{'
        i += 1  # skip '{'
        parts = []
        while True:
            part, i = parse(i)
            parts.append(part)
            if i < n and expression[i] == ',':
                i += 1  # skip ','
                continue
            break
        # i should be at '}'
        i += 1  # skip '}'
        union = set()
        for p in parts:
            union |= p
        return union, i

    result_set, _ = parse(0)
    return sorted(result_set)

