def parse_bool_expr(expression: str) -> bool:
    def eval_expr(expr: str) -> bool:
        if len(expr) == 1:
            return expr == 't'
        op = expr[0]
        # extract inner part without outermost parentheses
        inner = expr[2:-1]
        operands: List[str] = []
        depth = 0
        cur = ''
        for ch in inner:
            if ch == '(':
                depth += 1
                cur += ch
            elif ch == ')':
                depth -= 1
                cur += ch
            elif ch == ',' and depth == 0:
                operands.append(cur)
                cur = ''
            else:
                cur += ch
        operands.append(cur)

        if op == '!':
            return not eval_expr(operands[0])
        if op == '&':
            for sub in operands:
                if not eval_expr(sub):
                    return False
            return True
        if op == '|':
            for sub in operands:
                if eval_expr(sub):
                    return True
            return False
        # Should never reach here
        raise ValueError(f'Invalid operator: {op}')

    return eval_expr(expression)

