def smallest_sufficient_team(req_skills, people):
    skill_to_bit = {}
    for i, skill in enumerate(req_skills):
        skill_to_bit[skill] = 1 << i

    person_skills = []
    for person in people:
        mask = 0
        for skill in person:
            mask |= skill_to_bit[skill]
        person_skills.append(mask)

    n = len(req_skills)
    dp = [None] * (1 << n)
    dp[0] = []

    for i, p_mask in enumerate(person_skills):
        for j in range((1 << n) - 1, -1, -1):
            if dp[j] is not None:
                new_mask = j | p_mask
                if dp[new_mask] is None or len(dp[j]) + 1 < len(dp[new_mask]):
                    dp[new_mask] = dp[j] + [i]

    return dp[(1 << n) - 1]

