        return 0
    if n == 1 or n == 2:
        return 1
    a, b, c = 0, 1, 1
    for i in range(3, n + 1):
        temp = a + b + c
        a = b
        b = c
        c = temp
    return c

def alphabet_board_path(target: str) -> str:
    result = []
    cur_row, cur_col = 0, 0

    for ch in target:
        idx = ord(ch) - ord('a')
        tgt_row, tgt_col = divmod(idx, 5)

        # move up first, then left, then down, then right
        while cur_row > tgt_row:
            result.append('U')
            cur_row -= 1
        while cur_col > tgt_col:
            result.append('L')
            cur_col -= 1
        while cur_row < tgt_row:
            result.append('D')
            cur_row += 1
        while cur_col < tgt_col:
            result.append('R')
            cur_col += 1

        result.append('!')

    return ''.join(result)

