def stone_game_ii(piles: List[int]) -> int:
    n = len(piles)
    suffix_sum = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_sum[i] = suffix_sum[i + 1] + piles[i]
    memo = [[-1] * (n + 1) for _ in range(n)]

    def dp(i: int, m: int) -> int:
        if i + 2 * m >= n:
            return suffix_sum[i]
        if memo[i][m] != -1:
            return memo[i][m]
        max_score = -float('inf')
        for x in range(1, 2 * m + 1):
            score = suffix_sum[i] - dp(i + x, max(x, m))
            if score > max_score:
                max_score = score
        memo[i][m] = max_score
        return max_score

    return dp(0, 1)

