        if node:
            parent_map[node.val] = parent
            if node.left:
                dfs(node.left, node)
            if node.right:
                dfs(node.right, node)
    dfs(root, None)

    target_node = None
    def find_node(node):
        nonlocal target_node
        if node and node.val == x:
            target_node = node
        if node and node.left:
            find_node(node.left)
        if node and node.right:
            find_node(node.right)
    find_node(root)

    def count_size(node):
        if not node:
            return 0
        return 1 + count_size(node.left) + count_size(node.right)
    left_count = count_size(target_node.left)
    right_count = count_size(target_node.right)

    return left_count > n / 2 or right_count > n / 2 or n - left_count - right_count - 1 > n / 2

class SnapshotArray:
    def __init__(self, length: int):
        self.snapshots = [{} for _ in range(length)]
        self.snap_id = 0
    def set(self, index: int, val: int) -> None:
        self.snapshots[index][self.snap_id] = val
    def snap(self) -> int:
        self.snap_id += 1
        return self.snap_id - 1
    def get(self, index: int, snap_id: int) -> int:
        record = self.snapshots[index]
        best_id, best_val = -1, 0
        for sid, val in record.items():
            if sid <= snap_id and sid > best_id:
                best_id, best_val = sid, val
        return best_val

def num_rolls_to_target(n: int, k: int, target: int) -> int:
    MOD = 10**9 + 7
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, target + 1):
            for x in range(1, min(j, k) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - x]) % MOD
    return dp[n][target]

