        return 0

    total_counts: Dict[str, int] = {}
    for ch in text:
        total_counts[ch] = total_counts.get(ch, 0) + 1

    n = len(text)
    max_len = 0

    for target, total in total_counts.items():
        left = 0
        non_target = 0
        for right in range(n):
            if text[right] != target:
                non_target += 1
            while non_target > 1:
                if text[left] != target:
                    non_target -= 1
                left += 1
            # window size cannot exceed total occurrences of target
            current_len = right - left + 1
            max_len = max(max_len, min(total, current_len))

    return max_len

