def max_distance(grid: List[List[int]]) -> int:
    n = len(grid)
    queue = deque()
    distance = 0
    visited = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))
                visited[i][j] = True
    if len(queue) == 0 or len(queue) == n * n:
        return -1
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        size = len(queue)
        for _ in range(size):
            x0, y0 = queue.popleft()
            for dx, dy in directions:
                x = x0 + dx
                y = y0 + dy
                if 0 <= x < n and 0 <= y < n and not visited[x][y]:
                    queue.append((x, y))
                    visited[x][y] = True
        distance += 1
    return distance - 1

