def num_prime_arrangements(n: int) -> int:
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    i = 2
    while i * i <= n:
        if is_prime[i]:
            j = i * i
            while j <= n:
                is_prime[j] = False
                j += i
        i += 1

    prime_count = 0
    non_prime_count = 0
    for i in range(1, n + 1):
        if is_prime[i]:
            prime_count += 1
        else:
            non_prime_count += 1

    mod = 10**9 + 7
    result = 1
    for i in range(2, prime_count + 1):
        result = (result * i) % mod
    for i in range(2, non_prime_count + 1):
        result = (result * i) % mod

    return result

