        first_bit = 1 << (ord(puzzle[0]) - ord('a'))
        for wmask, cnt in word_count.items():
            if (wmask & mask) == wmask and (wmask & first_bit):
                count += cnt
        result.append(count)
    return result

def distance_between_bus_stops(distance: list[int], start: int, destination: int) -> int:
    total_distance = 0
    for d in distance:
        total_distance += d
    if start > destination:
        start, destination = destination, start
    clockwise_distance = 0
    for i in range(start, destination):
        clockwise_distance += distance[i]
    counterclockwise_distance = total_distance - clockwise_distance
    return min(clockwise_distance, counterclockwise_distance)

import heapq

class DinnerPlates:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.stacks = []
        self.available = []
    def push(self, val: int) -> None:
        while self.available and (self.available[0] >= len(self.stacks) or len(self.stacks[self.available[0]]) >= self.capacity):
            heapq.heappop(self.available)
        if not self.available:
            self.stacks.append([val])
            if self.capacity > 1:
                heapq.heappush(self.available, len(self.stacks) - 1)
        else:
            idx = self.available[0]
            self.stacks[idx].append(val)
            if len(self.stacks[idx]) >= self.capacity:
                heapq.heappop(self.available)
    def pop(self) -> int:
        while self.stacks and not self.stacks[-1]:
            self.stacks.pop()
        if not self.stacks:
            return -1
        return self.popAtStack(len(self.stacks) - 1)
    def popAtStack(self, index: int) -> int:
        if index >= len(self.stacks) or not self.stacks[index]:
            return -1
        was_full = len(self.stacks[index]) == self.capacity
        val = self.stacks[index].pop()
        if was_full:
            heapq.heappush(self.available, index)
        while self.stacks and not self.stacks[-1]:
            self.stacks.pop()
        return val

def max_number_of_balloons(text: str) -> int:
