def reverse_parentheses(s: str) -> str:
    stack: List[str] = []
    for ch in s:
        if ch == ')':
            # Gather characters until the matching '('
            segment: List[str] = []
            while stack and stack[-1] != '(':
                segment.append(stack.pop())
            # Remove the '('
            if stack and stack[-1] == '(':
                stack.pop()
            # Append the reversed segment (already reversed by popping)
            stack.extend(segment)
        else:
            stack.append(ch)
    return ''.join(stack)

