def k_concatenation_max_sum(arr: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(arr)
    total = sum(arr)

    # Kadane's algorithm for max subarray sum (handles all‑negative)
    cur = max_sub = arr[0]
    for v in arr[1:]:
        cur = v if cur + v < v else cur + v
        if cur > max_sub:
            max_sub = cur

    # max prefix sum
    cur = 0
    max_prefix = float('-inf')
    for v in arr:
        cur += v
        if cur > max_prefix:
            max_prefix = cur

    # max suffix sum
    cur = 0
    max_suffix = float('-inf')
    for v in reversed(arr):
        cur += v
        if cur > max_suffix:
            max_suffix = cur

    if k == 1:
        best = max_sub
    else:
        if total > 0:
            candidate = max_suffix + max_prefix + (k - 2) * total
        else:
            candidate = max_suffix + max_prefix
        best = max(max_sub, candidate)

    # empty subarray is allowed → result cannot be negative
    best = max(0, best)
    return best % MOD

