def make_array_increasing(arr1: List[int], arr2: List[int]) -> int:
    arr2 = sorted(set(arr2))
    INF = float('inf')
    dp = {-1: 0}  # key: last value, value: min operations so far
    for a in arr1:
        next_dp = {}
        for prev_val, ops in dp.items():
            # keep current element if it keeps the array strictly increasing
            if a > prev_val:
                if a not in next_dp or ops < next_dp[a]:
                    next_dp[a] = ops
            # try replacing with each possible value from arr2 that is greater than prev_val
            for v in arr2:
                if v > prev_val:
                    new_ops = ops + 1
                    if v not in next_dp or new_ops < next_dp[v]:
                        next_dp[v] = new_ops
        dp = next_dp
        if not dp:
            return -1
    return min(dp.values()) if dp else -1

