def nth_ugly_number(n: int, a: int, b: int, c: int) -> int:
    def gcd(x: int, y: int) -> int:
        return x if y == 0 else gcd(y, x % y)
    def lcm(x: int, y: int) -> int:
        return x * y // gcd(x, y)
    lcm_ab = lcm(a, b)
    lcm_bc = lcm(b, c)
    lcm_ac = lcm(a, c)
    lcm_abc = lcm(lcm_ab, c)
    left, right = 1, 2 * 10 ** 9
    while left < right:
        mid = (left + right) // 2
        count = mid // a + mid // b + mid // c
        count -= mid // lcm_ab + mid // lcm_bc + mid // lcm_ac
        count += mid // lcm_abc
        if count < n:
            left = mid + 1
        else:
            right = mid
    return left

