def smallest_string_with_swaps(s: str, pairs: List[List[int]]) -> str:
    parent = list(range(len(s)))
    rank = [0] * len(s)

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x == root_y:
            return
        if rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        elif rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        else:
            parent[root_y] = root_x
            rank[root_x] += 1

    for x, y in pairs:
        union(x, y)

    groups = {}
    for i, ch in enumerate(s):
        root = find(i)
        groups.setdefault(root, []).append(ch)

    for key in groups:
        groups[key].sort()
        groups[key].reverse()

    result = [''] * len(s)
    for i in range(len(s)):
        root = find(i)
        result[i] = groups[root].pop()

    return ''.join(result)

import random

class Node:
    __slots__ = ("val", "forward")
    def __init__(self, val, level):
        self.val = val
        self.forward = [None] * level

class Skiplist:
    def __init__(self):
        self.levels = 16
        self.p = 0.5
        self.head = Node(0, self.levels)
    def _random_level(self):
        lvl = 1
        while random.random() < self.p and lvl < self.levels:
            lvl += 1
        return lvl
    def search(self, target: int) -> bool:
        cur = self.head
        for i in range(self.levels - 1, -1, -1):
            while cur.forward[i] is not None and cur.forward[i].val < target:
                cur = cur.forward[i]
        cur = cur.forward[0]
        return cur is not None and cur.val == target
    def add(self, num: int) -> None:
        update = [None] * self.levels
        cur = self.head
        for i in range(self.levels - 1, -1, -1):
            while cur.forward[i] is not None and cur.forward[i].val < num:
                cur = cur.forward[i]
            update[i] = cur
        lvl = self._random_level()
        new_node = Node(num, lvl)
        for i in range(lvl):
            new_node.forward[i] = update[i].forward[i]
            update[i].forward[i] = new_node
    def erase(self, num: int) -> bool:
        update = [None] * self.levels
        cur = self.head
        for i in range(self.levels - 1, -1, -1):
            while cur.forward[i] is not None and cur.forward[i].val < num:
                cur = cur.forward[i]
            update[i] = cur
        cur = cur.forward[0]
        if cur is None or cur.val != num:
            return False
        for i in range(self.levels):
            if update[i].forward[i] != cur:
                break
            update[i].forward[i] = cur.forward[i]
        return True

