from collections import deque, defaultdict

def sort_items(n: int, m: int, group: List[int], before_items: List[List[int]]) -> List[int]:
    # Assign unique groups to items without a group
    next_group = m
    for i in range(n):
        if group[i] == -1:
            group[i] = next_group
            next_group += 1
    total_groups = next_group

    # Build item graph
    item_adj: List[List[int]] = [[] for _ in range(n)]
    item_indeg: List[int] = [0] * n

    # Build group graph
    group_adj: List[List[int]] = [[] for _ in range(total_groups)]
    group_indeg: List[int] = [0] * total_groups

    for v in range(n):
        for u in before_items[v]:
            # u must come before v
            item_adj[u].append(v)
            item_indeg[v] += 1
            if group[u] != group[v]:
                group_adj[group[u]].append(group[v])
                group_indeg[group[v]] += 1

    def topological_sort(nodes: int, adj: List[List[int]], indeg: List[int], prepend_new: bool = False) -> List[int]:
        q: Deque[int] = deque([i for i in range(nodes) if indeg[i] == 0])
        order: List[int] = []
        while q:
            u = q.popleft()
            order.append(u)
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    if prepend_new:
                        q.appendleft(v)
                    else:
                        q.append(v)
        return order if len(order) == nodes else []

    item_order = topological_sort(n, item_adj, item_indeg, prepend_new=False)
    if not item_order:
        return []

    group_order = topological_sort(total_groups, group_adj, group_indeg, prepend_new=True)
    if not group_order:
        return []

    # Collect items per group respecting item order
    group_to_items: defaultdict[int, List[int]] = defaultdict(list)
    for item in item_order:
        group_to_items[group[item]].append(item)

    result: List[int] = []
    for g in group_order:
        result.extend(group_to_items.get(g, []))
    return result

