def get_maximum_gold(grid: List[List[int]]) -> int:
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    max_gold = 0

    def backtrack(row: int, col: int, current_gold: int, visited: Set[str]) -> None:
        nonlocal max_gold
        if current_gold > max_gold:
            max_gold = current_gold
        for dr, dc in directions:
            new_row = row + dr
            new_col = col + dc
            if (0 <= new_row < len(grid) and
                0 <= new_col < len(grid[0]) and
                grid[new_row][new_col] != 0 and
                f"{new_row},{new_col}" not in visited):
                visited.add(f"{new_row},{new_col}")
                backtrack(new_row, new_col, current_gold + grid[new_row][new_col], visited)
                visited.remove(f"{new_row},{new_col}")

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 0:
                backtrack(i, j, grid[i][j], {f"{i},{j}"})

    return max_gold

