        counts[ch] += 1

    # already balanced
    if all(v <= target for v in counts.values()):
        return 0

    left = 0
    ans = n
    for right, ch in enumerate(s):
        counts[ch] -= 1
        while left <= right and all(counts[c] <= target for c in "QWER"):
