    dp[0] = 1
    for _ in range(steps):
        nxt = [0] * (max_pos + 1)
        for pos in range(max_pos + 1):
            ways = dp[pos]
            if pos:
                ways += dp[pos - 1]
            if pos < max_pos:
                ways += dp[pos + 1]
            nxt[pos] = ways % MOD
        dp = nxt
    return dp[0]

