def min_push_box(grid: List[List[str]]) -> int:
    m, n = len(grid), len(grid[0])
    start_player = start_box = target = None
    for i in range(m):
        for j in range(n):
            cell = grid[i][j]
            if cell == 'S':
                start_player = (i, j)
            elif cell == 'B':
                start_box = (i, j)
            elif cell == 'T':
                target = (i, j)
    if start_player is None or start_box is None or target is None:
        return -1
    if start_box == target:
        return 0

    dirs: List[Tuple[int, int]] = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def in_bounds(x: int, y: int) -> bool:
        return 0 <= x < m and 0 <= y < n and grid[x][y] != '#'

    def can_reach(px: int, py: int, dest: Tuple[int, int], box_pos: Tuple[int, int]) -> bool:
        if (px, py) == dest:
            return True
        q = deque()
        q.append((px, py))
        visited: Set[Tuple[int, int]] = {(px, py)}
        while q:
            x, y = q.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if not in_bounds(nx, ny) or (nx, ny) == box_pos or (nx, ny) in visited:
                    continue
                if (nx, ny) == dest:
                    return True
                visited.add((nx, ny))
                q.append((nx, ny))
        return False

    start_state = (start_box[0], start_box[1], start_player[0], start_player[1])
    q = deque()
    q.append((start_state, 0))
    visited_states: Set[Tuple[int, int, int, int]] = {start_state}

    while q:
        (bx, by, px, py), pushes = q.popleft()
        if (bx, by) == target:
            return pushes
        for dx, dy in dirs:
            nbx, nby = bx + dx, by + dy
            req_px, req_py = bx - dx, by - dy
            if not in_bounds(nbx, nby) or not in_bounds(req_px, req_py):
                continue
            if not can_reach(px, py, (req_px, req_py), (bx, by)):
                continue
            new_state = (nbx, nby, bx, by)
            if new_state in visited_states:
                continue
            visited_states.add(new_state)
            q.append((new_state, pushes + 1))
    return -1

