def palindrome_partition(s: str, k: int) -> int:
    n = len(s)
    if k >= n:
        return 0

    cost = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            add = 0 if s[i] == s[j] else 1
            if j - i <= 1:
                cost[i][j] = add
            else:
                cost[i][j] = cost[i + 1][j - 1] + add

    INF = 10 ** 9
    prev = [INF] * (n + 1)
    prev[0] = 0

    for p in range(1, k + 1):
        cur = [INF] * (n + 1)

        def compute(l: int, r: int, opt_l: int, opt_r: int) -> None:
            if l > r:
                return
            mid = (l + r) // 2
            best_val = INF
            best_k = -1
            start = opt_l
            end = min(mid - 1, opt_r)
            for j in range(start, end + 1):
                val = prev[j] + cost[j][mid - 1]
                if val < best_val:
                    best_val = val
                    best_k = j
            cur[mid] = best_val
            compute(l, mid - 1, opt_l, best_k)
            compute(mid + 1, r, best_k, opt_r)

        compute(p, n, p - 1, n - 1)
        prev = cur

    return prev[n]

