    for i, size in enumerate(group_sizes):
        pending.setdefault(size, []).append(i)
        if len(pending[size]) == size:
            groups.append(pending[size])
            pending[size] = []
    groups.sort(key=lambda g: (len(g), g[0]))
    return groups

