def smallest_divisor(nums: List[int], threshold: int) -> int:
    low = 1
    high = max(nums)
    answer = high
    while low <= high:
        mid = (low + high) // 2
        total = 0
        for num in nums:
            total += math.ceil(num / mid)
            if total > threshold:
                break
        if total <= threshold:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1
    return answer

class CombinationIterator:
