        self.idx = 0
        n = len(characters)
        cur = []
        def dfs(start):
            if len(cur) == combination_length:
                self.combos.append(''.join(cur))
                return
            for i in range(start, n):
                cur.append(characters[i])
                dfs(i+1)
                cur.pop()
        dfs(0)
    def next(self) -> str:
        val = self.combos[self.idx]
        self.idx += 1
        return val
    def hasNext(self) -> bool:
        return self.idx < len(self.combos)

