from collections import deque

def min_flips(mat: List[List[int]]) -> int:
    m = len(mat)
    n = len(mat[0])
    total = m * n
    start_mask = 0
    for r in range(m):
        for c in range(n):
            if mat[r][c] == 1:
                start_mask |= 1 << (r * n + c)
    if start_mask == 0:
        return 0
    flip_mask = [0] * total
    dirs = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    for r in range(m):
        for c in range(n):
            mask = 0
            for dr, dc in dirs:
                nr = r + dr
                nc = c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    mask |= 1 << (nr * n + nc)
            flip_mask[r * n + c] = mask
    visited = {start_mask}
    q = deque()
    q.append((start_mask, 0))
    while q:
        cur_mask, steps = q.popleft()
        for i in range(total):
            next_mask = cur_mask ^ flip_mask[i]
            if next_mask == 0:
                return steps + 1
            if next_mask not in visited:
                visited.add(next_mask)
                q.append((next_mask, steps + 1))
    return -1

