def max_side_length(mat: List[List[int]], threshold: int) -> int:
    m = len(mat)
    n = len(mat[0]) if m else 0
    pref = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        row_sum = 0
        for j in range(n):
            row_sum += mat[i][j]
            pref[i + 1][j + 1] = pref[i][j + 1] + row_sum

    def can_fit(k: int) -> bool:
        for i in range(k, m + 1):
            pi = pref[i]
            pi_k = pref[i - k]
            for j in range(k, n + 1):
                total = pi[j] - pi_k[j] - pi[j - k] + pi_k[j - k]
                if total <= threshold:
                    return True
        return False

    lo, hi = 0, min(m, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_fit(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

