def shortest_path(grid: List[List[int]], k: int) -> int:
    rows, cols = len(grid), len(grid[0])
    if k >= rows + cols - 2:
        return rows + cols - 2
    if rows == 1 and cols == 1:
        return 0
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[-1] * cols for _ in range(rows)]
    queue = [(0, 0, k, 0)]
    visited[0][0] = k
    head = 0
    while head < len(queue):
        r, c, remain, steps = queue[head]
        head += 1
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                continue
            new_remain = remain - grid[nr][nc]
            if new_remain < 0:
                continue
            if nr == rows - 1 and nc == cols - 1:
                return steps + 1
            if visited[nr][nc] >= new_remain:
                continue
            visited[nr][nc] = new_remain
            queue.append((nr, nc, new_remain, steps + 1))
    return -1

