def divide_array(nums: List[int], k: int) -> bool:
    if len(nums) % k != 0:
        return False
    nums.sort()
    freq = {}
    for v in nums:
        freq[v] = freq.get(v, 0) + 1
    for v in nums:
        cnt = freq.get(v, 0)
        if cnt > 0:
            for i in range(k):
