                if cur_cnt < cnt:
                    return False
                freq[cur] = cur_cnt - cnt
    return True

def max_freq(s: str, max_letters: int, min_size: int, max_size: int) -> int:
    n = len(s)
    freq = {}
    cnt = [0] * 26
    unique = 0
    for i in range(min_size):
        idx = ord(s[i]) - 97
        if cnt[idx] == 0:
            unique += 1
        cnt[idx] += 1
    if unique <= max_letters:
        sub = s[:min_size]
        freq[sub] = freq.get(sub, 0) + 1
    for i in range(min_size, n):
        out_idx = ord(s[i - min_size]) - 97
        cnt[out_idx] -= 1
        if cnt[out_idx] == 0:
            unique -= 1
        in_idx = ord(s[i]) - 97
        if cnt[in_idx] == 0:
            unique += 1
        cnt[in_idx] += 1
        if unique <= max_letters:
            sub = s[i - min_size + 1:i + 1]
            freq[sub] = freq.get(sub, 0) + 1
    ans = 0
    for v in freq.values():
        if v > ans:
            ans = v
    return ans

