from typing import List

def find_best_value(arr: List[int], target: int) -> int:
    n = len(arr)
    if n == 0:
        return 0
    arr.sort()
    pref = [0] * (n + 1)
    for i, val in enumerate(arr, 1):
        pref[i] = pref[i - 1] + val
    max_val = arr[-1]

    def capped_sum(v: int) -> int:
        idx = bisect_right(arr, v)  # number of elements <= v
        return pref[idx] + v * (n - idx)

    low, high = 0, max_val
    while low < high:
        mid = (low + high) // 2
        if capped_sum(mid) < target:
            low = mid + 1
        else:
            high = mid

    best_v = low
    best_diff = abs(capped_sum(best_v) - target)

    if best_v > 0:
        v0 = best_v - 1
        diff0 = abs(capped_sum(v0) - target)
        if diff0 < best_diff or (diff0 == best_diff and v0 < best_v):
            best_v = v0
            best_diff = diff0

    return best_v

