def number_of_paths(board: List[str]) -> List[int]:
    MOD = 1000000007
    n = len(board)
    m = len(board[0])
    best = [[-1] * m for _ in range(n)]
    ways = [[0] * m for _ in range(n)]

    best[n - 1][m - 1] = 0
    ways[n - 1][m - 1] = 1

    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if board[i][j] == 'X':
                continue
            if i == n - 1 and j == m - 1:
                continue

            max_prev = -1
            cnt = 0
            for dx, dy in ((1, 0), (0, 1), (1, 1)):
                ni, nj = i + dx, j + dy
                if ni >= n or nj >= m:
                    continue
                if best[ni][nj] == -1:
                    continue
                if best[ni][nj] > max_prev:
                    max_prev = best[ni][nj]
                    cnt = ways[ni][nj]
                elif best[ni][nj] == max_prev:
                    cnt = (cnt + ways[ni][nj]) % MOD

            if max_prev == -1:
                continue

            cell_char = board[i][j]
            add = int(cell_char) if '0' <= cell_char <= '9' else 0
            best[i][j] = max_prev + add
            ways[i][j] = cnt % MOD

    if best[0][0] == -1:
        return [0, 0]
    return [best[0][0], ways[0][0]]

def deepest_leaves_sum(root):
