    def dfs(node, depth):
        nonlocal max_depth, sum_at_max
        if not node:
            return
        if not node.left and not node.right:
            if depth > max_depth:
                max_depth = depth
                sum_at_max = node.val
            elif depth == max_depth:
                sum_at_max += node.val
        dfs(node.left, depth + 1)
        dfs(node.right, depth + 1)
    dfs(root, 0)
    return sum_at_max

