def max_candies(status: List[int], candies: List[int], keys: List[List[int]],
                containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
    n = len(status)
    have_key = [False] * n
    owned = [False] * n
    opened = [False] * n

    q = deque()
    for b in initialBoxes:
        owned[b] = True
        if status[b] == 1:
            q.append(b)

    total = 0
    while q:
        b = q.popleft()
        if opened[b]:
            continue
        opened[b] = True
        total += candies[b]

        for k in keys[b]:
            if not have_key[k]:
                have_key[k] = True
                if owned[k] and not opened[k]:
                    q.append(k)

        for nb in containedBoxes[b]:
            if not owned[nb]:
                owned[nb] = True
                if status[nb] == 1 or have_key[nb]:
                    q.append(nb)

    return total

