    while i >= 0:
        if s[i] == '#':
            num = int(s[i - 2]) * 10 + int(s[i - 1])
            result.append(chr(96 + num))
            i -= 3
        else:
            num = int(s[i])
            result.append(chr(96 + num))
            i -= 1
    result.reverse()
    return ''.join(result)

def solve(n):
    result = []
    if n % 2 == 0:
        for i in range(1, n // 2 + 1):
            result.append(i)
            result.append(-i)
    else:
        if n == 1:
            result.append(0)
        elif n == 3:
            result.extend([-1, 0, 1])
        else:
            result.extend([-1, 1])
            sum_pos = 0
            for i in range(3, n):
                result.append(i)
                sum_pos += i
            result.append(-sum_pos)
    result.sort()
    return result

import sys
from typing import List

def is_solvable(words: List[str], result: str) -> bool:
    letters = set()
    for w in words:
        letters.update(w)
    letters.update(result)
    if len(letters) > 10:
        return False

    leading = set()
    for w in words:
        if len(w) > 1:
            leading.add(w[0])
    if len(result) > 1:
        leading.add(result[0])

    assign = {}
    used = set()
    max_len = max([len(result)] + [len(w) for w in words])

    sys.setrecursionlimit(10000)

    def dfs(col: int, carry: int) -> bool:
        if col == max_len:
            return carry == 0

        def assign_add(i: int, cur_sum: int) -> bool:
            if i == len(words):
                if col < len(result):
                    res_ch = result[-1 - col]
                else:
                    res_ch = None

                total = cur_sum + carry
                needed_digit = total % 10
                next_carry = total // 10

                if res_ch is None:
                    if needed_digit != 0:
                        return False
                    return dfs(col + 1, next_carry)

                if res_ch in assign:
                    if assign[res_ch] != needed_digit:
                        return False
                    return dfs(col + 1, next_carry)

                if needed_digit in used:
                    return False
                if needed_digit == 0 and res_ch in leading:
                    return False

                assign[res_ch] = needed_digit
                used.add(needed_digit)
                if dfs(col + 1, next_carry):
                    return True
                del assign[res_ch]
                used.remove(needed_digit)
                return False

            w = words[i]
            if col >= len(w):
                return assign_add(i + 1, cur_sum)

            ch = w[-1 - col]
            if ch in assign:
                return assign_add(i + 1, cur_sum + assign[ch])

            for d in range(10):
                if d in used:
                    continue
                if d == 0 and ch in leading:
                    continue
                assign[ch] = d
                used.add(d)
                if assign_add(i + 1, cur_sum + d):
                    return True
                del assign[ch]
                used.remove(d)
            return False

        return assign_add(0, 0)

    return dfs(0, 0)

