INF = 10**9
COLS = 6
NONE = 26  # sentinel for unused finger


def minimum_distance(word: str) -> int:
    """Return the minimum total Manhattan distance needed to type *word* with two fingers."""
    if not word:
        return 0

    def manhattan(a: int, b: int) -> int:
        ra, ca = divmod(a, COLS)
        rb, cb = divmod(b, COLS)
        return abs(ra - rb) + abs(ca - cb)

    # dp[p1][p2] = minimal cost after processing current prefix,
    # where p1 and p2 are the last keys pressed by finger1 and finger2 respectively.
    dp: List[List[int]] = [[INF] * 27 for _ in range(27)]
    dp[NONE][NONE] = 0

    for ch in word:
        cur = ord(ch) - ord('A')
        ndp: List[List[int]] = [[INF] * 27 for _ in range(27)]
        for p1 in range(27):
            row = dp[p1]
            for p2 in range(27):
                cur_cost = row[p2]
                if cur_cost == INF:
                    continue
                # Use finger 1 for this character
                add = 0 if p1 == NONE else manhattan(p1, cur)
                new_cost = cur_cost + add
                if new_cost < ndp[cur][p2]:
                    ndp[cur][p2] = new_cost
                # Use finger 2 for this character
                add = 0 if p2 == NONE else manhattan(p2, cur)
                new_cost = cur_cost + add
                if new_cost < ndp[p1][cur]:
                    ndp[p1][cur] = new_cost
        dp = ndp

    answer = INF
    for row in dp:
        for val in row:
            if val < answer:
                answer = val
    return answer

