def make_connected(n: int, connections: List[List[int]]) -> int:
    if len(connections) < n - 1:
        return -1
    parent = [i for i in range(n)]
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return False
        if rank[root_a] < rank[root_b]:
            parent[root_a] = root_b
        elif rank[root_a] > rank[root_b]:
            parent[root_b] = root_a
        else:
            parent[root_b] = root_a
            rank[root_a] += 1
        return True

    extra_edges = 0
    for u, v in connections:
        if not union(u, v):
            extra_edges += 1

    components = {find(i) for i in range(n)}
    needed = len(components) - 1
    return needed if extra_edges >= needed else -1

