def min_taps(n: int, ranges: List[int]) -> int:
    max_reach = [0] * (n + 1)
    for i in range(n + 1):
        left = max(0, i - ranges[i])
        right = min(n, i + ranges[i])
        if right > max_reach[left]:
            max_reach[left] = right

    taps = 0
    cur_end = 0
    farthest = 0

    for i in range(n + 1):
        farthest = max(farthest, max_reach[i])
        if i == cur_end:
            taps += 1
            cur_end = farthest
            if cur_end <= i:
                return -1
        if cur_end >= n:
            break

    return taps if cur_end >= n else -1

