def remove_palindrome_sub(s: str) -> int:
    if len(s) == 0:
        return 0
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            break
        left += 1
        right -= 1
    return 1 if left >= right else 2

