def find_the_city(n: int, edges: List[List[int]], distanceThreshold: int) -> int:
    inf = float('inf')
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = w
        dist[v][u] = w
    for k in range(n):
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            for j in range(n):
                new_dist = dik + dist[k][j]
                if new_dist < dist[i][j]:
                    dist[i][j] = new_dist
    best_city = -1
    best_count = inf
    for i in range(n):
        cnt = 0
        for j in range(n):
            if i != j and dist[i][j] <= distanceThreshold:
                cnt += 1
        if cnt < best_count or (cnt == best_count and i > best_city):
            best_count = cnt
            best_city = i
    return best_city

