def min_difficulty(job_difficulty: List[int], d: int) -> int:
    n = len(job_difficulty)
    if d > n:
        return -1
    INF = float('inf')
    prev = [INF] * (n + 1)
    prev[0] = 0
    for day in range(1, d + 1):
        cur = [INF] * (n + 1)
        for i in range(day, n + 1):
            day_max = 0
            for j in range(i - 1, day - 2, -1):
                day_max = max(day_max, job_difficulty[j])
                if prev[j] != INF:
                    cur[i] = min(cur[i], prev[j] + day_max)
        prev = cur
    return -1 if prev[n] == INF else prev[n]

