def k_weakest_rows(mat: List[List[int]], k: int) -> List[int]:
    def count_ones(row: List[int]) -> int:
        lo, hi = 0, len(row)
        while lo < hi:
            mid = (lo + hi) >> 1
            if row[mid] == 1:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def greater(a: List[int], b: List[int]) -> bool:
        if a[0] != b[0]:
            return a[0] > b[0]
        return a[1] > b[1]

    def heap_push(heap: List[List[int]], node: List[int]) -> None:
        heap.append(node)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if greater(heap[p], heap[i]):
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop(heap: List[List[int]]) -> List[int]:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                largest = i
                if l < len(heap) and not greater(heap[largest], heap[l]):
                    largest = l
                if r < len(heap) and not greater(heap[largest], heap[r]):
                    largest = r
                if largest == i:
                    break
                heap[i], heap[largest] = heap[largest], heap[i]
                i = largest
        return top

    heap: List[List[int]] = []
    for i in range(len(mat)):
        soldiers = count_ones(mat[i])
        heap_push(heap, [soldiers, i])
        if len(heap) > k:
            heap_pop(heap)

    return [pair[1] for pair in sorted(heap, key=lambda x: (x[0], x[1]))]

def max_product(root):
    MOD = 10**9 + 7

    # first DFS: compute the sum of the WHOLE tree only (root's subtree sum)
    def sum_sub(node):
        if not node:
            return 0
        return node.val + sum_sub(node.left) + sum_sub(node.right)

    total = sum_sub(root)
    best = 0

    def dfs(node):
        nonlocal best
        if not node:
            return 0
        left = dfs(node.left)
        right = dfs(node.right)
        cur = node.val + left + right
        product = cur * (total - cur)
        if product > best:
            best = product
        return cur

    dfs(root)
    return best % MOD

