def max_jumps(arr: List[int], d: int) -> int:
    n = len(arr)
    memo = [0] * n

    def dfs(i: int) -> int:
        if memo[i] != 0:
            return memo[i]
        best = 1
        for step in range(1, d + 1):
            if i - step < 0:
                break
            if arr[i] > arr[i - step]:
                best = max(best, 1 + dfs(i - step))
            else:
                break
        for step in range(1, d + 1):
            if i + step >= n:
                break
            if arr[i] > arr[i + step]:
                best = max(best, 1 + dfs(i + step))
            else:
                break
        memo[i] = best
        return best

    answer = 0
    for i in range(n):
        answer = max(answer, dfs(i))
    return answer

