def min_jumps(arr: List[int]) -> int:
    n = len(arr)
    if n <= 1:
        return 0
    pos_map = {}
    for i in range(n):
        pos_map.setdefault(arr[i], []).append(i)
    visited = [False] * n
    queue = deque([0])
    visited[0] = True
    steps = 0
    while queue:
        level_size = len(queue)
        for _ in range(level_size):
            i = queue.popleft()
            if i == n - 1:
                return steps
            neighbours = []
            if i - 1 >= 0:
                neighbours.append(i - 1)
            if i + 1 < n:
                neighbours.append(i + 1)
            if arr[i] in pos_map:
                neighbours.extend(pos_map[arr[i]])
                del pos_map[arr[i]]
            for nb in neighbours:
                if not visited[nb]:
                    visited[nb] = True
                    queue.append(nb)
        steps += 1
    return -1

