def tweet_counts() -> SimpleNamespace:
    tweets: Dict[str, List[int]] = {}
    sorted_set = set()

    def record_tweet(tweet_name: str, time: int) -> None:
        tweets.setdefault(tweet_name, []).append(time)
        sorted_set.discard(tweet_name)

    def get_tweet_counts_per_frequency(freq: str, tweet_name: str, start_time: int, end_time: int) -> List[int]:
        if tweet_name not in tweets:
            return []
        if tweet_name not in sorted_set:
            tweets[tweet_name].sort()
            sorted_set.add(tweet_name)
        interval = 60 if freq == "minute" else 3600 if freq == "hour" else 86400
        n = (end_time - start_time) // interval + 1
        result = [0] * n
        arr = tweets[tweet_name]
        i = bisect_left(arr, start_time)
        while i < len(arr) and arr[i] <= end_time:
            idx = (arr[i] - start_time) // interval
            result[idx] += 1
            i += 1
        return result

    return SimpleNamespace(record_tweet=record_tweet, get_tweet_counts_per_frequency=get_tweet_counts_per_frequency)

