def max_students(seats: List[List[str]]) -> int:
    m = len(seats)
    n = len(seats[0])
    avail_masks = []
    for r in range(m):
        mask = 0
        for c, ch in enumerate(seats[r]):
            if ch == '.':
                mask |= 1 << c
        avail_masks.append(mask)

    all_masks = list(range(1 << n))
    popcnt = {}
    for mask in all_masks:
        popcnt[mask] = mask.bit_count() if hasattr(int, "bit_count") else bin(mask).count('1')

    valid_masks_per_row = []
    for r in range(m):
        row_valid = []
        avail = avail_masks[r]
        for mask in all_masks:
            if mask & ~avail:
                continue
            if mask & (mask << 1):
                continue
            row_valid.append(mask)
        valid_masks_per_row.append(row_valid)

    dp = {0: 0}
    for r in range(m):
        new_dp = {}
        for mask in valid_masks_per_row[r]:
            cnt = popcnt[mask]
            for prev_mask, prev_val in dp.items():
                if mask & (prev_mask << 1):
                    continue
                if mask & (prev_mask >> 1):
                    continue
                val = prev_val + cnt
                if val > new_dp.get(mask, -1):
                    new_dp[mask] = val
        dp = new_dp
    return max(dp.values())

