def is_possible(target: List[int]) -> bool:
    heap: List[int] = []
    def swap(i: int, j: int) -> None:
        heap[i], heap[j] = heap[j], heap[i]
    def push(val: int) -> None:
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] >= heap[i]:
                break
            swap(i, p)
            i = p
    def pop() -> int:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                largest = i
                if l < len(heap) and heap[l] > heap[largest]:
                    largest = l
                if r < len(heap) and heap[r] > heap[largest]:
                    largest = r
                if largest == i:
                    break
                swap(i, largest)
                i = largest
        return top

    if len(target) == 1:
        return target[0] == 1

    total = 0
    for v in target:
        push(v)
        total += v

    while True:
        max_val = pop()
        rest = total - max_val
        if max_val == 1 or rest == 1:
            return True
        prev = max_val % rest or rest
        if prev == 0 or prev == max_val:
            return False
        push(prev)
        total = rest + prev

