def validate_binary_tree_nodes(n: int, left_child: List[int], right_child: List[int]) -> bool:
    indegree = [0] * n
    for i in range(n):
        l = left_child[i]
        r = right_child[i]
        if l != -1:
            indegree[l] += 1
        if r != -1:
            indegree[r] += 1

    root = -1
    for i in range(n):
        if indegree[i] == 0:
            if root != -1:
                return False
            root = i
        elif indegree[i] > 1:
            return False
    if root == -1:
        return False

    stack = [root]
    visited = [False] * n
    visited[root] = True
    visited_count = 0

    while stack:
        node = stack.pop()
        visited_count += 1

        l = left_child[node]
        r = right_child[node]

        if l != -1:
            if visited[l]:
                return False
            visited[l] = True
            stack.append(l)
        if r != -1:
            if visited[r]:
                return False
            visited[r] = True
            stack.append(r)

    return visited_count == n

