def largest_multiple_of_three(digits: List[int]) -> str:
    cnt = [0] * 10
    total = 0
    for d in digits:
        cnt[d] += 1
        total += d

    rem = total % 3

    def try_remove(target: int, need: int) -> bool:
        need_remaining = need
        for d in range(10):
            if need_remaining == 0:
                break
            if d % 3 == target:
                take = min(cnt[d], need_remaining)
                cnt[d] -= take
                need_remaining -= take
        return need_remaining == 0

    if rem == 1:
        if not try_remove(1, 1):
            if not try_remove(2, 2):
                return ""
    elif rem == 2:
        if not try_remove(2, 1):
            if not try_remove(1, 2):
                return ""

    result = ""
    for d in range(9, -1, -1):
        if cnt[d]:
            result += str(d) * cnt[d]

    if not result:
        return ""
    first_non_zero = next((i for i, ch in enumerate(result) if ch != '0'), None)
    if first_non_zero is None:
        return "0"
    return result[first_non_zero:]

