def is_sub_path(head: Optional['ListNode'], root: Optional['TreeNode']) -> bool:
    def match(node: Optional['TreeNode'], lst: Optional['ListNode']) -> bool:
        if not lst:
            return True
        if not node:
            return False
        if node.val != lst.val:
            return False
        return match(node.left, lst.next) or match(node.right, lst.next)
    if not root:
        return False
    if match(root, head):
        return True
    return is_sub_path(head, root.left) or is_sub_path(head, root.right)

