def frog_position(n: int, edges: List[List[int]], t: int, target: int) -> float:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    queue = deque([(1, 1.0, 0)])
    visited = [False] * (n + 1)
    visited[1] = True

    while queue:
        node, prob, time = queue.popleft()
        unvisited = [v for v in adj[node] if not visited[v]]

        if node == target:
            if time == t or (time < t and not unvisited):
                return prob

        if time == t:
            continue

        cnt = len(unvisited)
        if cnt == 0:
            continue

        next_prob = prob / cnt
        for nb in unvisited:
            visited[nb] = True
            queue.append((nb, next_prob, time + 1))

    return 0.0

class CustomStack:
    def __init__(self, maxSize):
        self.stack = []
        self.maxSize = maxSize
        self.inc = [0]*maxSize
    def push(self, x):
        if len(self.stack) < self.maxSize: self.stack.append(x)
    def pop(self):
        if not self.stack: return -1
        i = len(self.stack)-1
        val = self.stack.pop() + self.inc[i]
        if i > 0: self.inc[i-1] += self.inc[i]
        self.inc[i] = 0
        return val
    def increment(self, k, val):
        i = min(k, len(self.stack)) - 1
        if i >= 0: self.inc[i] += val

