def max_performance(n, speed, efficiency, k):
    MOD = 1_000_000_007

    engineers = [(efficiency[i], speed[i]) for i in range(n)]
    engineers.sort(key=lambda x: -x[0])

    heap = []

    def heap_push(val):
        heap.append(val)
        idx = len(heap) - 1
        while idx > 0:
            parent = (idx - 1) >> 1
            if heap[parent] <= heap[idx]:
                break
            heap[parent], heap[idx] = heap[idx], heap[parent]
            idx = parent

    def heap_pop():
        min_val = heap[0]
        last = heap.pop()
        if not heap:
            return min_val
        heap[0] = last
        idx = 0
        while True:
            left = idx * 2 + 1
            right = left + 1
            smallest = idx
            if left < len(heap) and heap[left] < heap[smallest]:
                smallest = left
            if right < len(heap) and heap[right] < heap[smallest]:
                smallest = right
            if smallest == idx:
                break
            heap[smallest], heap[idx] = heap[idx], heap[smallest]
            idx = smallest
        return min_val

    def heap_size():
        return len(heap)

    sum_speeds = 0
    best = 0

    for eff, spd in engineers:
        heap_push(spd)
        sum_speeds += spd
        if heap_size() > k:
            sum_speeds -= heap_pop()
        perf = (sum_speeds * eff) % MOD
        if perf > best:
            best = perf

    return best

