def max_number_of_families(n: int, reserved_seats: List[Tuple[int, int]]) -> int:
    row_mask = {}
    for r, s in reserved_seats:
        mask = row_mask.get(r, 0) | (1 << (s - 1))
        row_mask[r] = mask

    families = (n - len(row_mask)) * 2

    left_mask = (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4)   # seats 2-5
    right_mask = (1 << 5) | (1 << 6) | (1 << 7) | (1 << 8)  # seats 6-9
    middle_mask = (1 << 3) | (1 << 4) | (1 << 5) | (1 << 6) # seats 4-7

    for mask in row_mask.values():
        left_free = (mask & left_mask) == 0
        right_free = (mask & right_mask) == 0
        middle_free = (mask & middle_mask) == 0

        if left_free and right_free:
            families += 2
        elif middle_free:
            families += 1
        elif left_free or right_free:
            families += 1

    return families

def get_kth(lo: int, hi: int, k: int) -> int:
    memo = {1: 0}
    def power(x: int) -> int:
        if x in memo:
            return memo[x]
        nxt = x // 2 if x % 2 == 0 else 3 * x + 1
        val = 1 + power(nxt)
        memo[x] = val
        return val
    pairs = []
    for n in range(lo, hi + 1):
        pairs.append((n, power(n)))
    pairs.sort(key=lambda a: (a[1], a[0]))
    return pairs[k - 1][0]

