def sum_four_divisors(nums):
    max_num = 0
    for v in nums:
        if v > max_num:
            max_num = v
    limit = int(max_num ** 0.5)
    is_prime = bytearray(limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if not is_prime[i]:
            primes.append(i)
            step = i
            start = i * i
            if start > limit:
                continue
            for j in range(start, limit + 1, step):
                is_prime[j] = 1

    total = 0
    for num in nums:
        if num < 2:
            continue
        n = num
        distinct = 0
        first_prime = second_prime = 0
        first_exp = second_exp = 0

        for p in primes:
            if p * p > n:
                break
            if n % p == 0:
                distinct += 1
                exp = 0
                while n % p == 0:
                    n //= p
                    exp += 1
                if distinct == 1:
                    first_prime = p
                    first_exp = exp
                else:
                    second_prime = p
                    second_exp = exp
                if distinct > 2:
                    break

        if n > 1:
            distinct += 1
            if distinct == 1:
                first_prime = n
                first_exp = 1
            else:
                second_prime = n
                second_exp = 1

        if distinct == 1 and first_exp == 3:
            p = first_prime
            total += 1 + p + p * p + p * p * p
        elif distinct == 2 and first_exp == 1 and second_exp == 1:
            p = first_prime
            q = second_prime
            total += 1 + p + q + p * q

    return total

