MOD = 10**9 + 7

def find_good_strings(n: int, s1: str, s2: str, evil: str) -> int:
    """
    Count the number of strings of length n that are lexicographically between s1 and s2
    (inclusive) and do not contain the substring evil.
    """
    m = len(evil)

    # Build KMP failure function for evil
    pi: List[int] = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j > 0 and evil[i] != evil[j]:
            j = pi[j - 1]
        if evil[i] == evil[j]:
            j += 1
        pi[i] = j

    # Build transition table: trans[state][ch] -> next state length of matched prefix
    trans: List[List[int]] = [[0] * 26 for _ in range(m + 1)]
    for state in range(m):
        for c in range(26):
            if c == ord(evil[state]) - 97:
                trans[state][c] = state + 1
            else:
                t = state
                while t > 0 and c != ord(evil[t]) - 97:
                    t = pi[t - 1]
                if c == ord(evil[t]) - 97:
                    trans[state][c] = t + 1
                else:
                    trans[state][c] = 0
    trans[m] = [m] * 26  # once evil is matched we stay in forbidden state

    # dp[pos][state][tight_low][tight_high] -> count
    # we compress dimensions: only keep current position
    dp = [[[0, 0] for _ in range(2)] for _ in range(m)]
    dp[0][1][1] = 1  # start with empty prefix, both bounds tight

    for i in range(n):
        ndp = [[[0, 0] for _ in range(2)] for _ in range(m)]
        low_bound = ord(s1[i]) - 97
        high_bound = ord(s2[i]) - 97
        for state in range(m):
            for lt in (0, 1):
                for ut in (0, 1):
                    cur = dp[state][lt][ut]
                    if cur == 0:
                        continue
                    low = low_bound if lt else 0
                    high = high_bound if ut else 25
                    for ch in range(low, high + 1):
                        nlt = lt and (ch == low_bound)
                        nut = ut and (ch == high_bound)
                        nstate = trans[state][ch]
                        if nstate == m:  # evil appears, discard
                            continue
                        ndp[nstate][nlt][nut] = (ndp[nstate][nlt][nut] + cur) % MOD
        dp = ndp

    ans = 0
    for state in range(m):
        for lt in (0, 1):
            for ut in (0, 1):
                ans = (ans + dp[state][lt][ut]) % MOD
    return ans

