    letters = []
    digits = []
    for ch in s:
        if '0' <= ch <= '9':
            digits.append(ch)
        else:
            letters.append(ch)
    if abs(len(letters) - len(digits)) > 1:
        return ''
    res = []
    li = di = 0
    start_with_letter = len(letters) > len(digits)  # start with the more frequent type; if equal, start with digit
    while li < len(letters) or di < len(digits):
        if start_with_letter:
            if li < len(letters):
                res.append(letters[li])
                li += 1
            if di < len(digits):
                res.append(digits[di])
                di += 1
        else:
            if di < len(digits):
                res.append(digits[di])
                di += 1
            if li < len(letters):
                res.append(letters[li])
                li += 1
    return ''.join(res)

