def build_array(n: int, m: int, k: int) -> int:
    if k == 0 or k > n or k > m:
        return 0

    # dp[cnt][mx] = ways for current length with exactly cnt comparisons and current max = mx
    dp: List[List[int]] = [[0] * (m + 1) for _ in range(k + 1)]
    for mx in range(1, m + 1):
        dp[1][mx] = 1  # first element sets the max and counts as one comparison

    for _ in range(1, n):
        ndp: List[List[int]] = [[0] * (m + 1) for _ in range(k + 1)]
        for cnt in range(1, k + 1):
            cur = dp[cnt]
            # keep the same maximum
            for mx in range(1, m + 1):
                if cur[mx]:
                    ndp[cnt][mx] = (ndp[cnt][mx] + cur[mx] * mx) % MOD
            # increase the maximum
            if cnt + 1 <= k:
                prefix = 0
                for new_mx in range(1, m + 1):
                    ndp[cnt + 1][new_mx] = (ndp[cnt + 1][new_mx] + prefix) % MOD
                    prefix = (prefix + cur[new_mx]) % MOD
        dp = ndp

    return sum(dp[k][mx] for mx in range(1, m + 1)) % MOD

