def diagonal_traverse(nums: List[List[int]]) -> List[int]:
    buckets = []
    for i, row in enumerate(nums):
        for j, val in enumerate(row):
            d = i + j
            if d >= len(buckets):
                buckets.extend([None] * (d - len(buckets) + 1))
            if buckets[d] is None:
                buckets[d] = []
            buckets[d].append(val)  # type: ignore
    result = []
    for bucket in buckets:
        if not bucket:
            continue
        for k in range(len(bucket) - 1, -1, -1):
            result.append(bucket[k])
    return result

