def number_of_ways(hats):
    MOD = 1_000_000_007
    n = len(hats)
    full_mask = (1 << n) - 1

    hat_to_people = [[] for _ in range(41)]
    for person in range(n):
        for h in hats[person]:
            hat_to_people[h].append(person)

    dp = [0] * (1 << n)
    dp[0] = 1

    for h in range(1, 41):
        next_dp = dp[:]
        for mask in range(full_mask + 1):
            ways = dp[mask]
            if not ways:
                continue
            for p in hat_to_people[h]:
                if (mask & (1 << p)) == 0:
                    new_mask = mask | (1 << p)
                    next_dp[new_mask] = (next_dp[new_mask] + ways) % MOD
        dp = next_dp

    return dp[full_mask]

