def kth_smallest_sum(mat: List[List[int]], k: int) -> int:
    if not mat or k <= 0:
        raise ValueError("Matrix must be non-empty and k must be positive")
    sums = mat[0][:]
    for row in mat[1:]:
        heap = []
        limit = min(k, len(sums))
        for i in range(limit):
            heapq.heappush(heap, (sums[i] + row[0], i, 0))
        new_sums = []
        while heap and len(new_sums) < k:
            total, i, j = heapq.heappop(heap)
            new_sums.append(total)
            if j + 1 < len(row):
                heapq.heappush(heap, (sums[i] + row[j + 1], i, j + 1))
        sums = new_sums
    return sums[k - 1]

