        while min_deque and nums[min_deque[-1]] > val:
            min_deque.pop()
        min_deque.append(right)
        while nums[max_deque[0]] - nums[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1
        best = max(best, right - left + 1)
    return best

