MOD = 10**9 + 7

def number_of_ways(pizza: List[str], k: int) -> int:
    rows, cols = len(pizza), len(pizza[0])
    # prefix sum of apples from (i,j) to bottom‑right
    apples = [[0] * (cols + 1) for _ in range(rows + 1)]
    for i in range(rows - 1, -1, -1):
        row = pizza[i]
        for j in range(cols - 1, -1, -1):
            apples[i][j] = (1 if row[j] == 'A' else 0) + apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1]

    # dp_cur[i][j] = ways to cut sub‑pizza starting at (i,j) with current number of cuts already made
    dp_cur = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            dp_cur[i][j] = 1 if apples[i][j] > 0 else 0

    # we need k‑1 cuts to obtain k pieces
    for _ in range(1, k):
        dp_next = [[0] * cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                if apples[i][j] == 0:
                    continue
                # horizontal cuts
                for ni in range(i + 1, rows):
                    if apples[i][j] - apples[ni][j] > 0:  # top piece has an apple
                        dp_next[i][j] = (dp_next[i][j] + dp_cur[ni][j]) % MOD
                # vertical cuts
                for nj in range(j + 1, cols):
                    if apples[i][j] - apples[i][nj] > 0:  # left piece has an apple
                        dp_next[i][j] = (dp_next[i][j] + dp_cur[i][nj]) % MOD
        dp_cur = dp_next

    return dp_cur[0][0] % MOD
# TIME: O(k * rows * cols * (rows + cols)) SPACE: O(rows * cols)

