def pseudo_palindromic_paths(root: Optional['TreeNode']) -> int:
    result = 0
    stack = [(root, 0)]
    while stack:
        node, mask = stack.pop()
        if not node:
            continue
        new_mask = mask ^ (1 << node.val)
        if not node.left and not node.right:
            if (new_mask & (new_mask - 1)) == 0:
                result += 1
        else:
            if node.right:
                stack.append((node.right, new_mask))
            if node.left:
                stack.append((node.left, new_mask))
    return result

