def cherry_pickup(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    dp = [[-float('inf')] * cols for _ in range(cols)]
    dp[0][cols - 1] = grid[0][0] + (0 if cols == 1 else grid[0][cols - 1])

    for r in range(1, rows):
        nxt = [[-float('inf')] * cols for _ in range(cols)]
        for c1 in range(cols):
            for c2 in range(cols):
                if dp[c1][c2] == -float('inf'):
                    continue
                for d1 in (-1, 0, 1):
                    nc1 = c1 + d1
                    if nc1 < 0 or nc1 >= cols:
                        continue
                    for d2 in (-1, 0, 1):
                        nc2 = c2 + d2
                        if nc2 < 0 or nc2 >= cols:
                            continue
                        add = grid[r][nc1]
                        if nc1 != nc2:
                            add += grid[r][nc2]
                        nxt[nc1][nc2] = max(nxt[nc1][nc2], dp[c1][c2] + add)
        dp = nxt

    ans = 0
    for c1 in range(cols):
        for c2 in range(cols):
            ans = max(ans, dp[c1][c2])
    return ans

