def same_distinct_probability(balls: List[int]) -> float:
    total = sum(balls)
    if total % 2:
        return 0.0
    half = total // 2
    dp = [dict() for _ in range(half + 1)]
    dp[0][0] = 1
    for c in balls:
        newdp = [dict() for _ in range(half + 1)]
        combs = [comb(c, x) for x in range(c + 1)]
        for sel in range(half + 1):
            if not dp[sel]:
                continue
            for diff, ways in dp[sel].items():
                for x in range(c + 1):
                    ns = sel + x
                    if ns > half:
                        break
                    nd = diff + (1 if x > 0 else 0) - (1 if x < c else 0)
                    newdp[ns][nd] = newdp[ns].get(nd, 0) + ways * combs[x]
        dp = newdp
    favorable = dp[half].get(0, 0)
    total_ways = comb(total, half)
    return round(favorable / total_ways, 5)
# TIME: O(N * total/2 * max(balls)) SPACE: O(total/2 * distinct_diff_range)

def has_all_codes(s: str, k: int) -> bool:
    total_codes = 1 << k
    if len(s) < k:
        return False
    seen = bytearray(total_codes)
    h = 0
    for i in range(k):
        h = (h << 1) | (ord(s[i]) - 48)
    seen[h] = 1
    found = 1
    mask = total_codes - 1
    for i in range(k, len(s)):
        h = ((h << 1) & mask) | (ord(s[i]) - 48)
        if not seen[h]:
            seen[h] = 1
            found += 1
            if found == total_codes:
                return True
    return found == total_codes

