def min_cost(houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
    INF = 10 ** 15
    dp = [[INF] * (n + 1) for _ in range(target + 1)]
    if houses[0] != 0:
        dp[1][houses[0]] = 0
    else:
        for c in range(1, n + 1):
            dp[1][c] = cost[0][c - 1]
    for i in range(1, m):
        # precompute best and second best for each group count
        best1 = [INF] * (target + 1)
        best2 = [INF] * (target + 1)
        best_color = [0] * (target + 1)
        for t in range(1, target + 1):
            b1, b2, bc = INF, INF, 0
            for c in range(1, n + 1):
                val = dp[t][c]
                if val < b1:
                    b2, b1 = b1, val
                    bc = c
                elif val < b2:
                    b2 = val
            best1[t], best2[t], best_color[t] = b1, b2, bc
        new_dp = [[INF] * (n + 1) for _ in range(target + 1)]
        possible_colors = [houses[i]] if houses[i] != 0 else range(1, n + 1)
        for t in range(1, target + 1):
            for cur_c in possible_colors:
                add = 0 if houses[i] != 0 else cost[i][cur_c - 1]
                same = dp[t][cur_c] + add
                if t > 1:
                    if best_color[t - 1] != cur_c:
                        diff = best1[t - 1] + add
                    else:
                        diff = best2[t - 1] + add
                else:
                    diff = INF
                new_dp[t][cur_c] = same if same < diff else diff
        dp = new_dp
    ans = min(dp[target][c] for c in range(1, n + 1))
    return -1 if ans >= INF else ans

