def min_sum_of_lengths(arr: List[int], target: int) -> int:
    n = len(arr)
    INF = float('inf')
    min_len_ending_at = [INF] * n
    min_len_starting_at = [INF] * n
    left = 0
    cur_sum = 0
    for right in range(n):
        cur_sum += arr[right]
        while cur_sum > target and left <= right:
            cur_sum -= arr[left]
            left += 1
        if cur_sum == target:
            length = right - left + 1
            min_len_ending_at[right] = length
            min_len_starting_at[left] = length
    best_prefix = [INF] * n
    for i in range(n):
        if i == 0:
            best_prefix[i] = min_len_ending_at[i]
        else:
            best_prefix[i] = min(best_prefix[i - 1], min_len_ending_at[i])
    best_suffix = [INF] * n
    for i in range(n - 1, -1, -1):
        if i == n - 1:
            best_suffix[i] = min_len_starting_at[i]
        else:
            best_suffix[i] = min(best_suffix[i + 1], min_len_starting_at[i])
    answer = INF
    for i in range(n - 1):
        if best_prefix[i] < INF and best_suffix[i + 1] < INF:
            answer = min(answer, best_prefix[i] + best_suffix[i + 1])
    return -1 if answer == INF else answer

