def xor_operation(n: int, start: int) -> int:
    a = start >> 1
    b = start & 1
    def xor0_to(k: int) -> int:
        r = k & 3
        if r == 0:
            return k
        elif r == 1:
            return 1
        elif r == 2:
            return k + 1
        else:
            return 0
    high_xor = xor0_to(a + n - 1) ^ xor0_to(a - 1)
    return (high_xor << 1) | (b & (n & 1))

