def min_days(bloom_day: List[int], m: int, k: int) -> int:
    if m * k > len(bloom_day):
        return -1

    def can_make(day: int) -> bool:
        bouquets = 0
        consecutive = 0
        for d in bloom_day:
            if d <= day:
                consecutive += 1
                if consecutive == k:
                    bouquets += 1
                    consecutive = 0
                    if bouquets >= m:
                        return True
            else:
                consecutive = 0
        return False

    low = min(bloom_day)
    high = max(bloom_day)

    while low < high:
        mid = (low + high) // 2
        if can_make(mid):
            high = mid
        else:
            low = mid + 1
    return low

