class DSU:
    __slots__ = ("parent", "rank", "components")
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n
    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, x: int, y: int) -> bool:
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        if self.rank[xr] < self.rank[yr]:
            xr, yr = yr, xr
        self.parent[yr] = xr
        if self.rank[xr] == self.rank[yr]:
            self.rank[xr] += 1
        self.components -= 1
        return True

def find_critical_and_pseudo_critical_edges(n: int, edges: List[List[int]]) -> List[List[int]]:
    indexed = [(u, v, w, i) for i, (u, v, w) in enumerate(edges)]
    indexed.sort(key=lambda x: x[2])
    INF = 10 ** 15

    def mst(skip: int = -1, force: int = -1) -> int:
        dsu = DSU(n)
        total = 0
        if force != -1:
            u, v, w, _ = indexed[force]
            if dsu.union(u, v):
                total += w
        for idx, (u, v, w, _) in enumerate(indexed):
            if idx == skip or idx == force:
                continue
            if dsu.union(u, v):
                total += w
                if dsu.components == 1:
                    break
        return total if dsu.components == 1 else INF

    original = mst()
    critical: List[int] = []
    pseudo: List[int] = []

    for i in range(len(indexed)):
        if mst(skip=i) > original:
            critical.append(indexed[i][3])
        elif mst(force=i) == original:
            pseudo.append(indexed[i][3])

    return [critical, pseudo]

