def can_pair(arr: List[int], k: int) -> bool:
    if k == 0:
        return False
    remainder_count: Dict[int, int] = {}
    for num in arr:
        r = num % k
        remainder_count[r] = remainder_count.get(r, 0) + 1
    for r, cnt in list(remainder_count.items()):
        if r == 0:
            if cnt % 2:
                return False
        elif k % 2 == 0 and r == k // 2:
            if cnt % 2:
                return False
        else:
            complement = (k - r) % k
            if cnt != remainder_count.get(complement, 0):
                return False
    return True

