def max_value_of_equation(points: List[List[int]], k: int) -> int:
    dq: deque[tuple[int, int]] = deque()
    best = float('-inf')
    for xj, yj in points:
        while dq and dq[0][0] < xj - k:
            dq.popleft()
        if dq:
            candidate = dq[0][1] + yj + xj
            if candidate > best:
                best = candidate
