def count_pairs(root: Optional[TreeNode], distance: int) -> int:
    good_pairs = 0

    def dfs(node: Optional[TreeNode]) -> List[int]:
        nonlocal good_pairs
        if not node:
            return []
        if not node.left and not node.right:
            return [1]

        left_dist = dfs(node.left)
        right_dist = dfs(node.right)

        for l in left_dist:
            for r in right_dist:
                if l + r <= distance:
                    good_pairs += 1

        cur_dist: List[int] = []
        for d in left_dist:
            nd = d + 1
            if nd <= distance:
                cur_dist.append(nd)
        for d in right_dist:
            nd = d + 1
            if nd <= distance:
                cur_dist.append(nd)
        return cur_dist

    dfs(root)
    return good_pairs

