def string_compression(s: str, k: int) -> int:
    n = len(s)

    @lru_cache(None)
    def dp(i: int, k_left: int) -> int:
        if i == n:
            return 0
        # option: delete current character
        best = dp(i + 1, k_left - 1) if k_left > 0 else n

        cnt = 0          # kept characters equal to s[i]
        del_cnt = 0      # deletions needed to form the group up to position j
        for j in range(i, n):
            if s[j] == s[i]:
                cnt += 1
            else:
                del_cnt += 1
            if del_cnt > k_left:
                break
            add = 1
            if cnt > 1:
                add += len(str(cnt))
            best = min(best, add + dp(j + 1, k_left - del_cnt))
        return best

    return dp(0, k)

