def stone_game_v(stone_value: List[int]) -> int:
    n = len(stone_value)
    if n < 2:
        return 0
    prefix = [0] * (n + 1)
    for i, v in enumerate(stone_value):
        prefix[i + 1] = prefix[i] + v
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            total = prefix[j + 1] - prefix[i]
            lo, hi = i, j - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                left = prefix[mid + 1] - prefix[i]
                if left * 2 <= total:
                    lo = mid
                else:
                    hi = mid - 1
            best = 0
            for k in (lo, lo + 1):
                if k < i or k >= j:
                    continue
                left = prefix[k + 1] - prefix[i]
                right = total - left
                if left < right:
                    val = left + dp[i][k]
                elif left > right:
                    val = right + dp[k + 1][j]
                else:
                    val = left + max(dp[i][k], dp[k + 1][j])
                if val > best:
                    best = val
            dp[i][j] = best
    return dp[0][n - 1]

