def detect_cycle(grid: List[List[str]]) -> bool:
    rows = len(grid)
    if rows == 0:
        return False
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(r: int, c: int, pr: int, pc: int, ch: str) -> bool:
        visited[r][c] = True
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                continue
            if grid[nr][nc] != ch:
                continue
            if nr == pr and nc == pc:
                continue
            if visited[nr][nc]:
                return True
            if dfs(nr, nc, r, c, ch):
                return True
        return False

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                if dfs(r, c, -1, -1, grid[r][c]):
                    return True
    return False

