def min_days(grid: List[List[int]]) -> int:
    m = len(grid)
    if m == 0:
        return 0
    n = len(grid[0])

    total = sum(cell for row in grid for cell in row)
    if total <= 1:
        return total

    def is_connected() -> bool:
        visited = [[False] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    start = (i, j)
                    break
            else:
                continue
            break
        stack = [start]
        visited[start[0]][start[1]] = True
        cnt = 0
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        while stack:
            x, y = stack.pop()
            cnt += 1
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 1 and not visited[nx][ny]:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
        return cnt == total

    if not is_connected():
        return 0

    disc = [[0] * n for _ in range(m)]
    low = [[0] * n for _ in range(m)]
    time = 0
    found = False
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(i: int, j: int, pi: int, pj: int) -> None:
        nonlocal time, found
        time += 1
        disc[i][j] = low[i][j] = time
        children = 0
        for dx, dy in dirs:
            ni, nj = i + dx, j + dy
            if not (0 <= ni < m and 0 <= nj < n) or grid[ni][nj] == 0:
                continue
            if disc[ni][nj] == 0:
                children += 1
                dfs(ni, nj, i, j)
                low[i][j] = min(low[i][j], low[ni][nj])
                if pi == -1 and children > 1:
                    found = True
                if pi != -1 and low[ni][nj] >= disc[i][j]:
                    found = True
            elif (ni, nj) != (pi, pj):
                low[i][j] = min(low[i][j], disc[ni][nj])

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j, -1, -1)
                break
        else:
            continue
        break

    return 1 if found else 2

