def detect_pattern(arr: List[int], m: int, k: int) -> bool:
    n = len(arr)
    if m * k > n:
        return False
    MOD = 1000000007
    BASE = 1000003
    prefix = [0] * (n + 1)
    power = [1] * (n + 1)
    for i in range(n):
        prefix[i + 1] = (prefix[i] * BASE + arr[i]) % MOD
        power[i + 1] = (power[i] * BASE) % MOD
    def get_hash(l: int, r: int) -> int:
        return (prefix[r] - (prefix[l] * power[r - l]) % MOD + MOD) % MOD
    repeat = [0] * n
    for i in range(n - m, -1, -1):
        if i + 2 * m <= n and get_hash(i, i + m) == get_hash(i + m, i + 2 * m):
            repeat[i] = repeat[i + m] + 1
        else:
            repeat[i] = 1
        if repeat[i] >= k:
            return True
    return False

