def max_num_edges_to_remove(n: int, edges: List[List[int]]) -> int:
    class DSU:
        __slots__ = ("parent", "rank", "components")
        def __init__(self, size: int):
            self.parent = list(range(size + 1))
            self.rank = [0] * (size + 1)
            self.components = size
        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, a: int, b: int) -> bool:
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            if self.rank[ra] == self.rank[rb]:
                self.rank[ra] += 1
            self.components -= 1
            return True

    alice = DSU(n)
    bob = DSU(n)
    used = 0

    for typ, u, v in edges:
        if typ == 3:
            merged_a = alice.union(u, v)
            merged_b = bob.union(u, v)
            if merged_a or merged_b:
                used += 1

    for typ, u, v in edges:
        if typ == 1:
            if alice.union(u, v):
                used += 1
        elif typ == 2:
            if bob.union(u, v):
                used += 1

    if alice.components != 1 or bob.components != 1:
        return -1
    return len(edges) - used

