def min_cost_connect_points(points: List[List[int]]) -> int:
    n = len(points)
    visited = [False] * n
    min_dist = [float('inf')] * n
    min_dist[0] = 0
    total_cost = 0

    for _ in range(n):
        u = -1
        best = float('inf')
        for j in range(n):
            if not visited[j] and min_dist[j] < best:
                best = min_dist[j]
                u = j

        visited[u] = True
        total_cost += best

        for v in range(n):
            if not visited[v]:
                dist = abs(points[u][0] - points[v][0]) + abs(points[u][1] - points[v][1])
                if dist < min_dist[v]:
                    min_dist[v] = dist

    return total_cost

