def count_unhappy_friends(n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
    partner = [0] * n
    for a, b in pairs:
        partner[a] = b
        partner[b] = a

    rank = [[0] * n for _ in range(n)]
    for i in range(n):
        lst = preferences[i]
        for pos, friend in enumerate(lst):
            rank[i][friend] = pos

    unhappy = [False] * n

    for x, y in pairs:
        for u in preferences[x]:
            if u == y:
                break
            v = partner[u]
            if rank[u][x] < rank[u][v]:
                unhappy[x] = True
                break
        for u in preferences[y]:
            if u == x:
                break
            v = partner[u]
            if rank[u][y] < rank[u][v]:
                unhappy[y] = True
                break

    return sum(1 for flag in unhappy if flag)

