def min_subarray(nums: list[int], p: int) -> int:
    total = 0
    for i in range(len(nums)):
        total = (total + nums[i]) % p
    target = total
    if target == 0:
        return 0
    prefix = 0
    best = len(nums)
    first_idx = {0: -1}
    for i in range(len(nums)):
        prefix = (prefix + nums[i]) % p
        need = (prefix - target + p) % p
        if need in first_idx:
            length = i - first_idx[need]
            if length < best:
                best = length
        first_idx[prefix] = i
    return best if best != len(nums) else -1

def max_unique_split(s: str) -> int:
    n = len(s)
    best = 0
    used = set()

    def dfs(pos: int, cnt: int) -> None:
        nonlocal best
        if pos == n:
            if cnt > best:
                best = cnt
            return
        if cnt + (n - pos) <= best:
            return
        for i in range(pos + 1, n + 1):
            sub = s[pos:i]
            if sub not in used:
                used.add(sub)
                dfs(i, cnt + 1)
                used.remove(sub)

    dfs(0, 0)
    return best

