def is_printable(target_grid: List[List[int]]) -> bool:
    m = len(target_grid)
    if m == 0:
        return True
    n = len(target_grid[0])
    rect: Dict[int, List[int]] = {}
    for r in range(m):
        for c in range(n):
            col = target_grid[r][c]
            if col == 0:
                continue
            if col not in rect:
                rect[col] = [r, r, c, c]
            else:
                cur = rect[col]
                cur[0] = min(cur[0], r)
                cur[1] = max(cur[1], r)
                cur[2] = min(cur[2], c)
                cur[3] = max(cur[3], c)

    colors = list(rect.keys())
    indegree: Dict[int, int] = {col: 0 for col in colors}
    graph: Dict[int, Set[int]] = {col: set() for col in colors}

    for col in colors:
        min_r, max_r, min_c, max_c = rect[col]
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                inner = target_grid[r][c]
                if inner != col and inner != 0:
                    if inner not in graph[col]:
                        graph[col].add(inner)
                        indegree[inner] += 1

    queue = deque([col for col in colors if indegree[col] == 0])
    visited = 0
    while queue:
        cur = queue.popleft()
        visited += 1
        for nxt in graph[cur]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)

    return visited == len(colors)

