def minimum_cost(cost: List[List[int]]) -> int:
    n = len(cost)
    m = len(cost[0])
    INF = 10 ** 15
    full_mask = (1 << m) - 1

    # precompute minimal cost for each column (group2 point)
    min_col = [min(cost[i][j] for i in range(n)) for j in range(m)]

    dp = [INF] * (1 << m)
    dp[0] = 0

    for i in range(n):
        ndp = [INF] * (1 << m)
        row = cost[i]

        # connect current point i to at least one point in group2
        for mask in range(1 << m):
            cur = dp[mask]
            if cur == INF:
                continue
            for j in range(m):
                new_mask = mask | (1 << j)
                val = cur + row[j]
                if val < ndp[new_mask]:
                    ndp[new_mask] = val

        # allow adding extra connections from i to already covered points
        for mask in range(1 << m):
            cur = ndp[mask]
            if cur == INF:
                continue
            for j in range(m):
                new_mask = mask | (1 << j)
                val = cur + row[j]
                if val < ndp[new_mask]:
                    ndp[new_mask] = val

        dp = ndp

    answer = INF
    for mask in range(1 << m):
        cur = dp[mask]
        if cur == INF:
            continue
        extra = 0
        for j in range(m):
            if not (mask & (1 << j)):
                extra += min_col[j]
        total = cur + extra
        if total < answer:
            answer = total

    return answer

