def is_even_odd_tree(root):
    if not root:
        return True
    from collections import deque
    q = deque([root])
    level = 0
    while q:
        sz = len(q)
        prev = float('-inf') if level % 2 == 0 else float('inf')
        for _ in range(sz):
            node = q.popleft()
            if level % 2 == 0:
                if node.val % 2 == 0 or node.val <= prev:
                    return False
            else:
                if node.val % 2 == 1 or node.val >= prev:
                    return False
            prev = node.val
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        level += 1
    return True

import math

def visible_points(points, angle, location):
    loc_x, loc_y = location
    same_place = 0
    angles = []
    for x, y in points:
        dx = x - loc_x
        dy = y - loc_y
        if dx == 0 and dy == 0:
            same_place += 1
            continue
        deg = math.atan2(dy, dx) * 180 / math.pi
        if deg < 0:
            deg += 360
        angles.append(deg)
    if not angles:
        return same_place
    if angle >= 360:
        return len(points)
    angles.sort()
    extended = angles + [v + 360 for v in angles]
    max_in_window = 0
    left = 0
    for right in range(len(extended)):
        while extended[right] - extended[left] > angle + 1e-9:
            left += 1
        window_size = right - left + 1
        if window_size > max_in_window:
            max_in_window = window_size
    return max_in_window + same_place

