def coordinate_with_max_network_quality(towers: List[List[int]], radius: int) -> List[int]:
    min_x = float('inf')
    max_x = float('-inf')
    min_y = float('inf')
    max_y = float('-inf')
    for tower in towers:
        x, y = tower[0], tower[1]
        if x < min_x:
            min_x = x
        if x > max_x:
            max_x = x
        if y < min_y:
            min_y = y
        if y > max_y:
            max_y = y
    best_quality = -1
    best_x = 0
    best_y = 0
    for x in range(min_x - radius, max_x + radius + 1):
        for y in range(min_y - radius, max_y + radius + 1):
            total = 0
            for tower in towers:
                tx, ty, q = tower[0], tower[1], tower[2]
                dx = x - tx
                dy = y - ty
                dist = sqrt(dx * dx + dy * dy)
                if dist <= radius:
                    total += floor(q / (1 + dist))
            if total > best_quality or (total == best_quality and (x < best_x or (x == best_x and y < best_y))):
                best_quality = total
                best_x = x
                best_y = y
    return [best_x, best_y]

