def best_team_score(scores: List[int], ages: List[int]) -> int:
    n = len(scores)
    if n == 0:
        return 0

    players = list(zip(ages, scores))
    players.sort(key=lambda x: (x[0], x[1]))

    # Coordinate compression of scores
    unique_scores = sorted({s for _, s in players})
    index = {s: i + 1 for i, s in enumerate(unique_scores)}  # 1-based for BIT

    size = len(unique_scores) + 2

    bit = [0] * size

    def bit_update(i: int, val: int) -> None:
        while i < size:
            if val > bit[i]:
                bit[i] = val
            i += i & -i

    def bit_query(i: int) -> int:
        res = 0
        while i > 0:
            if bit[i] > res:
                res = bit[i]
            i -= i & -i
        return res

    best = 0
    for _, score in players:
        idx = index[score]
        cur = bit_query(idx) + score
        if cur > best:
            best = cur
        bit_update(idx, cur)

    return best

