def are_connected(n: int, threshold: int, queries: List[Tuple[int, int]]) -> List[bool]:
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for d in range(threshold + 1, n + 1):
        for multiple in range(d * 2, n + 1, d):
            union(d, multiple)

    ans = [False] * len(queries)
    for i, (a, b) in enumerate(queries):
        ans[i] = find(a) == find(b)
    return ans

