from collections import defaultdict

def matrix_rank_transform(matrix: List[List[int]]) -> List[List[int]]:
    m, n = len(matrix), len(matrix[0])
    # Map each value to its positions
    val_pos = defaultdict(list)
    for i in range(m):
        for j in range(n):
            val_pos[matrix[i][j]].append((i, j))

    # Current maximum rank for each row and column
    row_max = [0] * m
    col_max = [0] * n
    answer = [[0] * n for _ in range(m)]

    # Union‑Find structures (size = m * n)
    parent = [i for i in range(m * n)]
    rank = [0] * (m * n)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Process values in increasing order
    for value in sorted(val_pos):
        positions = val_pos[value]

        # Re‑initialize DSU for the current set of cells
        for i, j in positions:
            idx = i * n + j
            parent[idx] = idx
            rank[idx] = 0

        # Union cells that share a row or a column
        row_rep = {}
        col_rep = {}
        for i, j in positions:
            idx = i * n + j
            if i not in row_rep:
                row_rep[i] = idx
            else:
                union(idx, row_rep[i])
            if j not in col_rep:
                col_rep[j] = idx
            else:
                union(idx, col_rep[j])

        # Determine the rank for each component
        comp_rank = {}
        for i, j in positions:
            idx = i * n + j
            root = find(idx)
            needed = 1 + max(row_max[i], col_max[j])
            if root not in comp_rank or needed > comp_rank[root]:
                comp_rank[root] = needed

        # Assign ranks and update row/column maxima
        for i, j in positions:
            idx = i * n + j
            root = find(idx)
            r = comp_rank[root]
            answer[i][j] = r
            row_max[i] = r
            col_max[j] = r

    return answer
# TIME: O(m*n log(m*n)) SPACE: O(m*n)

