def count_substrings(s: str, t: str) -> int:
    n, m = len(s), len(t)
    pre = [[0] * (m + 1) for _ in range(n + 1)]
    post = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if s[i] == t[j]:
                pre[i + 1][j + 1] = pre[i][j] + 1

    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if s[i] == t[j]:
                post[i][j] = post[i + 1][j + 1] + 1

    ans = 0
    for i in range(n):
        for j in range(m):
            if s[i] != t[j]:
                ans += (pre[i][j] + 1) * (post[i + 1][j + 1] + 1)

    return ans

def kth_smallest_instruction(destination, k):
    row = destination[0]
    col = destination[1]
    v = row
    h = col
    kk = int(k)
    result = ''

    def ncr(n, r):
        if r < 0 or r > n:
            return 0
        if r > n - r:
            r = n - r
        res = 1
        for i in range(1, r + 1):
            res = res * (n - r + i) // i
        return res

    while v > 0 or h > 0:
        count_h = ncr(v + h - 1, v) if h > 0 else 0
        if h > 0 and kk <= count_h:
            result += 'H'
            h -= 1
        else:
            if h > 0:
                kk -= count_h
            result += 'V'
            v -= 1
    return result

