def furthest_building(heights, bricks, ladders):
    heap = []
    def heap_push(val):
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] <= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p
    def heap_pop():
        if len(heap) == 1:
            return heap.pop()
        min_val = heap[0]
        heap[0] = heap.pop()
        i = 0
        while True:
            l = i * 2 + 1
            r = i * 2 + 2
            smallest = i
            if l < len(heap) and heap[l] < heap[smallest]:
                smallest = l
            if r < len(heap) and heap[r] < heap[smallest]:
                smallest = r
            if smallest == i:
                break
            heap[i], heap[smallest] = heap[smallest], heap[i]
            i = smallest
        return min_val
    for i in range(len(heights) - 1):
        diff = heights[i + 1] - heights[i]
        if diff <= 0:
            continue
        heap_push(diff)
        if len(heap) > ladders:
            bricks -= heap_pop()
            if bricks < 0:
                return i
    return len(heights) - 1

