    max_val = 1
    for i in range(2, n + 1):
        if (i & 1) == 0:
            nums[i] = nums[i >> 1]
        else:
            k = i >> 1
            nums[i] = nums[k] + nums[k + 1]
        if nums[i] > max_val:
            max_val = nums[i]
    return max_val

