def can_distribute(nums: List[int], quantity: List[int]) -> bool:
    freq_map = {}
    for v in nums:
        freq_map[v] = freq_map.get(v, 0) + 1
    counts = list(freq_map.values())
    m = len(quantity)
    full_mask = (1 << m) - 1
    need = [0] * (1 << m)
    for mask in range(1, full_mask + 1):
        lsb = mask & -mask
        idx = lsb.bit_length() - 1
        need[mask] = need[mask ^ lsb] + quantity[idx]
    dp = [False] * (1 << m)
    dp[0] = True
    for c in counts:
        next_dp = dp[:]
        for mask in range(full_mask + 1):
            if not dp[mask]:
                continue
            remaining = full_mask ^ mask
            sub = remaining
            while sub:
                if need[sub] <= c:
                    next_dp[mask | sub] = True
                sub = (sub - 1) & remaining
        dp = next_dp
    return dp[full_mask]

def decrypt(code: list[int], k: int) -> list[int]:
    n = len(code)
    result = [0] * n
    if k == 0:
        return result
    if k > 0:
        window_sum = 0
        for i in range(1, k + 1):
            window_sum += code[i % n]
        for i in range(n):
            result[i] = window_sum
            window_sum -= code[(i + 1) % n]
            window_sum += code[(i + k + 1) % n]
    else:
        m = -k
        window_sum = 0
        for i in range(m):
            window_sum += code[(n - 1 - i + n) % n]
        for i in range(n):
            result[i] = window_sum
            window_sum -= code[(i - m + n) % n]
            window_sum += code[i]
    return result

