    total = 0
    for i in range(n):
        total += nums[i]
    target = total - x
    if target == 0:
        return n
    left = 0
    window_sum = 0
    max_len = -1
    for right in range(n):
        window_sum += nums[right]
        while window_sum > target and left <= right:
            window_sum -= nums[left]
            left += 1
        if window_sum == target:
            cur_len = right - left + 1
            if cur_len > max_len:
                max_len = cur_len
    return n - max_len if max_len != -1 else -1

