def get_maximum_grid_happiness(m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
    pow3 = [3 ** i for i in range(n)]

    def set_digit(mask: int, idx: int, val: int) -> int:
        cur = (mask // pow3[idx]) % 3
        return mask + (val - cur) * pow3[idx]

    def delta(new_type: int, up_type: int, left_type: int) -> int:
        total = 120 if new_type == 1 else 40
        for nb in (up_type, left_type):
            if nb == 0:
                continue
            if new_type == 1 and nb == 1:
                total += -60
            elif new_type == 1 and nb == 2:
                total += -10
            elif new_type == 2 and nb == 1:
                total += -10
            elif new_type == 2 and nb == 2:
                total += 40
        return total

    from functools import lru_cache

    @lru_cache(None)
    def dfs(pos: int, mask: int, i_left: int, e_left: int, left: int) -> int:
        if pos == m * n or (i_left == 0 and e_left == 0):
            return 0
        r, c = divmod(pos, n)
        up = (mask // pow3[c]) % 3

        # option 1: leave empty
        best = dfs(pos + 1, set_digit(mask, c, 0), i_left, e_left, 0 if c == n - 1 else 0)

        # option 2: place introvert
        if i_left > 0:
            new_mask = set_digit(mask, c, 1)
            add = delta(1, up, left)
            nxt_left = 0 if c == n - 1 else 1
            best = max(best, add + dfs(pos + 1, new_mask, i_left - 1, e_left, nxt_left))

        # option 3: place extrovert
        if e_left > 0:
            new_mask = set_digit(mask, c, 2)
            add = delta(2, up, left)
            nxt_left = 0 if c == n - 1 else 2
            best = max(best, add + dfs(pos + 1, new_mask, i_left, e_left - 1, nxt_left))

        return best

    return dfs(0, 0, introvertsCount, extrovertsCount, 0)

