    inc = [0] * n
    dec = [0] * n

    tails = []
    for i, x in enumerate(nums):
        l, r = 0, len(tails)
        while l < r:
            m = (l + r) >> 1
            if tails[m] < x:
                l = m + 1
            else:
                r = m
        pos = l
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
        inc[i] = pos + 1

    tails = []
    for i in range(n - 1, -1, -1):
        x = nums[i]
