class FrontMiddleBackQueue:
    def __init__(self):
        self.left = deque()
        self.right = deque()
    def pushFront(self, val: int) -> None:
        self.left.appendleft(val)
        if len(self.left) > len(self.right) + 1:
            self.right.appendleft(self.left.pop())
    def pushMiddle(self, val: int) -> None:
        if len(self.left) > len(self.right):
            self.right.appendleft(self.left.pop())
        self.left.append(val)
    def pushBack(self, val: int) -> None:
        self.right.append(val)
        if len(self.left) < len(self.right):
            self.left.append(self.right.popleft())
    def popFront(self) -> int:
        if not self.left and not self.right: return -1
        val = self.left.popleft() if self.left else self.right.popleft()
        if len(self.left) < len(self.right):
            self.left.append(self.right.popleft())
        return val
    def popMiddle(self) -> int:
        if not self.left and not self.right: return -1
        val = self.left.pop()
        if len(self.left) < len(self.right):
            self.left.append(self.right.popleft())
        return val
    def popBack(self) -> int:
        if not self.left and not self.right: return -1
        val = self.right.pop() if self.right else self.left.pop()
        if len(self.left) > len(self.right) + 1:
            self.right.appendleft(self.left.pop())
        return val

def minimum_deviation(nums: list[int]) -> int:
    heap: list[int] = []
    def peek() -> int:
        return heap[0]
    def push(val: int) -> None:
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] >= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p
    def pop() -> int:
        top = heap[0]
        last = heap.pop()
        if not heap:
            return top
        heap[0] = last
        i = 0
        while True:
            l = i * 2 + 1
            r = i * 2 + 2
            largest = i
            if l < len(heap) and heap[l] > heap[largest]:
                largest = l
            if r < len(heap) and heap[r] > heap[largest]:
                largest = r
            if largest == i:
                break
            heap[i], heap[largest] = heap[largest], heap[i]
            i = largest
        return top

    min_val = float('inf')
    for x in nums:
        if x % 2 == 1:
            x *= 2
        push(x)
        if x < min_val:
            min_val = x

    answer = peek() - min_val

    while peek() % 2 == 0:
        max_val = pop()
        new_val = max_val // 2
        push(new_val)
        if new_val < min_val:
            min_val = new_val
        cur_dev = peek() - min_val
        if cur_dev < answer:
            answer = cur_dev

    return answer

