def min_incompatibility(nums, k):
    n = len(nums)
    g = n // k
    freq = {}
    for v in nums:
        freq[v] = freq.get(v, 0) + 1
        if freq[v] > k:
            return -1
    total_mask = 1 << n
    inc = [-1] * total_mask
    def popcnt(x):
        c = 0
        while x:
            x &= x - 1
            c += 1
        return c
    for mask in range(total_mask):
        if popcnt(mask) != g:
            continue
        mn = float('inf')
        mx = -float('inf')
        seen = set()
        ok = True
        i = 0
        m = mask
        while m:
            if m & 1:
                v = nums[i]
                if v in seen:
                    ok = False
                    break
                seen.add(v)
                if v < mn:
                    mn = v
                if v > mx:
                    mx = v
            i += 1
            m >>= 1
        if ok:
            inc[mask] = mx - mn
    INF = 10**9
    dp = [INF] * total_mask
    dp[0] = 0
    for mask in range(1, total_mask):
        if popcnt(mask) % g != 0:
            continue
        sub = mask
        while sub:
            cost = inc[sub]
            if cost != -1:
                prev = dp[mask ^ sub]
                if prev + cost < dp[mask]:
                    dp[mask] = prev + cost
            sub = (sub - 1) & mask
    ans = dp[total_mask - 1]
    return -1 if ans >= INF else ans

