def check_edge_limited_paths(n: int, edge_list: List[List[int]], queries: List[List[int]]) -> List[bool]:
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    edge_list.sort(key=lambda e: e[2])
    queries_with_idx = [{'p': q[0], 'q': q[1], 'limit': q[2], 'idx': i} for i, q in enumerate(queries)]
    queries_with_idx.sort(key=lambda x: x['limit'])

    answer = [False] * len(queries)
    e_idx = 0

    for item in queries_with_idx:
        p, q, limit, idx = item['p'], item['q'], item['limit'], item['idx']
        while e_idx < len(edge_list) and edge_list[e_idx][2] < limit:
            union(edge_list[e_idx][0], edge_list[e_idx][1])
            e_idx += 1
        answer[idx] = find(p) == find(q)

    return answer

