def ways_to_split(nums: List[int]) -> int:
    n = len(nums)
    if n < 3:
        return 0
    prefix = [0] * (n + 1)
    for i, v in enumerate(nums):
        prefix[i + 1] = prefix[i] + v
    total = prefix[n]
    ans = 0
    low = 1
    high = 1
    for i in range(1, n - 1):
        left_sum = prefix[i]
        if low < i:
            low = i
        if high < low:
            high = low
        while low < n - 1 and prefix[low + 1] - prefix[i] < left_sum:
            low += 1
        while high < n - 1 and prefix[high + 1] - prefix[i] <= total - prefix[high + 1]:
            high += 1
        if low <= high - 1:
            ans = (ans + (high - low)) % MOD
    return ans

