def construct_largest_sequence(n: int) -> List[int]:
    length = 2 * n - 1
    seq = [0] * length
    placed = [False] * (n + 1)

    def dfs(pos: int) -> bool:
        # move to next empty position
        while pos < length and seq[pos] != 0:
            pos += 1
        if pos == length:
            return True  # all filled

        for k in range(n, 0, -1):
            if placed[k]:
                continue
            if k == 1:
                # place the single 1
                seq[pos] = 1
                placed[1] = True
                if dfs(pos + 1):
                    return True
                placed[1] = False
                seq[pos] = 0
            else:
                if pos + k < length and seq[pos + k] == 0:
                    seq[pos] = k
                    seq[pos + k] = k
                    placed[k] = True
                    if dfs(pos + 1):
                        return True
                    placed[k] = False
                    seq[pos] = 0
                    seq[pos + k] = 0
        return False

    dfs(0)
    return seq

