def minimum_hamming_distance(source: List[int], target: List[int], allowed_swaps: List[Tuple[int, int]]) -> int:
    n = len(source)
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    for a, b in allowed_swaps:
        union(a, b)

    groups = {}
    for i in range(n):
        root = find(i)
        groups.setdefault(root, []).append(i)

    mismatches = 0
    for indices in groups.values():
        freq = {}
        for idx in indices:
            val = source[idx]
            freq[val] = freq.get(val, 0) + 1
        for idx in indices:
            val = target[idx]
            if freq.get(val, 0) > 0:
                freq[val] -= 1
            else:
                mismatches += 1
