def number_of_ways(pairs: List[List[int]]) -> int:
    adj: Dict[int, Set[int]] = {}
    nodes: Set[int] = set()
    for x, y in pairs:
        nodes.add(x)
        nodes.add(y)
        adj.setdefault(x, set()).add(y)
        adj.setdefault(y, set()).add(x)
    for v in nodes:
        adj.setdefault(v, set())
    n = len(nodes)
    root_candidates = [v for v in nodes if len(adj[v]) == n - 1]
    if not root_candidates:
        return 0
    if len(root_candidates) > 1:
        return 2
    root = root_candidates[0]
    multiple = False
    masks: Dict[int, Set[int]] = {v: adj[v] | {v} for v in nodes}
    for v in nodes:
        if v == root:
            continue
        best_deg = None
        cnt_best = 0
        for u in adj[v]:
            if not masks[v].issubset(masks[u]):
                continue
            deg_u = len(adj[u])
            if best_deg is None or deg_u < best_deg:
                best_deg = deg_u
                cnt_best = 1
            elif deg_u == best_deg:
                cnt_best += 1
        if best_deg is None:
            return 0
        if cnt_best > 1:
            multiple = True
    return 2 if multiple else 1

