    bad_users = set()
    for u, v in friendships:
        a = u - 1
        b = v - 1
        share = False
        for lang in user_lang[a]:
            if lang in user_lang[b]:
                share = True
                break
        if not share:
            bad_users.add(a)
            bad_users.add(b)
    if not bad_users:
        return 0
    answer = float('inf')
    for L in range(1, n + 1):
        teach = 0
        for u in bad_users:
            if L not in user_lang[u]:
                teach += 1
        if teach < answer:
            answer = teach
