from functools import lru_cache

def cat_and_mouse(grid: List[str], catJump: int, mouseJump: int) -> bool:
    rows, cols = len(grid), len(grid[0])
    mouse_start = cat_start = food = (0, 0)
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'M':
                mouse_start = (r, c)
            elif ch == 'C':
                cat_start = (r, c)
            elif ch == 'F':
                food = (r, c)

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def generate_moves(pos: Tuple[int, int], jump: int) -> List[Tuple[int, int]]:
        r, c = pos
        moves = [(r, c)]  # staying in place is always allowed
        for dr, dc in dirs:
            nr, nc = r, c
            for _ in range(jump):
                nr += dr
                nc += dc
                if not (0 <= nr < rows and 0 <= nc < cols):
                    break
                if grid[nr][nc] == '#':
                    break
                moves.append((nr, nc))
        return moves

    mouse_moves_cache = {}
    cat_moves_cache = {}

    def get_moves(pos: Tuple[int, int], jump: int, cache: dict) -> List[Tuple[int, int]]:
        if pos not in cache:
            cache[pos] = generate_moves(pos, jump)
        return cache[pos]

    max_steps = 2 * rows * cols  # sufficient bound to avoid infinite loops

    @lru_cache(None)
    def dfs(m_pos: Tuple[int, int], c_pos: Tuple[int, int], turn: int, steps: int) -> bool:
        # turn: 0 -> mouse, 1 -> cat
        if m_pos == food:
            return True
        if c_pos == food or c_pos == m_pos:
            return False
        if steps > max_steps:
            return False

        if turn == 0:  # mouse's move
            for nxt in get_moves(m_pos, mouseJump, mouse_moves_cache):
                if nxt == c_pos:  # moving onto cat means immediate capture
                    continue
                if dfs(nxt, c_pos, 1, steps + 1):
                    return True
            return False
        else:  # cat's move
            for nxt in get_moves(c_pos, catJump, cat_moves_cache):
                if nxt == m_pos or nxt == food:
                    return False
                if not dfs(m_pos, nxt, 0, steps + 1):
                    return False
            return True

    return dfs(mouse_start, cat_start, 0, 0)

