def min_characters(a: str, b: str) -> int:
    if not a or not b:
        return 0

    cnt_a = [0] * 26
    cnt_b = [0] * 26
    for ch in a:
        cnt_a[ord(ch) - 97] += 1
    for ch in b:
        cnt_b[ord(ch) - 97] += 1

    n_a = len(a)
    n_b = len(b)

    pref_a = [0] * 26
    pref_b = [0] * 26
    cur = 0
    for i in range(26):
        cur += cnt_a[i]
        pref_a[i] = cur
    cur = 0
    for i in range(26):
        cur += cnt_b[i]
        pref_b[i] = cur

    best_same = 0
    for i in range(26):
        best_same = max(best_same, cnt_a[i] + cnt_b[i])
    ans = n_a + n_b - best_same

    for s in range(25):
        changes1 = (n_a - pref_a[s]) + pref_b[s]
        if changes1 < ans:
            ans = changes1
        changes2 = (n_b - pref_b[s]) + pref_a[s]
        if changes2 < ans:
            ans = changes2

    return ans

