MOD = 10**9 + 7

def count_ways(queries: List[List[int]]) -> List[int]:
    if not queries:
        return []

    # maximum k to know how far to sieve for primes
    max_k = max(k for _, k in queries)

    # sieve primes up to sqrt(max_k)
    limit = int(max_k ** 0.5) + 1
    is_prime = [True] * (limit + 1)
    primes: List[int] = []
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            step = p
            start = p * p
            for multiple in range(start, limit + 1, step):
                is_prime[multiple] = False

    def prime_exponents(k: int) -> List[int]:
        exps: List[int] = []
        for p in primes:
            if p * p > k:
                break
            if k % p == 0:
                cnt = 0
                while k % p == 0:
                    k //= p
                    cnt += 1
                exps.append(cnt)
        if k > 1:
            exps.append(1)
        return exps

    def comb_small_k(n: int, k: int) -> int:
        """Compute C(n, k) mod MOD where k is small (k <= ~30)."""
        if k < 0 or k > n:
            return 0
        k = min(k, n - k)
        if k == 0:
            return 1
        res = 1
        for i in range(1, k + 1):
            res = res * (n - k + i) % MOD
            res = res * pow(i, MOD - 2, MOD) % MOD
        return res

    answers: List[int] = []
    for n, k in queries:
        if k == 1:
            answers.append(1)
            continue
        exps = prime_exponents(k)
        ways = 1
        for e in exps:
            # distribute e identical prime factors among n positions
            ways = ways * comb_small_k(e + n - 1, n - 1) % MOD
        answers.append(ways)

    return answers
# TIME: O(Q * sqrt(max_k) + total_exponents * log MOD) SPACE: O(sqrt(max_k))

def check_partitioning(s: str) -> bool:
    n = len(s)
    if n < 3:
        return False
    pref = [False] * (n + 1)
    suff = [False] * (n + 1)

    for c in range(n):
        l = r = c
        while l >= 0 and r < n and s[l] == s[r]:
            if l == 0:
                pref[r + 1] = True
            l -= 1
            r += 1
        l = c
        r = c + 1
        while l >= 0 and r < n and s[l] == s[r]:
            if l == 0:
                pref[r + 1] = True
            l -= 1
            r += 1

    for c in range(n):
        l = r = c
        while l >= 0 and r < n and s[l] == s[r]:
            if r == n - 1:
                suff[l] = True
            l -= 1
            r += 1
        l = c
        r = c + 1
        while l >= 0 and r < n and s[l] == s[r]:
            if r == n - 1:
                suff[l] = True
            l -= 1
            r += 1

    for c in range(n):
        l = r = c
        while l >= 0 and r < n and s[l] == s[r]:
            if l > 0 and r + 1 < n and pref[l] and suff[r + 1]:
                return True
            l -= 1
            r += 1
        l = c
        r = c + 1
        while l >= 0 and r < n and s[l] == s[r]:
            if l > 0 and r + 1 < n and pref[l] and suff[r + 1]:
                return True
            l -= 1
            r += 1
    return False

