        adj[a].append(b)
        adj[b].append(a)
    start = None
    for val, neigh in adj.items():
        if len(neigh) == 1:
            start = val
            break
    n = len(adjacent_pairs) + 1
    result = [0] * n
    result[0] = start
    result[1] = adj[start][0]
    for i in range(2, n):
