def closest_subsequence_sum(nums: List[int], goal: int) -> int:
    mid = len(nums) // 2
    left = nums[:mid]
    right = nums[mid:]

    def all_sums(arr: List[int]) -> List[int]:
        n = len(arr)
        total = 1 << n
        sums = [0] * total
        for mask in range(total):
            s = 0
            for i in range(n):
                if mask & (1 << i):
                    s += arr[i]
            sums[mask] = s
        return sums

    left_sums = all_sums(left)
    right_sums = all_sums(right)
    right_sums.sort()

    best = float('inf')
    for sL in left_sums:
        need = goal - sL
        lo, hi = 0, len(right_sums)
        while lo < hi:
            mid_idx = (lo + hi) >> 1
            if right_sums[mid_idx] < need:
                lo = mid_idx + 1
            else:
                hi = mid_idx
        if lo < len(right_sums):
            cur = abs(sL + right_sums[lo] - goal)
            if cur < best:
                best = cur
        if lo > 0:
            cur = abs(sL + right_sums[lo - 1] - goal)
            if cur < best:
                best = cur
        if best == 0:
            return 0
    return int(best)

