def closest_dessert_cost(base_costs: List[int], topping_costs: List[int], target: int) -> int:
    topping_sums = []

    def dfs(i: int, cur: int) -> None:
        if i == len(topping_costs):
            topping_sums.append(cur)
            return
        dfs(i + 1, cur)
        dfs(i + 1, cur + topping_costs[i])
        dfs(i + 1, cur + 2 * topping_costs[i])

    dfs(0, 0)
    topping_sums.sort()

    best = float('inf')

    def update(cost: int) -> None:
        nonlocal best
        diff = abs(cost - target)
        best_diff = abs(best - target)
        if diff < best_diff or (diff == best_diff and cost < best):
            best = cost

    for base in base_costs:
        need = target - base
        lo, hi = 0, len(topping_sums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if topping_sums[mid] < need:
                lo = mid + 1
            else:
                hi = mid - 1
        if lo < len(topping_sums):
            update(base + topping_sums[lo])
        if hi >= 0:
            update(base + topping_sums[hi])

    return best

