def min_operations(nums1: List[int], nums2: List[int]) -> int:
    sum1, sum2 = sum(nums1), sum(nums2)
    if sum1 == sum2:
        return 0
    # Ensure sum1 is the smaller one
    if sum1 > sum2:
        nums1, nums2 = nums2, nums1
        sum1, sum2 = sum2, sum1
    diff = sum2 - sum1
    cnt = [0] * 6  # indices 0..5, we use 1..5 for possible gains
    for v in nums1:
        gain = 6 - v
        if gain:
            cnt[gain] += 1
    for v in nums2:
        gain = v - 1
        if gain:
            cnt[gain] += 1
    total_gain = sum(i * cnt[i] for i in range(1, 6))
    if total_gain < diff:
        return -1
    ops = 0
    for g in range(5, 0, -1):
        if diff <= 0:
            break
        if cnt[g] == 0:
            continue
        need = (diff + g - 1) // g
        use = cnt[g] if cnt[g] < need else need
        diff -= use * g
        ops += use
    return ops

