        graph[v].append((u, w))

    dist = [float('inf')] * (n + 1)
    dist[n] = 0
    heap = []

    def heap_push(item):
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p][0] <= heap[i][0]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop():
        if not heap:
            return None
        top = heap[0]
        end = heap.pop()
        if heap:
            heap[0] = end
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                smallest = i
                if l < len(heap) and heap[l][0] < heap[smallest][0]:
                    smallest = l
                if r < len(heap) and heap[r][0] < heap[smallest][0]:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return top

    heap_push((0, n))
    while heap:
        d, u = heap_pop()
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heap_push((nd, v))

    memo = [-1] * (n + 1)

    def dfs(u):
        if u == n:
            return 1
        if memo[u] != -1:
            return memo[u]
        total = 0
        for v, _ in graph[u]:
            if dist[v] < dist[u]:
                total = (total + dfs(v)) % MOD
        memo[u] = total
        return total

    return dfs(1)

