def min_changes(nums: List[int], k: int) -> int:
    if k == 0:
        return 0
    period = k
    groups: List[List[int]] = [[] for _ in range(period)]
    for i, v in enumerate(nums):
        groups[i % period].append(v)

    INF = 10 ** 9
    dp = [INF] * 1024
    dp[0] = 0

    for grp in groups:
        if not grp:
            continue
        size = len(grp)
        freq: dict[int, int] = {}
        for v in grp:
            freq[v] = freq.get(v, 0) + 1

        min_dp = min(dp)
        new_dp = [min_dp + size] * 1024

        for v, cnt in freq.items():
            cost = size - cnt
            for cur_xor in range(1024):
                cur_cost = dp[cur_xor]
                if cur_cost == INF:
                    continue
                nx = cur_xor ^ v
                cand = cur_cost + cost
                if cand < new_dp[nx]:
                    new_dp[nx] = cand
        dp = new_dp

    return dp[0]

