def max_average_ratio(classes: List[Tuple[int, int]], extra_students: int) -> float:
    def gain(p: int, t: int) -> float:
        return (p + 1) / (t + 1) - p / t

    heap: List[dict] = []

    def heap_swap(i: int, j: int) -> None:
        heap[i], heap[j] = heap[j], heap[i]

    def heap_push(node: dict) -> None:
        heap.append(node)
        idx = len(heap) - 1
        while idx > 0:
            parent = (idx - 1) >> 1
            if heap[parent]['gain'] >= heap[idx]['gain']:
                break
            heap_swap(parent, idx)
            idx = parent

    def heap_pop() -> dict:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            idx = 0
            while True:
                left = idx * 2 + 1
                right = left + 1
                largest = idx
                if left < len(heap) and heap[left]['gain'] > heap[largest]['gain']:
                    largest = left
                if right < len(heap) and heap[right]['gain'] > heap[largest]['gain']:
                    largest = right
                if largest == idx:
                    break
                heap_swap(idx, largest)
                idx = largest
        return top

    for p, t in classes:
        heap_push({'p': p, 't': t, 'gain': gain(p, t)})

    for _ in range(extra_students):
        best = heap_pop()
        best['p'] += 1
        best['t'] += 1
        best['gain'] = gain(best['p'], best['t'])
        heap_push(best)

    total = sum(node['p'] / node['t'] for node in heap)
    return round(total / len(classes), 5)

