def max_score(nums: List[int]) -> int:
    m = len(nums)
    full_mask = (1 << m) - 1

    def compute_gcd(a: int, b: int) -> int:
        while b != 0:
            a, b = b, a % b
        return a

    gcd = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            gcd[i][j] = compute_gcd(nums[i], nums[j])

    dp = [0] * (1 << m)

    for mask in range(full_mask + 1):
        used = mask.bit_count()
        if used % 2 != 0:
            continue
        op = used // 2 + 1

        i = 0
        while i < m and (mask >> i) & 1:
            i += 1
        if i == m:
            continue

        for j in range(i + 1, m):
            if (mask >> j) & 1:
                continue
            new_mask = mask | (1 << i) | (1 << j)
            candidate = dp[mask] + op * gcd[i][j]
            if candidate > dp[new_mask]:
                dp[new_mask] = candidate

    return dp[full_mask]

