def get_number_of_backlog_orders(orders: List[Tuple[int, int, int]]) -> int:
    MOD = 1_000_000_007
    buy_heap: List[dict] = []
    sell_heap: List[dict] = []

    def heap_push(heap: List[dict], node: dict, compare):
        heap.append(node)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if compare(heap[p], heap[i]):
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop(heap: List[dict], compare):
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = l + 1
                best = i
                if l < len(heap) and not compare(heap[best], heap[l]):
                    best = l
                if r < len(heap) and not compare(heap[best], heap[r]):
                    best = r
                if best == i:
                    break
                heap[i], heap[best] = heap[best], heap[i]
                i = best
        return top

    compare_buy = lambda a, b: a['price'] >= b['price']
    compare_sell = lambda a, b: a['price'] <= b['price']

    for price, amount, typ in orders:
        if typ == 0:  # BUY
            while amount > 0 and sell_heap and sell_heap[0]['price'] <= price:
                sell = sell_heap[0]
                matched = amount if amount < sell['amount'] else sell['amount']
                amount -= matched
                sell['amount'] -= matched
                if sell['amount'] == 0:
                    heap_pop(sell_heap, compare_sell)
            if amount > 0:
                heap_push(buy_heap, {'price': price, 'amount': amount}, compare_buy)
        else:  # SELL
            while amount > 0 and buy_heap and buy_heap[0]['price'] >= price:
                buy = buy_heap[0]
                matched = amount if amount < buy['amount'] else buy['amount']
                amount -= matched
                buy['amount'] -= matched
                if buy['amount'] == 0:
                    heap_pop(buy_heap, compare_buy)
            if amount > 0:
                heap_push(sell_heap, {'price': price, 'amount': amount}, compare_sell)

    total = 0
    for node in buy_heap:
        total = (total + node['amount']) % MOD
    for node in sell_heap:
        total = (total + node['amount']) % MOD
    return total

