def max_value(n: int, index: int, max_sum: int) -> int:
    def side_sum(val: int, length: int) -> int:
        if length == 0:
            return 0
        if val > length:
            # arithmetic series from val-1 down to val-length
            return length * (2 * val - length - 1) // 2
        # decreasing to 1 then flat
        descending = (val - 1) * val // 2
        return descending + (length - (val - 1))

    def can_achieve(x: int) -> bool:
        left = side_sum(x, index)
        right = side_sum(x, n - index - 1)
        return left + right + x <= max_sum

    low, high = 1, max_sum
    while low < high:
        mid = (low + high + 1) // 2
        if can_achieve(mid):
            low = mid
        else:
            high = mid - 1
    return low

