def count_pairs(nums: List[int], low: int, high: int) -> int:
    if not nums:
        return 0

    max_val = max(max(nums), high)
    max_bit = max_val.bit_length() - 1

    def count_le(bound: int) -> int:
        if bound < 0:
            return 0
        children: List[List[int]] = [[-1, -1]]
        cnt: List[int] = [0]

        def insert(num: int) -> None:
            node = 0
            for i in range(max_bit, -1, -1):
                bit = (num >> i) & 1
                nxt = children[node][bit]
                if nxt == -1:
                    children.append([-1, -1])
                    cnt.append(0)
                    nxt = len(children) - 1
                    children[node][bit] = nxt
                node = nxt
                cnt[node] += 1

        def query(num: int) -> int:
            node = 0
            total = 0
            for i in range(max_bit, -1, -1):
                if node == -1:
                    break
                bit_num = (num >> i) & 1
                bit_k = (bound >> i) & 1
                if bit_k == 1:
                    child = children[node][bit_num]
                    if child != -1:
                        total += cnt[child]
                    node = children[node][1 - bit_num]
                else:
                    node = children[node][bit_num]
            if node != -1:
                total += cnt[node]
            return total

        ans = 0
        for num in nums:
            ans += query(num)
            insert(num)
        return ans

    return count_le(high) - count_le(low - 1)

