def max_nice_divisors(prime_factors: int) -> int:
    MOD = 1000000007

    def mod_pow(base: int, exp: int) -> int:
        res = 1
        base %= MOD
        while exp > 0:
            if exp & 1:
                res = (res * base) % MOD
            base = (base * base) % MOD
            exp >>= 1
        return res

    if prime_factors == 1:
        return 1

    a = prime_factors // 3
    r = prime_factors % 3

    if r == 0:
        return mod_pow(3, a)
    if r == 1:
        return (mod_pow(3, a - 1) * 4) % MOD
    return (mod_pow(3, a) * 2) % MOD

