def min_absolute_sum_diff(nums1: List[int], nums2: List[int]) -> int:
    MOD = 1_000_000_007
    n = len(nums1)
    sorted_nums = sorted(nums1)

    def lower_bound(arr: List[int], target: int) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    total_diff = 0
    best_gain = 0

    for i in range(n):
        a = nums1[i]
        b = nums2[i]
        cur_diff = abs(a - b)
        total_diff = (total_diff + cur_diff) % MOD

        pos = lower_bound(sorted_nums, b)
        min_diff = cur_diff

        if pos < n:
            cand = abs(sorted_nums[pos] - b)
            if cand < min_diff:
                min_diff = cand
        if pos > 0:
            cand = abs(sorted_nums[pos - 1] - b)
            if cand < min_diff:
                min_diff = cand

        gain = cur_diff - min_diff
        if gain > best_gain:
            best_gain = gain

    answer = (total_diff - best_gain + MOD) % MOD
    return answer

