MOD = 10**9 + 7

def min_operations_to_make_string_sorted(s: str) -> int:
    n = len(s)
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD
    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - MOD // i * inv[MOD % i] % MOD

    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1

    total = fact[n]
    for c in cnt:
        total = total * inv_fact[c] % MOD

    ans = 0
    remaining = n
    for ch in s:
        idx = ord(ch) - 97
        for c in range(idx):
            if cnt[c]:
                ans = (ans + total * cnt[c] % MOD * inv[remaining]) % MOD
        total = total * cnt[idx] % MOD * inv[remaining] % MOD
        cnt[idx] -= 1
        remaining -= 1

    return ans % MOD

