import bisect

class MKAverage:
    def __init__(self, m: int, k: int):
        self.m = m
        self.k = k
        self.window = []
        self.sorted = []
    def addElement(self, num: int) -> None:
        self.window.append(num)
        bisect.insort(self.sorted, num)
        if len(self.window) > self.m:
            removed = self.window.pop(0)
            idx = bisect.bisect_left(self.sorted, removed)
            self.sorted.pop(idx)
    def calculateMKAverage(self) -> int:
        if len(self.window) < self.m:
            return -1
        mid = self.sorted[self.k : self.m - self.k]
        return sum(mid) // len(mid)

