        # try all possible substrings starting at idx
        for end in range(idx + 1, n + 1):
            val = int(s[idx:end])
            if val == expected:
                if match(end, expected - 1):
                    memo[key] = True
                    return True
            elif val > expected:
                break
        memo[key] = False
        return False

    # try every possible first number (must leave at least one digit for the next number)
    for end in range(1, n):
        first_val = int(s[:end])
        if match(end, first_val - 1):
            return True
    return False

def min_swaps(num: str, k: int) -> int:
    target = list(num)
    n = len(target)
    for _ in range(k):
        i = n - 2
        while i >= 0 and target[i] >= target[i + 1]:
            i -= 1
        j = n - 1
        while target[j] <= target[i]:
            j -= 1
        target[i], target[j] = target[j], target[i]
        left, right = i + 1, n - 1
        while left < right:
            target[left], target[right] = target[right], target[left]
            left += 1
            right -= 1

    orig = list(num)
    swaps = 0
    for i in range(n):
        if orig[i] == target[i]:
            continue
        j = i + 1
        while orig[j] != target[i]:
            j += 1
        while j > i:
            orig[j], orig[j - 1] = orig[j - 1], orig[j]
            swaps += 1
            j -= 1
    return swaps

