def largest_path_value(colors: str, edges: List[List[int]]) -> int:
    n = len(colors)
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        adj[a].append(b)
        indeg[b] += 1

    dp = [[0] * 26 for _ in range(n)]
    for i in range(n):
        dp[i][ord(colors[i]) - 97] = 1

    queue = deque(i for i in range(n) if indeg[i] == 0)
    processed = 0
    answer = 0

    while queue:
        u = queue.popleft()
        processed += 1
        for c in range(26):
            if dp[u][c] > answer:
                answer = dp[u][c]
        for v in adj[u]:
            for c in range(26):
                cand = dp[u][c] + (1 if ord(colors[v]) - 97 == c else 0)
                if cand > dp[v][c]:
                    dp[v][c] = cand
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)

    return answer if processed == n else -1

