    for v in nums2:
        freq[v] = freq.get(v, 0) + 1

    def add(index: int, val: int) -> None:
        old_val = nums2[index]
        new_val = old_val + val
        nums2[index] = new_val
        old_count = freq[old_val]
        if old_count == 1:
            del freq[old_val]
        else:
            freq[old_val] = old_count - 1
        freq[new_val] = freq.get(new_val, 0) + 1

    def count(tot: int) -> int:
        pairs = 0
        for x in nums1:
            pairs += freq.get(tot - x, 0)
        return pairs

    return {"add": add, "count": count}

