def sum_of_floored_pairs(nums: List[int]) -> int:
    if not nums:
        return 0
    max_val = max(nums)
    cnt = [0] * (max_val + 1)
    for v in nums:
        cnt[v] += 1
    pref = [0] * (max_val + 1)
    s = 0
    for i in range(max_val + 1):
        s += cnt[i]
        pref[i] = s
    answer = 0
    for d in range(1, max_val + 1):
        freq_den = cnt[d]
        if freq_den == 0:
            continue
        max_k = max_val // d
        for k in range(1, max_k + 1):
            left = k * d
            right = (k + 1) * d - 1
            if right > max_val:
                right = max_val
            range_count = pref[right] - pref[left - 1]
            if range_count:
                answer += freq_den * k * range_count
    return answer

