    zeros = ones = 0
    for ch in s:
        if ch == '0':
            zeros += 1
        else:
            ones += 1

    def swaps_if_possible(start_char: str) -> int:
        need_zeros = (n + 1) // 2 if start_char == '0' else n // 2
        need_ones = n - need_zeros
        if zeros != need_zeros or ones != need_ones:
            return float('inf')
        zero_to_one = 0
        for i in range(n):
            expected = start_char if i % 2 == 0 else ('1' if start_char == '0' else '0')
            if s[i] != expected and s[i] == '0':
                zero_to_one += 1
        return zero_to_one

    ans = min(swaps_if_possible('0'), swaps_if_possible('1'))
    return -1 if ans == float('inf') else ans

