    for i in range(1, n + 1):
        ndp = [0] * (k + 1)
        limit = i if i < k else k
        for j in range(1, limit + 1):
            ndp[j] = (dp[j - 1] + (i - 1) * dp[j]) % MOD
        dp = ndp
    return dp[k]

