def min_skips(dist: List[int], speed: int, hours_before: float) -> int:
    n = len(dist)

    def can_finish(max_skips: int) -> bool:
        INF = 1e30
        dp = [INF] * (max_skips + 1)
        dp[0] = 0.0
        for i in range(n):
            ndp = [INF] * (max_skips + 1)
            travel = dist[i] / speed
            for used in range(max_skips + 1):
                if dp[used] == INF:
                    continue
                arrive = dp[used] + travel
                if i == n - 1:
                    ndp[used] = min(ndp[used], arrive)
                else:
                    wait = math.ceil(arrive)
                    ndp[used] = min(ndp[used], wait)
                    if used < max_skips:
                        ndp[used + 1] = min(ndp[used + 1], arrive)
            dp = ndp
        for used in range(max_skips + 1):
            if dp[used] <= hours_before + 1e-9:
                return True
        return False

    if can_finish(0):
        return 0

    lo, hi = 1, n - 1
    answer = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_finish(mid):
            answer = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return answer

