def minimum_xor_sum(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    full_mask = (1 << n) - 1
    INF = 10**15
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(full_mask + 1):
        k = mask.bit_count()
        if k >= n:
            continue
        cur = dp[mask]
        for j in range(n):
            if (mask & (1 << j)) == 0:
                new_mask = mask | (1 << j)
                cand = cur + (nums1[k] ^ nums2[j])
                if cand < dp[new_mask]:
                    dp[new_mask] = cand
    return dp[full_mask]

