        ch = doubled[i]
        expected_a = '0' if i % 2 == 0 else '1'
        expected_b = '1' if i % 2 == 0 else '0'
        if ch != expected_a:
            diff_a += 1
        if ch != expected_b:
            diff_b += 1
        if i >= n:
            j = i - n
            left = doubled[j]
            left_exp_a = '0' if j % 2 == 0 else '1'
            left_exp_b = '1' if j % 2 == 0 else '0'
            if left != left_exp_a:
                diff_a -= 1
            if left != left_exp_b:
                diff_b -= 1
        if i >= n - 1:
            best = min(best, diff_a, diff_b)
    return best

