import bisect

def min_wasted_space(packages: List[int], boxes: List[List[int]]) -> int:
    MOD = 1_000_000_007
    packages.sort()
    n = len(packages)
    prefix = [0] * (n + 1)
    for i, v in enumerate(packages, 1):
        prefix[i] = prefix[i - 1] + v

    best = float('inf')
    for supplier in boxes:
        supplier.sort()
        if supplier[-1] < packages[-1]:
            continue
        waste = 0
        prev = 0
        for size in supplier:
            idx = bisect.bisect_right(packages, size, lo=prev)
            if idx > prev:
                waste += size * (idx - prev) - (prefix[idx] - prefix[prev])
                if waste >= best:
                    break
            prev = idx
            if prev == n:
                break
        if prev == n and waste < best:
            best = waste

    return -1 if best == float('inf') else best % MOD

