    for j in range(n):
        s = 0
        for i in range(m):
            s += grid[i][j]
            col_pref[j][i + 1] = s
    diag1 = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            diag1[i + 1][j + 1] = grid[i][j] + diag1[i][j]
    diag2 = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n - 1, -1, -1):
            diag2[i + 1][j] = grid[i][j] + diag2[i][j + 1]

