def min_cost_to_change_final_value(expression: str) -> int:
    def combine(left, right, op):
        l0, l1 = left
        r0, r1 = right
        if op == '&':
            keep0 = min(l0 + r0, l0 + r1, l1 + r0)
            keep1 = l1 + r1
        else:  # '|'
            keep0 = l0 + r0
            keep1 = min(l1 + r1, l0 + r1, l1 + r0)

        flipped = '&' if op == '|' else '|'
        if flipped == '&':
            flip0 = min(l0 + r0, l0 + r1, l1 + r0)
            flip1 = l1 + r1
        else:
            flip0 = l0 + r0
            flip1 = min(l1 + r1, l0 + r1, l1 + r0)
        flip0 += 1
        flip1 += 1
        return min(keep0, flip0), min(keep1, flip1)

    vals = []
    ops = []

    def apply():
        op = ops.pop()
        right = vals.pop()
        left = vals.pop()
        vals.append(combine(left, right, op))

    i = 0
    n = len(expression)
    while i < n:
        ch = expression[i]
        if ch == '0':
            vals.append((0, 1))
        elif ch == '1':
            vals.append((1, 0))
        elif ch == '(':
            ops.append('(')
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply()
            ops.pop()
        elif ch in ('&', '|'):
            while ops and ops[-1] in ('&', '|'):
                apply()
            ops.append(ch)
        i += 1

    while ops:
        apply()

    cost0, cost1 = vals[-1]
    return cost1 if cost0 == 0 else cost0

