def number_of_full_rounds(login_time: str, logout_time: str) -> int:
    def to_min(t: str) -> int:
        return int(t[:2]) * 60 + int(t[3:5])
    login = to_min(login_time)
    logout = to_min(logout_time)
    if logout < login:
        logout += 24 * 60
    first_start = math.ceil(login / 15) * 15
    last_start = math.floor((logout - 15) / 15) * 15
    return 0 if first_start > last_start else (last_start - first_start) // 15 + 1

