def remove_occurrences(s: str, part: str) -> str:
    m = len(part)
    if m == 0:
        return s
    lps = [0] * m
    i = 1
    length = 0
    while i < m:
        if part[i] == part[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    stack = []
    match_stack = []
    for ch in s:
        stack.append(ch)
        k = match_stack[-1] if match_stack else 0
        while k > 0 and ch != part[k]:
            k = lps[k - 1]
        if ch == part[k]:
            k += 1
        match_stack.append(k)
        if k == m:
            for _ in range(m):
                stack.pop()
                match_stack.pop()
    return ''.join(stack)

