def longest_common_subpath(n: int, paths: List[List[int]]) -> int:
    if not paths:
        return 0
    min_len = min(len(p) for p in paths)
    max_len = max(len(p) for p in paths)

    MOD1 = 1_000_000_007
    MOD2 = 1_000_000_009
    BASE = 100_007

    pow1 = [1] * (max_len + 1)
    pow2 = [1] * (max_len + 1)
    for i in range(1, max_len + 1):
        pow1[i] = (pow1[i - 1] * BASE) % MOD1
        pow2[i] = (pow2[i - 1] * BASE) % MOD2

    prefixes: List[Tuple[List[int], List[int]]] = []
    for p in paths:
        pref1 = [0] * (len(p) + 1)
        pref2 = [0] * (len(p) + 1)
        for i, v in enumerate(p):
            x = v + 1
            pref1[i + 1] = (pref1[i] * BASE + x) % MOD1
            pref2[i + 1] = (pref2[i] * BASE + x) % MOD2
        prefixes.append((pref1, pref2))

    def check(L: int) -> bool:
        if L == 0:
            return True
        common: set = set()
        for idx, p in enumerate(paths):
            pref1, pref2 = prefixes[idx]
            cur_set = set()
            plen = len(p)
            mul1 = pow1[L]
            mul2 = pow2[L]
            for start in range(plen - L + 1):
                h1 = (pref1[start + L] - pref1[start] * mul1) % MOD1
                h2 = (pref2[start + L] - pref2[start] * mul2) % MOD2
                cur_set.add((h1, h2))
            if idx == 0:
                common = cur_set
                if not common:
                    return False
            else:
                common &= cur_set
                if not common:
                    return False
        return bool(common)

    low, high = 0, min_len
    while low < high:
        mid = (low + high + 1) // 2
        if check(mid):
            low = mid
        else:
            high = mid - 1
    return low

