def sum_game(num: str) -> bool:
    n = len(num)
    half = n // 2
    left_sum = right_sum = 0
    left_q = right_q = 0

    for i, ch in enumerate(num):
        if i < half:
            if ch == '?':
                left_q += 1
            else:
                left_sum += int(ch)
        else:
            if ch == '?':
                right_q += 1
            else:
                right_sum += int(ch)

    diff = left_sum - right_sum
    cnt = left_q - right_q

    if cnt == 0:
        return diff != 0
    return diff * 2 != -9 * cnt

