class TreeNode:
    def __init__(self, val: int, left: Optional['TreeNode'] = None, right: Optional['TreeNode'] = None):
        self.val = val
        self.left = left
        self.right = right


def can_merge(trees: List[TreeNode]) -> Optional[TreeNode]:
    root_map = {tree.val: tree for tree in trees}
    leaf_vals = set()
    for tree in trees:
        if tree.left:
            leaf_vals.add(tree.left.val)
        if tree.right:
            leaf_vals.add(tree.right.val)

    overall_root = None
    for val, node in root_map.items():
        if val not in leaf_vals:
            if overall_root is not None:
                return None
            overall_root = node
    if overall_root is None:
        return None

    root_map.pop(overall_root.val)

    def dfs(node: TreeNode, low: int, high: int) -> bool:
        if not (low < node.val < high):
            return False

        if node.left is None and node.right is None:
            if node.val in root_map:
                sub = root_map.pop(node.val)
                node.left = sub.left
                node.right = sub.right
                left_ok = dfs(node.left, low, node.val) if node.left else True
                right_ok = dfs(node.right, node.val, high) if node.right else True
                return left_ok and right_ok
            return True

        left_ok = dfs(node.left, low, node.val) if node.left else True
        right_ok = dfs(node.right, node.val, high) if node.right else True
        return left_ok and right_ok

    if not dfs(overall_root, float('-inf'), float('inf')):
        return None
    if root_map:
        return None
    return overall_root

