MOD = 10**9 + 7

def painting_grid(m: int, n: int) -> int:
    # generate all column patterns with no vertical equal neighbors
    patterns: List[Tuple[int, ...]] = []
    for mask in range(3 ** m):
        col: List[int] = []
        tmp = mask
        for _ in range(m):
            col.append(tmp % 3)
            tmp //= 3
        ok = True
        for i in range(m - 1):
            if col[i] == col[i + 1]:
                ok = False
                break
        if ok:
            patterns.append(tuple(col))

    p_len = len(patterns)

    # build transition matrix: trans[i][j] = 1 if columns i and j are compatible horizontally
    trans: List[List[int]] = [[0] * p_len for _ in range(p_len)]
    for i, pi in enumerate(patterns):
        for j, pj in enumerate(patterns):
            for row in range(m):
                if pi[row] == pj[row]:
                    break
            else:
                trans[i][j] = 1

    # initial vector: each pattern is possible for the first column
    vec: List[int] = [1] * p_len
    power = n - 1
    mat = trans

    def mat_mul(a: List[List[int]], b: List[List[int]]) -> List[List[int]]:
        size = len(a)
        res = [[0] * size for _ in range(size)]
        for i in range(size):
            ai = a[i]
            ri = res[i]
            for k in range(size):
                aik = ai[k]
                if aik:
                    bk = b[k]
                    for j in range(size):
                        ri[j] = (ri[j] + aik * bk[j]) % MOD
        return res

    def vec_mul(v: List[int], mtx: List[List[int]]) -> List[int]:
        size = len(v)
        res = [0] * size
        for i in range(size):
            vi = v[i]
            if vi:
                row = mtx[i]
                for j in range(size):
                    res[j] = (res[j] + vi * row[j]) % MOD
        return res

    while power > 0:
        if power & 1:
            vec = vec_mul(vec, mat)
        mat = mat_mul(mat, mat)
        power >>= 1

    return sum(vec) % MOD

