def max_points(points: List[List[int]]) -> int:
    if not points or not points[0]:
        return 0
    m, n = len(points), len(points[0])
    dp = points[0][:]
    for i in range(1, m):
        left = [0] * n
        right = [0] * n
        left[0] = dp[0]
        for j in range(1, n):
            left[j] = max(dp[j], left[j - 1] - 1)
        right[n - 1] = dp[n - 1]
        for j in range(n - 2, -1, -1):
            right[j] = max(dp[j], right[j + 1] - 1)
        new_dp = [0] * n
        row = points[i]
        for j in range(n):
            new_dp[j] = row[j] + (left[j] if left[j] > right[j] else right[j])
        dp = new_dp
    return max(dp)

