def max_genetic_difference(parents: List[int], queries: List[List[int]]) -> List[int]:
    sys.setrecursionlimit(300000)
    n = len(parents)
    children = [[] for _ in range(n)]
    root = -1
    for i, p in enumerate(parents):
        if p == -1:
            root = i
        else:
            children[p].append(i)

    q_by_node = [[] for _ in range(n)]
    for idx, (node, val) in enumerate(queries):
        q_by_node[node].append((val, idx))

    if queries:
        max_query_val = max(v for _, v in queries)
    else:
        max_query_val = 0
    max_num = max(n - 1, max_query_val)
    MAX_BIT = max_num.bit_length()
    if MAX_BIT == 0:
        MAX_BIT = 1

    trie = [[-1, -1, 0]]  # child0, child1, count

    def new_node() -> int:
        trie.append([-1, -1, 0])
        return len(trie) - 1

    def add(num: int, delta: int) -> None:
        node = 0
        trie[node][2] += delta
        for i in range(MAX_BIT - 1, -1, -1):
            b = (num >> i) & 1
            nxt = trie[node][b]
            if nxt == -1:
                nxt = new_node()
                trie[node][b] = nxt
            node = nxt
            trie[node][2] += delta

    def query_max_xor(num: int) -> int:
        node = 0
        ans = 0
        for i in range(MAX_BIT - 1, -1, -1):
            b = (num >> i) & 1
            prefer = 1 - b
            nxt = trie[node][prefer]
            if nxt != -1 and trie[nxt][2] > 0:
                ans |= (1 << i)
                node = nxt
            else:
                nxt = trie[node][b]
                if nxt == -1 or trie[nxt][2] == 0:
                    break
                node = nxt
        return ans

    answers = [0] * len(queries)

    def dfs(u: int) -> None:
        add(u, 1)
        for val, idx in q_by_node[u]:
            answers[idx] = query_max_xor(val)
        for v in children[u]:
            dfs(v)
        add(u, -1)

    dfs(root)
    return answers

