def delete_duplicate_folders(paths: List[List[str]]) -> List[List[str]]:
    class _Node:
        __slots__ = ("name", "children", "serial")

        def __init__(self, name: str):
            self.name: str = name
            self.children: Dict[str, "_Node"] = {}
            self.serial: str = ""

    root = _Node("")

    # Build trie
    for p in paths:
        cur = root
        for name in p:
            cur = cur.children.setdefault(name, _Node(name))

    counter: Dict[str, int] = defaultdict(int)

    def dfs_build(node: _Node) -> None:
        for child in node.children.values():
            dfs_build(child)
        child_serials = sorted(child.serial for child in node.children.values())
        if not child_serials:
            node.serial = node.name
        else:
            node.serial = "(" + "".join(child_serials) + ")"
        if node is not root:
            counter[node.serial] += 1

    dfs_build(root)

    result: List[List[str]] = []

    def dfs_collect(node: _Node, path: List[str]) -> None:
        for name in sorted(node.children.keys(), reverse=True):
            child = node.children[name]
            if counter[child.serial] > 1:
                continue
            new_path = path + [name]
            result.append(new_path)
            dfs_collect(child, new_path)

    dfs_collect(root, [])
    return result

