def minimum_garden_perimeter(needed_apples: int) -> int:
    if needed_apples <= 0:
        return 0

    def apples(k: int) -> int:
        return 2 * k * (k + 1) * (2 * k + 1)

    lo, hi = 0, 1
    while apples(hi) < needed_apples:
        hi <<= 1

    while lo < hi:
        mid = (lo + hi) // 2
        if apples(mid) >= needed_apples:
            hi = mid
        else:
            lo = mid + 1

    return 8 * lo

