def minimize_stone_sum(piles: List[int], k: int) -> int:
    heap: List[int] = []

    def swap(i: int, j: int) -> None:
        heap[i], heap[j] = heap[j], heap[i]

    def heapify_up(i: int) -> None:
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] >= heap[i]:
                break
            swap(p, i)
            i = p

    def heapify_down(i: int) -> None:
        n = len(heap)
        while True:
            largest = i
            l = i * 2 + 1
            r = i * 2 + 2
            if l < n and heap[l] > heap[largest]:
                largest = l
            if r < n and heap[r] > heap[largest]:
                largest = r
            if largest == i:
                break
            swap(i, largest)
            i = largest

    def push(val: int) -> None:
        heap.append(val)
        heapify_up(len(heap) - 1)

    def pop() -> int:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            heapify_down(0)
        return top

    for v in piles:
        push(v)

    for _ in range(k):
        largest = pop()
        reduced = largest - largest // 2  # keep the remaining stones
        push(reduced)

    total = 0
    for v in heap:
        total += v
    return total

