def latest_day_to_cross(row: int, col: int, cells: List[List[int]]) -> int:
    total = row * col
    parent = list(range(total + 2))
    rank = [0] * (total + 2)
    top = total
    bottom = total + 1

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    land = [[False] * col for _ in range(row)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for i in range(total - 1, -1, -1):
        r, c = cells[i]
        r -= 1
        c -= 1
        land[r][c] = True
        idx = r * col + c

        if r == 0:
            union(idx, top)
        if r == row - 1:
            union(idx, bottom)

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < row and 0 <= nc < col and land[nr][nc]:
                neighbor_idx = nr * col + nc
                union(idx, neighbor_idx)

        if find(top) == find(bottom):
            return i  # the latest day (0‑based) when crossing is still possible

    return 0
# TIME: O(row*col α(row*col)) SPACE: O(row*col)

