def number_of_patterns(patterns: List[str], word: str) -> int:
    # Build Aho‑Corasick automaton
    nodes = [{'children': {}, 'fail': 0, 'out': []}]
    for idx, pat in enumerate(patterns):
        cur = 0
        for ch in pat:
            if ch not in nodes[cur]['children']:
                nodes[cur]['children'][ch] = len(nodes)
                nodes.append({'children': {}, 'fail': 0, 'out': []})
            cur = nodes[cur]['children'][ch]
        nodes[cur]['out'].append(idx)

    queue = []
    for ch, child in nodes[0]['children'].items():
        nodes[child]['fail'] = 0
        queue.append(child)

    while queue:
        v = queue.pop(0)
        for ch, u in nodes[v]['children'].items():
            f = nodes[v]['fail']
            while f and ch not in nodes[f]['children']:
                f = nodes[f]['fail']
            if ch in nodes[f]['children']:
                nodes[u]['fail'] = nodes[f]['children'][ch]
            else:
                nodes[u]['fail'] = 0
            nodes[u]['out'].extend(nodes[nodes[u]['fail']]['out'])
            queue.append(u)

    found = [False] * len(patterns)
    state = 0
    for ch in word:
        while state and ch not in nodes[state]['children']:
            state = nodes[state]['fail']
        state = nodes[state]['children'].get(ch, 0)
        for idx in nodes[state]['out']:
            found[idx] = True

    return sum(found)

