    for row in matrix:
        for v in row:
            a = abs(v)
            sum_abs += a
            if v < 0:
                neg_count += 1
            if a < min_abs:
                min_abs = a
            if v == 0:
                has_zero = True
    if neg_count % 2 == 1 and not has_zero:
        sum_abs -= 2 * min_abs
    return sum_abs

