def valid_path(n: int, edges: List[List[int]], source: int, destination: int) -> bool:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    queue = [source]
    visited[source] = True

    while queue:
        node = queue.pop(0)
        if node == destination:
            return True
        for nxt in graph[node]:
            if not visited[nxt]:
                visited[nxt] = True
                queue.append(nxt)
    return False

