def find_gcd_of_array(nums: List[int]) -> int:
    min_val = nums[0]
    max_val = nums[0]
    for i in range(1, len(nums)):
        v = nums[i]
        if v < min_val:
            min_val = v
        elif v > max_val:
            max_val = v
    def gcd(a: int, b: int) -> int:
        while b != 0:
            r = a % b
            a = b
            b = r
        return a
    return gcd(min_val, max_val)

