def min_abs_difference(mat: List[List[int]], target: int) -> int:
    max_sum = sum(max(row) for row in mat)
    dp = bytearray(max_sum + 1)
    dp[0] = 1

    for row in mat:
        nxt = bytearray(max_sum + 1)
        for val in row:
            limit = max_sum + 1 - val
            for s in range(limit):
                if dp[s]:
                    nxt[s + val] = 1
        dp = nxt

    best = float('inf')
    for s, reachable in enumerate(dp):
        if reachable:
            diff = abs(target - s)
            if diff < best:
                best = diff
                if best == 0:
                    break
    return int(best)

