def number_of_ways_separate_numbers(num: str) -> int:
    MOD = 1_000_000_007
    n = len(num)
    # LCP array
    lcp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if num[i] == num[j]:
                lcp[i][j] = lcp[i + 1][j + 1] + 1
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    pref = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for length in range(1, i + 1):
            start = i - length
            if num[start] == '0':
                continue
            if start == 0:
                dp[i][length] = 1
            else:
                total = 0
                if length > 1:
                    total = pref[start][min(length - 1, start)]
                if length <= start:
                    a = start - length
                    b = start
                    common = lcp[a][b]
                    if common < length and num[a + common] < num[b + common]:
                        total = (total + dp[start][length]) % MOD
                dp[i][length] = total
            pref[i][length] = (pref[i][length - 1] + dp[i][length]) % MOD
    return pref[n][n]

