def minimum_sessions(tasks: list[int], session_time: int) -> int:
    n = len(tasks)
    total_mask = 1 << n
    dp = [None] * total_mask
    dp[0] = (1, 0)
    for mask in range(total_mask):
        sess, used = dp[mask]
        for i in range(n):
            if mask & (1 << i):
                continue
            new_mask = mask | (1 << i)
            new_sess = sess
            new_used = used + tasks[i]
            if new_used > session_time:
                new_sess = sess + 1
                new_used = tasks[i]
            old = dp[new_mask]
            if old is None or new_sess < old[0] or (new_sess == old[0] and new_used < old[1]):
                dp[new_mask] = (new_sess, new_used)
    return dp[total_mask - 1][0]

