def find_kth_largest(nums: List[str], k: int) -> str:
    target = len(nums) - k
    left, right = 0, len(nums) - 1

    def compare(a: str, b: str) -> int:
        if len(a) != len(b):
            return len(a) - len(b)
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    def partition(arr: List[str], lo: int, hi: int) -> int:
        pivot = arr[hi]
        i = lo
        for j in range(lo, hi):
            if compare(arr[j], pivot) <= 0:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[hi] = arr[hi], arr[i]
        return i

    while True:
        pivot_idx = partition(nums, left, right)
        if pivot_idx == target:
            return nums[pivot_idx]
        if pivot_idx < target:
            left = pivot_idx + 1
        else:
            right = pivot_idx - 1

