def smallest_missing_value_subtree(parents: List[int], nums: List[int]) -> List[int]:
    n = len(parents)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parents[i]].append(i)

    # If 1 is absent, every subtree's answer is 1
    try:
        node_one = nums.index(1)
    except ValueError:
        return [1] * n

    seen = [False] * (n + 2)          # track values up to n+1
    visited_node = [False] * n        # mark nodes already processed

    def dfs(start: int) -> None:
        stack = [start]
        while stack:
            u = stack.pop()
            if visited_node[u]:
                continue
            visited_node[u] = True
            val = nums[u]
            if val <= n + 1:
                seen[val] = True
            for v in children[u]:
                stack.append(v)

    # Process the subtree containing value 1
    dfs(node_one)

    mex = 1
    while mex <= n + 1 and seen[mex]:
        mex += 1

    ans = [1] * n
    ans[node_one] = mex

    cur = parents[node_one]
    while cur != -1:
        dfs(cur)                     # include the ancestor itself and any new nodes
        while mex <= n + 1 and seen[mex]:
            mex += 1
        ans[cur] = mex
        cur = parents[cur]

    return ans

