def max_product(s: str) -> int:
    n = len(s)
    total_masks = 1 << n
    pal_len = [0] * total_masks

    for mask in range(total_masks):
        subseq = [s[i] for i in range(n) if (mask >> i) & 1]
        if subseq == subseq[::-1]:
            pal_len[mask] = len(subseq)

    max_prod = 0
    for mask1 in range(total_masks):
        len1 = pal_len[mask1]
        if len1 == 0:
            continue
        for mask2 in range(mask1 + 1, total_masks):
            if mask1 & mask2:
                continue
            len2 = pal_len[mask2]
            if len2 == 0:
                continue
            prod = len1 * len2
            if prod > max_prod:
                max_prod = prod
    return max_prod

def count_pairs(nums: list[int], k: int) -> int:
    freq: dict[int, int] = {}
    for v in nums:
        freq[v] = freq.get(v, 0) + 1
    total = 0
    if k == 0:
        for f in freq.values():
            total += f * (f - 1) // 2
    else:
        for key, f in freq.items():
            target = key + k
            if target in freq:
                total += f * freq[target]
    return total

