def find_original(changed):
    if len(changed) % 2 != 0:
        return []
    cnt = Counter(changed)
    result = []
    for x in sorted(cnt):
        if cnt[x] == 0:
            continue
        if x == 0:
            if cnt[x] % 2 != 0:
                return []
            pairs = cnt[x] // 2
            result.extend([0] * pairs)
            cnt[x] = 0
            continue
        double = x * 2
        if cnt[double] < cnt[x]:
            return []
        cnt[double] -= cnt[x]
        result.extend([x] * cnt[x])
        cnt[x] = 0
    return result

