def longest_subsequence_repeated_k_times(s: str, k: int) -> str:
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1

    def is_valid(seq: str) -> bool:
        i = 0
        rep = 0
        seq_len = len(seq)
        if seq_len == 0:
            return True
        for ch in s:
            if ch == seq[i]:
                i += 1
                if i == seq_len:
                    i = 0
                    rep += 1
                    if rep == k:
                        return True
        return False

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(prefix: str) -> str:
        best = prefix
        for idx in range(25, -1, -1):
            if freq[idx] < k:
                continue
            cand = prefix + chr(97 + idx)
            if is_valid(cand):
                extended = dfs(cand)
                if len(extended) > len(best) or (len(extended) == len(best) and extended > best):
                    best = extended
        return best

    return dfs("")

