    return total

def detect_squares():
    points_map: dict[int, dict[int, int]] = {}

    def add(point):
        x = point['x']
        y = point['y']
        if x not in points_map:
            points_map[x] = {}
        y_map = points_map[x]
        y_map[y] = y_map.get(y, 0) + 1

    def count(point):
        x = point['x']
        y = point['y']
        total = 0
        if x not in points_map:
            return 0
        y_map = points_map[x]
        for y2, cnt in y_map.items():
            if y2 == y:
                continue
            d = abs(y2 - y)
            x_right = x + d
            x_left = x - d
            map_right = points_map.get(x_right)
            map_left = points_map.get(x_left)
            if map_right:
                cnt1 = map_right.get(y, 0)
                cnt2 = map_right.get(y2, 0)
                total += cnt * cnt1 * cnt2
            if map_left:
                cnt1 = map_left.get(y, 0)
                cnt2 = map_left.get(y2, 0)
                total += cnt * cnt1 * cnt2
        return total

    return {'add': add, 'count': count}

