def place_word_in_crossword(board: List[str], word: str) -> bool:
    rows = len(board)
    cols = len(board[0])
    rev = word[::-1]

    def matches(seg, w):
        for i in range(len(seg)):
            if seg[i] != ' ' and seg[i] != w[i]:
                return False
        return True

    for r in range(rows):
        c = 0
        while c < cols:
            while c < cols and board[r][c] == '#':
                c += 1
            if c >= cols:
                break
            start = c
            while c < cols and board[r][c] != '#':
                c += 1
            segment = board[r][start:c]
            if len(segment) == len(word):
                if matches(segment, word) or matches(segment, rev):
                    return True

    for c in range(cols):
        r = 0
        while r < rows:
            while r < rows and board[r][c] == '#':
                r += 1
            if r >= rows:
                break
            start = r
            while r < rows and board[r][c] != '#':
                r += 1
            segment = [board[k][c] for k in range(start, r)]
            if len(segment) == len(word):
                if matches(segment, word) or matches(segment, rev):
                    return True

    return False

