import sys

def smallest_subsequence(s: str, k: int, letter: str, need: int) -> str:
    n = len(s)
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + (s[i] == letter)

    stack = []
    cnt_letter = 0

    for i, c in enumerate(s):
        while stack:
            top = stack[-1]
            if len(stack) - 1 + (n - i) < k:
                break
            if top == letter and cnt_letter - 1 + suffix[i] < need:
                break
            if top > c:
                popped = stack.pop()
                if popped == letter:
                    cnt_letter -= 1
            else:
                break

        if len(stack) < k:
            if c == letter:
                stack.append(c)
                cnt_letter += 1
            else:
                remaining_needed = need - cnt_letter
                slots_left = k - (len(stack) + 1)
                if slots_left >= remaining_needed:
                    stack.append(c)

    return ''.join(stack)

