def two_out_of_three(nums1: List[int], nums2: List[int], nums3: List[int]) -> List[int]:
    counts: dict[int, int] = {}
    earliest: dict[int, tuple[int, int]] = {}
    for idx, arr in enumerate((nums1, nums2, nums3), start=1):
