def min_difference(nums: List[int]) -> int:
    total = sum(nums)
    half = total / 2
    n = len(nums) // 2
    left = nums[:n]
    right = nums[n:]

    def all_sums(arr: List[int]) -> List[List[int]]:
        m = len(arr)
        sums_by_cnt: List[List[int]] = [[] for _ in range(m + 1)]
        limit = 1 << m
        for mask in range(limit):
            cnt = 0
            s = 0
            for i in range(m):
                if mask & (1 << i):
                    cnt += 1
                    s += arr[i]
            sums_by_cnt[cnt].append(s)
        return sums_by_cnt

    left_sums = all_sums(left)
    right_sums = all_sums(right)

    for i in range(n + 1):
        right_sums[i].sort()

    best = 10**18

    for i in range(n + 1):
        L = left_sums[i]
        R = right_sums[n - i]
        if not L or not R:
            continue
        for sL in L:
            target = half - sL
            lo = 0
            hi = len(R) - 1
            while lo < hi:
                mid = (lo + hi) >> 1
                if R[mid] < target:
                    lo = mid + 1
                else:
                    hi = mid
            for idx in (lo, lo - 1):
                if idx < 0 or idx >= len(R):
                    continue
                s = sL + R[idx]
                diff = abs(total - 2 * s)
                if diff < best:
                    best = diff
                    if best == 0:
                        return 0
    return best

