import bisect

def kth_smallest_product(nums1: List[int], nums2: List[int], k: int) -> int:
    nums1.sort()
    nums2.sort()
    n, m = len(nums1), len(nums2)

    def count_le(x: int) -> int:
        cnt = 0
        for a in nums1:
            if a > 0:
                bound = x // a
                cnt += bisect.bisect_right(nums2, bound)
            elif a < 0:
                # ceil division for negative a
                if x % a == 0:
                    bound = x // a
                else:
                    bound = x // a + 1
                idx = bisect.bisect_left(nums2, bound)
                cnt += m - idx
            else:  # a == 0
                if x >= 0:
                    cnt += m
        return cnt

    low = -10**18 - 1
    high = 10**18 + 1
    while low < high:
        mid = (low + high) // 2
        if count_le(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low
