def second_minimum_time(n: int, edges: List[List[int]], time: int, change: int) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    heap = [(0, 1)]  # (current_time, node)
    visited = [0] * (n + 1)

    while heap:
        cur_time, node = heapq.heappop(heap)
        if visited[node] >= 2:
            continue
        visited[node] += 1
        if node == n and visited[node] == 2:
            return cur_time

        # Determine departure time from this node
        if (cur_time // change) % 2 == 0:
            depart = cur_time
        else:
            depart = cur_time + (change - (cur_time % change))

        for nb in adj[node]:
            nxt_time = depart + time
            heapq.heappush(heap, (nxt_time, nb))

    return -1

