def network_become_idle(edges: List[List[int]], patience: List[int]) -> int:
    n = len(patience)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    dist = [-1] * n
    dist[0] = 0
    q = collections.deque([0])
    while q:
        node = q.popleft()
        for nb in adj[node]:
            if dist[nb] == -1:
                dist[nb] = dist[node] + 1
                q.append(nb)

    max_time = 0
    for i in range(1, n):
        round_trip = 2 * dist[i]
        if patience[i] >= round_trip:
            last_arrival = round_trip
        else:
            last_sent = ((round_trip - 1) // patience[i]) * patience[i]
            last_arrival = last_sent + round_trip
        if last_arrival > max_time:
            max_time = last_arrival

    return max_time + 1

