def count_highest_score_nodes(parents: List[int]) -> int:
    n = len(parents)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parents[i]].append(i)

    order = []
    stack = [0]
    while stack:
        v = stack.pop()
        order.append(v)
        for c in children[v]:
            stack.append(c)

    sub_size = [0] * n
    for v in reversed(order):
        sz = 1
        for c in children[v]:
            sz += sub_size[c]
        sub_size[v] = sz

    max_score = -1
    count = 0
    for i in range(n):
        product = 1
        rest = n - sub_size[i]
        if rest > 0:
            product *= rest
        for c in children[i]:
            product *= sub_size[c]

        if product > max_score:
            max_score = product
            count = 1
        elif product == max_score:
            count += 1

    return count

