def minimum_time(n: int, relations: List[List[int]], time: List[int]) -> int:
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for pre, nxt in relations:
        u = pre - 1
        v = nxt - 1
        adj[u].append(v)
        indeg[v] += 1

    dp = [0] * n
    q = deque()
    for i in range(n):
        if indeg[i] == 0:
            dp[i] = time[i]
            q.append(i)

    while q:
        u = q.popleft()
        du = dp[u]
        for v in adj[u]:
            cand = du + time[v]
            if cand > dp[v]:
                dp[v] = cand
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    return max(dp)

