def plates_between_candles(s: str, queries: List[List[int]]) -> List[int]:
    n = len(s)
    pref = [0] * (n + 1)
    for i, ch in enumerate(s):
        pref[i + 1] = pref[i] + (ch == '*')
    left_candle = [-1] * n
    last = -1
    for i, ch in enumerate(s):
        if ch == '|':
            last = i
        left_candle[i] = last
    right_candle = [-1] * n
    nxt = -1
    for i in range(n - 1, -1, -1):
        if s[i] == '|':
            nxt = i
        right_candle[i] = nxt
    ans = [0] * len(queries)
    for idx, (l, r) in enumerate(queries):
        left = right_candle[l]
        right = left_candle[r]
        if left != -1 and right != -1 and left < right:
            ans[idx] = pref[right] - pref[left + 1]
