def max_two_events(events: List[Tuple[int, int, int]]) -> int:
    events = sorted(events, key=lambda e: e[1])
    n = len(events)
    ends = [0] * n
    pref_max = [0] * n
    best_single = 0
    best_two = 0

    for i in range(n):
        ends[i] = events[i][1]
        val = events[i][2]
        pref_max[i] = val if i == 0 else max(pref_max[i - 1], val)
        if val > best_single:
            best_single = val

    for i in range(n):
        start = events[i][0]
        val = events[i][2]
        lo, hi, j = 0, i - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if ends[mid] < start:
                j = mid
                lo = mid + 1
            else:
                hi = mid - 1
        if j != -1:
            best_two = max(best_two, val + pref_max[j])

    return max(best_single, best_two)

