def count_valid_move_combinations(pieces: List[str], positions: List[List[int]]) -> int:
    n = len(pieces)
    start_pos: List[Tuple[int, int]] = [tuple(pos) for pos in positions]

    def sign(x: int) -> int:
        return (x > 0) - (x < 0)

    # generate all reachable destinations (including staying)
    dest_lists: List[List[Tuple[int, int]]] = []
    for i, piece_type in enumerate(pieces):
        r0, c0 = start_pos[i]
        lst: List[Tuple[int, int]] = []
        for r in range(1, 9):
            for c in range(1, 9):
                dr = r - r0
                dc = c - c0
                if piece_type == "rook":
                    ok = (r == r0 or c == c0)
                elif piece_type == "bishop":
                    ok = (abs(dr) == abs(dc))
                else:  # queen
                    ok = (r == r0 or c == c0 or abs(dr) == abs(dc))
                if ok:
                    lst.append((r, c))
        dest_lists.append(lst)

    count = 0
    paths: List[List[Tuple[int, int]]] = []  # paths of already placed pieces

    def build_path(start: Tuple[int, int], dest: Tuple[int, int]) -> List[Tuple[int, int]]:
        sr, sc = start
        dr, dc = dest
        step_r = sign(dr - sr)
        step_c = sign(dc - sc)
        path: List[Tuple[int, int]] = [(sr, sc)]
        r, c = sr, sc
        while (r, c) != (dr, dc):
            r += step_r
            c += step_c
            path.append((r, c))
        return path

    def can_place(new_path: List[Tuple[int, int]]) -> bool:
        new_len = len(new_path)
        for existing_path in paths:
            max_len = max(new_len, len(existing_path))
            for t in range(max_len):
                pos_new = new_path[t] if t < new_len else new_path[-1]
                pos_exist = existing_path[t] if t < len(existing_path) else existing_path[-1]
                if pos_new == pos_exist:
                    return False
        return True

    def dfs(idx: int) -> None:
        nonlocal count
        if idx == n:
            count += 1
            return
        for dest in dest_lists[idx]:
            new_path = build_path(start_pos[idx], dest)
            if can_place(new_path):
                paths.append(new_path)
                dfs(idx + 1)
                paths.pop()

    dfs(0)
    return count

