def find_critical_points(head):
    if not head or not head.next or not head.next.next:
        return [-1, -1]

    idx = 0
    prev_val = head.val
    cur = head.next
    nxt = cur.next

    first_crit = -1
    prev_crit = -1
    min_dist = float('inf')
    max_dist = 0

    while nxt:
        if (cur.val > prev_val and cur.val > nxt.val) or (cur.val < prev_val and cur.val < nxt.val):
            if first_crit == -1:
                first_crit = idx
            else:
                diff = idx - prev_crit
                if diff < min_dist:
                    min_dist = diff
                span = idx - first_crit
                if span > max_dist:
                    max_dist = span
            prev_crit = idx

        prev_val = cur.val
        cur = nxt
        nxt = nxt.next
        idx += 1

    if prev_crit == first_crit:
        return [-1, -1]
    return [min_dist, max_dist]

