def minimum_operations(nums: List[int], start: int, goal: int) -> int:
    if start == goal:
        return 0
    MAX = 1000
    visited = [False] * (MAX + 1)
    queue = []
    head = 0
    if 0 <= start <= MAX:
        visited[start] = True
        queue.append((start, 0))
    while head < len(queue):
        x, steps = queue[head]
        head += 1
        for num in nums:
            add = x + num
            sub = x - num
            if add == goal or sub == goal:
                return steps + 1
            if 0 <= add <= MAX and not visited[add]:
                visited[add] = True
                queue.append((add, steps + 1))
            if 0 <= sub <= MAX and not visited[sub]:
                visited[sub] = True
                queue.append((sub, steps + 1))
    return -1

