        self.dir_idx = 0
        self.dx = [1,0,-1,0]; self.dy = [0,1,0,-1]
    def move(self, num: int) -> None:
        for _ in range(num):
            nx, ny = self.x + self.dx[self.dir_idx], self.y + self.dy[self.dir_idx]
            if nx < 0 or nx >= self.width or ny < 0 or ny >= self.height:
                self.dir_idx = (self.dir_idx + 1) % 4
                nx, ny = self.x + self.dx[self.dir_idx], self.y + self.dy[self.dir_idx]
            self.x, self.y = nx, ny
    def getPos(self):
        return [self.x, self.y]
    def getDir(self) -> str:
        return ["East","North","West","South"][self.dir_idx]

