def minimized_maximum(n: int, quantities: List[int]) -> int:
    low = 1
    high = max(quantities)
    while low < high:
        mid = (low + high) // 2
        needed = 0
        for q in quantities:
            needed += (q + mid - 1) // mid
            if needed > n:
                break
        if needed <= n:
            high = mid
        else:
            low = mid + 1
    return low

