def decode_ciphertext(encoded_text: str, rows: int) -> str:
    if rows == 0:
        return ""
    n = len(encoded_text)
    cols = n // rows
    # Build matrix rows as substrings
    matrix = [encoded_text[i * cols:(i + 1) * cols] for i in range(rows)]
    result_chars = []
    for start_col in range(cols):
        i, j = 0, start_col
        while i < rows and j < cols:
            result_chars.append(matrix[i][j])
            i += 1
            j += 1
    # Remove trailing spaces that were padding
    return ''.join(result_chars).rstrip(' ')

