def process_restricted_friend_requests(n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    answer: List[bool] = []

    for u, v in requests:
        ru = find(u)
        rv = find(v)
        if ru == rv:
            answer.append(True)
            continue

        conflict = False
        for x, y in restrictions:
            rx = find(x)
            ry = find(y)
            if (rx == ru and ry == rv) or (rx == rv and ry == ru):
                conflict = True
                break

        if conflict:
            answer.append(False)
        else:
            answer.append(True)
            union(ru, rv)

    return answer

def max_distance(colors: list[int]) -> int:
    n = len(colors)
    if colors[0] != colors[n - 1]:
        return n - 1

    left_diff = -1
    right_color = colors[n - 1]
    for i in range(n):
        if colors[i] != right_color:
            left_diff = i
            break

    right_diff = -1
    left_color = colors[0]
    for i in range(n - 1, -1, -1):
        if colors[i] != left_color:
            right_diff = i
            break

    dist_from_left = 0 if left_diff == -1 else n - 1 - left_diff
    dist_from_right = 0 if right_diff == -1 else right_diff

    return max(dist_from_left, dist_from_right)

