def range_freq_query(nums):
    pos_map = {}
    for i, v in enumerate(nums):
        pos_map.setdefault(v, []).append(i)

    def lower_bound(arr, target):
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(arr, target):
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def query(left, right, value):
        lst = pos_map.get(value)
        if lst is None:
            return 0
        l = lower_bound(lst, left)
        r = upper_bound(lst, right)
        return r - l

    return SimpleNamespace(query=query)

