def count_fertile_pyramids(grid: List[List[int]]) -> int:
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    ans = 0

    # Upright pyramids (apex at top)
    next_row = [0] * n
    for i in range(m - 1, -1, -1):
        cur = [0] * n
        for j in range(n):
            if grid[i][j] == 1:
                if i == m - 1 or j == 0 or j == n - 1:
                    cur[j] = 1
                else:
                    cur[j] = 1 + min(next_row[j - 1], next_row[j], next_row[j + 1])
                ans += cur[j] - 1
        next_row = cur

    # Inverted pyramids (apex at bottom)
    prev_row = [0] * n
    for i in range(m):
        cur = [0] * n
        for j in range(n):
            if grid[i][j] == 1:
                if i == 0 or j == 0 or j == n - 1:
                    cur[j] = 1
                else:
                    cur[j] = 1 + min(prev_row[j - 1], prev_row[j], prev_row[j + 1])
                ans += cur[j] - 1
        prev_row = cur

    return ans

def k_radius_averages(nums: list[int], k: int) -> list[int]:
    n = len(nums)
    result = [-1] * n
    window_size = 2 * k + 1
    if window_size > n:
        return result
    total = 0
    for i in range(window_size):
        total += nums[i]
    for i in range(k, n - k):
        if i > k:
            total += nums[i + k] - nums[i - k - 1]
        result[i] = int(total / window_size)
    return result

