def min_deletion(nums: List[int]) -> int:
    n = len(nums)
    min_idx = 0
    max_idx = 0
    for i in range(1, n):
        if nums[i] < nums[min_idx]:
            min_idx = i
        if nums[i] > nums[max_idx]:
            max_idx = i
    front_both = max(min_idx, max_idx) + 1
    back_both = n - min(min_idx, max_idx)
    front_min_back_max = min_idx + 1 + (n - max_idx)
    front_max_back_min = max_idx + 1 + (n - min_idx)
    return min(front_both, back_both, front_min_back_max, front_max_back_min)

