    knows[0] = True
    knows[first_person] = True
    i = 0
    while i < len(meetings):
        cur_time = meetings[i][2]
        group = []
        nodes_set = set()
        while i < len(meetings) and meetings[i][2] == cur_time:
            x, y = meetings[i][0], meetings[i][1]
            group.append((x, y))
            nodes_set.add(x)
            nodes_set.add(y)
            i += 1
        parent = {}
        def find(v: int) -> int:
            if parent[v] != v:
                parent[v] = find(parent[v])
            return parent[v]
        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra != rb:
                parent[rb] = ra
        for v in nodes_set:
            parent[v] = v
        for x, y in group:
            union(x, y)
        comp_has_secret = {}
        for v in nodes_set:
            root = find(v)
            if knows[v]:
                comp_has_secret[root] = True
        for v in nodes_set:
            root = find(v)
            if comp_has_secret.get(root, False):
                knows[v] = True
    return [p for p in range(n) if knows[p]]

