def find_good_days(security: List[int], time: int) -> List[int]:
    n = len(security)
    left = [0] * n
    right = [0] * n

    for i in range(1, n):
        if security[i - 1] >= security[i]:
            left[i] = left[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if security[i] <= security[i + 1]:
            right[i] = right[i + 1] + 1

    good_days = []
    for i in range(n):
        if left[i] >= time and right[i] >= time:
            good_days.append(i)
    return good_days

def get_directions(root, start_value, dest_value):
    def find_lca(node):
        if not node:
            return None
        if node.val == start_value or node.val == dest_value:
            return node
        left = find_lca(node.left)
        right = find_lca(node.right)
        if left and right:
            return node
        return left or right

    lca = find_lca(root)

    def distance(node, target):
        if not node:
            return -1
        if node.val == target:
            return 0
        left = distance(node.left, target)
        if left != -1:
            return left + 1
        right = distance(node.right, target)
        if right != -1:
            return right + 1
        return -1

    up_steps = distance(lca, start_value)

    def path_from_node(node, target):
        if not node:
            return None
        if node.val == target:
            return ""
        left = path_from_node(node.left, target)
        if left is not None:
            return "L" + left
        right = path_from_node(node.right, target)
        if right is not None:
            return "R" + right
        return None

    down_path = path_from_node(lca, dest_value) or ""
    return "U" * up_steps + down_path

