def maximum_detonation(bombs: List[List[int]]) -> int:
    n = len(bombs)
    adj: List[List[int]] = [[] for _ in range(n)]
    for i in range(n):
        xi, yi, ri = bombs[i]
        ri2 = ri * ri
        for j in range(n):
            if i == j:
                continue
            xj, yj, _ = bombs[j]  # radius of j is not needed for the check
            dx = xi - xj
            dy = yi - yj
            if dx * dx + dy * dy <= ri2:
                adj[i].append(j)
    best = 0
    for start in range(n):
        visited = [False] * n
        stack = [start]
        visited[start] = True
        count = 0
        while stack:
            v = stack.pop()
            count += 1
            for w in adj[v]:
                if not visited[w]:
                    visited[w] = True
                    stack.append(w)
        if count > best:
            best = count
    return best

import heapq

class SORTracker:
    def __init__(self):
        self.k = 0
        self.best = []
        self.rest = []
    def add(self, name: str, score: int) -> None:
        heapq.heappush(self.best, (score, [-ord(c) for c in name], name))
        if len(self.best) > self.k:
            item = heapq.heappop(self.best)
            heapq.heappush(self.rest, (-item[0], item[2]))
    def get(self) -> str:
        self.k += 1
        if self.rest:
            neg_score, name = heapq.heappop(self.rest)
            heapq.heappush(self.best, (-neg_score, [-ord(c) for c in name], name))
        return self.best[0][2]

