def find_all_recipes(recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
    available = set(supplies)
    recipe_set = set(recipes)

    indegree = {}
    graph = {}
    possible = {}

    for r in recipes:
        indegree[r] = 0
        possible[r] = True

    for i, rec in enumerate(recipes):
        for ing in ingredients[i]:
            if ing in recipe_set:
                indegree[rec] += 1
                if ing not in graph:
                    graph[ing] = []
                graph[ing].append(rec)
            elif ing not in available:
                possible[rec] = False

    queue = []
    q_head = 0
    for r in recipes:
        if possible[r] and indegree[r] == 0:
            queue.append(r)

    result = []
    while q_head < len(queue):
        cur = queue[q_head]
        q_head += 1
        result.append(cur)
        available.add(cur)

        if cur not in graph:
            continue
        for nxt in graph[cur]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0 and possible[nxt]:
                queue.append(nxt)

    return result

