        return False
    balance = 0
    free = 0
    for i in range(n):
        if locked[i] == '1':
            balance += 1 if s[i] == '(' else -1
        else:
            free += 1
        if balance < 0:
            if free == 0:
                return False
            free -= 1
            balance += 1
    return balance <= free

