from typing import List

def max_employees(favorite: List[int]) -> int:
    n = len(favorite)
    rev = [[] for _ in range(n)]
    for i, f in enumerate(favorite):
        rev[f].append(i)

    visited = [False] * n
    in_cycle = [False] * n
    pairs: List[tuple[int, int]] = []
    max_cycle_len = 0

    for i in range(n):
        if visited[i]:
            continue
        cur = i
        order: dict[int, int] = {}
        while True:
            if visited[cur]:
                break
            if cur in order:
                cycle_start = cur
                cycle_nodes = []
                node = cur
                while True:
                    cycle_nodes.append(node)
                    node = favorite[node]
                    if node == cycle_start:
                        break
                for node in cycle_nodes:
                    in_cycle[node] = True
                if len(cycle_nodes) == 2:
                    a, b = cycle_nodes[0], cycle_nodes[1]
                    pairs.append((a, b))
                else:
                    if len(cycle_nodes) > max_cycle_len:
                        max_cycle_len = len(cycle_nodes)
                break
            order[cur] = len(order)
            cur = favorite[cur]
        for node in order:
            visited[node] = True

    sys.setrecursionlimit(10**6)
    memo: dict[int, int] = {}

    def dfs(u: int) -> int:
        if u in memo:
            return memo[u]
        best = 0
        for v in rev[u]:
            if in_cycle[v]:
                continue
            depth = dfs(v) + 1
            if depth > best:
                best = depth
        memo[u] = best
        return best

    sum_pairs = 0
    for a, b in pairs:
        sum_pairs += 2 + dfs(a) + dfs(b)

    return max(max_cycle_len, sum_pairs)

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    favorite = data[1:1 + n]
    ans = max_employees(favorite)
    sys.stdout.write(str(ans))

