def min_swaps(nums: List[int]) -> int:
    n = len(nums)
    total_ones = 0
    for i in range(n):
        total_ones += nums[i]
    if total_ones <= 1:
        return 0
    ones_in_window = 0
    for i in range(total_ones):
        ones_in_window += nums[i]
    max_ones = ones_in_window
    for start in range(1, n):
        out_idx = start - 1
        in_idx = (start + total_ones - 1) % n
        ones_in_window += nums[in_idx] - nums[out_idx]
        if ones_in_window > max_ones:
            max_ones = ones_in_window
    return total_ones - max_ones

def longest_palindrome(words):
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1

    length = 0
    has_center = False

    for w in list(freq.keys()):
        cnt = freq[w]
        rev = w[1] + w[0]

        if w == rev:
            pairs = cnt // 2
            length += pairs * 4
            if cnt % 2 == 1:
                has_center = True
        elif rev in freq:
            pairs = min(cnt, freq[rev])
            length += pairs * 4
            freq[rev] = 0

    if has_center:
        length += 2
    return length

