                - pref[i][j + stamp_width]
                - pref[i + stamp_height][j]
                + pref[i][j]
            )
            if total == 0:
                diff[i][j] += 1
                diff[i + stamp_height][j] -= 1
                diff[i][j + stamp_width] -= 1
                diff[i + stamp_height][j + stamp_width] += 1
    for i in range(m):
        for j in range(n):
            if i > 0:
                diff[i][j] += diff[i - 1][j]
            if j > 0:
                diff[i][j] += diff[i][j - 1]
            if i > 0 and j > 0:
                diff[i][j] -= diff[i - 1][j - 1]
            if grid[i][j] == 0 and diff[i][j] == 0:
                return False
    return True

