    for i in range(n):
        if not isinstance(matrix[i], list) or len(matrix[i]) != n:
            return False
    for i in range(n):
        seen_row = [0] * (n + 1)
        seen_col = [0] * (n + 1)
        for j in range(n):
            row_val = matrix[i][j]
            if row_val < 1 or row_val > n or seen_row[row_val]:
                return False
            seen_row[row_val] = 1
            col_val = matrix[j][i]
            if col_val < 1 or col_val > n or seen_col[col_val]:
                return False
            seen_col[col_val] = 1
    return True

