def groups_of_strings(words: List[str]) -> List[int]:
    n = len(words)
    if n == 0:
        return [0, 0]

    masks = [0] * n
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    mask_to_idx = {}
    for i, w in enumerate(words):
        m = 0
        for ch in w:
            m |= 1 << (ord(ch) - 97)
        masks[i] = m
        if m in mask_to_idx:
            union(i, mask_to_idx[m])
        else:
            mask_to_idx[m] = i

    bits = [1 << i for i in range(26)]

    for i, m in enumerate(masks):
        for b in range(26):
            bit = bits[b]
            if m & bit:
                nb = m ^ bit  # delete
                if nb in mask_to_idx:
                    union(i, mask_to_idx[nb])
                # replace
                for c in range(26):
                    if c == b:
                        continue
                    bitc = bits[c]
                    if not (m & bitc):
                        nb = (m ^ bit) | bitc
                        if nb in mask_to_idx:
                            union(i, mask_to_idx[nb])
            else:
                nb = m | bit  # add
                if nb in mask_to_idx:
                    union(i, mask_to_idx[nb])

    group_counts = {}
    for i in range(n):
        r = find(i)
        group_counts[r] = group_counts.get(r, 0) + 1

    num_groups = len(group_counts)
    max_group = max(group_counts.values()) if group_counts else 0
    return [num_groups, max_group]

