class Bitset:
    def __init__(self, size: int):
        self.size = size
        self.bits = [0]*size
        self.flipped = False
        self.ones_count = 0
    def fix(self, idx: int) -> None:
        if (self.bits[idx] ^ self.flipped) == 0:
            self.bits[idx] = 1 ^ self.flipped
            self.ones_count += 1
    def unfix(self, idx: int) -> None:
        if (self.bits[idx] ^ self.flipped) == 1:
            self.bits[idx] = 0 ^ self.flipped
            self.ones_count -= 1
    def flip(self) -> None:
        self.flipped = not self.flipped
        self.ones_count = self.size - self.ones_count
    def all(self) -> bool:
        return self.ones_count == self.size
    def one(self) -> bool:
        return self.ones_count > 0
    def count(self) -> int:
        return self.ones_count
    def toString(self) -> str:
        return ''.join(str(int(self.bits[i]) ^ int(self.flipped)) for i in range(self.size))

