def maximum_and_sum(nums: List[int], numSlots: int) -> int:
    n = len(nums)
    # Sort numbers to potentially improve caching (larger numbers first)
    nums_sorted = tuple(sorted(nums, reverse=True))

    @lru_cache(maxsize=None)
    def dfs(idx: int, caps: Tuple[int, ...]) -> int:
        if idx == n:
            return 0
        best = 0
        val = nums_sorted[idx]
        for slot in range(numSlots):
            if caps[slot] > 0:
                new_caps = list(caps)
                new_caps[slot] -= 1
                cand = (val & (slot + 1)) + dfs(idx + 1, tuple(new_caps))
                if cand > best:
                    best = cand
        return best

    initial_caps = tuple([2] * numSlots)
    return dfs(0, initial_caps)

