def count_even_digit_sum(num: int) -> int:
    s = str(num)
    n = len(s)
    memo = [[-1, -1] for _ in range(n)]

    def dfs(pos: int, parity: int, tight: bool) -> int:
        if pos == n:
            return 1 if parity == 0 else 0
        if not tight and memo[pos][parity] != -1:
            return memo[pos][parity]

        limit = int(s[pos]) if tight else 9
        res = 0
        for d in range(limit + 1):
            next_parity = (parity + d) & 1
            next_tight = tight and d == limit
            res += dfs(pos + 1, next_parity, next_tight)

        if not tight:
            memo[pos][parity] = res
        return res

    return dfs(0, 0, True) - 1

