def minimum_finish_time(tires: List[List[int]], change_time: int, num_laps: int) -> int:
    INF = 10**18
    best = [INF] * (num_laps + 1)
    for f, r in tires:
        lap = 1
        cur = f
        total = f
        while lap <= num_laps:
            if total < best[lap]:
                best[lap] = total
            next_time = cur * r
            if next_time > change_time + f:
                break
            cur = next_time
            total += cur
            lap += 1
    dp = [INF] * (num_laps + 1)
    dp[0] = 0
    for i in range(1, num_laps + 1):
        dp[i] = best[i]
        for k in range(1, i):
            if best[k] != INF:
                cand = dp[i - k] + change_time + best[k]
                if cand < dp[i]:
                    dp[i] = cand
    return dp[num_laps]

def create_binary_tree(descriptions):
    nodes = {}
    children = set()
    def get_node(val):
        if val not in nodes:
            nodes[val] = {'val': val, 'left': None, 'right': None}
        return nodes[val]
    for parent_val, child_val, is_left in descriptions:
        parent_node = get_node(parent_val)
        child_node = get_node(child_val)
        if is_left:
            parent_node['left'] = child_node
        else:
            parent_node['right'] = child_node
        children.add(child_val)
    for val in nodes:
        if val not in children:
            return nodes[val]
    return None

