def min_moves_to_make_palindrome(s: str) -> int:
    n = len(s)
    pos_map = {}
    for i, ch in enumerate(s):
        if ch not in pos_map:
            pos_map[ch] = []
        pos_map[ch].append(i)

    target = [0] * n
    left, right = 0, n - 1

    for arr in pos_map.values():
        i, j = 0, len(arr) - 1
        while i < j:
            target[left] = arr[i]
            left += 1
            target[right] = arr[j]
            right -= 1
            i += 1
            j -= 1
        if i == j:
            target[n // 2] = arr[i]

    ft = [0] * (n + 1)

    def ft_add(idx: int, delta: int) -> None:
        while idx <= n:
            ft[idx] += delta
            idx += idx & -idx

    def ft_sum(idx: int) -> int:
        res = 0
        while idx > 0:
            res += ft[idx]
            idx -= idx & -idx
        return res

    moves = 0
    for i in range(n):
        pos = target[i]
        placed_before = ft_sum(pos + 1)
        moves += i - placed_before
        ft_add(pos + 1, 1)

    return moves

