def count_artifacts(n: int, artifacts: List[List[int]], dig: List[List[int]]) -> int:
    cell_to_artifact = {}
    remaining = [0] * len(artifacts)
    for i, (r1, c1, r2, c2) in enumerate(artifacts):
        area = (r2 - r1 + 1) * (c2 - c1 + 1)
        remaining[i] = area
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                cell_to_artifact[f"{r},{c}"] = i
    for r, c in dig:
        key = f"{r},{c}"
        if key in cell_to_artifact:
            idx = cell_to_artifact[key]
            remaining[idx] -= 1
            del cell_to_artifact[key]
    extracted = 0
    for v in remaining:
        if v == 0:
            extracted += 1
    return extracted

def max_number_of_subsequences(text: str, pattern: str) -> int:
    a, b = pattern[0], pattern[1]
    seen_a = 0
    baseline = 0
    count_a = 0
    count_b = 0
    for ch in text:
        if ch == a:
            seen_a += 1
            count_a += 1
        if ch == b:
            baseline += seen_a
            count_b += 1
    if a == b:
        return baseline + count_a
    return baseline + max(count_a, count_b)

