def maximum_bob_arrows(num_arrows: int, alice_arrows: List[int]) -> List[int]:
    n = 12
    best_score = -1
    best_mask = 0
    for mask in range(1 << n):
        arrows_needed = 0
        score = 0
        for i in range(n):
            if mask & (1 << i):
                arrows_needed += alice_arrows[i] + 1
                score += i
        if arrows_needed > num_arrows:
            continue
        if score > best_score:
            best_score = score
            best_mask = mask
    bob_arrows = [0] * n
