def longest_repeating_substring(s: str, query_characters, query_indices):
    n = len(s)
    size = 4 * n
    tree = [None] * size

    def make_node(ch):
        return {
            'len': 1,
            'leftChar': ch,
            'leftLen': 1,
            'rightChar': ch,
            'rightLen': 1,
            'best': 1
        }

    def merge(a, b):
        node = {
            'len': a['len'] + b['len'],
            'leftChar': a['leftChar'],
            'leftLen': a['leftLen'],
            'rightChar': b['rightChar'],
            'rightLen': b['rightLen'],
            'best': a['best'] if a['best'] > b['best'] else b['best']
        }

        if a['rightChar'] == b['leftChar']:
            cross = a['rightLen'] + b['leftLen']
            if cross > node['best']:
                node['best'] = cross

        if a['leftLen'] == a['len'] and a['rightChar'] == b['leftChar']:
            node['leftLen'] = a['len'] + b['leftLen']

        if b['rightLen'] == b['len'] and a['rightChar'] == b['leftChar']:
            node['rightLen'] = b['len'] + a['rightLen']

        return node

    def build(idx, l, r):
        if l == r:
            tree[idx] = make_node(s_list[l])
            return
        mid = (l + r) >> 1
        build(idx << 1, l, mid)
        build(idx << 1 | 1, mid + 1, r)
        tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1])

    def update(idx, l, r, pos, ch):
        if l == r:
            tree[idx] = make_node(ch)
            return
        mid = (l + r) >> 1
        if pos <= mid:
            update(idx << 1, l, mid, pos, ch)
        else:
            update(idx << 1 | 1, mid + 1, r, pos, ch)
        tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1])

    s_list = list(s)
    if n > 0:
        build(1, 0, n - 1)
    ans = []

    for i in range(len(query_indices)):
        pos = query_indices[i]
        ch = query_characters[i]
        if s_list[pos] != ch:
            s_list[pos] = ch
            update(1, 0, n - 1, pos, ch)
        ans.append(tree[1]['best'])
    return ans

