def max_value_of_coins(piles: List[List[int]], k: int) -> int:
    dp = [0] * (k + 1)
    for pile in piles:
        max_take = min(len(pile), k)
        pref = [0] * (max_take + 1)
        for t in range(1, max_take + 1):
            pref[t] = pref[t - 1] + pile[t - 1]
        nxt = dp[:]
        for j in range(k + 1):
            limit = min(max_take, j)
            for t in range(1, limit + 1):
                cand = dp[j - t] + pref[t]
                if cand > nxt[j]:
                    nxt[j] = cand
        dp = nxt
    return dp[k]

def number_of_ways(s: str) -> int:
