        return 0
    total_one = s.count('1')
    total_zero = n - total_one
    prefix_one = prefix_zero = 0
    ans = 0
    for ch in s:
        if ch == '0':
            ans += prefix_one * (total_one - prefix_one)
            prefix_zero += 1
        else:
            ans += prefix_zero * (total_zero - prefix_zero)
            prefix_one += 1
    return ans

