def maximum_candies(candies: list[int], k: int) -> int:
    if k == 0:
        return 0
    low = 1
    high = 0
    for v in candies:
        if v > high:
            high = v
    best = 0
    while low <= high:
        mid = (low + high) // 2
        pieces = 0
        for v in candies:
            pieces += v // mid
        if pieces >= k:
            best = mid
            low = mid + 1
        else:
            high = mid - 1
    return best

def sum_scores(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0
    Z = [0] * n
    Z[0] = n
    l = r = 0
    for i in range(1, n):
        if i <= r:
            Z[i] = min(r - i + 1, Z[i - l])
        while i + Z[i] < n and s[Z[i]] == s[i + Z[i]]:
            Z[i] += 1
        if i + Z[i] - 1 > r:
            l = i
            r = i + Z[i] - 1
    total = 0
    for v in Z:
        total += v
    return total

