class ATM:
    def __init__(self):
        self.denoms = [20, 50, 100, 200, 500]
        self.counts = [0]*5
    def deposit(self, banknotesCount) -> None:
        for i in range(5):
            self.counts[i] += banknotesCount[i]
    def withdraw(self, amount: int):
        used = [0]*5
        remaining = amount
        for i in range(4, -1, -1):
            need = remaining // self.denoms[i]
            take = min(need, self.counts[i])
            remaining -= take * self.denoms[i]
            used[i] = take
        if remaining != 0:
            return [-1]
        for i in range(5):
            self.counts[i] -= used[i]
        return used

