def maximum_score(scores: List[int], edges: List[List[int]]) -> int:
    n = len(scores)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    top_neighbors = [[] for _ in range(n)]
    for i in range(n):
        if adj[i]:
            neigh = sorted(adj[i], key=lambda x: scores[x], reverse=True)
            top_neighbors[i] = neigh[:3]

    best = -1
    for b, c in edges:
