def count_lattice_points(circles: List[Tuple[int, int, int]]) -> int:
    visited = set()
    for cx, cy, r in circles:
        r2 = r * r
        for x in range(cx - r, cx + r + 1):
            dx = x - cx
            max_dy = int(math.floor(math.sqrt(r2 - dx * dx)))
            for y in range(cy - max_dy, cy + max_dy + 1):
                visited.add((x, y))
    return len(visited)

