from typing import List

def escape_fire(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    INF = 10 ** 9 + 5

    # 1. multi‑source BFS for fire times (fire sources are cells with value 1,
    #    cells with value 2 are walls and never catch fire)
    fire_time = [[INF] * n for _ in range(m)]
    q = deque()
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:          # fire source
                fire_time[i][j] = 0
                q.append((i, j))
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while q:
        x, y = q.popleft()
        t = fire_time[x][y] + 1
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != 2 and fire_time[nx][ny] == INF:
                fire_time[nx][ny] = t
                q.append((nx, ny))

    # 2. check for unlimited waiting (a path that never meets fire)
    def reachable_without_fire() -> bool:
        if fire_time[0][0] != INF:
            return False
        vis = [[False] * n for _ in range(m)]
        dq = deque()
        dq.append((0, 0))
        vis[0][0] = True
        while dq:
            x, y = dq.popleft()
            if x == m - 1 and y == n - 1:
                return True
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not vis[nx][ny] and grid[nx][ny] != 2 and fire_time[nx][ny] == INF:
                    vis[nx][ny] = True
                    dq.append((nx, ny))
        return False

    if reachable_without_fire():
        return 10 ** 9

    # 3. feasibility check for a given waiting time W
    def can_wait(W: int) -> bool:
        if fire_time[0][0] <= W:
            return False
        dist = [[-1] * n for _ in range(m)]
        dq = deque()
        dq.append((0, 0))
        dist[0][0] = 0
        while dq:
            x, y = dq.popleft()
            d = dist[x][y]
            if x == m - 1 and y == n - 1:
                return True
            nd = d + 1
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if not (0 <= nx < m and 0 <= ny < n):
                    continue
                if grid[nx][ny] == 2 or dist[nx][ny] != -1:
                    continue
                arrival = W + nd
                if nx == m - 1 and ny == n - 1:
                    # reaching the safehouse is allowed even if fire arrives at the same time
                    if fire_time[nx][ny] >= arrival:
                        dist[nx][ny] = nd
                        dq.append((nx, ny))
                else:
                    if fire_time[nx][ny] > arrival:
                        dist[nx][ny] = nd
                        dq.append((nx, ny))
        return False

    # 4. binary search maximum waiting time
    if not can_wait(0):
        return -1
    lo, hi = 0, 10 ** 9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_wait(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

