def has_valid_path(grid: List[List[str]]) -> bool:
    m = len(grid)
    n = len(grid[0])
    max_bal = m + n

    dp_prev = [None] * n
    dp_curr = [None] * n

    for i in range(m):
        for j in range(n):
            cur_bal = bytearray(max_bal + 1)
            ch = grid[i][j]

            if i == 0 and j == 0:
                if ch == '(':
                    cur_bal[1] = 1
            else:
                from_top = dp_prev[j] if i > 0 else None
                from_left = dp_curr[j - 1] if j > 0 else None

                for b in range(max_bal + 1):
                    if (from_top and from_top[b]) or (from_left and from_left[b]):
                        if ch == '(' and b + 1 <= max_bal:
                            cur_bal[b + 1] = 1
                        elif ch == ')' and b > 0:
