def k_beauty(num: int, k: int) -> int:
    s = str(num)
    n = len(s)
    if k <= 0 or k > n:
        return 0
    power = 10 ** (k - 1)
    cur = 0
    for i in range(k):
        cur = cur * 10 + (ord(s[i]) - 48)
    ans = 0
    if cur > 0 and num % cur == 0:
        ans += 1
    for i in range(k, n):
        out_digit = ord(s[i - k]) - 48
        in_digit = ord(s[i]) - 48
        cur = (cur - out_digit * power) * 10 + in_digit
        if cur > 0 and num % cur == 0:
            ans += 1
    return ans

