        return 0
    freq_s: List[int] = [0] * 26
    for ch in s:
        idx = ord(ch) - 97
        if 0 <= idx < 26:
            freq_s[idx] += 1
    freq_t: List[int] = [0] * 26
    for ch in target:
        idx = ord(ch) - 97
        if 0 <= idx < 26:
            freq_t[idx] += 1
    max_copies = float('inf')
