class BookMyShow:
    def __init__(self, n: int, m: int):
        self.n = n
        self.m = m
        self.rem = [m]*n
        size = 4*n
        self.sum_arr = [0]*size
        self.mx = [0]*size
        self._build(1, 0, n-1)
    def _pull(self, node):
        self.sum_arr[node] = self.sum_arr[node*2] + self.sum_arr[node*2+1]
        self.mx[node] = max(self.mx[node*2], self.mx[node*2+1])
    def _build(self, node, l, r):
        if l == r:
            self.sum_arr[node] = self.m
            self.mx[node] = self.m
        else:
            mid = (l+r)//2
            self._build(node*2, l, mid)
            self._build(node*2+1, mid+1, r)
            self._pull(node)
    def _update(self, node, l, r, idx, val):
        if l == r:
            self.sum_arr[node] = val
            self.mx[node] = val
        else:
            mid = (l+r)//2
            if idx <= mid: self._update(node*2, l, mid, idx, val)
            else: self._update(node*2+1, mid+1, r, idx, val)
            self._pull(node)
    def _query_sum(self, node, l, r, ql, qr):
        if ql > r or qr < l: return 0
        if ql <= l and r <= qr: return self.sum_arr[node]
        mid = (l+r)//2
        return self._query_sum(node*2,l,mid,ql,qr) + self._query_sum(node*2+1,mid+1,r,ql,qr)
    def _find_gather(self, node, l, r, maxRow, k):
        if l > maxRow or self.mx[node] < k: return -1
        if l == r: return l
        mid = (l+r)//2
        left = self._find_gather(node*2, l, mid, maxRow, k)
        if left != -1: return left
        return self._find_gather(node*2+1, mid+1, r, maxRow, k)
    def _find_first_positive(self, node, l, r, maxRow):
        if l > maxRow or self.mx[node] == 0: return -1
        if l == r: return l
        mid = (l+r)//2
        left = self._find_first_positive(node*2, l, mid, maxRow)
        if left != -1: return left
        return self._find_first_positive(node*2+1, mid+1, r, maxRow)
    def gather(self, k: int, maxRow: int):
        row = self._find_gather(1, 0, self.n-1, maxRow, k)
        if row == -1: return []
        start_seat = self.m - self.rem[row]
        self.rem[row] -= k
        self._update(1, 0, self.n-1, row, self.rem[row])
        return [row, start_seat]
    def scatter(self, k: int, maxRow: int) -> bool:
        total = self._query_sum(1, 0, self.n-1, 0, maxRow)
        if total < k: return False
        while k > 0:
            row = self._find_first_positive(1, 0, self.n-1, maxRow)
            take = min(self.rem[row], k)
            self.rem[row] -= take
            self._update(1, 0, self.n-1, row, self.rem[row])
            k -= take
        return True

