def match_substring_after_replacement(s: str, sub: str, mappings: List[Tuple[str, str]]) -> bool:
    replace_map: Dict[str, Set[str]] = {}
    for old, new in mappings:
        replace_map.setdefault(old, set()).add(new)

    allowed: Dict[str, Set[str]] = {}
    for ch in set(sub):
        chars = {ch}
        if ch in replace_map:
            chars.update(replace_map[ch])
        allowed[ch] = chars

    n, m = len(s), len(sub)
    if m > n:
        return False

    for i in range(n - m + 1):
