def distribute_cookies(cookies: List[int], k: int) -> int:
    cookies.sort(reverse=True)
    n = len(cookies)
    if k >= n:
        return max(cookies) if cookies else 0

    total = sum(cookies)
    low = max(cookies)
    high = total

    while low < high:
        mid = (low + high) // 2
        load = [0] * k

        def dfs(idx: int) -> bool:
            if idx == n:
                return True
            cur = cookies[idx]
            for i in range(k):
                if load[i] + cur > mid:
                    continue
                load[i] += cur
                if dfs(idx + 1):
                    return True
                load[i] -= cur
                if load[i] == 0:
                    break
            return False

        if dfs(0):
            high = mid
        else:
            low = mid + 1

    return low

