def max_profit(m: int, n: int, prices: List[Tuple[int, int, int]]) -> int:
    price_map = [[0] * (n + 1) for _ in range(m + 1)]
    for h, w, p in prices:
        if h <= m and w <= n and p > price_map[h][w]:
            price_map[h][w] = p

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for h in range(1, m + 1):
        for w in range(1, n + 1):
            best = price_map[h][w]
            for cut in range(1, h):
                cur = dp[cut][w] + dp[h - cut][w]
                if cur > best:
                    best = cur
            for cut in range(1, w):
                cur = dp[h][cut] + dp[h][w - cut]
                if cur > best:
                    best = cur
            dp[h][w] = best

    return dp[m][n]

