def count_pairs(n: int, edges: List[List[int]]) -> int:
    parent = [i for i in range(n)]
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    for u, v in edges:
        union(u, v)

    comp_count = {}
    for i in range(n):
        root = find(i)
        comp_count[root] = comp_count.get(root, 0) + 1

    total_pairs = n * (n - 1) // 2
    intra_pairs = 0
    for c in comp_count.values():
        intra_pairs += c * (c - 1) // 2

    return total_pairs - intra_pairs

