    MOD = 1_000_000_007
    start = [0] * (n + 2)
    end = [0] * (n + 2)

    active = 0
    result = 0

    if 1 + delay <= n:
        start[1 + delay] = 1
    if 1 + forget <= n:
        end[1 + forget] = 1
    if 1 + forget > n:
        result = (result + 1) % MOD

    for day in range(2, n + 1):
        active = (active + start[day] - end[day]) % MOD
        dp_day = active
        if dp_day:
            if day + delay <= n:
                start[day + delay] = (start[day + delay] + dp_day) % MOD
            if day + forget <= n:
                end[day + forget] = (end[day + forget] + dp_day) % MOD
