def count_increasing_paths(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    def dfs(i: int, j: int) -> int:
        if dp[i][j]:
            return dp[i][j]
        total = 1
        for dx, dy in DIRS:
            x, y = i + dx, j + dy
            if x < 0 or x >= m or y < 0 or y >= n:
                continue
            if grid[x][y] <= grid[i][j]:
                continue
            total = (total + dfs(x, y)) % MOD
        dp[i][j] = total
        return total

    answer = 0
    for i in range(m):
        for j in range(n):
            answer = (answer + dfs(i, j)) % MOD
    return answer

