MOD = 10**9 + 7

def count_ideal_arrays(n: int, maxValue: int) -> int:
    spf = list(range(maxValue + 1))
    limit_i = int(maxValue ** 0.5) + 1
    for i in range(2, limit_i):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, maxValue + 1, step):
                if spf[j] == j:
                    spf[j] = i

    total_exp = [0] * (maxValue + 1)
    max_exp = 0
    for i in range(2, maxValue + 1):
        p = spf[i]
        total_exp[i] = total_exp[i // p] + 1
        if total_exp[i] > max_exp:
            max_exp = total_exp[i]

    limit = n - 1 + max_exp
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a: int, b: int) -> int:
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    ans = 0
    for i in range(1, maxValue + 1):
        ans = (ans + comb(n - 1 + total_exp[i], total_exp[i])) % MOD
    return ans

