        comb = 1
        for i in range(1, L + 1):
            comb = comb * (n - i + 1) // i
            if comb >= total:
                break
        if total > comb:
            return L

        # depth‑first search with early exit
        stack = [(0, -1)]  # (depth, last_index)
        while stack:
            depth, cur = stack.pop()
            if depth == L:
                continue
            for v in range(1, k + 1):
                lst = pos[v]
                idx = bisect.bisect_right(lst, cur)
                if idx == len(lst):
                    return L
                stack.append((depth + 1, lst[idx]))
        L += 1

import heapq

class NumberContainers:
    def __init__(self):
        self.num_to_heap = {}
        self.index_to_num = {}
    def change(self, index: int, number: int) -> None:
        self.index_to_num[index] = number
        self.num_to_heap.setdefault(number, [])
        heapq.heappush(self.num_to_heap[number], index)
    def find(self, number: int) -> int:
        heap = self.num_to_heap.get(number)
        if not heap: return -1
        while heap and self.index_to_num.get(heap[0]) != number:
            heapq.heappop(heap)
        return heap[0] if heap else -1

