def number_of_excellent_pairs(nums: List[int], k: int) -> int:
    # Use distinct values only, as the problem definition counts pairs of values,
    # not positions, and allows ordered pairs (including a value paired with itself).
    distinct_vals = set(nums)
    max_bits = 60
    freq = [0] * (max_bits + 1)

    for v in distinct_vals:
        pc = v.bit_count() if hasattr(v, "bit_count") else bin(v).count("1")
        freq[pc] += 1

    ans = 0
    for i in range(max_bits + 1):
        if freq[i] == 0:
            continue
        for j in range(max_bits + 1):
            if freq[j] == 0:
                continue
            if i + j >= k:
                ans += freq[i] * freq[j]
    return ans

