def longest_cycle(edges: List[int]) -> int:
    n = len(edges)
    visited = [False] * n
    best = -1
    for i in range(n):
        if visited[i]:
            continue
        cur = i
        step = 0
        local_step = {}
        while cur != -1 and not visited[cur]:
            visited[cur] = True
            local_step[cur] = step
            cur = edges[cur]
            step += 1
        if cur != -1 and cur in local_step:
            cycle_len = step - local_step[cur]
            if cycle_len > best:
                best = cycle_len
    return best

