_fact = [factorial(i) for i in range(11)]

def _perm(m: int, k: int) -> int:
    if k <= 0:
        return 1
    if k > m:
        return 0
    return _fact[m] // _fact[m - k]

def count_special(n: int) -> int:
    if n <= 0:
        return 0
    s = str(n)
    L = len(s)
    total = 0
    for l in range(1, L):
        total += 9 * _perm(9, l - 1)
    used = set()
    for i, ch in enumerate(s):
        cur = int(ch)
        start = 1 if i == 0 else 0
        for d in range(start, cur):
            if d in used:
                continue
            remaining = L - i - 1
            available = 10 - (i + 1)
            total += _perm(available, remaining)
        if cur in used:
            break
        used.add(cur)
    else:
        total += 1
    return total

