def largest_palindromic(num: str) -> str:
    cnt = [0] * 10
    for ch in num:
        cnt[ord(ch) - 48] += 1

    left_parts = []
    # add pairs for digits 9..1
    for d in range(9, 0, -1):
        pair = cnt[d] // 2
        if pair:
            left_parts.append(str(d) * pair)
            cnt[d] -= pair * 2

    # add zero pairs only if we already have a non‑zero left part
    if left_parts:
        zero_pair = cnt[0] // 2
        if zero_pair:
            left_parts.append('0' * zero_pair)
            cnt[0] -= zero_pair * 2

    left = ''.join(left_parts)

    # choose the highest remaining digit for the middle (if any)
    middle = ''
    for d in range(9, -1, -1):
        if cnt[d] > 0:
            middle = str(d)
            break

    if not left and not middle:
        return '0'
    if not left:
        return middle

    result = left + middle + left[::-1]
    # result cannot start with '0' because left starts with a non‑zero digit
    return result

def min_recolors(blocks: str, k: int) -> int:
    n = len(blocks)
    if k == 0:
        return 0
    if k > n:
