    for i in range(k):
        if blocks[i] == 'W':
            white_in_window += 1
    min_white = white_in_window
    for i in range(k, n):
        if blocks[i - k] == 'W':
            white_in_window -= 1
        if blocks[i] == 'W':
            white_in_window += 1
        if white_in_window < min_white:
            min_white = white_in_window
    return min_white

def amount_of_time(root, start):
    adj = {}
    def dfs(node):
        if not node:
            return
        if node.val not in adj:
            adj[node.val] = []
        if node.left:
            if node.left.val not in adj:
                adj[node.left.val] = []
            adj[node.val].append(node.left.val)
            adj[node.left.val].append(node.val)
            dfs(node.left)
        if node.right:
            if node.right.val not in adj:
                adj[node.right.val] = []
            adj[node.val].append(node.right.val)
            adj[node.right.val].append(node.val)
            dfs(node.right)
    dfs(root)
    from collections import deque
    queue = deque([start])
    visited = {start}
    minutes = -1
    while queue:
        size = len(queue)
        minutes += 1
        for _ in range(size):
            cur = queue.popleft()
            for nb in adj.get(cur, []):
                if nb not in visited:
                    visited.add(nb)
                    queue.append(nb)
    return minutes

