def build_matrix(k: int, row_conditions: List[List[int]], col_conditions: List[List[int]]) -> List[List[int]]:
    def topo_sort(edges: List[List[int]]) -> List[int] | None:
        adj: List[List[int]] = [[] for _ in range(k + 1)]
        indeg: List[int] = [0] * (k + 1)
        for u, v in edges:
            adj[u].append(v)
            indeg[v] += 1
        stack: List[int] = [i for i in range(1, k + 1) if indeg[i] == 0]
        order: List[int] = []
        while stack:
            cur = stack.pop()
            order.append(cur)
            for nxt in adj[cur]:
                indeg[nxt] -= 1
                if indeg[nxt] == 0:
                    stack.append(nxt)
        return order if len(order) == k else None

    row_order = topo_sort(row_conditions)
    col_order = topo_sort(col_conditions)
    if not row_order or not col_order:
        return []
    row_pos: List[int] = [0] * (k + 1)
    col_pos: List[int] = [0] * (k + 1)
    for i, v in enumerate(row_order):
        row_pos[v] = i
    for i, v in enumerate(col_order):
        col_pos[v] = i
    ans: List[List[int]] = [[0] * k for _ in range(k)]
    for v in range(1, k + 1):
        ans[row_pos[v]][col_pos[v]] = v
    return ans
# TIME: O(k + len(row_conditions) + len(col_conditions)) SPACE: O(k)

