def max_rows_covered(matrix: list[list[int]], num_select: int) -> int:
    if not matrix or not matrix[0] or num_select <= 0:
        return 0
    m, n = len(matrix), len(matrix[0])
    if num_select > n:
        num_select = n
    from collections import Counter
    freq = Counter()
    for row in matrix:
        mask = 0
        for j, v in enumerate(row):
            if v:
                mask |= 1 << j
        freq[mask] += 1
    best = 0
    from itertools import combinations
    cols = range(n)
    for comb in combinations(cols, num_select):
        chosen_mask = 0
        for c in comb:
            chosen_mask |= 1 << c
        covered = 0
        sub = chosen_mask
        while True:
            covered += freq.get(sub, 0)
            if sub == 0:
                break
            sub = (sub - 1) & chosen_mask
        if covered > best:
            best = covered
    return best

