def reconstruct_matrix(upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
    n = len(colsum)
    row0 = [0] * n
    row1 = [0] * n
    upper_rem = upper
    lower_rem = lower

    # First handle columns that must have a 1 in both rows
    for i, v in enumerate(colsum):
        if v == 2:
            row0[i] = 1
            row1[i] = 1
            upper_rem -= 1
            lower_rem -= 1
            if upper_rem < 0 or lower_rem < 0:
                return []

    # Then handle columns that have a single 1
    for i, v in enumerate(colsum):
        if v == 1:
            if upper_rem > 0:
                row0[i] = 1
                upper_rem -= 1
            elif lower_rem > 0:
                row1[i] = 1
                lower_rem -= 1
            else:
                return []

    # Verify that all required sums are satisfied
    if upper_rem != 0 or lower_rem != 0:
        return []

    return [row0, row1]

