def max_score_words(words: List[str], letters: List[str], score: List[int]) -> int:
    letter_count = [0] * 26
    for letter in letters:
        letter_count[ord(letter) - ord('a')] += 1

    word_counts = []
    for word in words:
        count = [0] * 26
        for letter in word:
            count[ord(letter) - ord('a')] += 1
        word_counts.append(count)

    max_score = 0
    n = len(words)
    for mask in range(1 << n):
        current_score = 0
        current_count = [0] * 26
        for i in range(n):
            if mask & (1 << i):
                word_count = word_counts[i]
                for j in range(26):
                    if current_count[j] + word_count[j] > letter_count[j]:
                        current_score = -1
                        break
                if current_score == -1:
                    break
                for j in range(26):
                    current_count[j] += word_count[j]
                    current_score += score[j] * word_count[j]
        if current_score > max_score:
            max_score = current_score
    return max_score

