                frequency[nums[i]] += 1
            else:
                frequency[nums[i]] = 1

    max_frequency = 0
    smallest_element = -1

    for key, freq in frequency.items():
        if freq > max_frequency:
            max_frequency = freq
            smallest_element = key
        elif freq == max_frequency and key < smallest_element:
            smallest_element = key

    return smallest_element if smallest_element != -1 else -1

