def min_groups(intervals: List[List[int]]) -> int:
    if not intervals:
        return 0
    starts = sorted(interval[0] for interval in intervals)
    ends = sorted(interval[1] for interval in intervals)
    i = j = 0
    current = max_groups = 0
    n = len(intervals)
    while i < n:
        if starts[i] <= ends[j]:
            current += 1
            if current > max_groups:
                max_groups = current
            i += 1
