def paths_divisible(grid, k):
    MOD = 1_000_000_007
    m = len(grid)
    n = len(grid[0])
    dp_prev = [[0] * k for _ in range(n)]

    for i in range(m):
        dp_curr = [[0] * k for _ in range(n)]
        for j in range(n):
            val_mod = grid[i][j] % k
            cur = dp_curr[j]

            if i == 0 and j == 0:
                cur[val_mod] = 1
                continue

            if i > 0:
                top = dp_prev[j]
                for r in range(k):
                    cnt = top[r]
                    if cnt:
                        nr = (r + val_mod) % k
                        cur[nr] = (cur[nr] + cnt) % MOD

            if j > 0:
                left = dp_curr[j - 1]
                for r in range(k):
                    cnt = left[r]
                    if cnt:
                        nr = (r + val_mod) % k
                        cur[nr] = (cur[nr] + cnt) % MOD

        dp_prev = dp_curr

    return dp_prev[n - 1][0]

