def magnificent_sets(n: int, edges: List[List[int]]) -> int:
    # build adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    color = [-1] * (n + 1)          # -1 = uncolored, 0/1 = two colors
    visited = [False] * (n + 1)
    answer = 0

    # helper to compute diameter of a component starting from src
    def bfs_diameter(src: int) -> int:
        q = deque([src])
        seen = {src}
        dist = {src: 0}
        max_dist = 0
        while q:
            u = q.popleft()
            du = dist[u]
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    dist[v] = du + 1
                    max_dist = max(max_dist, du + 1)
                    q.append(v)
        return max_dist

    for i in range(1, n + 1):
        if not visited[i]:
            # BFS to explore the component, check bipartiteness, and find a farthest node
            q = deque([i])
            visited[i] = True
            color[i] = 0
            far_node = i
            dist_local = {i: 0}
            while q:
                u = q.popleft()
                du = dist_local[u]
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        visited[v] = True
                        dist_local[v] = du + 1
                        if dist_local[v] > dist_local[far_node]:
                            far_node = v
                        q.append(v)
                    else:
                        if color[v] == color[u]:
                            return -1  # not bipartite
            # component is bipartite; compute its diameter
            diameter = bfs_diameter(far_node)
            answer += diameter + 1

    return answer

