def divide_players(skill: List[int]) -> int:
    n = len(skill)
    total = sum(skill)
    target = (2 * total) / n
    if target != int(target):
        return -1
    target = int(target)

    cnt = {}
    for v in skill:
        cnt[v] = cnt.get(v, 0) + 1

    chemistry_sum = 0
    for val in list(cnt.keys()):
        while cnt.get(val, 0) > 0:
            partner = target - val
            if cnt.get(partner, 0) == 0:
                return -1
            if partner == val and cnt.get(val, 0) < 2:
                return -1
            cnt[val] -= 1
            cnt[partner] -= 1
            chemistry_sum += val * partner

    return chemistry_sum

