def longest_square_streak(nums: List[int]) -> int:
    present = set(nums)
    memo = {}
    def chain_len(x: int) -> int:
        if x not in present:
            return 0
        if x in memo:
            return memo[x]
        nxt = x * x
        length = 1
        if nxt in present:
            length = 1 + chain_len(nxt)
        memo[x] = length
        return length
    best = 0
    for v in present:
        best = max(best, chain_len(v))
    return best if best >= 2 else -1

