        degree_parity[u] ^= 1
        degree_parity[v] ^= 1

    odd_nodes = [i for i in range(1, n + 1) if degree_parity[i]]
    odd_cnt = len(odd_nodes)

    if odd_cnt == 0:
        return True
    if odd_cnt > 4:
        return False

    if odd_cnt == 2:
        a, b = odd_nodes
        if (min(a, b), max(a, b)) not in edge_set:
            return True
        for c in range(1, n + 1):
            if c == a or c == b:
                continue
            if (min(a, c), max(a, c)) in edge_set:
                continue
            if (min(b, c), max(b, c)) in edge_set:
                continue
            return True
        return False

    # odd_cnt == 4
    o = odd_nodes
    pairings = [
        ((o[0], o[1]), (o[2], o[3])),
        ((o[0], o[2]), (o[1], o[3])),
        ((o[0], o[3]), (o[1], o[2])),
    ]
    for (x1, y1), (x2, y2) in pairings:
        e1 = (min(x1, y1), max(x1, y1))
        e2 = (min(x2, y2), max(x2, y2))
        if e1 not in edge_set and e2 not in edge_set:
            return True
    return False

