def smallest_value(n: int) -> int:
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        d = 3
        while d * d <= x:
            if x % d == 0:
                return False
            d += 2
        return True

    def sum_prime_factors(x: int) -> int:
        total = 0
        while x % 2 == 0:
            total += 2
            x //= 2
        d = 3
        while d * d <= x:
            while x % d == 0:
                total += d
                x //= d
            d += 2
        if x > 1:
            total += x
        return total

    while n > 1 and not is_prime(n):
        n = sum_prime_factors(n)
    return n

