def top_students(positive_feedback, negative_feedback, report, student_id, k):
    pos_set = set(positive_feedback)
    neg_set = set(negative_feedback)

    points = {}
    for i in range(len(report)):
        words = report[i].split(' ')
        cur = 0
        for w in words:
            if w in pos_set:
                cur += 3
            elif w in neg_set:
                cur -= 1
        sid = student_id[i]
        points[sid] = points.get(sid, 0) + cur

    heap = []

    def less(a, b):
        return a['pts'] < b['pts'] or (a['pts'] == b['pts'] and a['id'] > b['id'])

    def swap(i, j):
        heap[i], heap[j] = heap[j], heap[i]

    def heapify_up(idx):
        while idx > 0:
            p = (idx - 1) >> 1
            if not less(heap[idx], heap[p]):
                break
            swap(idx, p)
            idx = p

    def heapify_down(idx):
        n = len(heap)
        while True:
            left = idx * 2 + 1
            right = left + 1
            smallest = idx
            if left < n and less(heap[left], heap[smallest]):
                smallest = left
            if right < n and less(heap[right], heap[smallest]):
                smallest = right
            if smallest == idx:
                break
            swap(idx, smallest)
            idx = smallest

    def push(node):
        heap.append(node)
        heapify_up(len(heap) - 1)
        if len(heap) > k:
            heap[0] = heap.pop()
            heapify_down(0)

    for sid, pts in points.items():
        push({'id': sid, 'pts': pts})

    heap.sort(key=lambda x: (-x['pts'], x['id']))
    return [x['id'] for x in heap]

