def maximum_tastiness(price: List[int], k: int) -> int:
    price.sort()
    def can_place(dist: int) -> bool:
        count = 1
        last = price[0]
        for i in range(1, len(price)):
            if price[i] - last >= dist:
                count += 1
                last = price[i]
                if count == k:
                    return True
        return False
    low, high = 0, price[-1] - price[0]
    while low < high:
        mid = (low + high + 1) // 2
        if can_place(mid):
            low = mid
        else:
            high = mid - 1
    return low

def min_minutes(s: str, k: int) -> int:
    n = len(s)
    total_a = s.count('a')
    total_b = s.count('b')
    total_c = s.count('c')
    if total_a < k or total_b < k or total_c < k:
        return -1
    limit_a = total_a - k
    limit_b = total_b - k
    limit_c = total_c - k
    cnt_a = cnt_b = cnt_c = 0
    left = 0
    max_len = 0
    for right, ch in enumerate(s):
        if ch == 'a':
            cnt_a += 1
        elif ch == 'b':
            cnt_b += 1
        else:
            cnt_c += 1
        while cnt_a > limit_a or cnt_b > limit_b or cnt_c > limit_c:
            ch_left = s[left]
            if ch_left == 'a':
                cnt_a -= 1
            elif ch_left == 'b':
                cnt_b -= 1
            else:
                cnt_c -= 1
            left += 1
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return n - max_len

def count_anagrams(s: str) -> int:
    MOD = 1000000007

    words = s.split(' ')
    max_len = 0
    for w in words:
        if len(w) > max_len:
            max_len = len(w)

    fact = [0] * (max_len + 1)
    inv_fact = [0] * (max_len + 1)
    fact[0] = 1
    for i in range(1, max_len + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    def mod_pow(base: int, exp: int) -> int:
        res = 1
        b = base % MOD
        e = exp
        while e > 0:
            if e & 1:
                res = (res * b) % MOD
            b = (b * b) % MOD
            e >>= 1
        return res

    inv_fact[max_len] = mod_pow(fact[max_len], MOD - 2)
    for i in range(max_len, 0, -1):
        inv_fact[i - 1] = (inv_fact[i] * i) % MOD

    answer = 1
    for w in words:
        ways = fact[len(w)]
        freq = {}
        for ch in w:
            freq[ch] = freq.get(ch, 0) + 1
        for cnt in freq.values():
            ways = (ways * inv_fact[cnt]) % MOD
        answer = (answer * ways) % MOD

    return answer

