    return parts + 1

def number_of_great_partitions(nums: list[int], k: int) -> int:
    MOD = 1_000_000_007
    total = sum(nums)
    if k > total:
        return 0
    dp = [0] * (total + 1)
    dp[0] = 1
    cur_max = 0
    for v in nums:
        for t in range(cur_max, -1, -1):
            add = dp[t]
            if add:
                nxt = t + v
                val = dp[nxt] + add
                if val >= MOD:
                    val -= MOD
                dp[nxt] = val
        cur_max += v
    ans = 0
    upper = total - k
    for t in range(k, upper + 1):
        ans += dp[t]
        if ans >= MOD:
            ans -= MOD
    return ans

