def closest_primes(left: int, right: int) -> List[int]:
    limit = right
    is_prime = bytearray(limit + 1)
    if limit >= 2:
        is_prime[2:] = b'\x01' * (limit - 1)
    p = 2
    while p * p <= limit:
        if is_prime[p] == 1:
            mult = p * p
            step = p
            while mult <= limit:
                is_prime[mult] = 2
                mult += step
        p += 1

    primes_in_range = []
    start = max(2, left)
    for i in range(start, right + 1):
        if is_prime[i] == 1:
            primes_in_range.append(i)

    if len(primes_in_range) < 2:
        return [-1, -1]

    best_gap = float('inf')
    best_pair = [-1, -1]
    for i in range(1, len(primes_in_range)):
        gap = primes_in_range[i] - primes_in_range[i - 1]
        if gap < best_gap:
            best_gap = gap
            best_pair = [primes_in_range[i - 1], primes_in_range[i]]
    return best_pair

