def maximum_count(nums: List[int]) -> int:
    def first_greater(arr: List[int], target: int) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] > target:
                hi = mid
            else:
                lo = mid + 1
        return lo

    def first_ge(arr: List[int], target: int) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] >= target:
                hi = mid
            else:
                lo = mid + 1
        return lo

    n = len(nums)
    first_non_neg = first_ge(nums, 0)
    first_pos = first_greater(nums, 0)
    neg_count = first_non_neg
    pos_count = n - first_pos
    return neg_count if neg_count > pos_count else pos_count

