def make_number_of_distinct_characters_equal(word1: str, word2: str) -> bool:
    freq1: List[int] = [0] * 26
    freq2: List[int] = [0] * 26
    for ch in word1:
        idx = ord(ch) - 97
        if 0 <= idx < 26:
            freq1[idx] += 1
    for ch in word2:
        idx = ord(ch) - 97
        if 0 <= idx < 26:
            freq2[idx] += 1

    d1 = sum(1 for v in freq1 if v > 0)
    d2 = sum(1 for v in freq2 if v > 0)

    # If we swap the same character, counts stay the same
    if d1 == d2:
        return True

    for a in range(26):
        if freq1[a] == 0:
            continue
        for b in range(26):
            if freq2[b] == 0:
                continue
            # swapping same character does not change distinct counts,
            # already handled above
            delta1 = (1 if freq1[b] == 0 else 0) - (1 if freq1[a] == 1 else 0)
            delta2 = (1 if freq2[a] == 0 else 0) - (1 if freq2[b] == 1 else 0)
            if d1 + delta1 == d2 + delta2:
                return True
    return False

