def count_good_subarrays(nums: List[int], k: int) -> int:
    n = len(nums)
    if k <= 0:
        return n * (n + 1) // 2

    freq = {}
    pair_cnt = 0
    left = 0
    answer = 0

    for right in range(n):
        val = nums[right]
        cur = freq.get(val, 0)
        pair_cnt += cur
        freq[val] = cur + 1

        while pair_cnt >= k:
            left_val = nums[left]
            left_cnt = freq[left_val]
            pairs_lost = left_cnt - 1
            if pair_cnt - pairs_lost < k:
                break
            pair_cnt -= pairs_lost
            if left_cnt == 1:
                del freq[left_val]
            else:
                freq[left_val] = left_cnt - 1
            left += 1

        if pair_cnt >= k:
            answer += left + 1

    return answer

