from collections import deque

def minimum_operations(root):
    if root is None:
        return 0
    result = 0
    queue = deque([root])
    while queue:
        level_size = len(queue)
        level_values = []
        for _ in range(level_size):
            node = queue.popleft()
            level_values.append(node.val)
            if node.left is not None:
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
        sorted_level_values = sorted(level_values)
        # decompose the permutation into cycles: a cycle of length L needs (L-1) swaps
        index_mapping = {v: i for i, v in enumerate(level_values)}
        visited = [False] * level_size
        for i in range(level_size):
            if visited[i] or level_values[i] == sorted_level_values[i]:
                continue
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = index_mapping[sorted_level_values[j]]
                cycle_size += 1
            result += cycle_size - 1
    return result

