def distinct_integers(n: int) -> int:
    """
    Returns the number of distinct integers that will appear on the board
    after repeatedly adding, for each current integer x, every integer y>1
    such that x % y == 1 (equivalently, y is a divisor of x-1).
    The process stabilises after a few iterations because numbers only
    decrease.
    """
    if n < 2:
        return 1  # only the initial number itself

    visited = {n}
    stack = [n]

    while stack:
        x = stack.pop()
        m = x - 1
        if m < 2:
            continue
        # find all divisors of m greater than 1
        d = 2
        while d * d <= m:
            if m % d == 0:
                if d not in visited:
                    visited.add(d)
                    stack.append(d)
                other = m // d
                if other != d and other not in visited:
                    visited.add(other)
                    stack.append(other)
            d += 1
        # m itself is also a divisor (if >1)
        if m not in visited:
            visited.add(m)
            stack.append(m)

    return len(visited)

