def is_possible_to_disconnect(grid: List[List[int]]) -> bool:
    m = len(grid)
    n = len(grid[0])
    # forward reachable from (0,0)
    f = [[False] * n for _ in range(m)]
    if grid[0][0] == 1:
        f[0][0] = True
    for i in range(m):
        row_f = f[i]
        for j in range(n):
            if grid[i][j] != 1:
                continue
            if i > 0 and f[i - 1][j]:
                row_f[j] = True
            if j > 0 and row_f[j - 1]:
                row_f[j] = True
            if i == 0 and j == 0:
                row_f[j] = True
    if not f[m - 1][n - 1]:
        return True

    total_diagonals = m + n - 1
    cnt = [0] * total_diagonals
    cell_i = [-1] * total_diagonals
    cell_j = [-1] * total_diagonals

    # backward reachable and count per diagonal
    b_next = [False] * n  # row i+1 values
    for i in range(m - 1, -1, -1):
        b_curr = [False] * n
        for j in range(n - 1, -1, -1):
            if grid[i][j] != 1:
                continue
            if i == m - 1 and j == n - 1:
                b_curr[j] = True
            else:
                if i < m - 1 and b_next[j]:
                    b_curr[j] = True
                if j < n - 1 and b_curr[j + 1]:
                    b_curr[j] = True
            if b_curr[j] and f[i][j]:
                k = i + j
                if cnt[k] == 0:
                    cell_i[k] = i
                    cell_j[k] = j
                cnt[k] += 1
        b_next = b_curr

    for k in range(total_diagonals):
        if cnt[k] == 1:
            i, j = cell_i[k], cell_j[k]
