def take_gifts(gifts: List[int], k: int) -> int:
    heap: List[int] = []

    def heap_swap(i: int, j: int) -> None:
        heap[i], heap[j] = heap[j], heap[i]

    def heap_push(val: int) -> None:
        heap.append(val)
        idx = len(heap) - 1
        while idx > 0:
            parent = (idx - 1) >> 1
            if heap[parent] >= heap[idx]:
                break
            heap_swap(parent, idx)
            idx = parent

    def heap_pop() -> int:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            idx = 0
            while True:
                left = idx * 2 + 1
                right = left + 1
                largest = idx
                if left < len(heap) and heap[left] > heap[largest]:
                    largest = left
                if right < len(heap) and heap[right] > heap[largest]:
                    largest = right
                if largest == idx:
                    break
                heap_swap(idx, largest)
                idx = largest
        return top

    for v in gifts:
        heap_push(v)

    for _ in range(k):
        mx = heap_pop()
        new_val = math.isqrt(mx)
        heap_push(new_val)
        if mx == 1:
            break

    total = 0
    for v in heap:
        total += v
    return total

