# mask_of[x] = bitmask of prime factors of x if x is square‑free, else -1
_mask_of = [-1] * 31
for x in range(2, 31):
    temp = x
    mask = 0
    ok = True
    for p in PRIMES:
        if p * p > temp:
            break
        cnt = 0
        while temp % p == 0:
            temp //= p
            cnt += 1
        if cnt > 1:
            ok = False
            break
        if cnt == 1:
            mask |= 1 << _prime_to_bit[p]
    if not ok:
