def countSquareFreeSubsets(nums: List[int]) -> int:
    cnt_one = 0
    freq = {}
    for x in nums:
        if x == 1:
            cnt_one += 1
            continue
        if x <= 30:
            m = _mask_of[x]
            if m == -1:
                continue
            freq[m] = freq.get(m, 0) + 1

    size = 1 << len(PRIMES)
    dp = [0] * size
    dp[0] = 1

    for m, f in freq.items():
        for s in range(size - 1, -1, -1):
            if dp[s] and (s & m) == 0:
                dp[s | m] = (dp[s | m] + dp[s] * f) % MOD

    total_nonempty = (sum(dp) - dp[0]) % MOD
    ans = ((total_nonempty + 1) * pow(2, cnt_one, MOD) - 1) % MOD
    return ans

import heapq

def min_time(grid):
    m, n = len(grid), len(grid[0])
    INF = float('inf')
    dist = [[INF] * n for _ in range(m)]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    start_time = max(0, grid[0][0])
    dist[0][0] = start_time
    heap = [(start_time, 0, 0)]
    while heap:
        time, r, c = heapq.heappop(heap)
        if time != dist[r][c]:
            continue
        if r == m - 1 and c == n - 1:
            return time
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                arrival = time + 1
                if arrival >= grid[nr][nc]:
                    if arrival < dist[nr][nc]:
                        dist[nr][nc] = arrival
                        heapq.heappush(heap, (arrival, nr, nc))
    return -1

