def find_string(lcp: List[List[int]]) -> str:
    n = len(lcp)
    if n == 0:
        return ""
    for row in lcp:
        if len(row) != n:
            return ""
    for i in range(n):
        if lcp[i][i] != n - i:
            return ""
        for j in range(i + 1, n):
            if lcp[i][j] != lcp[j][i]:
                return ""
            if not (0 <= lcp[i][j] <= min(n - i, n - j)):
                return ""

    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int) -> None:
        a = find(a)
        b = find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    nxt = list(range(n + 1))

    def next_unprocessed(x: int) -> int:
        if x >= n:
            return n
        if nxt[x] == x:
            return x
        nxt[x] = next_unprocessed(nxt[x])
        return nxt[x]

    for d in range(1, n):
        i = 0
        while i < n - d:
            k = lcp[i][i + d]
            limit = i + k
            p = next_unprocessed(i)
            while p < limit:
                unite(p, p + d)
                nxt[p] = p + 1
                p = next_unprocessed(p)
            i += 1

    adj_map = {}
    for i in range(n):
        for j in range(i + 1, n):
            k = lcp[i][j]
            max_len = min(n - i, n - j)
            if k < max_len:
                a = find(i + k)
                b = find(j + k)
                if a == b:
                    return ""
                adj_map.setdefault(a, set()).add(b)
                adj_map.setdefault(b, set()).add(a)

    comp_index = {}
    comp_id = [0] * n
    idx = 0
    for i in range(n):
        r = find(i)
        if r not in comp_index:
            comp_index[r] = idx
            idx += 1
        comp_id[i] = comp_index[r]

    m = idx
    adj = [[] for _ in range(m)]
    for u_root, neigh in adj_map.items():
        u = comp_index[u_root]
        for v_root in neigh:
            v = comp_index[v_root]
            adj[u].append(v)

    color = [-1] * m
    for u in range(m):
        if color[u] != -1:
            continue
        used = [False] * 26
        for nb in adj[u]:
            if color[nb] != -1:
                used[color[nb]] = True
        for c in range(26):
            if not used[c]:
                color[u] = c
                break
        if color[u] == -1:
            return ""
        for nb in adj[u]:
            if color[nb] == -1:
                used_nb = [False] * 26
                for nb2 in adj[nb]:
                    if color[nb2] != -1:
                        used_nb[color[nb2]] = True
                for c in range(26):
                    if not used_nb[c]:
                        color[nb] = c
                        break
                if color[nb] == -1:
                    return ""

    result_chars = [chr(ord('a') + color[comp_id[i]]) for i in range(n)]
    result = ''.join(result_chars)

    for i in range(n):
        for j in range(i, n):
            cnt = 0
            while i + cnt < n and j + cnt < n and result[i + cnt] == result[j + cnt]:
                cnt += 1
            if cnt != lcp[i][j]:
                return ""
    return result

