def count_possible_roots(edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
    n = len(edges) + 1
    adj: List[List[int]] = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    guess_set: Set[Tuple[int, int]] = set((u, v) for u, v in guesses)

    parent = [-1] * n
    stack = [(0, -1)]
    order: List[int] = []
    initial_correct = 0
    while stack:
        node, par = stack.pop()
        parent[node] = par
        order.append(node)
        for nb in adj[node]:
            if nb == par:
                continue
            stack.append((nb, node))
            if (node, nb) in guess_set:
                initial_correct += 1

    answer = 0
    stack = [(0, -1, initial_correct)]
    while stack:
        node, par, correct = stack.pop()
        if correct >= k:
            answer += 1
        for nb in adj[node]:
            if nb == par:
                continue
            new_correct = correct
            if (node, nb) in guess_set:
                new_correct -= 1
            if (nb, node) in guess_set:
                new_correct += 1
            stack.append((nb, node, new_correct))

    return answer

