def kth_largest_level_sum(root, k):
    if not root:
        return -1

    queue = [root]
    head = 0
    min_heap = []

    def heap_push(val):
        min_heap.append(val)
        i = len(min_heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if min_heap[p] <= min_heap[i]:
                break
            min_heap[p], min_heap[i] = min_heap[i], min_heap[p]
            i = p

    def heap_replace_root(val):
        min_heap[0] = val
        i = 0
        while True:
            l = i * 2 + 1
            r = i * 2 + 2
            smallest = i
            if l < len(min_heap) and min_heap[l] < min_heap[smallest]:
                smallest = l
            if r < len(min_heap) and min_heap[r] < min_heap[smallest]:
                smallest = r
            if smallest == i:
                break
            min_heap[i], min_heap[smallest] = min_heap[smallest], min_heap[i]
            i = smallest

    while head < len(queue):
        level_size = len(queue) - head
        level_sum = 0
        for _ in range(level_size):
            node = queue[head]
            head += 1
            level_sum += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        if len(min_heap) < k:
            heap_push(level_sum)
        elif level_sum > min_heap[0]:
            heap_replace_root(level_sum)

    return min_heap[0] if len(min_heap) == k else -1

