def collect_coins_in_tree(coins: List[int], edges: List[Tuple[int, int]]) -> int:
    n = len(coins)
    if n == 0:
        return 0

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    degree = [len(adj[i]) for i in range(n)]
    removed = [False] * n

    # First, prune leaves without coins
    q = deque(i for i in range(n) if degree[i] == 1 and coins[i] == 0)
    while q:
        u = q.popleft()
        if removed[u]:
            continue
        removed[u] = True
        degree[u] = 0
        for v in adj[u]:
            if removed[v]:
                continue
            degree[v] -= 1
            if degree[v] == 1 and coins[v] == 0:
                q.append(v)

    # Then prune leaves up to two more rounds (any leaf)
    leaves = [i for i in range(n) if not removed[i] and degree[i] == 1]
    for _ in range(2):
        next_leaves = []
        for u in leaves:
            if removed[u]:
                continue
            removed[u] = True
            degree[u] = 0
            for v in adj[u]:
                if removed[v]:
                    continue
                degree[v] -= 1
                if degree[v] == 1:
                    next_leaves.append(v)
        leaves = next_leaves

    remaining_edges = sum(degree) // 2
    return remaining_edges * 2

