def shortest_cycle(n: int, edges: List[Tuple[int, int]]) -> int:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    best = float('inf')

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        queue = []
        q_head = 0

        dist[start] = 0
        queue.append(start)

        while q_head < len(queue):
            u = queue[q_head]
            q_head += 1
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len

    return -1 if best == float('inf') else int(best)

