def time_limited_cache(commands: List[str], arguments: List[List[int]], timestamps: List[int]) -> List[Any]:
    cache: Dict[int, Tuple[int, int]] = {}
    result: List[Any] = []

    def purge(now: int) -> None:
        expired = [k for k, (_, exp) in cache.items() if exp <= now]
        for k in expired:
            del cache[k]

    for cmd, args, now in zip(commands, arguments, timestamps):
        if cmd == "TimeLimitedCache":
            result.append(None)
            continue

        purge(now)

        if cmd == "set":
            key, value, duration = args
            existed = key in cache and cache[key][1] > now
            cache[key] = (value, now + duration)
            result.append(existed)
        elif cmd == "get":
            key = args[0]
            if key in cache and cache[key][1] > now:
                result.append(cache[key][0])
            else:
                result.append(-1)
        elif cmd == "count":
            result.append(len(cache))
        else:
            # unknown command, append None for safety
            result.append(None)

    return result

