from typing import List

def minimum_total_price(n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
    sys.setrecursionlimit(1 << 20)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    LOG = (n).bit_length()
    up = [[-1] * n for _ in range(LOG)]
    depth = [0] * n

    def dfs(u: int, p: int) -> None:
        up[0][u] = p
        for v in adj[u]:
            if v == p:
                continue
            depth[v] = depth[u] + 1
            dfs(v, u)

    dfs(0, -1)

    for k in range(1, LOG):
        for i in range(n):
            if up[k - 1][i] != -1:
                up[k][i] = up[k - 1][up[k - 1][i]]

    def lca(u: int, v: int) -> int:
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        bit = 0
        while diff:
            if diff & 1:
                u = up[bit][u]
            diff >>= 1
            bit += 1
        if u == v:
            return u
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    cnt = [0] * n
    for s, e in trips:
        l = lca(s, e)
        cnt[s] += 1
        cnt[e] += 1
        cnt[l] -= 1
        pl = up[0][l]
        if pl != -1:
            cnt[pl] -= 1

    def dfs_acc(u: int, p: int) -> None:
        for v in adj[u]:
            if v == p:
                continue
            dfs_acc(v, u)
            cnt[u] += cnt[v]

    dfs_acc(0, -1)

    total_original = sum(price[i] * cnt[i] for i in range(n))
    saved_weight = [price[i] * cnt[i] // 2 for i in range(n)]

    def dfs_dp(u: int, p: int) -> tuple[int, int]:
        sel = saved_weight[u]
        not_sel = 0
        for v in adj[u]:
            if v == p:
                continue
            child_not, child_sel = dfs_dp(v, u)
            sel += child_not
            not_sel += max(child_not, child_sel)
        return not_sel, sel

    not_root, sel_root = dfs_dp(0, -1)
    saved = max(not_root, sel_root)
    return total_original - saved

