def split_array_coprime(nums: List[int]) -> int:
    def prime_factors(x: int) -> set[int]:
        factors = set()
        while x % 2 == 0:
            factors.add(2)
            x //= 2
        f = 3
        while f * f <= x:
            if x % f == 0:
                factors.add(f)
                while x % f == 0:
                    x //= f
            f += 2
        if x > 1:
            factors.add(x)
        return factors

    n = len(nums)
    if n < 2:
        return -1

    first_occ: dict[int, int] = {}
    last_occ: dict[int, int] = {}

    for idx, val in enumerate(nums):
        for p in prime_factors(val):
            if p not in first_occ:
                first_occ[p] = idx
            last_occ[p] = idx

    max_last = -1
    for i in range(n - 1):
        for p in prime_factors(nums[i]):
            max_last = max(max_last, last_occ[p])
        if max_last == i:
            return i
    return -1

