def min_cost(basket1: List[int], basket2: List[int]) -> int:
    # Count frequencies in both baskets
    freq1 = {}
    freq2 = {}
    for v in basket1:
        freq1[v] = freq1.get(v, 0) + 1
    for v in basket2:
        freq2[v] = freq2.get(v, 0) + 1

    # Global minimum fruit value across both baskets
    all_vals = set(freq1) | set(freq2)
    if not all_vals:
        return 0
    global_min = min(all_vals)

    # Verify that each fruit appears an even total number of times
    for val in all_vals:
        total = freq1.get(val, 0) + freq2.get(val, 0)
        if total % 2 != 0:
            return -1

    # Build lists of excess elements that need to be moved
    excess_from_first = []   # elements to move from basket1 to basket2
    excess_from_second = []  # elements to move from basket2 to basket1

    for val in all_vals:
        diff = freq1.get(val, 0) - freq2.get(val, 0)
        if diff > 0:
            # diff is even; we need to move diff // 2 copies from first to second
            excess_from_first.extend([val] * (diff // 2))
        elif diff < 0:
            # move -diff // 2 copies from second to first
            excess_from_second.extend([val] * ((-diff) // 2))

    # No moves needed
    if not excess_from_first:
        return 0

    # Sort to pair smallest with smallest (cost uses min of the pair)
    excess_from_first.sort()
    excess_from_second.sort(reverse=True)

    total_cost = 0
    for a, b in zip(excess_from_first, excess_from_second):
        # Cost of swapping a and b directly vs via the global minimum element
        direct_cost = min(a, b)
        via_global = 2 * global_min
        total_cost += min(direct_cost, via_global)

    return total_cost

