def maximize_win_from_two_segments(prize_positions: List[int], k: int) -> int:
    if not prize_positions:
        return 0

    # Ensure positions are sorted for sliding‑window processing
    positions = sorted(prize_positions)
    n = len(positions)

    # win_start[i] = number of prizes in the best segment of length k that starts at i
    win_start: List[int] = [0] * n
    r = 0
    for l in range(n):
        while r + 1 < n and positions[r + 1] - positions[l] <= k:
            r += 1
        win_start[l] = r - l + 1
        # Move left pointer; if r == l, advance r to keep window valid
        if r == l:
            r += 1

    # suffix_max[i] = max win_start[j] for all j >= i
    suffix_max: List[int] = [0] * (n + 1)  # extra slot simplifies bounds
    for i in range(n - 1, -1, -1):
        suffix_max[i] = max(win_start[i], suffix_max[i + 1])

    max_prizes = 0
    for i in range(n):
        first = win_start[i]
        next_start = i + first
        if next_start <= n:
            total = first + suffix_max[next_start]
        else:
            total = first
        if total > max_prizes:
            max_prizes = total

    return max_prizes

