def min_operations(nums: List[int]) -> int:
    n = len(nums)
    order = sorted(range(n), key=lambda i: nums[i])
    tree = [0] * (n + 1)

    def update(i, delta):
        i += 1
        while i <= n:
            tree[i] += delta
            i += i & (-i)

    def query(i):
        i += 1
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & (-i)
        return s

    for i in range(n):
        update(i, 1)

    cur = 0
    total = 0
    for idx in order:
        if idx >= cur:
            active_before = query(idx) - query(cur - 1) - 1
        else:
            active_before = (query(n - 1) - query(cur - 1)) + query(idx) - 1
        total += active_before + 1
        update(idx, -1)
        cur = idx + 1
        if cur == n:
            cur = 0
    return total

