def min_operations(nums: List[int]) -> int:
    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    n = len(nums)
    ones = sum(1 for x in nums if x == 1)
    if ones:
        return n - ones

    min_len = n + 1
    for i in range(n):
        cur = nums[i]
        for j in range(i, n):
            cur = gcd(cur, nums[j])
            if cur == 1:
                min_len = min(min_len, j - i + 1)
                break

    if min_len == n + 1:
        return -1
    return (min_len - 1) + (n - 1)

import asyncio
