class CancelledError(Exception):
    pass

def cancellable(generator) -> Tuple[Callable[[], None], asyncio.Future]:
    cancelled = False
    loop = asyncio.get_event_loop()
    promise = loop.create_future()

    def cancel() -> None:
        nonlocal cancelled
        cancelled = True
        try:
            generator.throw(CancelledError())
        except StopIteration:
            pass

    def step(value=None, is_throw=False):
        nonlocal cancelled
        if cancelled:
            if not promise.done():
                promise.set_exception(CancelledError())
            return
        try:
            if is_throw:
                yielded = generator.throw(value)
            else:
                if value is None:
                    yielded = next(generator)
                else:
                    yielded = generator.send(value)
        except StopIteration as e:
            if not promise.done():
                promise.set_result(e.value)
            return
        except Exception as e:
            if not promise.done():
                promise.set_exception(e)
            return

        async def handle():
            try:
                result = await yielded
                if cancelled:
                    if not promise.done():
                        promise.set_exception(CancelledError())
                else:
                    step(result, False)
            except Exception as err:
                step(err, True)

        asyncio.ensure_future(handle())

    step()
    return cancel, promise

def minimum_cost(start, target, special_roads):
    points = [tuple(start), tuple(target)]
    for road in special_roads:
        points.append((road[0], road[1]))
        points.append((road[2], road[3]))
    points = list({p: None for p in points}.keys())
    distances = {p: float('inf') for p in points}
    distances[tuple(start)] = 0
    queue = [(0, tuple(start))]
    while queue:
        dist, point = queue.pop(0)
        if dist > distances[point]:
            continue
        for road in special_roads:
            if point[0] == road[0] and point[1] == road[1]:
                new_dist = dist + road[4]
                new_point = (road[2], road[3])
                if new_dist < distances[new_point]:
                    distances[new_point] = new_dist
                    queue.append((new_dist, new_point))
                    queue.sort(key=lambda x: x[0])
        for other_point in points:
            new_dist = dist + abs(other_point[0] - point[0]) + abs(other_point[1] - point[1])
            if new_dist < distances[other_point]:
                distances[other_point] = new_dist
                queue.append((new_dist, other_point))
                queue.sort(key=lambda x: x[0])
    return distances[tuple(target)]

def smallest_beautiful_string(s: str, k: int) -> str:
    n = len(s)
    original = list(s)
    max_char_ord = ord('a') + k - 1

    for i in range(n - 1, -1, -1):
        # try to increase position i
        for cand_ord in range(ord(original[i]) + 1, max_char_ord + 1):
            cand = chr(cand_ord)

            # check against previous two characters (still original)
            if i - 1 >= 0 and cand == original[i - 1]:
                continue
            if i - 2 >= 0 and cand == original[i - 2]:
                continue

            # build the prefix up to i
            result = original[:i] + [cand]

            # fill the rest with the smallest possible characters
            possible = True
            for j in range(i + 1, n):
                placed = False
                for c_ord in range(ord('a'), max_char_ord + 1):
                    c = chr(c_ord)
                    if j - 1 >= 0 and c == result[j - 1]:
                        continue
                    if j - 2 >= 0 and c == result[j - 2]:
                        continue
                    result.append(c)
                    placed = True
                    break
                if not placed:
                    possible = False
                    break

            if possible:
                return ''.join(result)

    return ""

