def min_increments(n: int, cost: List[int]) -> int:
    def dfs(i: int) -> tuple[int, int]:
        """Return (max_path_sum_from_i, increments_needed_in_subtree)."""
        left = 2 * i + 1
        right = 2 * i + 2

        # leaf node
        if left >= n and right >= n:
            return cost[i], 0

        # recurse on existing children
        if left < n:
            left_sum, left_inc = dfs(left)
        else:
            left_sum, left_inc = 0, 0

        if right < n:
            right_sum, right_inc = dfs(right)
        else:
            right_sum, right_inc = 0, 0

        target = max(left_sum, right_sum)
        inc = left_inc + right_inc + (target - left_sum) + (target - right_sum)
        return cost[i] + target, inc

    if n == 0:
        return 0
    _, total_inc = dfs(0)
    return total_inc

