def count_complete_components(n: int, edges: List[Tuple[int, int]]) -> int:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    count = 0

    def dfs(node: int, component: List[int]) -> None:
        visited[node] = True
        component.append(node)
        for nb in graph[node]:
            if not visited[nb]:
                dfs(nb, component)

    for i in range(n):
        if not visited[i]:
            component: List[int] = []
            dfs(i, component)
            is_complete = True
            for u in component:
                for v in component:
                    if u != v and v not in graph[u]:
                        is_complete = False
                        break
                if not is_complete:
                    break
            if is_complete:
                count += 1
    return count

