def maximum_moves(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])
    # dp[i][j] = max moves to reach cell (i, j); -1 means unreachable
    dp = [[-1] * n for _ in range(m)]
    for i in range(m):
        dp[i][0] = 0

    for j in range(1, n):
        for i in range(m):
            best = -1
            cur_val = grid[i][j]
            # consider only adjacent rows from previous column
            for k in (i - 1, i, i + 1):
                if 0 <= k < m and grid[k][j - 1] < cur_val and dp[k][j - 1] != -1:
                    if dp[k][j - 1] > best:
                        best = dp[k][j - 1]
            if best != -1:
                dp[i][j] = best + 1

    max_moves = 0
    for i in range(m):
        for j in range(n):
            if dp[i][j] > max_moves:
                max_moves = dp[i][j]
    return max_moves

