def punishment_number(n: int) -> int:
    def can_partition(num: int, target: int) -> bool:
        s = str(num)
        @lru_cache(maxsize=None)
        def dfs(idx: int, cur: int) -> bool:
            if cur > target:
                return False
            if idx == len(s):
                return cur == target
            # try all possible next splits
            for j in range(idx + 1, len(s) + 1):
                part = int(s[idx:j])
                if dfs(j, cur + part):
                    return True
            return False
        return dfs(0, 0)

