def max_cells_in_matrix(mat: List[List[int]]) -> int:
    if not mat or not mat[0]:
        return 0
    rows, cols = len(mat), len(mat[0])
    dp = [[1] * cols for _ in range(rows)]
    cells = [(mat[i][j], i, j) for i in range(rows) for j in range(cols)]
    cells.sort(key=lambda x: x[0])
    row_best = [0] * rows
    col_best = [0] * cols
    idx = 0
    n = len(cells)
    while idx < n:
        cur_val = cells[idx][0]
        group = []
        while idx < n and cells[idx][0] == cur_val:
            _, r, c = cells[idx]
            group.append((r, c))
            idx += 1
        # compute dp for this group using previous bests
        for r, c in group:
            dp[r][c] = max(row_best[r], col_best[c]) + 1
        # update bests with results from this group
        for r, c in group:
            if dp[r][c] > row_best[r]:
                row_best[r] = dp[r][c]
            if dp[r][c] > col_best[c]:
                col_best[c] = dp[r][c]
    return max(max(row) for row in dp)  # TIME: O(R*C log(R*C)) SPACE: O(R*C)

