MOD = 10**9 + 7

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    def dec_str(s: str) -> str:
        # subtract 1 from a non‑negative integer represented as a string
        if s == "0":
            return "0"
        digits = list(s)
        i = len(digits) - 1
        while i >= 0:
            if digits[i] > '0':
                digits[i] = chr(ord(digits[i]) - 1)
                break
            else:
                digits[i] = '9'
                i -= 1
        # strip leading zeros
        result = ''.join(digits).lstrip('0')
        return result if result else "0"

    def count_upto(bound: str) -> int:
        n = len(bound)

        @lru_cache(maxsize=None)
        def dfs(pos: int, tight: bool, cur_sum: int) -> int:
            if cur_sum > max_sum:
                return 0
            if pos == n:
                return 1 if min_sum <= cur_sum <= max_sum else 0
            limit = int(bound[pos]) if tight else 9
            total = 0
            for d in range(0, limit + 1):
                total += dfs(pos + 1, tight and d == limit, cur_sum + d)
            return total % MOD

        return dfs(0, True, 0)

    total_up_to_num2 = count_upto(num2)
    total_up_to_num1_minus_one = count_upto(dec_str(num1))
    return (total_up_to_num2 - total_up_to_num1_minus_one) % MOD

