def lexicographically_smallest_string(s: str) -> str:
    n = len(s)
    chars = list(s)
    # find first character that is not 'a'
    i = 0
    while i < n and chars[i] == 'a':
        i += 1
    if i == n:  # all 'a's
        chars[-1] = 'z'
        return ''.join(chars)
    # decrement consecutive non-'a' characters
    while i < n and chars[i] != 'a':
        # shift character one step back in alphabet
        chars[i] = chr(ord(chars[i]) - 1)
        i += 1
    return ''.join(chars)

