def special_perm(nums: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    # precompute adjacency: can[i][j] is True if nums[i] and nums[j] satisfy divisibility condition
    can = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                can[i][j] = True

    total_masks = 1 << n
    dp = [[0] * n for _ in range(total_masks)]

    # initialize dp with each single element permutation
    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(total_masks):
        for last in range(n):
            cur = dp[mask][last]
            if cur == 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if can[last][nxt]:
                    nxt_mask = mask | (1 << nxt)
                    dp[nxt_mask][nxt] = (dp[nxt_mask][nxt] + cur) % MOD

    full_mask = total_masks - 1
    return sum(dp[full_mask][i] for i in range(n)) % MOD

