def longest_even_odd_subarray(nums: List[int], threshold: int) -> int:
    best = 0
    cur_len = 0
    prev_parity = None  # type: int | None
    for x in nums:
        if x > threshold:
            cur_len = 0
            prev_parity = None
            continue
        parity = x & 1
        if cur_len == 0:
            if parity == 0:
                cur_len = 1
                prev_parity = 0
                best = max(best, cur_len)
            else:
                cur_len = 0
                prev_parity = None
        else:
            if parity != prev_parity:
                cur_len += 1
                prev_parity = parity
                best = max(best, cur_len)
            else:
                if parity == 0:
                    cur_len = 1
                    prev_parity = 0
                    best = max(best, cur_len)
                else:
                    cur_len = 0
                    prev_parity = None
    return best

