def continuousSubarrays(nums: List[int]) -> int:
    maxd, mind = deque(), deque()
    l = 0
    ans = 0
    for r, x in enumerate(nums):
        while maxd and nums[maxd[-1]] <= x:
            maxd.pop()
        maxd.append(r)
        while mind and nums[mind[-1]] >= x:
            mind.pop()
        mind.append(r)
        while nums[maxd[0]] - nums[mind[0]] > 2:
            l += 1
            if maxd[0] < l:
                maxd.popleft()
            if mind[0] < l:
                mind.popleft()
        ans += r - l + 1
    return ans

