        return -1
    max_len = 0
    cur_len = 1
    prev_sign = 0
    for i in range(1, len(nums)):
        diff = nums[i] - nums[i - 1]
        if diff == 0:
            cur_len = 1
            prev_sign = 0
            continue
        sign = 1 if diff > 0 else -1
        if prev_sign != 0 and sign != prev_sign:
            cur_len += 1
        else:
            cur_len = 2
        prev_sign = sign
        if cur_len > max_len:
            max_len = cur_len
    return max_len if max_len >= 2 else -1

