def prime_pairs(n: int) -> List[List[int]]:
    if n < 4:
        return []
    is_prime = bytearray(n + 1)
    for i in range(2, n + 1):
        is_prime[i] = 1
    p = 2
    while p * p <= n:
        if is_prime[p]:
            m = p * p
            while m <= n:
                is_prime[m] = 0
                m += p
        p += 1
    result: List[List[int]] = []
    x = 2
    while x <= n // 2:
        y = n - x
        if is_prime[x] and is_prime[y]:
            result.append([x, y])
        x += 1
    return result

