def minimum_length(words: List[str]) -> int:
    n = len(words)
    if n == 0:
        return 0
    lengths = [len(w) for w in words]
    total_len = sum(lengths)

    # can_merge[i][j] == 1 if last char of words[i] equals first char of words[j]
    can_merge = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and words[i][-1] == words[j][0]:
                can_merge[i][j] = 1

    size = 1 << n
    dp = [[-1] * n for _ in range(size)]
    for i in range(n):
        dp[1 << i][i] = 0  # single word, no merges yet

    for mask in range(size):
        for last in range(n):
            cur = dp[mask][last]
            if cur < 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                new_mask = mask | (1 << nxt)
                merges = cur + can_merge[last][nxt]
                if merges > dp[new_mask][nxt]:
                    dp[new_mask][nxt] = merges

    full_mask = size - 1
    max_merges = 0
    for last in range(n):
        if dp[full_mask][last] > max_merges:
            max_merges = dp[full_mask][last]

    return total_len - max_merges

