def can_make_zero(nums: List[int], k: int) -> bool:
    n = len(nums)
    if k <= 0 or k > n:
        return all(x == 0 for x in nums)
    diff = [0] * (n + 1)
    cur = 0
    for i, val in enumerate(nums):
        cur += diff[i]
        need = val - cur
        if need < 0:
            return False
        if need:
            if i + k > n:
                return False
            cur += need
            diff[i + k] -= need
    return True

