def number_of_black_blocks(m: int, n: int, coordinates: List[List[int]]) -> List[int]:
    block_count = {}
    for x, y in coordinates:
        for dx in (-1, 0):
            r = x + dx
            if r < 0 or r >= m - 1:
                continue
            for dy in (-1, 0):
                c = y + dy
                if c < 0 or c >= n - 1:
                    continue
                key = r * n + c
                block_count[key] = block_count.get(key, 0) + 1
    ans = [0, 0, 0, 0, 0]
    total_blocks = max(0, (m - 1) * (n - 1))
    ans[0] = total_blocks - len(block_count)
    for cnt in block_count.values():
        ans[cnt] += 1
    return ans

