def sum_of_squares_special(nums: List[int]) -> int:
    n = len(nums)
    total = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            total += nums[d - 1] * nums[d - 1]
            other = n // d
            if other != d:
                total += nums[other - 1] * nums[other - 1]
        d += 1
    return total

