def longest_valid_substring(word: str, forbidden: List[str]) -> int:
    nodes = [{'next': {}, 'fail': 0, 'out': []}]
    for pat in forbidden:
        cur = 0
        for ch in pat:
            if ch not in nodes[cur]['next']:
                nodes[cur]['next'][ch] = len(nodes)
                nodes.append({'next': {}, 'fail': 0, 'out': []})
            cur = nodes[cur]['next'][ch]
        nodes[cur]['out'].append(len(pat))
    queue = deque()
    for ch, nxt in nodes[0]['next'].items():
        nodes[nxt]['fail'] = 0
        queue.append(nxt)
    while queue:
        v = queue.popleft()
        for ch, u in nodes[v]['next'].items():
            f = nodes[v]['fail']
            while f and ch not in nodes[f]['next']:
                f = nodes[f]['fail']
            if ch in nodes[f]['next']:
                f = nodes[f]['next'][ch]
            nodes[u]['fail'] = f
            nodes[u]['out'].extend(nodes[f]['out'])
            queue.append(u)
    state = 0
    last_bad = -1
    best = 0
    for i, ch in enumerate(word):
        while state and ch not in nodes[state]['next']:
            state = nodes[state]['fail']
        if ch in nodes[state]['next']:
            state = nodes[state]['next'][ch]
        for length in nodes[state]['out']:
            bad_start = i - length + 1
            if bad_start > last_bad:
                last_bad = bad_start
        cur_len = i - last_bad
        if cur_len > best:
            best = cur_len
    return best

