def max_score(nums: List[int], x: int) -> int:
    if not nums:
        return 0

    INF_NEG = -10**18
    best_even = INF_NEG
    best_odd = INF_NEG

    first_val = nums[0]
    if first_val % 2 == 0:
        best_even = first_val
    else:
        best_odd = first_val

    for val in nums[1:]:
        if val % 2 == 0:
            same = best_even
            opp = best_odd - x if best_odd != INF_NEG else INF_NEG
            dp = val + (same if same > opp else opp)
            if dp > best_even:
                best_even = dp
        else:
            same = best_odd
            opp = best_even - x if best_even != INF_NEG else INF_NEG
            dp = val + (same if same > opp else opp)
            if dp > best_odd:
                best_odd = dp

    return best_even if best_even > best_odd else best_odd

