    required = len(set(nums))
    freq: dict[int, int] = {}
    distinct = 0
    right = 0
    answer = 0
    for left in range(n):
        while right < n and distinct < required:
            v = nums[right]
            cnt = freq.get(v, 0) + 1
            freq[v] = cnt
            if cnt == 1:
