def shortest_string(a: str, b: str, c: str) -> str:
    def is_sub(t: str, s: str) -> bool:
        return s in t

    def merge(s: str, t: str) -> str:
        if is_sub(s, t):
            return s
        max_overlap = 0
        limit = min(len(s), len(t))
        for k in range(limit, 0, -1):
            if s[-k:] == t[:k]:
                max_overlap = k
                break
        return s + t[max_overlap:]

    arr = [a, b, c]
    filtered = []
    for i in range(3):
        keep = True
        for j in range(3):
            if i != j and is_sub(arr[j], arr[i]):
                keep = False
                break
        if keep:
            filtered.append(arr[i])

    n = len(filtered)
    if n == 0:
        return ""
    if n == 1:
        return filtered[0]

    perms = []
    used = [False] * n
    cur = []

    def dfs():
        if len(cur) == n:
            perms.append(cur[:])
            return
        for i in range(n):
            if not used[i]:
                used[i] = True
                cur.append(filtered[i])
                dfs()
                cur.pop()
                used[i] = False

    dfs()

    best = None
    for p in perms:
        merged = p[0]
        for i in range(1, len(p)):
            merged = merge(merged, p[i])
        if best is None or len(merged) < len(best) or (len(merged) == len(best) and merged < best):
            best = merged
    return best

def insert_greatest_common_divisors(head):
    if not head or not head.next:
        return head

    def gcd(a, b):
        while b != 0:
            t = a % b
            a = b
            b = t
        return a

    cur = head
    while cur and cur.next:
        g = gcd(cur.val, cur.next.val)
        g_node = type(head)(g, cur.next)
        cur.next = g_node
        cur = g_node.next
    return head

