def count_stepping_numbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def dec_str(s):
        a = list(s)
        i = len(a) - 1
        while i >= 0 and a[i] == '0':
            a[i] = '9'
            i -= 1
        if i >= 0:
            a[i] = str(int(a[i]) - 1)
        while len(a) > 1 and a[0] == '0':
            a.pop(0)
        return ''.join(a)

    def count(bound):
        n = len(bound)

        @lru_cache(maxsize=None)
        def dfs(pos, prev, tight, started):
            if pos == n:
                return 1 if started else 0
            limit = int(bound[pos]) if tight else 9
            res = 0
            for d in range(0, limit + 1):
                if not started:
                    if d == 0:
                        res += dfs(pos + 1, -1, tight and d == limit, False)
                    else:
                        res += dfs(pos + 1, d, tight and d == limit, True)
                else:
                    if abs(d - prev) == 1:
                        res += dfs(pos + 1, d, tight and d == limit, True)
            return res % MOD

        r = dfs(0, -1, True, False)
        dfs.cache_clear()
        return r

    low_minus1 = dec_str(low)
    c_high = count(high)
    c_low_minus1 = 0 if low == '1' else count(low_minus1)
    return (c_high - c_low_minus1) % MOD

