def minimum_time(nums1, nums2, x):
    n = len(nums1)
    total1 = sum(nums1)
    total2 = sum(nums2)
    if total1 <= x:
        return 0

    idx = sorted(range(n), key=lambda i: nums2[i])
    # dp[j] = max savings achievable using exactly j resets among processed indices so far
    NEG = float('-inf')
    dp = [0] + [NEG] * n
    for i in idx:
        for j in range(n, 0, -1):
            if dp[j - 1] == NEG:
                continue
            candidate = dp[j - 1] + nums1[i] + nums2[i] * j
            if candidate > dp[j]:
                dp[j] = candidate

    for T in range(0, n + 1):
        k = min(T, n)
        savings = dp[k] if dp[k] != NEG else 0
        final_sum = total1 + T * total2 - savings
        if final_sum <= x:
            return T
    return -1

