def minimum_seconds(nums: List[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0

    info = {}
    for i, v in enumerate(nums):
        if v not in info:
            info[v] = [i, i, 0]  # first, prev, max_gap
        else:
            first, prev, max_gap = info[v]
            gap = i - prev - 1
            if gap > max_gap:
                max_gap = gap
            info[v] = [first, i, max_gap]

    answer = float('inf')
    for first, prev, max_gap in info.values():
        if max_gap == n - 1:  # value appears only once, whole array is gap
            wrap_gap = n - 1
        else:
            wrap_gap = (first + n - prev - 1) % n
        if wrap_gap > max_gap:
            max_gap = wrap_gap
        if max_gap == n - 1 and len(info) == 1:
            return 0
        seconds = (max_gap + 1) // 2
        if seconds < answer:
            answer = seconds
    return answer

