def can_split(nums: List[int], m: int) -> bool:
    n = len(nums)
    if n == 0:
        return True
    # prefix sums
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + nums[i]

    # dp[l][r] = True if interval [l, r] can be split into singletons
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True  # single element is trivially good

    # consider intervals of increasing length
    for length in range(2, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            total = pref[r + 1] - pref[l]
            if total < m:
                continue  # cannot be good
            # try all split points
            for k in range(l, r):
                if dp[l][k] and dp[k + 1][r]:
                    dp[l][r] = True
                    break

    return dp[0][n - 1]

