def minimum_absolute_difference(nums: List[int], x: int) -> int:
    class Node:
        __slots__ = ("key", "pri", "left", "right")
        def __init__(self, key: int):
            self.key = key
            self.pri = random.random()
            self.left = None
            self.right = None

    def rotate_right(p: Node) -> Node:
        q = p.left
        p.left = q.right
        q.right = p
        return q

    def rotate_left(p: Node) -> Node:
        q = p.right
        p.right = q.left
        q.left = p
        return q

    def insert(node: Node | None, key: int) -> Node:
        if node is None:
            return Node(key)
        if key < node.key:
            node.left = insert(node.left, key)
            if node.left.pri < node.pri:
                node = rotate_right(node)
        else:
            node.right = insert(node.right, key)
            if node.right.pri < node.pri:
                node = rotate_left(node)
        return node

    def lower_bound(node: Node | None, key: int) -> Node | None:
        if node is None:
            return None
        if node.key >= key:
            left = lower_bound(node.left, key)
            return left if left is not None else node
        return lower_bound(node.right, key)

    def predecessor(node: Node | None, key: int) -> Node | None:
        if node is None:
            return None
        if node.key < key:
            right = predecessor(node.right, key)
            return right if right is not None else node
        return predecessor(node.left, key)

    root = None
    best = float('inf')
    for i, val in enumerate(nums):
        if i - x >= 0:
            root = insert(root, nums[i - x])
        if root is not None:
            lb = lower_bound(root, val)
            if lb is not None:
                diff = abs(lb.key - val)
                if diff < best:
                    best = diff
            pred = predecessor(root, val)
            if pred is not None:
                diff = abs(pred.key - val)
                if diff < best:
                    best = diff
    return 0 if best == float('inf') else int(best)

