def maximum_safeness_factor(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    dist = [[-1] * cols for _ in range(rows)]
    q = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dist[r][c] = 0
                q.append((r, c))
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        nd = dist[r][c] + 1
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] == -1:
                dist[nr][nc] = nd
                q.append((nr, nc))
    best = [[-1] * cols for _ in range(rows)]
    start_safety = dist[0][0]
    best[0][0] = start_safety
    heap = [(-start_safety, 0, 0)]
    while heap:
        neg_safety, r, c = heapq.heappop(heap)
        safety = -neg_safety
        if r == rows - 1 and c == cols - 1:
            return safety
        if safety < best[r][c]:
            continue
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                new_safety = min(safety, dist[nr][nc])
                if new_safety > best[nr][nc]:
                    best[nr][nc] = new_safety
                    heapq.heappush(heap, (-new_safety, nr, nc))
    return 0

