                nstarted = started or d != 0
                ndiff = diff
                nrem = rem
                if nstarted:
                    ndiff += 1 if d % 2 else -1
                    nrem = (rem * 10 + d) % k
                total += dfs(pos + 1, ndiff, nrem, ntight, nstarted)
            return total

        return dfs(0, 0, 0, True, False)

    return count_upto(high) - count_upto(low - 1)

