        return 0

    freq: dict[int, int] = {}
    distinct_cnt = 0
    cur_sum = 0

    for i in range(k):
        cur_sum += nums[i]
        freq[nums[i]] = freq.get(nums[i], 0) + 1
        if freq[nums[i]] == 1:
            distinct_cnt += 1

