def min_operations(nums: list[int], target: int) -> int:
    if target == 0:
        return 0
    max_val = max(nums + [target])
    max_bits = max_val.bit_length() + 1
    cnt = [0] * max_bits
    for v in nums:
        if v == 0:
            continue
        exp = v.bit_length() - 1
        cnt[exp] += 1
    ops = 0
    for i in range(max_bits):
        if (target >> i) & 1:
            if cnt[i] > 0:
                cnt[i] -= 1
            else:
                j = i + 1
                while j < max_bits and cnt[j] == 0:
                    j += 1
                if j == max_bits:
                    return -1
                while j > i:
                    cnt[j] -= 1
                    cnt[j - 1] += 2
                    ops += 1
                    j -= 1
                cnt[i] -= 1
        if i + 1 < max_bits:
            cnt[i + 1] += cnt[i] // 2
    return ops

