def min_moves(grid: list[list[int]]) -> int:
    stones = []
    for r in range(3):
        for c in range(3):
            cnt = grid[r][c]
            for _ in range(cnt):
                stones.append((r, c))
    targets = [(r, c) for r in range(3) for c in range(3)]
    n = 9
    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        sr, sc = stones[i]
        for j in range(n):
            tr, tc = targets[j]
            dist[i][j] = abs(sr - tr) + abs(sc - tc)
    INF = 10 ** 9
    size = 1 << n
    dp = [INF] * size
    dp[0] = 0
    for mask in range(size):
        k = mask.bit_count()
        if k >= n:
            continue
        cur = dp[mask]
        if cur == INF:
            continue
        for j in range(n):
            if mask & (1 << j):
                continue
            next_mask = mask | (1 << j)
            cand = cur + dist[k][j]
            if cand < dp[next_mask]:
                dp[next_mask] = cand
    return dp[-1]

