def matmul(A, B):
    return [[ (A[i][0]*B[0][j] + A[i][1]*B[1][j]) % MOD for j in range(2)] for i in range(2)]

def matpow(M, p):
    R = [[1,0],[0,1]]
    while p:
        if p & 1:
            R = matmul(R, M)
        M = matmul(M, M)
        p >>= 1
    return R

def numberOfWays(s, t, k):
    n = len(s)
    c = countGood(s, t)
    g0 = 1 if s == t else 0
    b0 = 1 - g0
    M = [[(c-1) % MOD, c % MOD], [(n-c) % MOD, (n-c-1) % MOD]]
    Mp = matpow(M, k)
    return (Mp[0][0]*g0 + Mp[0][1]*b0) % MOD

