        stock_value += stock[j] * cost[j]

    best = 0

    for i in range(k):
        base_cost = 0
        for j in range(n):
            base_cost += composition[i][j] * cost[j]

        high = (budget + stock_value) // base_cost
        low = 0

        while low < high:
            mid = (low + high + 1) // 2
            needed = 0
            for j in range(n):
                required = mid * composition[i][j]
                if required > stock[j]:
                    needed += (required - stock[j]) * cost[j]
                    if needed > budget:
                        break
            if needed <= budget:
                low = mid
            else:
                high = mid - 1

        if low > best:
            best = low

    return best

