def max_mountain_sum(heights: List[int]) -> int:
    n = len(heights)
    left = [0] * n
    stack: List[int] = []
    for i, h in enumerate(heights):
        while stack and heights[stack[-1]] >= h:
            stack.pop()
        if stack:
            prev = stack[-1]
            left[i] = left[prev] + h * (i - prev)
        else:
            left[i] = h * (i + 1)
        stack.append(i)

    right = [0] * n
    stack.clear()
    for i in range(n - 1, -1, -1):
        h = heights[i]
        while stack and heights[stack[-1]] >= h:
            stack.pop()
        if stack:
            nxt = stack[-1]
            right[i] = right[nxt] + h * (nxt - i)
        else:
            right[i] = h * (n - i)
        stack.append(i)

    best = 0
    for i in range(n):
        total = left[i] + right[i] - heights[i]
        if total > best:
            best = total
    return best

