        if better(new_seq, existing_seq):
            best_by_group[g] = new_seq

            # update best_overall and second_best
            if best_overall[2] == g:
                best_overall = (len(new_seq), new_seq, g)
            else:
                if better(new_seq, best_overall[1]):
                    old_best = best_overall
                    best_overall = (len(new_seq), new_seq, g)
                    if old_best[2] != best_overall[2]:
                        second_best = old_best
                elif better(new_seq, second_best[1]) and g != best_overall[2]:
                    second_best = (len(new_seq), new_seq, g)

    return best_overall[1]

