                min_idx = j
            if nums[j] > max_val:
                max_val = nums[j]
                max_idx = j
        return [-1, -1]
    max_val = -float('inf')
    max_idx = -1
    min_val = float('inf')
    min_idx = -1
    for j in range(n):
        i = j - index_difference
        if i >= 0:
            v = nums[i]
            if v > max_val:
                max_val = v
                max_idx = i
            if v < min_val:
                min_val = v
                min_idx = i
        if max_idx != -1 and max_val - nums[j] >= value_difference:
            return [max_idx, j]
