INF = 10 ** 18

class FenwickMin:
    def __init__(self, size: int):
        self.n = size
        self.bit = [INF] * (size + 1)

    def update(self, idx: int, value: int) -> None:
        while idx <= self.n:
            if value < self.bit[idx]:
                self.bit[idx] = value
            idx += idx & -idx

    def query(self, idx: int) -> int:
        res = INF
        while idx > 0:
            if self.bit[idx] < res:
                res = self.bit[idx]
            idx -= idx & -idx
        return res

def min_sum_mountain_triplet(nums: List[int]) -> int:
    n = len(nums)
    if n < 3:
        return -1

    # coordinate compression
    uniq = sorted(set(nums))
    comp = {v: i + 1 for i, v in enumerate(uniq)}  # 1‑based

    left = [INF] * n
    ft_left = FenwickMin(len(uniq))
    for j in range(n):
        idx = comp[nums[j]]
        left[j] = ft_left.query(idx - 1)
        ft_left.update(idx, nums[j])

    right = [INF] * n
    ft_right = FenwickMin(len(uniq))
    for j in range(n - 1, -1, -1):
        idx = comp[nums[j]]
        right[j] = ft_right.query(idx - 1)
        ft_right.update(idx, nums[j])

    ans = INF
    for j in range(n):
        if left[j] != INF and right[j] != INF:
            total = left[j] + nums[j] + right[j]
            if total < ans:
                ans = total
    return -1 if ans == INF else ans

