def min_changes(s: str, k: int) -> int:
    n = len(s)
    if k >= n:
        return 0
    cost = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if length == 2:
                cost[i][j] = 0 if s[i] == s[j] else 1
            else:
                cost[i][j] = cost[i + 1][j - 1] + (0 if s[i] == s[j] else 1)
    INF = 10 ** 9
    prev = [INF] * (n + 1)
    prev[0] = 0
    for i in range(1, n + 1):
        prev[i] = cost[0][i - 1]
    for p in range(2, k + 1):
        cur = [INF] * (n + 1)
        for i in range(p, n + 1):
            for t in range(p - 1, i):
                cand = prev[t] + cost[t][i - 1]
                if cand < cur[i]:
                    cur[i] = cand
        prev = cur
    return prev[n]

