def max_number_of_pairs(words: List[str]) -> int:
    word_count = {}
    for w in words:
        word_count[w] = word_count.get(w, 0) + 1

    pairs = 0
    for word in list(word_count.keys()):
        cnt = word_count.get(word, 0)
        if cnt == 0:
            continue
        rev = word[::-1]
        if rev not in word_count:
            continue
        if word == rev:
            pairs += cnt // 2
            word_count[word] = cnt % 2
        else:
            rev_cnt = word_count.get(rev, 0)
            pairs += min(cnt, rev_cnt)
            word_count[word] = 0
            word_count[rev] = 0
    return pairs

