def longest_subsequence_sum(nums: List[int], target: int) -> int:
    dp = {0: 0}
    for x in nums:
        next_dp = dp.copy()
        for s, l in dp.items():
            new_sum = s + x
            new_len = l + 1
            if new_sum not in next_dp or next_dp[new_sum] < new_len:
                next_dp[new_sum] = new_len
        dp = next_dp
    return dp[target] if target in dp else -1

