from collections import Counter

def min_number_of_groups(balls: List[int]) -> int:
    if not balls:
        return 0
    freq = Counter(balls).values()
    max_f = max(freq)

    def feasible(k: int) -> bool:
        for f in freq:
            low = (f + k) // (k + 1)  # ceil(f/(k+1))
            high = f // k
            if low > high:
                return False
        return True

    lo, hi = 1, max_f
    best_k = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            best_k = mid
            lo = mid + 1
        else:
            hi = mid - 1

    total_groups = 0
    k = best_k
    for f in freq:
        total_groups += (f + k) // (k + 1)  # ceil(f/(k+1))
    return total_groups

