        ops = 0
        for i in range(n - 1):
            a, b = nums1[i], nums2[i]
            no_swap_ok = a <= end1 and b <= end2
            swap_ok = b <= end1 and a <= end2
            if no_swap_ok:
                continue
            elif swap_ok:
                ops += 1
            else:
                return -1
        return ops
    n1, n2 = nums1[-1], nums2[-1]
    case1 = try_case(n1, n2)
    case2 = try_case(n2, n1)
    best = float('inf')
