def leftmost_building_queries(heights: List[int], queries: List[List[int]]) -> List[int]:
    n = len(heights)
    size = 1
    while size < n:
        size <<= 1
    seg = [0] * (2 * size)

    # build segment tree (max)
    for i in range(n):
        seg[size + i] = heights[i]
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[2 * i], seg[2 * i + 1])

    def query_leftmost(pos: int, l: int, r: int, ql: int, thresh: int) -> int:
        """return leftmost index >= ql in [l, r] with height >= thresh, or -1"""
        if r < ql or seg[pos] < thresh:
            return -1
        if l == r:
            return l
        mid = (l + r) // 2
        left_res = query_leftmost(pos * 2, l, mid, ql, thresh)
        if left_res != -1:
            return left_res
        return query_leftmost(pos * 2 + 1, mid + 1, r, ql, thresh)

    ans: List[int] = []
    for a, b in queries:
        if a == b:
            ans.append(a)
            continue
        start = max(a, b)
        thresh = max(heights[a], heights[b])
        res = query_leftmost(1, 0, size - 1, start, thresh)
        ans.append(res if res != -1 and res < n else -1)

    return ans
