def find_rotation(mat: List[List[int]], k: int) -> bool:
    if not mat or not mat[0]:
        return True
    m = len(mat[0])
    shift = k % m
    for i, row in enumerate(mat):
        # effective shift for this row (rightward)
        effective = shift if i % 2 == 0 else (m - shift) % m
        if effective == 0:
            continue
        for j in range(m):
            if row[j] != row[(j + effective) % m]:
                return False
    return True

