def smallest_array(nums: List[int], limit: int) -> List[int]:
    n = len(nums)
    # Union-Find structure
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    # Sort indices by their values
    sorted_idx = sorted(range(n), key=lambda i: nums[i])

    # Union consecutive elements whose value difference <= limit
    for i in range(1, n):
        idx1, idx2 = sorted_idx[i - 1], sorted_idx[i]
        if abs(nums[idx1] - nums[idx2]) <= limit:
            union(idx1, idx2)

    # Group indices by their root
    groups = {}
    for i in range(n):
        root = find(i)
        groups.setdefault(root, []).append(i)

    # Build result array
    result = nums[:]
    for indices in groups.values():
        # sort positions and corresponding values
        indices.sort()
        values = sorted(result[i] for i in indices)
        for pos, val in zip(indices, values):
            result[pos] = val

    return result

