def min_operations(word: str) -> int:
    if not word:
        return 0

    n = len(word)
    # dp[c] = min operations up to current position ending with character c (0-25)
    dp: List[int] = [0] * 26
    # initialize for first character
    first_idx = ord(word[0]) - ord('a')
    for c in range(26):
        dp[c] = 0 if c == first_idx else 1

    for i in range(1, n):
        cur_idx = ord(word[i]) - ord('a')
        new_dp: List[int] = [0] * 26
        for c in range(26):
            # cost to change current character to c
            change_cost = 0 if c == cur_idx else 1
            # find minimal previous dp where previous char is not almost equal to c
            best_prev = float('inf')
            for pc in range(26):
                if abs(pc - c) > 1:
                    if dp[pc] < best_prev:
                        best_prev = dp[pc]
            new_dp[c] = best_prev + change_cost
        dp = new_dp

    return min(dp)

