def number_of_sets(n: int, max_distance: int, roads: List[List[int]]) -> int:
    INF = 10 ** 15
    # direct distances (no intermediate vertices)
    base = [[INF] * n for _ in range(n)]
    for i in range(n):
        base[i][i] = 0
    for u, v, w in roads:
        if w < base[u][v]:
            base[u][v] = base[v][u] = w

    full_mask = (1 << n) - 1
    size = 1 << n
    # dist[mask] stores flattened n*n matrix of shortest paths using only vertices in mask as intermediates
    dist: List[List[int]] = [None] * size
    # mask = 0 -> no intermediate vertices, just direct edges
    dist[0] = [base[i][j] for i in range(n) for j in range(n)]

    for mask in range(1, size):
        # take the least significant set bit as the new intermediate vertex
        v = (mask & -mask).bit_length() - 1
        sub = mask ^ (1 << v)
        d = dist[sub][:]  # copy previous distances
        # try to improve paths using vertex v as intermediate
        for i in range(n):
            iv = d[i * n + v]
            if iv == INF:
                continue
            for j in range(n):
                nd = iv + d[v * n + j]
                if nd < d[i * n + j]:
                    d[i * n + j] = nd
        dist[mask] = d

    total = 0
    for closed in range(size):
        allowed = full_mask ^ closed
        # count subsets with 0 or 1 remaining vertices automatically
        if allowed & (allowed - 1) == 0:
            total += 1
            continue
        d_allowed = dist[allowed]
        ok = True
        # iterate over pairs of remaining vertices
        bits = [i for i in range(n) if (allowed >> i) & 1]
        for idx_i, i in enumerate(bits):
            for j in bits[idx_i + 1 :]:
                if d_allowed[i * n + j] > max_distance:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            total += 1
    return total

