def count_incremovable_subarrays(nums: List[int]) -> int:
    n = len(nums)
    # prefix[i] is True if nums[0..i] is strictly increasing
    prefix = [True] * n
    for i in range(1, n):
        prefix[i] = prefix[i - 1] and nums[i - 1] < nums[i]
    # suffix[i] is True if nums[i..n-1] is strictly increasing
    suffix = [True] * n
    for i in range(n - 2, -1, -1):
        suffix[i] = suffix[i + 1] and nums[i] < nums[i + 1]

    total = 0
    s = 1  # start of suffix after removed subarray
    for l in range(n):
        # left part (0..l-1) must be increasing
        if l > 0 and not prefix[l - 1]:
            continue
        # removal must be non‑empty
        if s < l + 1:
            s = l + 1
        # advance s until the condition holds
        while s <= n:
            suffix_ok = (s == n) or suffix[s]
            compare_ok = (l == 0) or (s == n) or (nums[l - 1] < nums[s])
            if suffix_ok and compare_ok:
                break
            s += 1
        if s <= n:
            total += n - s + 1
    return total

