def placed_coins(edges: List[List[int]], cost: List[int]) -> List[int]:
    n = len(cost)
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    result = [0] * n

    def dfs(node: int, parent: int) -> List[int]:
        # start with the node's own cost
        top_vals = [cost[node]]
        for nxt in graph[node]:
            if nxt == parent:
                continue
            child_top = dfs(nxt, node)
            top_vals.extend(child_top)
        # keep only the three largest values
        if len(top_vals) > 3:
            top_vals.sort(reverse=True)
            top_vals = top_vals[:3]
        else:
            top_vals.sort(reverse=True)

        if len(top_vals) < 3:
            result[node] = 1
        else:
            prod = top_vals[0] * top_vals[1] * top_vals[2]
            result[node] = prod if prod > 0 else 0
        return top_vals

    dfs(0, -1)
    return result

