def min_cost_to_convert_string(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    # Build set of all distinct strings that appear in operations
    nodes = set(original) | set(changed)
    # Map each node to an index
    idx = {s: i for i, s in enumerate(nodes)}
    n_nodes = len(nodes)
    INF = float('inf')
    # Initialize distance matrix
    dist = [[INF] * n_nodes for _ in range(n_nodes)]
    for i in range(n_nodes):
        dist[i][i] = 0
    for o, c, w in zip(original, changed, cost):
        i, j = idx[o], idx[c]
        if w < dist[i][j]:
            dist[i][j] = w
    # Floyd‑Warshall to allow chaining of operations
    for k in range(n_nodes):
        dk = dist[k]
        for i in range(n_nodes):
            di = dist[i]
            ik = di[k]
            if ik == INF:
                continue
            for j in range(n_nodes):
                kj = dk[j]
                if kj == INF:
                    continue
                nd = ik + kj
                if nd < di[j]:
                    di[j] = nd
    # Helper to get minimal cost between two substrings (same length)
    def sub_cost(a: str, b: str) -> float:
        if a == b:
            return 0.0
        if a in idx and b in idx:
            return dist[idx[a]][idx[b]]
        return INF
    n = len(source)
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    max_len = max((len(s) for s in original), default=0)
    for i in range(n + 1):
        for j in range(n + 1):
            if i > 0 and j > 0 and source[i - 1] == target[j - 1]:
                if dp[i - 1][j - 1] < dp[i][j]:
                    dp[i][j] = dp[i - 1][j - 1]
            # try converting a block of length k ending at i and j
            for k in range(1, min(i, j, max_len) + 1):
                sub_s = source[i - k:i]
                sub_t = target[j - k:j]
                cst = sub_cost(sub_s, sub_t)
                if cst != INF and dp[i - k][j - k] + cst < dp[i][j]:
                    dp[i][j] = dp[i - k][j - k] + cst
    ans = dp[n][n]
    return -1 if ans == INF else int(ans)  # answer is integer per problem statement

