def minimum_cost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    INF = float('inf')
    # 26 lowercase letters
    n = 26
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    # build directed edges with minimal cost
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - 97
        v = ord(c) - 97
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd‑Warshall to compute all‑pairs shortest paths
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(n):
                if dk[j] == INF:
                    continue
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    if len(source) != len(target):
        return -1

    total = 0
    for s_char, t_char in zip(source, target):
        u = ord(s_char) - 97
        v = ord(t_char) - 97
        d = dist[u][v]
        if d == INF:
            return -1
        total += d
    return total

