def longest_special_substring(s: str) -> int:
    class State:
        __slots__ = ("next", "link", "length", "occ")
        def __init__(self):
            self.next = {}
            self.link = -1
            self.length = 0
            self.occ = 0

    # Build suffix automaton
    states: List[State] = [State()]  # state 0 is the initial state
    last = 0
    for ch in s:
        cur = len(states)
        states.append(State())
        states[cur].length = states[last].length + 1
        states[cur].occ = 1
        p = last
        while p != -1 and ch not in states[p].next:
            states[p].next[ch] = cur
            p = states[p].link
        if p == -1:
            states[cur].link = 0
        else:
            q = states[p].next[ch]
            if states[p].length + 1 == states[q].length:
                states[cur].link = q
            else:
                clone = len(states)
                states.append(State())
                states[clone].length = states[p].length + 1
                states[clone].next = states[q].next.copy()
                states[clone].link = states[q].link
                while p != -1 and states[p].next.get(ch) == q:
                    states[p].next[ch] = clone
                    p = states[p].link
                states[q].link = states[cur].link = clone
        last = cur

    # Bucket sort states by length
    max_len = max(st.length for st in states)
    bucket: List[List[int]] = [[] for _ in range(max_len + 1)]
    for idx, st in enumerate(states):
        bucket[st.length].append(idx)

    # Propagate occurrence counts from longer to shorter states
    for length in range(max_len, -1, -1):
        for idx in bucket[length]:
            link = states[idx].link
            if link != -1:
                states[link].occ += states[idx].occ

    # Find maximum length (>0) with at least three occurrences
    answer = -1
    for st in states:
        if st.length > 0 and st.occ >= 3 and st.length > answer:
            answer = st.length
    return answer

