def can_make_palindrome(s: str, queries: List[List[int]]) -> List[bool]:
    n = len(s)
    result: List[bool] = []

    for a, b, c, d in queries:
        mutable = [False] * n
        for i in range(a, b + 1):
            mutable[i] = True
        for i in range(c, d + 1):
            mutable[i] = True

        # frequency of characters in mutable positions
        freq = {}
        for i, ch in enumerate(s):
            if mutable[i]:
                freq[ch] = freq.get(ch, 0) + 1

        required = {}
        possible = True

        i = 0
        while i < n // 2:
            j = n - 1 - i
            i_fixed = not mutable[i]
            j_fixed = not mutable[j]

            if i_fixed and j_fixed:
                if s[i] != s[j]:
                    possible = False
                    break
            elif i_fixed and not j_fixed:
                required[s[i]] = required.get(s[i], 0) + 1
            elif not i_fixed and j_fixed:
                required[s[j]] = required.get(s[j], 0) + 1
            # both mutable -> no immediate requirement
            i += 1

        if not possible:
            result.append(False)
            continue

        # satisfy required characters from mutable pool
        for ch, cnt in required.items():
            if freq.get(ch, 0) < cnt:
                possible = False
                break
            freq[ch] -= cnt

        if not possible:
            result.append(False)
            continue

        # check parity of remaining characters
        odd_counts = sum(1 for cnt in freq.values() if cnt % 2)

        if n % 2 == 1:
            mid = n // 2
            if mutable[mid]:
                # middle can host an odd character
                if odd_counts > 1:
                    possible = False
            else:
                if odd_counts > 0:
                    possible = False
        else:
            if odd_counts > 0:
                possible = False

        result.append(possible)

    return result

def min_operations(x, y):
    if x == y:
        return 0
    queue = [(x, 0)]
    visited = {x}
    head = 0
    while head < len(queue):
        current, steps = queue[head]
        head += 1
        if current == y:
            return steps
        nxts = []
        if current % 5 == 0:
            nxts.append(current // 5)
        if current % 11 == 0:
            nxts.append(current // 11)
        nxts.append(current + 1)
        nxts.append(current - 1)
        for nxt in nxts:
            if nxt <= 0 or nxt in visited:
                continue
            visited.add(nxt)
            queue.append((nxt, steps + 1))
    return -1

def max_partitions(s: str, k: int) -> int:
    max_part = 0
    n = len(s)
    for i in range(n):
        prefix_set = set()
        for j in range(n):
            if i == j:
                for c in range(ord('a'), ord('z') + 1):
                    char = chr(c)
                    if char != s[j]:
                        prefix_set.add(char)
                    else:
                        prefix_set.add(s[j])
                    if len(prefix_set) <= k:
                        partitions = 1
                        distinct = set()
                        for x in range(n):
                            if x == j:
                                distinct.add(char)
                            else:
                                distinct.add(s[x])
                            if len(distinct) > k:
                                partitions += 1
                                distinct.clear()
                                if x == j:
                                    distinct.add(char)
                                else:
                                    distinct.add(s[x])
                        if partitions > max_part:
                            max_part = partitions
                    prefix_set.clear()
            else:
                prefix_set.add(s[j])
    # No change case
    distinct = set()
    partitions = 1
    for i in range(n):
        distinct.add(s[i])
        if len(distinct) > k:
            partitions += 1
            distinct.clear()
            distinct.add(s[i])
    if partitions > max_part:
        max_part = partitions
    return max_part

