def count_complete_substrings(word: str, k: int) -> int:
    n = len(word)
    a_code = ord('a')
    answer = 0
    for d in range(1, 27):
        if d * k > n:
            break
        cnt = [0] * 26
        distinct = 0
        good = 0
        exceed = 0
        left = 0
        for right in range(n):
            idx = ord(word[right]) - a_code
            cnt[idx] += 1
            if cnt[idx] == 1:
                distinct += 1
            if cnt[idx] == k:
                good += 1
            if cnt[idx] == k + 1:
                exceed += 1
            while distinct > d or exceed > 0:
                l_idx = ord(word[left]) - a_code
                if cnt[l_idx] == k:
                    good -= 1
                if cnt[l_idx] == k + 1:
                    exceed -= 1
                    good += 1
                cnt[l_idx] -= 1
                if cnt[l_idx] == 0:
                    distinct -= 1
                left += 1
            if distinct == d and (right - left + 1) == d * k and good == d:
                answer += 1
    return answer

