def find_grid_region_average(image: List[List[int]], threshold: int) -> List[List[int]]:
    m = len(image)
    n = len(image[0])
    # Prefix sum of image values
    img_ps = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        row_sum = 0
        for j in range(n):
            row_sum += image[i][j]
            img_ps[i + 1][j + 1] = img_ps[i][j + 1] + row_sum

    # Invalid horizontal edges
    h_invalid = [[0] * (n - 1) for _ in range(m)]
    for i in range(m):
        for j in range(n - 1):
            if abs(image[i][j] - image[i][j + 1]) > threshold:
                h_invalid[i][j] = 1
    h_ps = [[0] * (n) for _ in range(m + 1)]
    for i in range(m):
        row_sum = 0
        for j in range(n - 1):
            row_sum += h_invalid[i][j]
            h_ps[i + 1][j + 1] = h_ps[i][j + 1] + row_sum

    # Invalid vertical edges
    v_invalid = [[0] * n for _ in range(m - 1)]
    for i in range(m - 1):
        for j in range(n):
            if abs(image[i][j] - image[i + 1][j]) > threshold:
                v_invalid[i][j] = 1
    v_ps = [[0] * (n + 1) for _ in range(m)]
    for i in range(m - 1):
        row_sum = 0
        for j in range(n):
            row_sum += v_invalid[i][j]
            v_ps[i + 1][j + 1] = v_ps[i][j + 1] + row_sum

    def rect_sum(ps, r1, c1, r2, c2):
        return ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1] - ps[r2 + 1][c1] + ps[r1][c1]

    diff_sum = [[0] * (n + 1) for _ in range(m + 1)]
    diff_cnt = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m - 2):
        for j in range(n - 2):
            if rect_sum(h_ps, i, j, i + 2, j + 1) != 0:
                continue
            if rect_sum(v_ps, i, j, i + 1, j + 2) != 0:
                continue
            region_sum = rect_sum(img_ps, i, j, i + 2, j + 2)
            avg = region_sum // 9
            diff_sum[i][j] += avg
            diff_sum[i + 3][j] -= avg
            diff_sum[i][j + 3] -= avg
            diff_sum[i + 3][j + 3] += avg

            diff_cnt[i][j] += 1
            diff_cnt[i + 3][j] -= 1
            diff_cnt[i][j + 3] -= 1
            diff_cnt[i + 3][j + 3] += 1

    # Convert diff arrays to actual grids
    for i in range(1, m):
        for j in range(n + 1):
            diff_sum[i][j] += diff_sum[i - 1][j]
            diff_cnt[i][j] += diff_cnt[i - 1][j]

    for i in range(m):
        for j in range(1, n):
            diff_sum[i][j] += diff_sum[i][j - 1]
            diff_cnt[i][j] += diff_cnt[i][j - 1]

    result = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            cnt = diff_cnt[i][j]
            result[i][j] = image[i][j] if cnt == 0 else diff_sum[i][j] // cnt
    return result

