def minimum_time_to_revert(word: str, k: int) -> int:
    n = len(word)
    if n == 0:
        return 0
    # compute prefix function (KMP)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and word[i] != word[j]:
            j = pi[j - 1]
        if word[i] == word[j]:
            j += 1
        pi[i] = j
    candidate = n - pi[-1]
    period = candidate if n % candidate == 0 else n
    t_period = period // math.gcd(period, k)
    t_over = n // k
    return min(t_period, t_over)

