def count_valid_pairs(points: List[Tuple[int, int]]) -> int:
    n = len(points)
    xs = sorted({x for x, _ in points})
    ys = sorted({y for _, y in points})
    x_index = {x: i + 1 for i, x in enumerate(xs)}
    y_index = {y: i + 1 for i, y in enumerate(ys)}
    nx, ny = len(xs), len(ys)

    grid = [[0] * (ny + 1) for _ in range(nx + 1)]
    for x, y in points:
        grid[x_index[x]][y_index[y]] = 1

    ps = [[0] * (ny + 1) for _ in range(nx + 1)]
    for i in range(1, nx + 1):
        row_sum = 0
        gi = grid[i]
        psi = ps[i]
        psi_prev = ps[i - 1]
        for j in range(1, ny + 1):
            row_sum += gi[j]
            psi[j] = psi_prev[j] + row_sum

    compressed = [(x_index[x], y_index[y]) for x, y in points]
    ans = 0
    for a in range(n):
        xi_a, yi_a = compressed[a]
        for b in range(n):
            if a == b:
                continue
            xi_b, yi_b = compressed[b]
            if xi_a <= xi_b and yi_a >= yi_b and (xi_a < xi_b or yi_a > yi_b):
                cnt = (
                    ps[xi_b][yi_a]
                    - ps[xi_a - 1][yi_a]
                    - ps[xi_b][yi_b - 1]
                    + ps[xi_a - 1][yi_b - 1]
                )
                if cnt == 2:
                    ans += 1
    return ans

def minimum_time(word: str, k: int) -> int:
    n = len(word)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j and word[i] != word[j]:
            j = pi[j - 1]
        if word[i] == word[j]:
            j += 1
        pi[i] = j
    ans = (n + k - 1) // k
    l = pi[-1] if n else 0
    while l:
        diff = n - l
        if diff % k == 0:
            t = diff // k
            if t < ans:
                ans = t
        l = pi[l - 1]
    return ans

