def max_palindromes(words: List[str]) -> int:
    freq = [0] * 26
    for w in words:
        for c in w:
            freq[ord(c) - 97] += 1
    total_pairs = 0
    total_singles = 0
    for cnt in freq:
        total_pairs += cnt // 2
        total_singles += cnt & 1
    lengths = sorted(map(len, words))
    count = 0
    for length in lengths:
        need_pairs = length // 2
        if length % 2 == 0:
            if total_pairs >= need_pairs:
                total_pairs -= need_pairs
                count += 1
        else:
            extra = 0 if total_singles > 0 else 1
            if total_pairs >= need_pairs + extra:
                total_pairs -= need_pairs
                if total_singles:
                    total_singles -= 1
                else:
                    total_pairs -= 1
                count += 1
    return count

