def max_consecutive(nums: List[int]) -> int:
    if not nums:
        return 0
    a = sorted(nums)
    n = len(a)
    min_deque = deque()
    max_deque = deque()
    l = 0
    best = 0
    for r in range(n):
        b_r = a[r] - r
        while min_deque and (a[min_deque[-1]] - min_deque[-1]) >= b_r:
            min_deque.pop()
        min_deque.append(r)
        while max_deque and (a[max_deque[-1]] - max_deque[-1]) <= b_r:
            max_deque.pop()
        max_deque.append(r)
        while (a[max_deque[0]] - max_deque[0]) - (a[min_deque[0]] - min_deque[0]) > 1:
            l += 1
            if min_deque[0] < l:
                min_deque.popleft()
            if max_deque[0] < l:
                max_deque.popleft()
        if r - l + 1 > best:
            best = r - l + 1
    return best

