def max_sum(nums: List[int], k: int, edges: List[List[int]]) -> int:
    base_sum = sum(nums)
    pos_sum = 0
    pos_cnt = 0
    min_pos = None
    max_neg = None

    for x in nums:
        diff = (x ^ k) - x
        if diff > 0:
            pos_sum += diff
            pos_cnt += 1
            if min_pos is None or diff < min_pos:
                min_pos = diff
        else:
            if max_neg is None or diff > max_neg:
                max_neg = diff

    if pos_cnt % 2 == 0:
        return base_sum + pos_sum
    else:
        ans = base_sum + pos_sum - (min_pos if min_pos is not None else 0)
        if max_neg is not None:
            cand = base_sum + pos_sum + max_neg
            if cand > ans:
                ans = cand
        return ans

