MOD = 10**9 + 7

def sum_power(nums: List[int], k: int) -> int:
    n = len(nums)
    # dp[t][s] = number of subsets of size t with sum s
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for val in nums:
        # iterate sizes descending to avoid reuse within same element
        for t in range(n - 1, -1, -1):
            ndp = dp[t]
            ndp_next = dp[t + 1]
            if val > k:
                continue
            for s in range(k - val, -1, -1):
                cnt = ndp[s]
                if cnt:
                    ndp_next[s + val] = (ndp_next[s + val] + cnt) % MOD
    # precompute powers of 2
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i - 1] * 2) % MOD
    ans = 0
    for t in range(n + 1):
        cnt = dp[t][k]
        if cnt:
            ans = (ans + cnt * pow2[n - t]) % MOD
    return ans

