def mark_elements(nums: List[int], queries: List[Tuple[int, int]]) -> List[int]:
    heap: List[Tuple[int, int]] = []

    def heap_is_empty() -> bool:
        return not heap

    def heap_push(item: Tuple[int, int]) -> None:
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p][0] <= heap[i][0]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop() -> Tuple[int, int]:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = l + 1
                smallest = i
                if l < len(heap) and heap[l][0] < heap[smallest][0]:
                    smallest = l
                if r < len(heap) and heap[r][0] < heap[smallest][0]:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return top

    n = len(nums)
    marked = [False] * n
    total = sum(nums)

    for i, v in enumerate(nums):
        heap_push((v, i))

    answer: List[int] = []

    for idx, k in queries:
        if not marked[idx]:
            marked[idx] = True
            total -= nums[idx]

        taken = 0
        while taken < k and not heap_is_empty():
            val, i = heap_pop()
            if marked[i]:
                continue
            marked[i] = True
            total -= val
            taken += 1

        answer.append(total)

    return answer

def maximum_length_substring(s):
    n = len(s)
    if n == 0:
        return 0
    cnt = {}
    left = 0
    max_len = 0
    for right in range(n):
        c = s[right]
        cnt[c] = cnt.get(c, 0) + 1
        while cnt[s[right]] > 2:
            lc = s[left]
            cnt[lc] -= 1
            left += 1
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

