def min_operations_to_reach_k(k: int) -> int:
    if k <= 1:
        return 0
    best = k - 1
    for v in range(1, k + 1):
        copies = 0
        if k > v:
            copies = math.ceil((k - v) / v)
        ops = (v - 1) + copies
        if ops < best:
            best = ops
    return best

def longest_common_suffix_queries(words_container, words_query):
    root = {"children": {}, "bestIdx": -1}
    lengths = [len(s) for s in words_container]

    def update(node, idx):
        cur = node["bestIdx"]
        if cur == -1 or lengths[idx] < lengths[cur] or (lengths[idx] == lengths[cur] and idx < cur):
            node["bestIdx"] = idx

    for i, s in enumerate(words_container):
        node = root
        update(node, i)
        for p in range(len(s) - 1, -1, -1):
            ch = s[p]
            if ch not in node["children"]:
                node["children"][ch] = {"children": {}, "bestIdx": -1}
            node = node["children"][ch]
            update(node, i)

    answer = [0] * len(words_query)
    for qi, q in enumerate(words_query):
        node = root
        best = node["bestIdx"]
        for p in range(len(q) - 1, -1, -1):
            ch = q[p]
            if ch not in node["children"]:
                break
            node = node["children"][ch]
            best = node["bestIdx"]
        answer[qi] = best
    return answer

def most_frequent_ids(nums, freq):
    n = len(nums)
    ans = [0] * n
    id_count = {}
    heap = []

    def heap_push(item):
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p][0] >= heap[i][0]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop():
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = l + 1
                largest = i
                if l < len(heap) and heap[l][0] > heap[largest][0]:
                    largest = l
                if r < len(heap) and heap[r][0] > heap[largest][0]:
                    largest = r
                if largest == i:
                    break
                heap[i], heap[largest] = heap[largest], heap[i]
                i = largest
        return top

    for i in range(n):
        id_ = nums[i]
        delta = freq[i]
        prev = id_count.get(id_, 0)
        now = prev + delta
        if now > 0:
            id_count[id_] = now
            heap_push([now, id_])
        else:
            id_count.pop(id_, None)

        while heap and id_count.get(heap[0][1]) != heap[0][0]:
            heap_pop()

        ans[i] = heap[0][0] if heap else 0

    return ans

