def shortest_subarray_or(nums: List[int], k: int) -> int:
    B = 32
    cnt = [0] * B
    cur_or = 0
    left = 0
    best = float('inf')
    n = len(nums)
    for right in range(n):
        x = nums[right]
        for b in range(B):
            if (x >> b) & 1:
                cnt[b] += 1
                cur_or |= (1 << b)
        while left <= right and cur_or >= k:
            best = min(best, right - left + 1)
            y = nums[left]
            for b in range(B):
                if (y >> b) & 1:
                    cnt[b] -= 1
                    if cnt[b] == 0:
                        cur_or &= ~(1 << b)
            left += 1
    return -1 if best == float('inf') else best

