MOD = 10**9 + 7

def sum_of_powers(nums: List[int], k: int) -> int:
    n = len(nums)
    a = sorted(nums)

    # collect all possible differences (including 0)
    diffs = {0}
    for i in range(n):
        for j in range(i + 1, n):
            diffs.add(a[j] - a[i])
    diff_list = sorted(diffs, reverse=True)  # descending

    # DP to count subsets of size k with minimum gap >= d
    def count_at_least(d: int) -> int:
        # dp[i][j]: ways to pick j elements ending at position i
        dp = [[0] * (k + 1) for _ in range(n)]
        for i in range(n):
            dp[i][1] = 1
        for j in range(2, k + 1):
            for i in range(n):
                total = 0
                for p in range(i):
                    if a[i] - a[p] >= d:
                        total += dp[p][j - 1]
                dp[i][j] = total % MOD
        return sum(dp[i][k] for i in range(n)) % MOD

    cnt_ge = {}
    for d in diff_list:
        cnt_ge[d] = count_at_least(d)

    ans = 0
    prev = 0
    for idx, d in enumerate(diff_list):
        cnt = cnt_ge[d]
        if idx == 0:
            exact = cnt
        else:
            exact = (cnt - prev) % MOD
        ans = (ans + exact * d) % MOD
        prev = cnt

    return ans

