            inc_len += 1
        else:
            inc_len = 1
        if nums[i] < nums[i - 1]:
            dec_len += 1
        else:
            dec_len = 1
        if inc_len > max_len:
            max_len = inc_len
        if dec_len > max_len:
            max_len = dec_len
    return max_len

