def min_operations(nums: List[int], k: int) -> int:
    if not nums:
        return 0
    nums.sort()
    n = len(nums)
    median_idx = n // 2
    median_val = nums[median_idx]
    if median_val == k:
        return 0
    if median_val < k:
        # need to increase elements from median to end that are below k
        return sum(k - x for x in nums[median_idx:] if x < k)
    else:
        # need to decrease elements from start to median that are above k
        return sum(x - k for x in nums[: median_idx + 1] if x > k)

