def count_subarrays(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    next_greater = [n] * n
    stack = []
    for i, val in enumerate(nums):
        while stack and val > nums[stack[-1]]:
            idx = stack.pop()
            next_greater[idx] = i
        stack.append(i)
    pos_map = defaultdict(list)
    for i, v in enumerate(nums):
        pos_map[v].append(i)
    ans = 0
    for positions in pos_map.values():
        cnt = 0
        prev = -1
        for pos in positions:
            if cnt == 0:
                cnt = 1
                prev = pos
            else:
                if next_greater[prev] > pos:
                    cnt += 1
                else:
                    ans += cnt * (cnt + 1) // 2
                    cnt = 1
                prev = pos
        ans += cnt * (cnt + 1) // 2
    return ans

