def minimum_cost_walk(n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
    parent = list(range(n))
    size = [1] * n
    comp_and = [-1] * n  # all bits set

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int, w: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            comp_and[ra] &= w
            return
        new_and = comp_and[ra] & comp_and[rb] & w
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        comp_and[ra] = new_and

    for u, v, w in edges:
        unite(u, v, w)

    result: List[int] = []
    for s, t in queries:
        if find(s) != find(t):
            result.append(-1)
        else:
            result.append(comp_and[find(s)])
    return result

