    return ''.join(lst)

def count_special_characters(word: str) -> int:
    lower_mask = 0
    upper_mask = 0
    for ch in word:
        o = ord(ch)
        if 97 <= o <= 122:
            lower_mask |= 1 << (o - 97)
        elif 65 <= o <= 90:
            upper_mask |= 1 << (o - 65)
    return (lower_mask & upper_mask).bit_count()

