def count_special_characters(word: str) -> int:
    first_case: List[int] = [0] * 26  # 0 = unseen, 1 = lower, 2 = upper
    last_case: List[int] = [0] * 26   # same encoding
    for ch in word:
        if 'a' <= ch <= 'z':
            idx = ord(ch) - ord('a')
            if first_case[idx] == 0:
                first_case[idx] = 1
            last_case[idx] = 1
        elif 'A' <= ch <= 'Z':
            idx = ord(ch) - ord('A')
            if first_case[idx] == 0:
                first_case[idx] = 2
            last_case[idx] = 2
    count = 0
    for i in range(26):
        if first_case[i] == 1 and last_case[i] == 2:
            count += 1
    return count

