def minimum_sum(nums: List[int], targets: List[int]) -> int:
    n = len(nums)
    m = len(targets)
    INF = 10**19
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        # consider all possible segment starts j (0‑based) ending at i‑1
        and_val = 0
        # we will build the AND while moving j backwards
        for j in range(i - 1, -1, -1):
            if j == i - 1:
                and_val = nums[j]
            else:
                and_val &= nums[j]
            # try to match each target that could end here
            for k in range(1, m + 1):
                if and_val == targets[k - 1]:
                    prev = dp[j][k - 1]
                    if prev != INF:
                        cand = prev + nums[i - 1]
                        if cand < dp[i][k]:
                            dp[i][k] = cand
            # early break: if AND becomes 0 it will stay 0 for larger segments
            if and_val == 0:
                # still need to continue because later j may still be needed for other targets equal 0
                # but if all remaining targets are non‑zero we could break; keep simple and continue
                continue

    ans = dp[n][m]
    return -1 if ans == INF else ans

