def count_stable_binary_arrays(zero: int, one: int, limit: int) -> int:
    MOD = 1_000_000_007
    dp = [[[[0] * (limit + 1) for _ in range(2)] for _ in range(one + 1)] for _ in range(zero + 1)]
    if zero > 0:
        dp[1][0][0][1] = 1
    if one > 0:
        dp[0][1][1][1] = 1
    for z in range(zero + 1):
        for o in range(one + 1):
            for last in (0, 1):
                cur_arr = dp[z][o][last]
                for length in range(1, limit + 1):
                    cur = cur_arr[length]
                    if not cur:
                        continue
                    if last == 0:
                        if z < zero and length < limit:
                            dp[z + 1][o][0][length + 1] = (dp[z + 1][o][0][length + 1] + cur) % MOD
                        if o < one:
                            dp[z][o + 1][1][1] = (dp[z][o + 1][1][1] + cur) % MOD
                    else:
                        if o < one and length < limit:
                            dp[z][o + 1][1][length + 1] = (dp[z][o + 1][1][length + 1] + cur) % MOD
                        if z < zero:
                            dp[z + 1][o][0][1] = (dp[z + 1][o][0][1] + cur) % MOD
    ans = 0
    for last in (0, 1):
        arr = dp[zero][one][last]
        for length in range(1, limit + 1):
            ans = (ans + arr[length]) % MOD
    return ans

