from typing import List

def find_edges_in_shortest_paths(n: int, edges: List[List[int]]) -> List[bool]:
    adj = [[] for _ in range(n)]
    for idx, (u, v, w) in enumerate(edges):
        adj[u].append((v, w))
        adj[v].append((u, w))

    def dijkstra(src: int) -> List[int]:
        INF = 10**18
        dist = [INF] * n
        dist[src] = 0
        pq = [(0, src)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        return dist

    dist_start = dijkstra(0)
    dist_end = dijkstra(n - 1)
    INF = 10**18
    shortest = dist_start[n - 1]
    answer = [False] * len(edges)
    if shortest == INF:
        return answer

    for i, (u, v, w) in enumerate(edges):
        if dist_start[u] + w + dist_end[v] == shortest or dist_start[v] + w + dist_end[u] == shortest:
            answer[i] = True
    return answer

