def count_stable_binary_arrays(zero: int, one: int, limit: int) -> int:
    MOD = 1_000_000_007
    dp0 = [[0] * (one + 1) for _ in range(zero + 1)]
    dp1 = [[0] * (one + 1) for _ in range(zero + 1)]
    win1 = [0] * (one + 1)

    for i in range(zero + 1):
        if i > 0:
            remove_idx = i - 1 - limit
            for j in range(one + 1):
                win1[j] = (win1[j] + dp1[i - 1][j]) % MOD
                if remove_idx >= 0:
                    win1[j] = (win1[j] - dp1[remove_idx][j]) % MOD
        for j in range(one + 1):
            val = win1[j] if i > 0 else 0
            if j == 0 and i > 0 and i <= limit:
                val = (val + 1) % MOD
            dp0[i][j] = val

        win0 = 0
        for j in range(one + 1):
            if j > 0:
                win0 = (win0 + dp0[i][j - 1]) % MOD
                remove_idx = j - 1 - limit
                if remove_idx >= 0:
                    win0 = (win0 - dp0[i][remove_idx]) % MOD
                val = win0
            else:
                val = 0
            if i == 0 and j > 0 and j <= limit:
                val = (val + 1) % MOD
            dp1[i][j] = val

    return (dp0[zero][one] + dp1[zero][one]) % MOD

