def find_integer_added_to_array_ii(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    a = sorted(nums1)
    b = sorted(nums2)
    candidates = set()
    for i in range(min(3, n)):
        candidates.add(b[0] - a[i])
    for i in range(1, min(4, n + 1)):
        candidates.add(b[-1] - a[-i])
    best = None
    for x in candidates:
        i = j = 0
        skips = 0
        while i < n and j < n - 2:
            if a[i] + x == b[j]:
                i += 1
                j += 1
            else:
                skips += 1
                i += 1
                if skips > 2:
                    break
        skips += (n - i)
        if skips == 2 and (best is None or x < best):
            best = x
    return best if best is not None else 0

