def minimum_cost(nums, cost1, cost2):
    MOD = 1000000007
    n = len(nums)
    max_val = max(nums)

    def cost_for_target(target):
        diffs = [target - v for v in nums]
        S = sum(diffs)
        D = max(diffs)
        if cost2 >= 2 * cost1 or n < 2:
            return S * cost1
        rest = S - D
        if D <= rest:
            pairs = S // 2
            odd = S % 2
            return pairs * cost2 + odd * cost1
        else:
            excess = D - rest
            return excess * cost1 + rest * cost2

    if cost2 >= 2 * cost1 or n <= 2:
        return cost_for_target(max_val) % MOD

    diffs0 = [max_val - v for v in nums]
    S0 = sum(diffs0)
    D0 = max(diffs0)
    rest0 = S0 - D0
    excess0 = D0 - rest0
    if excess0 <= 0:
        t_star = 0
    else:
        t_star = -(-excess0 // (n - 2))

    candidates = {0, t_star - 1, t_star, t_star + 1}
    best = float('inf')
    for t in candidates:
        if t < 0:
            continue
        best = min(best, cost_for_target(max_val + t))
    return best % MOD

