def min_cost_permutation(nums: List[int]) -> List[int]:
    n = len(nums)
    full_mask = (1 << n) - 1
    # precompute costs: cost[i][j] = |i - nums[j]|
    cost = [[abs(i - nums[j]) for j in range(n)] for i in range(n)]

    INF = 10 ** 9
    best_total = INF
    best_perm: List[int] = []

    for start in range(n):
        # DP forward: minimal cost to reach 'last' covering 'mask'
        dp = [[INF] * n for _ in range(1 << n)]
        dp[1 << start][start] = 0

        for mask in range(1 << n):
            # skip masks that don't contain start
            if not (mask & (1 << start)):
                continue
            for last in range(n):
                cur = dp[mask][last]
                if cur == INF:
                    continue
                # try to go to next node
                nxt_mask = mask ^ full_mask  # bits not yet visited
                while nxt_mask:
                    nxt = (nxt_mask & -nxt_mask).bit_length() - 1
                    nxt_mask &= nxt_mask - 1
                    new_mask = mask | (1 << nxt)
                    new_cost = cur + cost[last][nxt]
                    if new_cost < dp[new_mask][nxt]:
                        dp[new_mask][nxt] = new_cost

        # compute minimal total cost for this start
        cur_best = INF
        best_last = -1
        for last in range(n):
            if dp[full_mask][last] == INF:
                continue
            total = dp[full_mask][last] + cost[last][start]
            if total < cur_best:
                cur_best = total
                best_last = last
        if cur_best > best_total:
            continue  # cannot improve global best

        # memoized remaining cost from a state to finish (including return to start)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def rem(mask: int, last: int) -> int:
            if mask == full_mask:
                return cost[last][start]
            best = INF
            for nxt in range(n):
                if not (mask >> nxt) & 1:
                    cand = cost[last][nxt] + rem(mask | (1 << nxt), nxt)
                    if cand < best:
                        best = cand
            return best

        # reconstruct lexicographically smallest permutation for this start
        path = [start]
        mask = 1 << start
        last = start
        while mask != full_mask:
            for nxt in range(n):
                if not (mask >> nxt) & 1:
                    if dp[mask][last] + cost[last][nxt] + rem(mask | (1 << nxt), nxt) == cur_best:
                        path.append(nxt)
                        mask |= 1 << nxt
                        last = nxt
                        break

        # compare with global best
        if cur_best < best_total or (cur_best == best_total and path < best_perm):
            best_total = cur_best
            best_perm = path

    return best_perm

