def sum_digit_differences(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return 0

    d = len(str(nums[0]))
    pos_count = [[0] * 10 for _ in range(d)]

    for num in nums:
        s = str(num)
        for i in range(d):
            digit = ord(s[i]) - 48
            pos_count[i][digit] += 1

    total = 0
    for i in range(d):
        diff_pairs = 0
        for digit in range(10):
            c = pos_count[i][digit]
            diff_pairs += c * (n - c)
        total += diff_pairs // 2

    return total

def min_balanced_partitions(s: str) -> int:
    n = len(s)
