    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        cnt = [0] * 26
        max_freq = 0
        distinct = 0
        for j in range(i - 1, -1, -1):
            idx = ord(s[j]) - 97
            if cnt[idx] == 0:
                distinct += 1
            cnt[idx] += 1
            if cnt[idx] > max_freq:
                max_freq = cnt[idx]
            if max_freq * distinct == i - j:
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
    return dp[n]

