def count_good_pairs(nums1: List[int], nums2: List[int], k: int) -> int:
    divisor_counts = Counter()
    for b in nums2:
        d = b * k
        if d != 0:
            divisor_counts[d] += 1

    total_nonzero = sum(divisor_counts.values())
    total = 0

    for a in nums1:
        if a == 0:
            total += total_nonzero
            continue
        limit = int(math.isqrt(a))
        for i in range(1, limit + 1):
            if a % i == 0:
                total += divisor_counts.get(i, 0)
                other = a // i
                if other != i:
                    total += divisor_counts.get(other, 0)
    return total

