class SegTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0]*(2*n)
    def update(self, pos, val):
        pos += self.n
        self.tree[pos] = val
        pos >>= 1
        while pos >= 1:
            self.tree[pos] = max(self.tree[2*pos], self.tree[2*pos+1])
            pos >>= 1
    def query(self, l, r):
        if l > r:
            return 0
        res = 0
        l += self.n; r += self.n+1
        while l < r:
            if l & 1:
                res = max(res, self.tree[l]); l += 1
            if r & 1:
                r -= 1; res = max(res, self.tree[r])
            l >>= 1; r >>= 1
        return res

class Solution:
    def getResults(self, queries: list[list[int]]) -> list[bool]:
        MAXX = 50002
        seg = SegTree(MAXX+1)
        obstacles = [0]  # 0 is a permanent virtual boundary, never a real obstacle
        ans = []
        for q in queries:
            if q[0] == 1:
                x = q[1]
                idx = bisect.bisect_left(obstacles, x)
                L = obstacles[idx-1]
                if idx < len(obstacles):
                    R = obstacles[idx]
                    seg.update(R, R-x)
                seg.update(x, x-L)
                obstacles.insert(idx, x)
            else:
                x, sz = q[1], q[2]
                idx = bisect.bisect_right(obstacles, x)
                last = obstacles[idx-1]
                trailing = x - last
                best = max(seg.query(0, x), trailing)
                ans.append(best >= sz)
        return ans

