    stack = []
    for ch in s:
        if ch == '*':
            deletions += 1
            continue
        while deletions and stack and stack[-1] > ch:
            stack.pop()
            deletions -= 1
        stack.append(ch)
    while deletions and stack:
        stack.pop()
        deletions -= 1
    return ''.join(stack)

