def count_peaks(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    bit = [0] * (n + 1)
    is_peak = [0] * n

    def add(idx: int, delta: int) -> None:
        i = idx + 1
        while i <= n:
            bit[i] += delta
            i += i & -i

    def prefix(idx: int) -> int:
        i = idx + 1
        s = 0
        while i:
            s += bit[i]
            i -= i & -i
        return s

    def range_sum(l: int, r: int) -> int:
        if l > r:
            return 0
        return prefix(r) - (prefix(l - 1) if l > 0 else 0)

    def compute(i: int) -> int:
        return 1 if 0 < i < n - 1 and nums[i] > nums[i - 1] and nums[i] > nums[i + 1] else 0

    for i in range(1, n - 1):
        p = compute(i)
        is_peak[i] = p
        if p:
            add(i, 1)

    ans: List[int] = []
    for q in queries:
        if q[0] == 1:
            l, r = q[1], q[2]
            ans.append(range_sum(l + 1, r - 1))
        else:
            pos, val = q[1], q[2]
            nums[pos] = val
            for i in (pos - 1, pos, pos + 1):
                if 0 < i < n - 1:
                    new_p = compute(i)
                    if new_p != is_peak[i]:
                        add(i, new_p - is_peak[i])
                        is_peak[i] = new_p
    return ans

