def count_permutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 1000000007
    reqCnt = [-1] * n
    maxCnt = 0
    for r in requirements:
        endi, cnti = r[0], r[1]
        reqCnt[endi] = cnti
        if cnti > maxCnt:
            maxCnt = cnti
    prev = [0] * (maxCnt + 1)
    cur = [0] * (maxCnt + 1)
    prev[0] = 1
    for i in range(1, n + 1):
        pref = [0] * (maxCnt + 1)
        pref[0] = prev[0]
        for k in range(1, maxCnt + 1):
            v = pref[k - 1] + prev[k]
            if v >= MOD:
                v -= MOD
            pref[k] = v
        for k in range(0, maxCnt + 1):
            left = k - (i - 1)
            val = pref[k]
            if left > 0:
                val -= pref[left - 1]
                if val < 0:
                    val += MOD
            cur[k] = val
        endIdx = i - 1
        if reqCnt[endIdx] != -1:
            need = reqCnt[endIdx]
            if need > endIdx * (endIdx + 1) // 2:
                return 0
            for k in range(0, maxCnt + 1):
                if k != need:
                    cur[k] = 0
        prev, cur = cur, prev
        for idx in range(len(cur)):
            cur[idx] = 0
    finalNeed = reqCnt[n - 1]
    if finalNeed == -1:
        return 0
    return prev[finalNeed]

