def min_area_three_rectangles(grid: List[List[int]]) -> int:
    R = len(grid)
    C = len(grid[0])

    # Prefix sums for rows and columns
    row_ps = [[0] * (C + 1) for _ in range(R)]
    for i in range(R):
        s = 0
        for j in range(C):
            s += grid[i][j]
            row_ps[i][j + 1] = s

    col_ps = [[0] * (R + 1) for _ in range(C)]
    for j in range(C):
        s = 0
        for i in range(R):
            s += grid[i][j]
            col_ps[j][i + 1] = s

    def has_one_row(i: int, c1: int, c2: int) -> bool:
        return row_ps[i][c2 + 1] - row_ps[i][c1] > 0

    def has_one_col(j: int, r1: int, r2: int) -> bool:
        return col_ps[j][r2 + 1] - col_ps[j][r1] > 0

    def box(r1: int, r2: int, c1: int, c2: int) -> int:
        # find min row
        min_r = r1
        while min_r <= r2 and not any(has_one_row(min_r, c1, c2) for _ in range(1)):
            if has_one_row(min_r, c1, c2):
                break
            min_r += 1
        if min_r > r2:
            return -1
        # find max row
        max_r = r2
        while max_r >= r1 and not any(has_one_row(max_r, c1, c2) for _ in range(1)):
            if has_one_row(max_r, c1, c2):
                break
            max_r -= 1
        # find min col
        min_c = c1
        while min_c <= c2 and not any(has_one_col(min_c, r1, r2) for _ in range(1)):
            if has_one_col(min_c, r1, r2):
                break
            min_c += 1
        # find max col
        max_c = c2
        while max_c >= c1 and not any(has_one_col(max_c, r1, r2) for _ in range(1)):
            if has_one_col(max_c, r1, r2):
                break
            max_c -= 1
        return (max_r - min_r + 1) * (max_c - min_c + 1)

    INF = 10 ** 30
    ans = INF

    # three horizontal strips
    for i in range(R - 2):
        for j in range(i + 1, R - 1):
            a1 = box(0, i, 0, C - 1)
            a2 = box(i + 1, j, 0, C - 1)
            a3 = box(j + 1, R - 1, 0, C - 1)
            if a1 != -1 and a2 != -1 and a3 != -1:
                s = a1 + a2 + a3
                if s < ans:
                    ans = s

    # three vertical strips
    for i in range(C - 2):
        for j in range(i + 1, C - 1):
            a1 = box(0, R - 1, 0, i)
            a2 = box(0, R - 1, i + 1, j)
            a3 = box(0, R - 1, j + 1, C - 1)
            if a1 != -1 and a2 != -1 and a3 != -1:
                s = a1 + a2 + a3
                if s < ans:
                    ans = s

    # L-shaped partitions (three quadrants)
    for r in range(R - 1):
        for c in range(C - 1):
            tl = box(0, r, 0, c)
            tr = box(0, r, c + 1, C - 1)
            bl = box(r + 1, R - 1, 0, c)
            br = box(r + 1, R - 1, c + 1, C - 1)
            has = [tl != -1, tr != -1, bl != -1, br != -1]
            if sum(has) == 3:
                s = (tl if has[0] else 0) + (tr if has[1] else 0) + (bl if has[2] else 0) + (br if has[3] else 0)
                if s < ans:
                    ans = s

    return ans if ans != INF else 0

