def min_area(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    top, bottom = rows, -1
    left, right = cols, -1
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val:
                if r < top:
                    top = r
                if r > bottom:
                    bottom = r
                if c < left:
                    left = c
                if c > right:
                    right = c
    if bottom == -1:
        return 0
    return (bottom - top + 1) * (right - left + 1)

