def number_of_alternating_groups(colors: List[int], k: int) -> int:
    n = len(colors)
    if n == 0 or k > n:
        return 0
    if k == 1:
        return n
    need = k - 1
    good = 0
    for i in range(need):
        if colors[i] != colors[i + 1]:
            good += 1
    ans = 1 if good == need else 0
    for start in range(1, n):
        if colors[start - 1] != colors[start]:
            good -= 1
        idx = (start + need - 1) % n
        nxt = (idx + 1) % n
        if colors[idx] != colors[nxt]:
            good += 1
        if good == need:
            ans += 1
    return ans

