def construct_string(target: str, words: List[str], costs: List[int]) -> int:
    n = len(target)
    if n == 0:
        return 0

    # Consolidate duplicate words with minimal cost
    min_cost = {}
    for w, c in zip(words, costs):
        if w not in min_cost or c < min_cost[w]:
            min_cost[w] = c

    # Build trie
    root = {}
    for w, c in min_cost.items():
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['_cost'] = c  # store cost at terminal node

    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] is INF:
            continue
        node = root
        j = i
        while j < n and target[j] in node:
            node = node[target[j]]
            j += 1
            if '_cost' in node:
                new_cost = dp[i] + node['_cost']
                if new_cost < dp[j]:
                    dp[j] = new_cost

    return -1 if dp[n] is INF else dp[n]

