class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # prefix[j][i] = sum of grid[0..i-1][j] (column-wise prefix sums)
        prefix = [[0] * (n + 1) for _ in range(n)]
        prevPick = [0] * (n + 1)
        prevSkip = [0] * (n + 1)

        for j in range(n):
            for i in range(n):
                prefix[j][i + 1] = prefix[j][i] + grid[i][j]

        # DP over columns; state = row index where the black region "ends" in
        # this column (height of black cells), tracking two cases: whether the
        # previous column was itself painted ("Pick") or not ("Skip"), since a
        # white cell only scores if it is horizontally adjacent to a black cell.
        for j in range(1, n):
            currPick = [0] * (n + 1)
            currSkip = [0] * (n + 1)
            for curr in range(n + 1):
                for prev in range(n + 1):
                    if curr > prev:
                        score = prefix[j - 1][curr] - prefix[j - 1][prev]
                        currPick[curr] = max(currPick[curr], prevSkip[prev] + score)
                        currSkip[curr] = max(currSkip[curr], prevSkip[prev] + score)
                    else:
                        score = prefix[j][prev] - prefix[j][curr]
                        currPick[curr] = max(currPick[curr], prevPick[prev] + score)
                        currSkip[curr] = max(currSkip[curr], prevPick[prev])
            prevPick, prevSkip = currPick, currSkip

        return max(prevPick)

import math

def count_not_special(l: int, r: int) -> int:
    total = r - l + 1

    def floor_sqrt(x: int) -> int:
        s = math.isqrt(x)
        while (s + 1) * (s + 1) <= x:
            s += 1
        while s * s > x:
            s -= 1
        return s

    def ceil_sqrt(x: int) -> int:
        s = floor_sqrt(x)
        return s if s * s == x else s + 1

    low = ceil_sqrt(l)
    high = floor_sqrt(r)
    if low > high:
        return total

    is_prime = [True] * (high + 1)
    if high >= 0:
        is_prime[0] = False
    if high >= 1:
        is_prime[1] = False

    limit = floor_sqrt(high)
    for i in range(2, limit + 1):
        if is_prime[i]:
            step = i
            start = i * i
            for j in range(start, high + 1, step):
                is_prime[j] = False

    prime_square_count = sum(1 for p in range(low, high + 1) if is_prime[p])
    return total - prime_square_count

