def is_rectangle_corner_reachable(x_corner: int, y_corner: int, circles: List[List[int]]) -> bool:
    n = len(circles)
    left = n
    right = n + 1
    bottom = n + 2
    top = n + 3

    parent = list(range(n + 4))
    rank = [0] * (n + 4)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    # if any circle covers the target corner, it's unreachable
    for x, y, r in circles:
        if (x - x_corner) ** 2 + (y - y_corner) ** 2 <= r * r:
            return False

    # connect circles that intersect rectangle sides (excluding mere corner touches)
    for i, (x, y, r) in enumerate(circles):
        if x - r <= 0 and y - r < y_corner and y + r > 0:
            unite(i, left)
        if x + r >= x_corner and y - r < y_corner and y + r > 0:
            unite(i, right)
        if y - r <= 0 and x - r < x_corner and x + r > 0:
            unite(i, bottom)
        if y + r >= y_corner and x - r < x_corner and x + r > 0:
            unite(i, top)

    # early block checks
    if find(left) == find(right) or find(bottom) == find(top) or find(left) == find(bottom) or find(right) == find(top):
        return False

    # connect intersecting circles
    for i in range(n):
        xi, yi, ri = circles[i]
        for j in range(i + 1, n):
            xj, yj, rj = circles[j]
            dx = xi - xj
            dy = yi - yj
            if dx * dx + dy * dy <= (ri + rj) * (ri + rj):
                unite(i, j)
                if find(left) == find(right) or find(bottom) == find(top) or find(left) == find(bottom) or find(right) == find(top):
                    return False
    return True

def time_taken(edges):
    n = len(edges) + 1
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    result = [0] * n
    for src in range(n):
        dist = [-1] * n
        dist[src] = 0
        stack = [src]
        max_dist = 0
        while stack:
            cur = stack.pop()
            for nb in adj[cur]:
                if dist[nb] == -1:
                    w = 2 if nb % 2 == 0 else 1
                    dist[nb] = dist[cur] + w
                    if dist[nb] > max_dist:
                        max_dist = dist[nb]
                    stack.append(nb)
        result[src] = max_dist
    return result

