def shortest_distance_after_road_addition_queries_ii(n: int, queries: List[Tuple[int, int]]) -> List[int]:
    out_edges: List[List[int]] = [[] for _ in range(n)]
    dist = list(range(n))
    results: List[int] = []
    for l, r in queries:
        out_edges[l].append(r)
        if dist[l] + 1 < dist[r]:
            dist[r] = dist[l] + 1
            q = deque([r])
            while q:
                u = q.popleft()
                nd = dist[u] + 1
                if u + 1 < n and nd < dist[u + 1]:
                    dist[u + 1] = nd
                    q.append(u + 1)
                for v in out_edges[u]:
                    if nd < dist[v]:
                        dist[v] = nd
                        q.append(v)
        results.append(dist[n - 1])
    return results

