def count_good_nodes(edges: List[List[int]]) -> int:
    n = len(edges) + 1
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    sys.setrecursionlimit(2 * n + 10)
    good = 0

    def dfs(u: int, parent: int) -> int:
        nonlocal good
        child_sizes = []
        for v in adj[u]:
            if v == parent:
                continue
            sz = dfs(v, u)
            child_sizes.append(sz)
        if not child_sizes or len(set(child_sizes)) == 1:
            good += 1
        return 1 + sum(child_sizes)

    dfs(0, -1)
    return good

