def count_monotonic_pairs(nums: List[int]) -> int:
    MOD = 1_000_000_007
    if not nums:
        return 0
    max_val = max(nums)
    dp = [0] * (max_val + 1)
    for v in range(nums[0] + 1):
        dp[v] = 1
    for i in range(len(nums) - 1):
        need = max(nums[i + 1] - nums[i], 0)
        pref = [0] * (max_val + 1)
        s = 0
        for v in range(max_val + 1):
            s += dp[v]
            if s >= MOD:
                s -= MOD
            pref[v] = s
        nxt = [0] * (max_val + 1)
        limit_max = nums[i + 1]
        for v in range(limit_max + 1):
            limit = v - need
            if limit >= 0:
                nxt[v] = pref[limit]
        dp = nxt
    ans = 0
    for v in range(nums[-1] + 1):
        ans += dp[v]
        if ans >= MOD:
            ans -= MOD
    return ans

