        pref[i + 1] = pref[i] + (ch == '1')
    limit = math.isqrt(n)
    ans = 0
    for r in range(n):
        l = r
        while True:
            ones = pref[r + 1] - pref[l]
            length = r - l + 1
            zeros = length - ones
            if zeros > limit:
                break
            if ones >= zeros * zeros:
                ans += 1
            if l == 0:
                break
            l -= 1
    return ans

