def count_k_constraint_substrings(s: str, k: int, queries: List[List[int]]) -> List[int]:
    n = len(s)
    r0 = [0] * n
    r1 = [0] * n

    right = -1
    zeros = 0
    for left in range(n):
        while right + 1 < n and zeros + (s[right + 1] == '0') <= k:
            right += 1
            if s[right] == '0':
                zeros += 1
        r0[left] = right
        if right >= left:
            if s[left] == '0':
                zeros -= 1
        else:
            right = left - 1

    right = -1
    ones = 0
    for left in range(n):
        while right + 1 < n and ones + (s[right + 1] == '1') <= k:
            right += 1
            if s[right] == '1':
                ones += 1
        r1[left] = right
        if right >= left:
            if s[left] == '1':
                ones -= 1
        else:
            right = left - 1

    max_good = [max(r0[i], r1[i]) for i in range(n)]

    class Fenwick:
        __slots__ = ('n', 'bit')
        def __init__(self, size: int):
            self.n = size
            self.bit = [0] * (size + 1)

        def add(self, idx: int, delta: int) -> None:
            i = idx
            while i <= self.n:
                self.bit[i] += delta
                i += i & -i

        def sum(self, idx: int) -> int:
            res = 0
            i = idx
            while i:
                res += self.bit[i]
                i -= i & -i
            return res

        def range_sum(self, l: int, r: int) -> int:
            return self.sum(r + 1) - self.sum(l)

    bit_cnt = Fenwick(n)
    bit_sum = Fenwick(n)

    q_objs = [{'l': q[0], 'r': q[1], 'idx': i} for i, q in enumerate(queries)]
    q_objs.sort(key=lambda x: x['r'])

    ans = [0] * len(queries)
    pos = 0
    for q in q_objs:
        while pos < n and max_good[pos] <= q['r']:
            bit_cnt.add(pos + 1, 1)
            bit_sum.add(pos + 1, max_good[pos])
            pos += 1
        l, r = q['l'], q['r']
        length = r - l + 1
        cnt_le = bit_cnt.range_sum(l, r)
        sum_le = bit_sum.range_sum(l, r)
        cnt_gt = length - cnt_le
        sum_min = sum_le + r * cnt_gt
        sum_i = (l + r) * length // 2
        ans[q['idx']] = sum_min + length - sum_i

    return ans

def largest_palindrome(n: int, k: int) -> str:
    if k == 0 or n == 0:
        return ""
    m = (n + 1) // 2
    pow10_mod = [0] * n
    pow10_mod[0] = 1 % k
    for i in range(1, n):
        pow10_mod[i] = (pow10_mod[i - 1] * 10) % k
    weight = [0] * m
    for i in range(m):
        j = n - 1 - i
        if i == j:
            weight[i] = pow10_mod[i] % k
        else:
            weight[i] = (pow10_mod[i] + pow10_mod[j]) % k
    reachable = [bytearray(k) for _ in range(m + 1)]
    reachable[m][0] = 1
    for i in range(m - 1, -1, -1):
        w = weight[i]
        cur = reachable[i]
        nxt = reachable[i + 1]
        for r in range(k):
            if not nxt[r]:
                continue
            for d in range(10):
                if i == 0 and d == 0:
                    continue
                nr = (d * w + r) % k
                cur[nr] = 1
    if not reachable[0][0]:
        return ""
    first_half = [''] * m
    need = 0
    for i in range(m):
        w = weight[i]
        for d in range(9, -1, -1):
            if i == 0 and d == 0:
                continue
            contrib = (d * w) % k
            suffix = (need - contrib) % k
            if reachable[i + 1][suffix]:
                first_half[i] = chr(ord('0') + d)
                need = suffix
                break
    res = []
    res.extend(first_half)
    start = m - 1 if n % 2 == 0 else m - 2
    for i in range(start, -1, -1):
        res.append(first_half[i])
    return ''.join(res)

from typing import List, Set

def count_pairs(nums: List[int]) -> int:
    """
    Counts index pairs (i, j) with i < j such that nums[i] and nums[j] can become
    identical after at most one swap of two different decimal digits in either number.
    """
    def reachable(num: int) -> Set[int]:
        """All numbers obtainable from `num` by swapping at most one pair of different digits."""
        s = str(num)
        res: Set[int] = {num}
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    continue
                lst = list(s)
                lst[i], lst[j] = lst[j], lst[i]
                res.add(int(''.join(lst)))
        return res

    reachable_sets = [reachable(x) for x in nums]

    count = 0
    n = len(nums)
    for i in range(n):
        set_i = reachable_sets[i]
        for j in range(i + 1, n):
            if nums[j] in set_i or nums[i] in reachable_sets[j]:
                count += 1
    return count

from typing import List, Set, Dict

def count_almost_equal_pairs_ii(nums: List[int]) -> int:
    def generate(num: int) -> Set[int]:
        s = str(num)
        L = len(s)
        result: Set[int] = {num}
        arr = list(s)
        for i in range(L):
            for j in range(i + 1, L):
                arr[i], arr[j] = arr[j], arr[i]
                swapped = ''.join(arr).lstrip('0')
                result.add(0 if swapped == '' else int(swapped))
                arr[i], arr[j] = arr[j], arr[i]
        return result

    n = len(nums)
    reachable: List[Set[int]] = [generate(x) for x in nums]
    value_to_indices: Dict[int, List[int]] = {}
    for idx, vals in enumerate(reachable):
        for v in vals:
            value_to_indices.setdefault(v, []).append(idx)

    seen: Set[int] = set()
    ans = 0
    for indices in value_to_indices.values():
        m = len(indices)
        for a in range(m):
            i = indices[a]
            for b in range(a + 1, m):
                j = indices[b]
                code = i * n + j
                if code not in seen:
                    seen.add(code)
                    ans += 1
    return ans

import math, heapq
from typing import List

MOD = 1_000_000_007

def final_array_state(nums: List[int], k: int, multiplier: int) -> List[int]:
    n = len(nums)
    if k == 0 or multiplier == 1:
        return [(x % MOD + MOD) % MOD for x in nums]

    if multiplier == 0:
        # choose element with smallest key according to original rule
        def key(val: int) -> float:
            if val == 0:
                return -float('inf')
            mag = math.log(abs(val))
            return -mag if val < 0 else mag

        best = 0
        for i in range(1, n):
            if key(nums[i]) < key(nums[best]):
                best = i
        result = []
        for i, v in enumerate(nums):
            if i == best:
                result.append(0)
            else:
                result.append((v % MOD + MOD) % MOD)
        return result

    logM = math.log(abs(multiplier))
    cnt = [0] * n
    heap = []
    for i, v in enumerate(nums):
        if v == 0:
            k_val = -float('inf')
        else:
            mag = math.log(abs(v))
            k_val = -mag if v < 0 else mag
        heap.append((k_val, i))
    heapq.heapify(heap)

    for _ in range(k):
        _, i = heapq.heappop(heap)
        cnt[i] += 1
        if nums[i] == 0:
            new_key = -float('inf')
        else:
            mag = math.log(abs(nums[i])) + cnt[i] * logM
            new_key = -mag if nums[i] < 0 else mag
        heapq.heappush(heap, (new_key, i))

    result = []
    for i, v in enumerate(nums):
        base = (v % MOD + MOD) % MOD
        mult = pow(multiplier, cnt[i], MOD)
        result.append((base * mult) % MOD)
    return result

