import heapq

def kth_nearest_obstacle(queries: List[Tuple[int, int]], k: int) -> List[int]:
    if k <= 0:
        return [-1] * len(queries)
    max_heap: List[int] = []
    results: List[int] = []
    for x, y in queries:
        dist = abs(x) + abs(y)
        if len(max_heap) < k:
            heapq.heappush(max_heap, -dist)
        elif dist < -max_heap[0]:
            heapq.heapreplace(max_heap, -dist)
        results.append(-max_heap[0] if len(max_heap) == k else -1)
    return results

