from typing import List

def count_good_integers(n: int, k: int) -> int:
    # pre‑compute factorials up to n
    fact: List[int] = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i

    answer = 0

    # helper to compute number of valid original permutations for a given count vector
    def valid_original_perms(cnt: List[int]) -> int:
        total = fact[n]
        for c in cnt:
            total //= fact[c]
        if cnt[0] == 0:
            return total
        # permutations with leading zero
        leading = fact[n - 1]
        leading //= fact[cnt[0] - 1]
        for d in range(1, 10):
            leading //= fact[cnt[d]]
        return total - leading

    # generate all digit count vectors that sum to n
    cnt = [0] * 10

    def dfs(digit: int, remaining: int) -> None:
        nonlocal answer
        if digit == 9:
            cnt[digit] = remaining
            # ----- check palindrome feasibility -----
            odd_cnt = 0
            odd_digit = -1
            for i in range(10):
                if cnt[i] % 2 == 1:
                    odd_cnt += 1
                    odd_digit = i
            if (n % 2 == 0 and odd_cnt != 0) or (n % 2 == 1 and odd_cnt != 1):
                return

            half_len = n // 2
            half_counts = [c // 2 for c in cnt]

            # generate all distinct permutations of the first half
            half = [0] * half_len
            used = [0] * 10

            found = False

            def backtrack(pos: int) -> None:
                nonlocal found
                if found:
                    return
                if pos == half_len:
                    # build palindrome string
                    left = ''.join(str(d) for d in half)
                    if n % 2 == 0:
                        pal = left + left[::-1]
                    else:
                        pal = left + str(odd_digit) + left[::-1]
                    if pal[0] == '0':
                        return
                    if int(pal) % k == 0:
                        found = True
                    return
                for d in range(10):
                    if half_counts[d] - used[d] > 0:
                        used[d] += 1
                        half[pos] = d
                        backtrack(pos + 1)
                        used[d] -= 1
                        if found:
                            return

            backtrack(0)

            if found:
                answer += valid_original_perms(cnt)
            return

        # assign count for current digit
        for c in range(remaining + 1):
            cnt[digit] = c
            dfs(digit + 1, remaining - c)

    dfs(0, n)
    return answer

