from typing import List, Tuple

def max_moves(kx: int, ky: int, positions: List[Tuple[int, int]]) -> int:
    N = 50
    p = len(positions)
    if p == 0:
        return 0

    nodes = [(kx, ky)] + positions
    m = p + 1
    dist = [[0] * m for _ in range(m)]
    moves = [(2, 1), (2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2), (-2, 1), (-2, -1)]

    for s in range(m):
        d = [[-1] * N for _ in range(N)]
        q = deque()
        sx, sy = nodes[s]
        d[sx][sy] = 0
        q.append((sx, sy))
        while q:
            x, y = q.popleft()
            nd = d[x][y] + 1
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and d[nx][ny] == -1:
                    d[nx][ny] = nd
                    q.append((nx, ny))
        for t in range(m):
            tx, ty = nodes[t]
            dist[s][t] = d[tx][ty]

    full_mask = (1 << p) - 1
    dp = [[0] * m for _ in range(1 << p)]

    for mask in range(full_mask, -1, -1):
        alice_turn = (mask.bit_count() % 2 == 0)
        for cur in range(m):
            if mask == full_mask:
                dp[mask][cur] = 0
                continue
            if alice_turn:
                best = -10**9
                for nxt in range(1, m):
                    bit = 1 << (nxt - 1)
                    if mask & bit:
                        continue
                    total = dist[cur][nxt] + dp[mask | bit][nxt]
                    if total > best:
                        best = total
                dp[mask][cur] = best
            else:
                best = 10**9
                for nxt in range(1, m):
                    bit = 1 << (nxt - 1)
                    if mask & bit:
                        continue
                    total = dist[cur][nxt] + dp[mask | bit][nxt]
                    if total < best:
                        best = total
                dp[mask][cur] = best

    return dp[0][0]

