def max_score(start: List[int], d: int) -> int:
    n = len(start)
    if n <= 1:
        return 0
    intervals = [(s, s + d) for s in start]
    intervals.sort(key=lambda x: x[0])
    min_l = intervals[0][0]
    max_r = intervals[-1][1]
    lo, hi = 0, max_r - min_l + 1

    def feasible(dist: int) -> bool:
        prev = intervals[0][0]
        for i in range(1, n):
            need = prev + dist
            lo_i, hi_i = intervals[i]
            if lo_i > need:
                prev = lo_i
            else:
                prev = need
            if prev > hi_i:
                return False
        return True

    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid + 1
        else:
            hi = mid
    return lo - 1

