class _Line:
    __slots__ = ("m", "b")
    def __init__(self, m: int, b: int):
        self.m = m
        self.b = b
    def value(self, x: int) -> int:
        return self.m * x + self.b

class _LiChaoNode:
    __slots__ = ("l", "r", "line", "left", "right")
    def __init__(self, l: int, r: int):
        self.l = l
        self.r = r
        self.line: _Line | None = None
        self.left: "_LiChaoNode | None" = None
        self.right: "_LiChaoNode | None" = None

class _LiChaoTree:
    def __init__(self, x_min: int, x_max: int):
        self.root = _LiChaoNode(x_min, x_max)

    def _add(self, node: _LiChaoNode, new: _Line) -> None:
        l, r = node.l, node.r
        mid = (l + r) // 2
        if node.line is None:
            node.line = new
            return
        left_is_better = new.value(l) > node.line.value(l)
        mid_is_better = new.value(mid) > node.line.value(mid)
        if mid_is_better:
            node.line, new = new, node.line
        if r - l == 0:
            return
        if left_is_better != mid_is_better:
            if node.left is None:
                node.left = _LiChaoNode(l, mid)
            self._add(node.left, new)
        else:
            if node.right is None:
                node.right = _LiChaoNode(mid + 1, r)
            self._add(node.right, new)

    def add_line(self, m: int, b: int) -> None:
        self._add(self.root, _Line(m, b))

    def _query(self, node: _LiChaoNode, x: int) -> int:
        if node is None:
            return -10**18
        res = node.line.value(x) if node.line is not None else -10**18
        if node.l == node.r:
            return res
        mid = (node.l + node.r) // 2
        if x <= mid and node.left is not None:
            return max(res, self._query(node.left, x))
        if x > mid and node.right is not None:
            return max(res, self._query(node.right, x))
        return res

    def query(self, x: int) -> int:
        return self._query(self.root, x)

def max_score(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    dp = [0] * n
    tree = _LiChaoTree(0, n)
    tree.add_line(nums[0], dp[0])  # intercept = dp[0] - 0*nums[0] = 0
    for i in range(1, n):
        dp[i] = tree.query(i)
        tree.add_line(nums[i], dp[i] - i * nums[i])
    return dp[-1]

class Solution:
    def maxValue(self, nums, k):
        m = 1 << 7
        n = len(nums)
        f = [[[False]*m for _ in range(k+2)] for _ in range(n+1)]
        f[0][0][0] = True
        for i in range(n):
            for j in range(k+1):
                for x in range(m):
                    if f[i][j][x]:
                        f[i+1][j][x] = True
                        f[i+1][j+1][x | nums[i]] = True
        g = [[[False]*m for _ in range(k+2)] for _ in range(n+1)]
        g[n][0][0] = True
        for i in range(n, 0, -1):
            for j in range(k+1):
                for y in range(m):
                    if g[i][j][y]:
                        g[i-1][j][y] = True
                        g[i-1][j+1][y | nums[i-1]] = True
        ans = 0
        for i in range(k, n-k+1):
            for x in range(m):
                if f[i][k][x]:
                    for y in range(m):
                        if g[i][k][y]:
                            ans = max(ans, x ^ y)
        return ans

