def can_reach_safe(grid: List[List[int]], health: int) -> bool:
    m, n = len(grid), len(grid[0])
    max_allowed = health - 1
    start_cost = grid[0][0]
    if start_cost > max_allowed:
        return False
    INF = max_allowed + 1
    dist = [[INF] * n for _ in range(m)]
    dq = deque()
    dist[0][0] = start_cost
    dq.appendleft((0, 0))
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while dq:
        x, y = dq.popleft()
        cur = dist[x][y]
        if cur > max_allowed:
            continue
        if x == m - 1 and y == n - 1:
            return True
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n:
                new_cost = cur + grid[nx][ny]
                if new_cost < dist[nx][ny] and new_cost <= max_allowed:
                    dist[nx][ny] = new_cost
                    if grid[nx][ny] == 0:
                        dq.appendleft((nx, ny))
                    else:
                        dq.append((nx, ny))
    return False

