def find_lexicographically_smallest_valid_sequence(word1: str, word2: str) -> List[int]:
    n = len(word1)
    m = len(word2)
    if m == 0:
        return []
    dp: List[List[Optional[Tuple[int, ...]]]] = [[None, None] for _ in range(m + 1)]
    dp[0][0] = ()
    for idx in range(n):
        for i in range(m - 1, -1, -1):
            for err in (0, 1):
                seq = dp[i][err]
                if seq is None:
                    continue
                if seq and seq[-1] >= idx:
                    continue
                new_err = err + (word1[idx] != word2[i])
                if new_err > 1:
                    continue
                cand = seq + (idx,)
                cur = dp[i + 1][new_err]
                if cur is None or cand < cur:
                    dp[i + 1][new_err] = cand
    best: Optional[Tuple[int, ...]] = None
    for err in (0, 1):
        seq = dp[m][err]
        if seq is None:
            continue
        if best is None or seq < best:
            best = seq
    return list(best) if best is not None else []

