def find_first_almost_equal(s: str, pattern: str) -> int:
    n, m = len(s), len(pattern)
    if m == 0:
        return 0
    if m > n:
        return -1

    def z_algorithm(t: str) -> list[int]:
        z = [0] * len(t)
        l = r = 0
        for i in range(1, len(t)):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < len(t) and t[z[i]] == t[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l, r = i, i + z[i] - 1
        return z

    # prefix matches
    concat = pattern + "#" + s
    z = z_algorithm(concat)
    offset = m + 1
    prefix_match = [min(z[offset + i], m) for i in range(n)]

    # suffix matches
    rev_s = s[::-1]
    rev_pat = pattern[::-1]
    concat_rev = rev_pat + "#" + rev_s
    z_rev = z_algorithm(concat_rev)
    offset_rev = m + 1
    suffix_match = [0] * n
    for i in range(n):
        match_len = min(z_rev[offset_rev + i], m)
        suffix_match[n - 1 - i] = match_len

    for start in range(n - m + 1):
        pref = prefix_match[start]
        if pref == m:
            return start
        suff = suffix_match[start + m - 1]
        if pref + suff >= m - 1:
            return start
    return -1

def kth_character(k: int) -> str:
    if k <= 0:
        return '\0'
    return chr(ord('a') + ((k - 1).bit_count() % 26))

