def find_kth_character(k: int, operations: List[int]) -> str:
    INF = 4_000_000_000_000_000_000
    cur_len = 1
    for _ in operations:
        cur_len = cur_len * 2
        if cur_len > INF:
            cur_len = INF
    pos = k
    shift = 0
    for op in reversed(operations):
        half = cur_len // 2
        if pos > half:
            pos -= half
            if op == 1:
                shift = (shift + 1) % 26
        cur_len = half
    return chr(ord('a') + shift)

def count_vowel_consonant_substrings(word: str, k: int) -> int:
    from bisect import bisect_right

    vowels = {'a', 'e', 'i', 'o', 'u'}
    n = len(word)

    pref_c = [0] * (n + 1)
    for i, ch in enumerate(word):
        pref_c[i + 1] = pref_c[i] + (ch not in vowels)

    last = {v: -1 for v in vowels}
    positions = {0: [0]}
    ans = 0

    for i, ch in enumerate(word):
        if ch in vowels:
            last[ch] = i
        min_last = min(last.values())
        if min_last != -1:
            target = pref_c[i + 1] - k
            arr = positions.get(target)
            if arr:
                ans += bisect_right(arr, min_last)
        positions.setdefault(pref_c[i + 1], []).append(i + 1)

    return ans

def count_substrings(word: str, k: int) -> int:
    n = len(word)
    vowel_to_idx = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
    latest = [-1] * 5

    left_k = 0
    left_km1 = 0
    cnt_k = 0
    cnt_km1 = 0
    ans = 0

    for r, ch in enumerate(word):
        v = vowel_to_idx.get(ch, -1)
        if v == -1:
            cnt_k += 1
            if k > 0:
                cnt_km1 += 1
        else:
            latest[v] = r

        while cnt_k > k:
            if vowel_to_idx.get(word[left_k], -1) == -1:
                cnt_k -= 1
            left_k += 1

        if k > 0:
            while cnt_km1 > k - 1:
                if vowel_to_idx.get(word[left_km1], -1) == -1:
                    cnt_km1 -= 1
                left_km1 += 1

        if -1 in latest:
            continue

        min_latest = min(latest)

        cnt_at_most_k = min_latest - left_k + 1 if min_latest >= left_k else 0
        cnt_at_most_km1 = (
            min_latest - left_km1 + 1 if k > 0 and min_latest >= left_km1 else 0
        )

        ans += cnt_at_most_k - cnt_at_most_km1

    return ans

