def remove_methods(n: int, k: int, invocations: List[Tuple[int, int]]) -> List[int]:
    adj = [[] for _ in range(n)]
    for a, b in invocations:
        adj[a].append(b)

    visited = [False] * n
    stack = [k]
    while stack:
        cur = stack.pop()
        if visited[cur]:
            continue
        visited[cur] = True
        stack.extend(adj[cur])

    for a, b in invocations:
        if not visited[a] and visited[b]:
            return list(range(n))

    return [i for i in range(n) if not visited[i]]

