def construct_grid(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    deg = [len(a) for a in adj]

    H = W = -1
    limit = int(n ** 0.5)
    deg_count = [0]*5
    for d in deg:
        if d <= 4:
            deg_count[d] += 1

    def compute_expect(h, w):
        expect = [0]*5
        if h == 1 or w == 1:
            expect[1] = 2
            expect[2] = n - 2
        else:
            expect[2] = 4
            expect[3] = 2*(h-2) + 2*(w-2)
            expect[4] = (h-2)*(w-2)
        return expect

    found = False
    for h in range(1, limit+1):
        if n % h != 0:
            continue
        w = n // h
        if h == 1 and w == 1:
            continue
        expect = compute_expect(h, w)
        if deg_count == expect:
            H, W = h, w
            found = True
            break
        if h != w:
            expect2 = compute_expect(w, h)
            if deg_count == expect2:
                H, W = w, h
                found = True
                break
    if not found:
        raise ValueError("not a rectangular grid")

    def walk_border(start, next_node, length_expected):
        path = [start]
        prev, cur = start, next_node
        while True:
            path.append(cur)
            if len(path) == length_expected:
                break
            nxt = None
            for nb in adj[cur]:
                if nb != prev and deg[nb] <= 3:
                    nxt = nb
                    break
            if nxt is None:
                break
            prev, cur = cur, nxt
        return path

    if H == 1:
        ends = [i for i in range(n) if deg[i] == 1]
        start = max(ends)
        order = []
        visited = [False]*n
        cur, prev = start, -1
        while cur != -1:
            order.append(cur)
            visited[cur] = True
            nxt = -1
            for nb in adj[cur]:
                if nb != prev:
                    nxt = nb
                    break
            prev = cur
            cur = nxt if (nxt != -1 and not visited[nxt]) else -1
        return [order]

    if W == 1:
        ends = [i for i in range(n) if deg[i] == 1]
        start = max(ends)
        order = []
        visited = [False]*n
        cur, prev = start, -1
        while cur != -1:
            order.append(cur)
            visited[cur] = True
            nxt = -1
            for nb in adj[cur]:
                if nb != prev:
                    nxt = nb
                    break
            prev = cur
            cur = nxt if (nxt != -1 and not visited[nxt]) else -1
        return [[v] for v in order]

    corners = [i for i in range(n) if deg[i] == 2]
    top_left = max(corners)
    neigh = adj[top_left]
    orientations = [(neigh[0], neigh[1]), (neigh[1], neigh[0])]

    for right_c, down_c in orientations:
        top = walk_border(top_left, right_c, W)
        if len(top) != W:
            continue
        left = walk_border(top_left, down_c, H)
        if len(left) != H:
            continue

        grid = [[-1]*W for _ in range(H)]
        placed = set()
        for j in range(len(top)):
            grid[0][j] = top[j]
            placed.add(top[j])
        for i in range(len(left)):
            grid[i][0] = left[i]
            placed.add(left[i])

        ok = True
        for i in range(1, H):
            if not ok:
                break
            for j in range(1, W):
                set_a = set(adj[grid[i-1][j]])
                candidates = [x for x in adj[grid[i][j-1]] if x in set_a]
                placed_here = False
                for cand in candidates:
                    if cand not in placed:
                        grid[i][j] = cand
                        placed.add(cand)
                        placed_here = True
                        break
                if not placed_here:
                    ok = False
                    break
        if ok:
            return grid
    raise ValueError("could not reconstruct grid")

