def x_sum_all_k_long_subarrays(nums: List[int], k: int, x: int) -> List[int]:
    n = len(nums)
    if k > n or k == 0:
        return []
    result: List[int] = []
    freq = {}
    for i in range(k):
        v = nums[i]
        freq[v] = freq.get(v, 0) + 1

    def compute_top_sum() -> int:
        entries = [(val, cnt) for val, cnt in freq.items()]
        entries.sort(key=lambda p: (-p[1], -p[0]))
        limit = x if x < len(entries) else len(entries)
        total = 0
        for i in range(limit):
            total += entries[i][0] * entries[i][1]
        return total

    result.append(compute_top_sum())

    for start in range(1, n - k + 1):
        out_val = nums[start - 1]
        in_val = nums[start + k - 1]

        cnt_out = freq[out_val]
        if cnt_out == 1:
            del freq[out_val]
        else:
            freq[out_val] = cnt_out - 1

        freq[in_val] = freq.get(in_val, 0) + 1

        result.append(compute_top_sum())

    return result

