from typing import Any

def kth_largest_perfect_subtree(root: Any, k: int) -> int:
    if k <= 0:
        return -1

    heap = []

    def dfs(node):
        if node is None:
            return True, -1, 0
        left_is_perf, left_h, left_sz = dfs(getattr(node, 'left', None))
        right_is_perf, right_h, right_sz = dfs(getattr(node, 'right', None))
        is_perf = left_is_perf and right_is_perf and left_h == right_h
        h = max(left_h, right_h) + 1
        sz = ((1 << (h + 1)) - 1) if is_perf else max(left_sz, right_sz)
        if is_perf:
            if len(heap) < k:
                heapq.heappush(heap, sz)
            else:
                heapq.heappushpop(heap, sz)
        return is_perf, h, sz

    dfs(root)
    return heap[0] if len(heap) == k else -1

