def max_removals(source: str, pattern: str, target_indices: List[int]) -> int:
    n = len(source)
    m = len(pattern)
    removable_set = set(target_indices)

    INF = 10 ** 9
    dp = [INF] * (m + 1)
    dp[0] = 0

    for idx, ch in enumerate(source):
        cost = 1 if idx in removable_set else 0
        # iterate backwards to avoid using updated values in the same iteration
        for i in range(m - 1, -1, -1):
            if ch == pattern[i] and dp[i] != INF:
                if dp[i] + cost < dp[i + 1]:
                    dp[i + 1] = dp[i] + cost

    min_needed = dp[m]
    # if pattern cannot be formed, no removals are possible
    if min_needed == INF:
        return 0
    return len(target_indices) - min_needed

