def count_winning_sequences(s: str) -> int:
    n = len(s)
    offset = n
    size = 2 * n + 1

    def idx(c: str) -> int:
        if c == 'F':
            return 0
        if c == 'W':
            return 1
        return 2  # 'E'

    alice = [idx(ch) for ch in s]

    win = [[0] * 3 for _ in range(3)]
    for b in range(3):
        for a in range(3):
            if b == a:
                win[b][a] = 0
            elif (b == 0 and a == 2) or (b == 1 and a == 0) or (b == 2 and a == 1):
                win[b][a] = 1
            else:
                win[b][a] = -1

    dp = [[0] * size for _ in range(3)]

    for i, a_move in enumerate(alice):
        dp_next = [[0] * size for _ in range(3)]
        if i == 0:
            for cur in range(3):
                delta = win[cur][a_move]
                sc = offset + delta
                if 0 <= sc < size:
                    dp_next[cur][sc] = 1
        else:
            sum_all = [(dp[0][j] + dp[1][j] + dp[2][j]) % MOD for j in range(size)]
            for cur in range(3):
                delta = win[cur][a_move]
                cur_dp = dp[cur]
                cur_next = dp_next[cur]
                for sc in range(size):
                    src = sc - delta
                    if 0 <= src < size:
                        total = sum_all[src] - cur_dp[src]
                        if total < 0:
                            total += MOD
                        cur_next[sc] = total
        dp = dp_next

    ans = 0
    for cur in range(3):
        row = dp[cur]
        for sc in range(offset + 1, size):
            ans += row[sc]
            if ans >= MOD:
                ans -= MOD
    return ans % MOD

def x_sum_of_k_subarrays(nums, k, x):
    n = len(nums)
    result = []
    for i in range(n - k + 1):
        freq = {}
        window_sum = 0
        for v in nums[i:i+k]:
            window_sum += v
            freq[v] = freq.get(v, 0) + 1
        if len(freq) <= x:
            result.append(window_sum)
        else:
            items = sorted(freq.items(), key=lambda kv: (-kv[1], -kv[0]))
            x_sum = sum(val*cnt for val, cnt in items[:x])
            result.append(x_sum)
    return result

