_spf_all: List[int] | None = None

def minimum_operations(nums: List[int]) -> int:
    global _spf_all
    if not nums:
        return 0
    max_val = max(nums)
    if _spf_all is None or len(_spf_all) - 1 < max_val:
        limit = max_val
        spf = [0] * (limit + 1)
        spf[1] = 1
        primes = []
        for i in range(2, limit + 1):
            if spf[i] == 0:
                spf[i] = i
                primes.append(i)
            for p in primes:
                if p * i > limit:
                    break
                spf[p * i] = p
                if p == spf[i]:
                    break
        _spf_all = spf
    spf = _spf_all

    INF = 10 ** 9
    dp0 = 0
    first = nums[0]
    first_spf = 1 if first == 1 else spf[first]
    dp1 = 1 if first_spf != first else INF
    prev_orig = first
    prev_spf = first_spf

    for cur in nums[1:]:
        cur_spf = 1 if cur == 1 else spf[cur]
        cur_has_spf = cur_spf != cur

        ndp0 = INF
        ndp1 = INF

        if dp0 < INF:
            if prev_orig <= cur:
                ndp0 = dp0
            if cur_has_spf and prev_orig <= cur_spf:
                ndp1 = dp0 + 1

        if dp1 < INF:
            if prev_spf <= cur:
                ndp0 = min(ndp0, dp1)
            if cur_has_spf and prev_spf <= cur_spf:
                ndp1 = min(ndp1, dp1 + 1)

        dp0, dp1 = ndp0, ndp1
        prev_orig, prev_spf = cur, cur_spf

    ans = dp0 if dp0 < dp1 else dp1
    return -1 if ans >= INF else ans

