def _lcm(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    return a // gcd(a, b) * b

def max_factor_score(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    pref_gcd = [0] * n
    pref_lcm = [0] * n

    pref_gcd[0] = nums[0]
    pref_lcm[0] = nums[0]
    for i in range(1, n):
        pref_gcd[i] = gcd(pref_gcd[i - 1], nums[i])
        pref_lcm[i] = _lcm(pref_lcm[i - 1], nums[i])

    best = pref_gcd[-1] * pref_lcm[-1]

    suffix_gcd = 0
    suffix_lcm = 1

    for i in range(n - 1, -1, -1):
        left_gcd = pref_gcd[i - 1] if i > 0 else 0
        if left_gcd == 0:
            cur_gcd = suffix_gcd
        elif suffix_gcd == 0:
            cur_gcd = left_gcd
        else:
            cur_gcd = gcd(left_gcd, suffix_gcd)

        left_lcm = pref_lcm[i - 1] if i > 0 else 1
        cur_lcm = _lcm(left_lcm, suffix_lcm)

        score = cur_gcd * cur_lcm
        if score > best:
            best = score

        # update suffix aggregates for next iteration
        if suffix_gcd == 0:
            suffix_gcd = nums[i]
        else:
            suffix_gcd = gcd(nums[i], suffix_gcd)

        if suffix_lcm == 1:
            suffix_lcm = nums[i]
        else:
            suffix_lcm = _lcm(nums[i], suffix_lcm)

    return best

