def count_equal_gcd_subsequence_pairs(nums: List[int]) -> int:
    if not nums:
        return 0
    max_val = max(nums)
    # precompute gcd for all pairs up to max_val
    gcd_table = [[0] * (max_val + 1) for _ in range(max_val + 1)]
    for i in range(max_val + 1):
        for j in range(max_val + 1):
            gcd_table[i][j] = gcd(i, j)

    dp = {(0, 0): 1}
    for x in nums:
        ndp = {}
        for (a, b), cur in dp.items():
            # keep current subsequences unchanged
            ndp[(a, b)] = (ndp.get((a, b), 0) + cur) % MOD
            # add x to first subsequence
            na = x if a == 0 else gcd_table[a][x]
            ndp[(na, b)] = (ndp.get((na, b), 0) + cur) % MOD
            # add x to second subsequence
            nb = x if b == 0 else gcd_table[b][x]
            ndp[(a, nb)] = (ndp.get((a, nb), 0) + cur) % MOD
        dp = ndp

    ans = 0
    for g in range(1, max_val + 1):
        ans = (ans + dp.get((g, g), 0)) % MOD
    return ans

