def find_subtree_sizes(parent: List[int], s: str) -> List[int]:
    n = len(parent)
    orig_children = [[] for _ in range(n)]
    for i in range(1, n):
        orig_children[parent[i]].append(i)

    new_parent = parent[:]
    saved_prev = [-1] * n
    last_seen = [-1] * 26

    stack = [(0, 0)]
    while stack:
        u, state = stack.pop()
        if state == 0:
            c = ord(s[u]) - 97
            saved_prev[u] = last_seen[c]
            last_seen[c] = u
            stack.append((u, 1))
            for v in orig_children[u]:
                cc = ord(s[v]) - 97
                new_parent[v] = last_seen[cc] if last_seen[cc] != -1 else parent[v]
                stack.append((v, 0))
        else:
            c = ord(s[u]) - 97
            last_seen[c] = saved_prev[u]

    final_children = [[] for _ in range(n)]
    for i in range(1, n):
        final_children[new_parent[i]].append(i)

    ans = [1] * n
    stack2 = [(0, 0)]
    while stack2:
        u, state = stack2.pop()
        if state == 0:
            stack2.append((u, 1))
            for v in final_children[u]:
                stack2.append((v, 0))
        else:
            for v in final_children[u]:
                ans[u] += ans[v]

    return ans

