def max_points(n: int, k: int, stay_score: List[List[int]], travel_score: List[List[int]]) -> int:
    if k == 0:
        return 0
    dp_prev = stay_score[0][:]
    neg_inf = -10**18
    for day in range(1, k):
        best_travel = [neg_inf] * n
        for p in range(n):
            base = dp_prev[p]
            row = travel_score[p]
            for c in range(n):
                if c == p:
                    continue
                val = base + row[c]
                if val > best_travel[c]:
                    best_travel[c] = val
        day_stay = stay_score[day]
        dp_curr = [0] * n
        for c in range(n):
            stay = dp_prev[c] + day_stay[c]
            travel = best_travel[c]
            dp_curr[c] = stay if stay > travel else travel
        dp_prev = dp_curr
    return max(dp_prev)

def total_characters_after_transformations(s: str, t: int) -> int:
    MOD = 1000000007
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] = (cnt[ord(ch) - 97] + 1) % MOD

    trans = [[0] * 26 for _ in range(26)]
    for i in range(25):
        trans[i][i + 1] = 1
    trans[25][0] = 2

    vec = cnt
    base = trans
    exp = t
    while exp:
        if exp & 1:
            new_vec = [0] * 26
            for i in range(26):
                vi = vec[i]
                if vi:
                    row = base[i]
                    for j in range(26):
                        bj = row[j]
                        if bj:
                            new_vec[j] = (new_vec[j] + vi * bj) % MOD
            vec = new_vec
        new_base = [[0] * 26 for _ in range(26)]
        for i in range(26):
            for k in range(26):
                aik = base[i][k]
                if aik:
                    rowk = base[k]
                    for j in range(26):
                        bj = rowk[j]
                        if bj:
                            new_base[i][j] = (new_base[i][j] + aik * bj) % MOD
        base = new_base
        exp >>= 1
    return sum(vec) % MOD

