SIZE = 26

def _multiply_matrix(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    C = [[0] * SIZE for _ in range(SIZE)]
    for i in range(SIZE):
        Ai = A[i]
        Ci = C[i]
        for k in range(SIZE):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(SIZE):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % MOD
    return C

def _multiply_matrix_vector(A: List[List[int]], v: List[int]) -> List[int]:
    res = [0] * SIZE
    for i in range(SIZE):
        row = A[i]
        s = 0
        for j in range(SIZE):
            s = (s + row[j] * v[j]) % MOD
        res[i] = s
    return res

def total_characters_after_transformations_ii(s: str, t: int, nums: List[int]) -> int:
    # Build transition matrix
    A = [[0] * SIZE for _ in range(SIZE)]
    for c in range(SIZE):
        cnt = nums[c]
        for d in range(1, cnt + 1):
            nxt = (c + d) % SIZE
            A[c][nxt] = (A[c][nxt] + 1) % MOD

    vec = [1] * SIZE
    cur = A
    exp = t
    while exp:
        if exp & 1:
            vec = _multiply_matrix_vector(cur, vec)
        cur = _multiply_matrix(cur, cur)
        exp >>= 1

    ans = 0
    for ch in s:
        ans = (ans + vec[ord(ch) - 97]) % MOD
    return ans

