    INF = 10**18
    dist0 = [[INF] * m for _ in range(n)]
    dist1 = [[INF] * m for _ in range(n)]
    dist0[0][0] = 0
    pq = [(0, 0, 0, 0)]  # time, i, j, parity (0 -> next move costs 1, 1 -> next move costs 2)
    di = (-1, 1, 0, 0)
    dj = (0, 0, -1, 1)
    while pq:
        cur, i, j, par = heapq.heappop(pq)
        if par == 0:
            if cur != dist0[i][j]:
                continue
        else:
            if cur != dist1[i][j]:
                continue
        move_cost = 1 if par == 0 else 2
        npar = 1 - par
        for d in range(4):
            ni = i + di[d]
            nj = j + dj[d]
            if not (0 <= ni < n and 0 <= nj < m):
                continue
            start = cur if cur > move_time[ni][nj] else move_time[ni][nj]
            arrival = start + move_cost
            if npar == 0:
                if arrival < dist0[ni][nj]:
                    dist0[ni][nj] = arrival
                    heapq.heappush(pq, (arrival, ni, nj, npar))
            else:
                if arrival < dist1[ni][nj]:
                    dist1[ni][nj] = arrival
                    heapq.heappush(pq, (arrival, ni, nj, npar))
    return min(dist0[n - 1][m - 1], dist1[n - 1][m - 1])

def smallest_divisible_digit_product(n: int, t: int) -> int:
    if t == 0:
        raise ValueError("t must be non‑zero")
    if n == 0:
        return 0
    n_str = str(n)
    len_n = len(n_str)

    from functools import lru_cache

    for L in range(len_n, len_n + 20):
        lower = n_str if L == len_n else None

        @lru_cache(maxsize=None)
        def dfs(pos: int, prod_mod: int, tight: bool, leading_zero: bool):
            if pos == L:
                return '' if prod_mod % t == 0 else None
            if lower is not None and tight:
                start = int(lower[pos])
            else:
                start = 0
            if pos == 0 and lower is None:
                start = max(start, 1)  # no leading zero for longer lengths
            for d in range(start, 10):
                new_tight = tight and lower is not None and d == int(lower[pos])
                if leading_zero and d == 0:
                    new_prod = prod_mod
                    new_leading = True
                else:
                    new_leading = False
                    if d == 0:
                        new_prod = 0
                    else:
                        new_prod = (prod_mod * d) % t if prod_mod != 0 else 0
                if new_prod == 0:
                    suffix = '0' * (L - pos - 1)
                    return str(d) + suffix
                res = dfs(pos + 1, new_prod, new_tight, new_leading)
                if res is not None:
                    return str(d) + res
            return None

        result = dfs(0, 1 % t, True if lower is not None else False, True)
        if result is not None:
            return int(result)

    # Fallback (should never be reached)
    cur = n
    while True:
        prod = 1
        temp = cur
        if temp == 0:
            prod = 0
        while temp > 0:
            digit = temp % 10
            prod *= digit
            temp //= 10
            if prod == 0:
                break
        if prod % t == 0:
            return cur
        cur += 1

