def adjacent_increasing_subarrays(nums: List[int], k: int) -> bool:
    n = len(nums)
    if k == 1:
        return n >= 2
    if n < 2 * k:
        return False

    def inc_at(p: int) -> bool:
        return nums[p] < nums[p + 1]

    count1 = sum(1 for j in range(0, k - 1) if inc_at(j))
    count2 = sum(1 for j in range(k, k + k - 1) if inc_at(j))

    max_start = n - 2 * k
    for i in range(max_start + 1):
        if count1 == k - 1 and count2 == k - 1:
            return True
        if i == max_start:
            break
        if inc_at(i):
            count1 -= 1
        if inc_at(i + k - 1):
            count1 += 1
        if inc_at(i + k):
            count2 -= 1
        if inc_at(i + 2 * k - 1):
            count2 += 1
    return False

