def max_frequency(nums: List[int], k: int, num_operations: int) -> int:
    if k == 0:
        cnt = {}
        best = 0
        for v in nums:
            cnt[v] = cnt.get(v, 0) + 1
            if cnt[v] > best:
                best = cnt[v]
        return best

    items = []
    for v in nums:
        r = v % k
        base = (v - r) // k
        items.append((r, base))
    items.sort(key=lambda x: (x[0], x[1]))

    answer = 0
    i = 0
    n = len(items)
    while i < n:
        j = i
        while j < n and items[j][0] == items[i][0]:
            j += 1
        total = 0
        left = i
        for right in range(i, j):
            total += items[right][1]
            while items[right][1] * (right - left + 1) - total > num_operations:
                total -= items[left][1]
                left += 1
            current_len = right - left + 1
            if current_len > answer:
                answer = current_len
        i = j
    return answer

