def max_frequency_after_operations(nums: List[int], k: int, num_operations: int) -> int:
    n = len(nums)
    if n == 0:
        return 0
    sorted_nums = sorted(nums)
    freq = Counter(nums)
    first_idx = {}
    for i, v in enumerate(sorted_nums):
        if v not in first_idx:
            first_idx[v] = i
    left = 0
    right = 0
    ans = 0
    for i, v in enumerate(sorted_nums):
        while sorted_nums[i] - sorted_nums[left] > k:
            left += 1
        if right < i:
            right = i
        while right + 1 < n and sorted_nums[right + 1] - sorted_nums[i] <= k:
            right += 1
        if i != first_idx[v]:
            continue
        interval_count = right - left + 1
        cnt_same = freq[v]
        possible = cnt_same + min(num_operations, interval_count - cnt_same)
        if possible > ans:
            ans = possible
    return ans

