def count_k_reducible_numbers(s: str, k: int) -> int:
    MOD = 1_000_000_007
    L = len(s)

    # factorials for binomial coefficients
    fact = [1] * (L + 1)
    for i in range(1, L + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (L + 1)
    inv_fact[L] = pow(fact[L], MOD - 2, MOD)
    for i in range(L, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def nCk(n: int, k_: int) -> int:
        if k_ < 0 or k_ > n:
            return 0
        return fact[n] * inv_fact[k_] % MOD * inv_fact[n - k_] % MOD

    # steps[c] = number of popcount reductions to reach 1 (excluding the starting number)
    steps = [0] * (L + 1)
    if L >= 1:
        steps[1] = 0
    for c in range(2, L + 1):
        pc = bin(c).count('1')
        steps[c] = 1 + steps[pc]

    # numbers whose popcount reduction steps are <= k-1
    good = [c for c in range(1, L + 1) if steps[c] <= k - 1]

    def count_less_than(target: int) -> int:
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = L - i - 1
                need = target - ones
                ans = (ans + nCk(remaining, need)) % MOD
                ones += 1
                if ones > target:
                    break
        return ans

    total = 0
    for c in good:
        total = (total + count_less_than(c)) % MOD

    # handle the special case when k == 0 (only the number 1 qualifies)
    if k == 0:
        total = 1 if int(s, 2) > 1 else 0

    return total

