def can_transform_to_zero_array(nums: List[int], queries: List[List[int]]) -> bool:
    n = len(nums)
    # map start index to list of end indices for intervals
    start_to_ends = {}
    for l, r in queries:
        if 0 <= l < n and 0 <= r < n and l <= r:
            start_to_ends.setdefault(l, []).append(r)

    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(n):
        if not dp[i]:
            continue
        # if current element is already zero, we can simply move forward
        if nums[i] == 0:
            dp[i + 1] = True
        # try all intervals that start at i
        for r in start_to_ends.get(i, []):
            dp[r + 1] = True

    return dp[n]

