def minimize_max_adjacent_diff(nums: List[int]) -> int:
    n = len(nums)
    base = 0
    INF = 10**18
    min_adj = INF
    max_adj = -INF
    for i in range(n - 1):
        a, b = nums[i], nums[i + 1]
        if a != -1 and b != -1:
            diff = abs(a - b)
            if diff > base:
                base = diff
        if a == -1 and b != -1:
            if b < min_adj:
                min_adj = b
            if b > max_adj:
                max_adj = b
        if a != -1 and b == -1:
            if a < min_adj:
                min_adj = a
            if a > max_adj:
                max_adj = a
    if min_adj == INF:
        return base
    k_diff = (max_adj - min_adj + 1) // 2
    return max(base, k_diff)

