def min_zero_array(nums: List[int], queries: List[List[int]]) -> int:
    n = len(nums)
    if n == 0 or all(x == 0 for x in nums):
        return 0

    for step, (l, r, v) in enumerate(queries, 1):
        for i in range(l, r + 1):
            nums[i] = max(0, nums[i] - v)
        if all(x == 0 for x in nums):
            return step
    return -1

