def min_array_sum(nums: List[int], k: int, op1: int, op2: int) -> int:
    INF = 10**18
    dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
    dp[0][0] = 0
    for v in nums:
        ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        half = (v + 1) // 2  # ceil division by 2
        dec = max(0, v - k)
        for i in range(op1 + 1):
            row_dp = dp[i]
            row_ndp = ndp[i]
            for j in range(op2 + 1):
                cur = row_dp[j]
                if cur == INF:
                    continue
                # no operation
                if cur + v < row_ndp[j]:
                    row_ndp[j] = cur + v
                # apply op1 only
                if i + 1 <= op1:
                    if cur + half < ndp[i + 1][j]:
                        ndp[i + 1][j] = cur + half
                # apply op2 only
                if j + 1 <= op2:
                    if cur + dec < ndp[i][j + 1]:
                        ndp[i][j + 1] = cur + dec
        dp = ndp
    ans = INF
    for i in range(op1 + 1):
        for j in range(op2 + 1):
            if dp[i][j] < ans:
                ans = dp[i][j]
    return ans

