import bisect

def min_positive_sum_subarray(nums: List[int], l: int, r: int) -> int:
    n = len(nums)
    if l > n:
        return -1
    pref = [0] * (n + 1)
    for i, v in enumerate(nums):
        pref[i + 1] = pref[i] + v

    sorted_prefixes = []
    best = float('inf')

    for i in range(1, n + 1):
        add_idx = i - l
        if add_idx >= 0:
            bisect.insort(sorted_prefixes, pref[add_idx])

        remove_idx = i - r - 1
        if remove_idx >= 0:
            pos = bisect.bisect_left(sorted_prefixes, pref[remove_idx])
            if pos < len(sorted_prefixes) and sorted_prefixes[pos] == pref[remove_idx]:
                sorted_prefixes.pop(pos)

        pos = bisect.bisect_left(sorted_prefixes, pref[i]) - 1
        if pos >= 0:
            cand = pref[i] - sorted_prefixes[pos]
            if 0 < cand < best:
                best = cand

    return -1 if best == float('inf') else best

