def maximize_target_nodes(edges1: List[Tuple[int, int]], edges2: List[Tuple[int, int]], k: int) -> List[int]:
    n = len(edges1) + 1
    m = len(edges2) + 1

    def build_adj(num: int, edges: List[Tuple[int, int]]) -> List[List[int]]:
        adj = [[] for _ in range(num)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        return adj

    adj1 = build_adj(n, edges1)
    adj2 = build_adj(m, edges2)

    def all_pairs_dist(num: int, adj: List[List[int]]) -> List[List[int]]:
        dist = [[-1] * num for _ in range(num)]
        for s in range(num):
            dq = deque([s])
            drow = dist[s]
            drow[s] = 0
            while dq:
                u = dq.popleft()
                du = drow[u]
                for v in adj[u]:
                    if drow[v] == -1:
                        drow[v] = du + 1
                        dq.append(v)
        return dist

    dist1 = all_pairs_dist(n, adj1)
    dist2 = all_pairs_dist(m, adj2)

    count_first = [0] * n
    for i in range(n):
        cnt = 0
        row = dist1[i]
        for d in row:
            if d != -1 and d <= k:
                cnt += 1
        count_first[i] = cnt

    best_second = [0] * (k + 1)
    for v in range(m):
        cnt = [0] * (k + 1)
        row = dist2[v]
        for d in row:
            if d != -1 and d <= k:
                cnt[d] += 1
        for r in range(1, k + 1):
            cnt[r] += cnt[r - 1]
        for r in range(k + 1):
            if cnt[r] > best_second[r]:
                best_second[r] = cnt[r]

    answer = [0] * n
    for i in range(n):
        max_add = 0
        row = dist1[i]
        for u in range(n):
            d = row[u]
            R = k - d - 1
            if R >= 0:
                add = best_second[R]
                if add > max_add:
                    max_add = add
        answer[i] = count_first[i] + max_add

    return answer

