def min_cost_transform(n: int, m: int) -> int:
    n_str = str(n)
    m_str = str(m)
    L = len(n_str)
    if len(m_str) != L:
        return -1
    max_val = 10 ** L - 1
    is_prime = [True] * (max_val + 1)
    if max_val >= 0:
        is_prime[0] = False
    if max_val >= 1:
        is_prime[1] = False
    i = 2
    while i * i <= max_val:
        if is_prime[i]:
            for j in range(i * i, max_val + 1, i):
                is_prime[j] = False
        i += 1
    n_int = int(n)
    m_int = int(m)
    if is_prime[n_int] or is_prime[m_int]:
        return -1
    if n_int == m_int:
        return n
    INF = 1 << 62
    dist = [INF] * (max_val + 1)
    dist[n_int] = n
    heap = [(dist[n_int], n_int)]
    while heap:
        cur_cost, u = heapq.heappop(heap)
        if cur_cost != dist[u]:
            continue
        if u == m_int:
            return cur_cost
        s = str(u).zfill(L)
        for idx in range(L):
            digit = ord(s[idx]) - ord('0')
            if digit > 0:
                ns = list(s)
                ns[idx] = chr(ord('0') + digit - 1)
                v = int(''.join(ns))
                if not is_prime[v] and dist[v] > cur_cost + v:
                    dist[v] = cur_cost + v
                    heapq.heappush(heap, (dist[v], v))
            if digit < 9:
                ns = list(s)
                ns[idx] = chr(ord('0') + digit + 1)
                v = int(''.join(ns))
                if not is_prime[v] and dist[v] > cur_cost + v:
                    dist[v] = cur_cost + v
                    heapq.heappush(heap, (dist[v], v))
    return -1

