def count_components(nums: List[int], threshold: int) -> int:
    n = len(nums)
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    rep = [-1] * (threshold + 1)
    for i, val in enumerate(nums):
        if 1 <= val <= threshold:
            mult = val
            while mult <= threshold:
                idx = rep[mult]
                if idx == -1:
                    rep[mult] = i
                else:
                    unite(i, idx)
                mult += val

    roots = set()
    for i in range(n):
        roots.add(find(i))
    return len(roots)

