def max_area(x_coord: List[int], y_coord: List[int]) -> int:
    n = len(x_coord)
    points = set(zip(x_coord, y_coord))

    # coordinate compression
    xs = sorted(set(x_coord))
    ys = sorted(set(y_coord))
    x_to_idx = {x: i for i, x in enumerate(xs)}
    y_to_idx = {y: i for i, y in enumerate(ys)}
    mx, my = len(xs), len(ys)

    # grid of points
    grid = [[0] * my for _ in range(mx)]
    for x, y in points:
        grid[x_to_idx[x]][y_to_idx[y]] = 1

    # 2‑D prefix sum (1‑based for easier formulas)
    pref = [[0] * (my + 1) for _ in range(mx + 1)]
    for i in range(1, mx + 1):
        row_sum = 0
        for j in range(1, my + 1):
            row_sum += grid[i - 1][j - 1]
            pref[i][j] = pref[i - 1][j] + row_sum

    def rect_cnt(x1: int, y1: int, x2: int, y2: int) -> int:
        """inclusive count of points in rectangle defined by compressed indices."""
        return (
            pref[x2 + 1][y2 + 1]
            - pref[x1][y2 + 1]
            - pref[x2 + 1][y1]
            + pref[x1][y1]
        )

    best = -1
    for i in range(n):
        x1, y1 = x_coord[i], y_coord[i]
        for j in range(i + 1, n):
            x2, y2 = x_coord[j], y_coord[j]
            if x1 == x2 or y1 == y2:
                continue
            if (x1, y2) not in points or (x2, y1) not in points:
                continue

            ix1, ix2 = x_to_idx[x1], x_to_idx[x2]
            iy1, iy2 = y_to_idx[y1], y_to_idx[y2]
            lo_x, hi_x = (ix1, ix2) if ix1 < ix2 else (ix2, ix1)
            lo_y, hi_y = (iy1, iy2) if iy1 < iy2 else (iy2, iy1)

            if rect_cnt(lo_x, lo_y, hi_x, hi_y) == 4:
                area = abs(x2 - x1) * abs(y2 - y1)
                if area > best:
                    best = area
    return best

def min_operations_to_make_good(s: str) -> int:
    n = len(s)
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1
    freq.sort(reverse=True)
    best = n
    max_k = min(26, n)
    for k in range(1, max_k + 1):
        if n % k:
            continue
        target = n // k
        sum_top = sum(freq[:k])
        extra = n - sum_top
        ops = extra
        for i in range(k):
            cur = freq[i]
            if cur > target:
                ops += cur - target
        if ops < best:
            best = ops
    return best

