def count_beautiful_splits(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return 0

    suffix_min = [0] * n
    cur_min = nums[-1]
    for i in range(n - 1, -1, -1):
        if nums[i] < cur_min:
            cur_min = nums[i]
        suffix_min[i] = cur_min

    count = 0
    cur_max = nums[0]
    for i in range(n - 1):
        if i > 0:
            cur_max = max(cur_max, nums[i])
        else:
            cur_max = nums[0]
        if cur_max == suffix_min[i + 1]:
            count += 1
