def count_paths_xor(grid: List[List[int]], k: int) -> int:
    m = len(grid)
    n = len(grid[0])
    dp_prev = [[0] * MAX_XOR for _ in range(n)]
    dp_prev[0][grid[0][0]] = 1

    for j in range(1, n):
        cur = [0] * MAX_XOR
        val = grid[0][j]
        left = dp_prev[j - 1]
        for x in range(MAX_XOR):
            cnt = left[x]
            if cnt:
                cur[x ^ val] = (cur[x ^ val] + cnt) % MOD
        dp_prev[j] = cur

    for i in range(1, m):
        dp_curr = [[0] * MAX_XOR for _ in range(n)]
        val = grid[i][0]
        above = dp_prev[0]
        for x in range(MAX_XOR):
            cnt = above[x]
            if cnt:
                dp_curr[0][x ^ val] = (dp_curr[0][x ^ val] + cnt) % MOD
        for j in range(1, n):
            val = grid[i][j]
            cur = dp_curr[j]
            above = dp_prev[j]
            left = dp_curr[j - 1]
            for x in range(MAX_XOR):
                cnt = above[x]
                if cnt:
                    cur[x ^ val] = (cur[x ^ val] + cnt) % MOD
            for x in range(MAX_XOR):
                cnt = left[x]
                if cnt:
                    cur[x ^ val] = (cur[x ^ val] + cnt) % MOD
        dp_prev = dp_curr

