def smallest_substring_with_identical_characters_i(s: str, num_ops: int) -> int:
    n = len(s)
    if n == 0:
        return 0
    runs = []
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        runs.append(j - i)
        i = j

    def flips_needed(limit: int) -> int:
        flips = 0
        for run in runs:
            flips += run // (limit + 1)
            if flips > num_ops:
                break
        return flips

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if flips_needed(mid) <= num_ops:
            hi = mid
        else:
            lo = mid + 1
    return lo

