def smallest_longest_substring(s: str, num_ops: int) -> int:
    n = len(s)
    if n == 0:
        return 0

    def can(limit: int) -> bool:
        flips = 0
        cur = s[0]
        run = 1
        for i in range(1, n):
            ch = s[i]
            if ch == cur:
                run += 1
            else:
                cur = ch
                run = 1
            if run > limit:
                flips += 1
                cur = '1' if cur == '0' else '0'
                run = 1
                if flips > num_ops:
                    return False
        return True

    low, high, ans = 1, n, n
    while low <= high:
        mid = (low + high) // 2
        if can(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

def find_lexicographically_largest_string(word: str, num_friends: int) -> str:
    n = len(word)
    L = n - (num_friends - 1)
    if L <= 0:
        return ""
    max_start = n - L
    i, j = 0, 1
    while i <= max_start and j <= max_start:
        k = 0
        while k < L and word[i + k] == word[j + k]:
            k += 1
        if k == L:
            break
        if word[i + k] < word[j + k]:
            i = i + k + 1
            if i <= j:
                i = j + 1
        else:
            j = j + k + 1
            if j <= i:
                j = i + 1
    start = min(i, j)
    return word[start:start + L]

def substring_matching_pattern(s: str, p: str) -> bool:
    star_pos = p.find('*')
    if star_pos == -1:
        return p in s

    pre = p[:star_pos]
    suf = p[star_pos + 1:]

    if not pre and not suf:
        return True
    if not pre:
        return suf in s
    if not suf:
        return pre in s

    pre_len = len(pre)
    start = s.find(pre)
    while start != -1:
        if s.find(suf, start + pre_len) != -1:
            return True
        start = s.find(pre, start + 1)
    return False

