class TaskManager:
    def __init__(self, tasks: List[List[int]]):
        self.heap = []
        self.info = {}
        for userId, taskId, priority in tasks:
            self.info[taskId] = (userId, priority)
            heapq.heappush(self.heap, (-priority, -taskId, taskId))
    def add(self, userId: int, taskId: int, priority: int) -> None:
        self.info[taskId] = (userId, priority)
        heapq.heappush(self.heap, (-priority, -taskId, taskId))
    def edit(self, taskId: int, newPriority: int) -> None:
        if taskId in self.info:
            userId, _ = self.info[taskId]
            self.info[taskId] = (userId, newPriority)
            heapq.heappush(self.heap, (-newPriority, -taskId, taskId))
    def rmv(self, taskId: int) -> None:
        self.info.pop(taskId, None)
    def execTop(self) -> int:
        while self.heap:
            neg_pri, neg_tid, tid = self.heap[0]
            entry = self.info.get(tid)
            if entry is None or -neg_pri != entry[1]:
                heapq.heappop(self.heap)
                continue
            heapq.heappop(self.heap)
            userId = entry[0]
            del self.info[tid]
            return userId
        return -1

