        return 0

    # Kadane for the original array
    cur = best = nums[0]
    for x in nums[1:]:
        cur = max(cur + x, x)
        best = max(best, cur)
    answer = best

    distinct = set(nums)
    for v in distinct:
        cur_v = None
        best_v = float('-inf')
        has_non_v = False
        for x in nums:
            if x == v:
                if cur_v is None:
                    cur_v = 0
                else:
