def minimize_max_edge_weight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Collect unique edge weights and sort them
    weights = sorted({w for _, _, w in edges})

    # Helper to check if all nodes can reach node 0 using edges with weight <= limit
    def feasible(limit: int) -> bool:
        rev_adj = [[] for _ in range(n)]
        for a, b, w in edges:
            if w <= limit:
                rev_adj[b].append(a)          # reverse edge for reachability to 0
        visited = [False] * n
        q = deque([0])
        visited[0] = True
        while q:
            v = q.popleft()
            for nxt in rev_adj[v]:
                if not visited[nxt]:
                    visited[nxt] = True
                    q.append(nxt)
        return all(visited)

    # If even the maximum weight cannot make the graph feasible, return -1
    if not weights or not feasible(weights[-1]):
        return -1

    lo, hi = 0, len(weights) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(weights[mid]):
            hi = mid
        else:
            lo = mid + 1
    return weights[lo]  # minimal feasible maximum edge weight

