def sum_max_min_subseq(nums, k):
    MOD = 1_000_000_007
    n = len(nums)
    if k <= 0 or n == 0:
        return 0
    nums.sort()
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(m, r):
        if r < 0 or r > m:
            return 0
        return fact[m] * inv_fact[r] % MOD * inv_fact[m - r] % MOD

    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i - 1] * 2 % MOD

    max_choose = k - 1
    S = [0] * (n + 1)
    for i in range(n + 1):
        if i <= max_choose:
            S[i] = pow2[i]
        else:
            S[i] = (2 * S[i - 1] - comb(i - 1, max_choose)) % MOD
            if S[i] < 0:
                S[i] += MOD

    ans = 0
    for i, val in enumerate(nums):
        left = i
        right = n - 1 - i
        ways_max = S[left]
        ways_min = S[right]
        contrib = val % MOD * ((ways_max + ways_min) % MOD) % MOD
        ans = (ans + contrib) % MOD
    return ans

