def max_free_time(event_time: int, k: int, start_time: List[int], end_time: List[int]) -> int:
    n = len(start_time)
    gaps = [0] * (n + 1)
    gaps[0] = start_time[0]
    for i in range(1, n):
        gaps[i] = start_time[i] - end_time[i - 1]
    gaps[-1] = event_time - end_time[-1]
    total_free = sum(gaps)
    m = len(gaps)
    if k >= m - 1:
        return total_free
    sorted_with_idx = sorted(((v, idx) for idx, v in enumerate(gaps)), reverse=True)
    prefix = [0]
    for v, _ in sorted_with_idx:
        prefix.append(prefix[-1] + v)
    rank = [0] * m
    for pos, (_, idx) in enumerate(sorted_with_idx):
        rank[idx] = pos
    best = 0
    for i, g in enumerate(gaps):
        if rank[i] < k:
            sum_top_k = prefix[k + 1] - g
        else:
            sum_top_k = prefix[k]
        cand = g + sum_top_k
        if cand > best:
            best = cand
    return best

