def count_mentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    # OFFLINE sorts before MESSAGE at the same timestamp
    def sort_key(e):
        ts = int(e[1])
        prio = 0 if e[0] == "OFFLINE" else 1
        return (ts, prio)

    events = sorted(events, key=sort_key)
    mentions = [0] * numberOfUsers
    offline_until = [-1] * numberOfUsers  # -1 means never offline / already back online

    for etype, t, content in events:
        ts = int(t)
        if etype == "OFFLINE":
            uid = int(content)
            offline_until[uid] = ts + 60
        else:
            if content == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif content == "HERE":
                for i in range(numberOfUsers):
                    if offline_until[i] <= ts:
                        mentions[i] += 1
            else:
                for part in content.split():
                    uid = int(part[2:])
                    mentions[uid] += 1
    return mentions

