def max_frequency_after_subarray_operation(nums: List[int], k: int) -> int:
    n = len(nums)
    original_count = sum(1 for v in nums if v == k)
    if original_count == n:
        return n

    delta_set = {0}
    for v in nums:
        delta_set.add(k - v)

    answer = original_count
    for delta in delta_set:
        if delta == 0:
            continue
        target = k - delta
        cur = best = 0
        for v in nums:
            if v == k:
                cur -= 1
            elif v == target:
                cur += 1
            if cur < 0:
                cur = 0
            if cur > best:
                best = cur
        candidate = original_count + best
        if candidate > answer:
            answer = candidate
    return answer

