def shortest_supersequence_frequencies(words: List[str]) -> List[List[int]]:
    edges = [(ord(w[0]) - 97, ord(w[1]) - 97) for w in words]
    nodes = sorted({u for u, _ in edges} | {v for _, v in edges})
    letter_to_index = {letter: i for i, letter in enumerate(nodes)}
    n = len(nodes)
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[letter_to_index[u]].append(letter_to_index[v])

    def has_cycle_skipping(doubled: Set[int]) -> bool:
        states = [0] * n
        def dfs(u: int) -> bool:
            if states[u] == 1:
                return True
            if states[u] == 2:
                return False
            states[u] = 1
            if u not in doubled:
                for v in graph[u]:
                    if v in doubled:
                        continue
                    if dfs(v):
                        return True
            states[u] = 2
            return False
        return any(dfs(i) for i in range(n))

    minimal_subsets: List[Tuple[int, ...]] = []
    for size in range(n + 1):
        found = []
        for combo in combinations(range(n), size):
            if not has_cycle_skipping(set(combo)):
                found.append(combo)
        if found:
            minimal_subsets = found
            break

    result: List[List[int]] = []
    for subset in minimal_subsets:
        freq = [0] * 26
        for letter in nodes:
            freq[letter] = 1
        for idx in subset:
            freq[nodes[idx]] = 2
        result.append(freq)
    return result

