def minimum_cost_good_caption(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    # Count frequencies
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    # Find maximum frequency
    max_freq = max(freq.values())
    # Characters achieving max frequency
    candidates: List[str] = [ch for ch, cnt in freq.items() if cnt == max_freq]

    if len(candidates) == 1:
        # Unique best character
        return candidates[0] * n
    # Tie case
    if n == 2:
        # For length‑2 strings with a tie, no unique optimal result
        return ""
    # For longer strings, pick the character that appears first in the original string
    for ch in s:
        if ch in candidates:
            return ch * n
    return ""  # Fallback, should not happen

def max_diff_even_odd(s: str) -> int:
    freq = [0] * 26
    for ch in s:
        idx = ord(ch) - 97
        if 0 <= idx < 26:
            freq[idx] += 1
    max_odd = -1
    min_even = len(s) + 1
    for f in freq:
        if f == 0:
            continue
        if f & 1:
            if f > max_odd:
                max_odd = f
        else:
            if f < min_even:
                min_even = f
    if max_odd == -1 or min_even == len(s) + 1:
        return 0
    return max_odd - min_even

