import math

def assign_elements(groups: List[int], elements: List[int]) -> List[int]:
    if not elements:
        return [-1] * len(groups)
    max_val = max(elements)
    INF = len(elements)
    first_idx = [INF] * (max_val + 1)
    for i, v in enumerate(elements):
        if v <= max_val and first_idx[v] == INF:
            first_idx[v] = i
    result: List[int] = []
    for g in groups:
        best = INF
        limit = int(math.isqrt(g))
        d = 1
        while d <= limit:
            if g % d == 0:
                if d <= max_val and first_idx[d] < best:
                    best = first_idx[d]
                    if best == 0:
                        break
                d2 = g // d
                if d2 != d and d2 <= max_val and first_idx[d2] < best:
                    best = first_idx[d2]
                    if best == 0:
                        break
            d += 1
        result.append(-1 if best == INF else best)
    return result

