def max_score(points: List[int], m: int) -> int:
    max_p = max(points) if points else 0
    low, high = 0, max_p * m
    while low < high:
        mid = (low + high + 1) // 2
        need = 0
        for v in points:
            need += (mid + v - 1) // v
            if need > m:
                break
        if need <= m:
            low = mid
        else:
            high = mid - 1
    return low

def count_substrings_divisible_by_last_digit(s: str) -> int:
    cnt = [None] + [[0] * d for d in range(1, 10)]
    ans = 0
    for ch in s:
        cur = ord(ch) - 48
        ndcnt = [None] + [[0] * d for d in range(1, 10)]
        for d in range(1, 10):
            cnt_d = cnt[d]
            ndcnt_d = ndcnt[d]
            for r, ways in enumerate(cnt_d):
                if ways:
                    nr = (r * 10 + cur) % d
                    ndcnt_d[nr] += ways
            nr = cur % d
            ndcnt_d[nr] += 1
        if cur != 0:
            ans += ndcnt[cur][0]
        cnt = ndcnt
    return ans

