def sum_good_numbers(nums: List[int], k: int) -> int:
    n = len(nums)
    total = 0
    for i, val in enumerate(nums):
        if (i - k < 0 or val > nums[i - k]) and (i + k >= n or val > nums[i + k]):
            total += val
    return total

from typing import List

def separate_squares(squares: List[List[int]]) -> float:
    total_area = 0.0
    low = float('inf')
    high = -float('inf')
    events = {}
    for sq in squares:
        y = sq[1]
        l = sq[2]
        total_area += l * l
        low = min(low, y)
        high = max(high, y + l)
        events[y] = events.get(y, 0.0) - l
        events[y + l] = events.get(y + l, 0.0) + l

    half = total_area / 2.0
    current_h = low
    current_area = total_area
    slope = 0.0

    for h in sorted(events):
        if h > current_h:
            if slope != 0.0:
                next_area = current_area + slope * (h - current_h)
                if (slope < 0 and current_area >= half >= next_area) or (slope > 0 and current_area <= half <= next_area):
                    return round(current_h + (half - current_area) / slope, 5)
            else:
                if current_area == half:
                    return round(current_h, 5)
            current_area += slope * (h - current_h)
            current_h = h
        slope += events[h]

    return round(high, 5)

def has_special_substring(s: str, k: int) -> bool:
    if k <= 0:
        return False
    n = len(s)
    if k == 1:
        return n > 0
    if k > n:
        return False
    count = 1
    for i in range(1, n):
        if s[i] == s[i - 1]:
            count += 1
            if count >= k:
                return True
        else:
            count = 1
    return False

def shortest_matching_substring(s: str, p: str) -> int:
    first = p.find('*')
    second = p.find('*', first + 1)
    A = p[:first]
    B = p[first + 1 : second]
    C = p[second + 1 :]
    n = len(s)

    def all_occurrences(sub: str):
        if not sub:
            return list(range(n + 1))
        res = []
        start = 0
        while True:
            idx = s.find(sub, start)
            if idx == -1:
                break
            res.append(idx)
            start = idx + 1
        return res

    startsA = all_occurrences(A)
    startsB = all_occurrences(B)
    startsC = all_occurrences(C)

    nextB = [-1] * (n + 1)
    idxB = 0
    for pos in range(n + 1):
        while idxB < len(startsB) and startsB[idxB] < pos:
            idxB += 1
        if idxB < len(startsB):
            nextB[pos] = startsB[idxB]

    nextC = [-1] * (n + 1)
    idxC = 0
    for pos in range(n + 1):
        while idxC < len(startsC) and startsC[idxC] < pos:
            idxC += 1
        if idxC < len(startsC):
            nextC[pos] = startsC[idxC]

    best = float("inf")
    lenA, lenB, lenC = len(A), len(B), len(C)

    for i in startsA:
        posB = i + lenA
        if posB > n:
            continue
        j = nextB[posB]
        if j == -1:
            continue
        posC = j + lenB
        if posC > n:
            continue
        k = nextC[posC]
        if k == -1:
            continue
        length = (k + lenC) - i
        if length < best:
            best = length

    return -1 if best == float("inf") else best

def separate_squares_ii(squares):
    import bisect

    if not squares:
        return 0.0

    events = []  # (y, type, x1, x2)
    xs = []
    for x, y, l in squares:
        x1 = x
        x2 = x + l
        y1 = y
        y2 = y + l
        events.append((y1, 1, x1, x2))
        events.append((y2, -1, x1, x2))
        xs.append(x1)
        xs.append(x2)

    events.sort(key=lambda e: e[0])
    uniq_x = sorted(set(xs))
    if len(uniq_x) < 2:
        return float(events[0][0])

    idx = {v: i for i, v in enumerate(uniq_x)}
    n_intervals = len(uniq_x) - 1

    cnt = [0] * (4 * n_intervals)
    length = [0.0] * (4 * n_intervals)

    def update(node, l, r, ql, qr, delta):
        if ql > r or qr < l:
            return
        if ql <= l and r <= qr:
            cnt[node] += delta
        else:
            mid = (l + r) // 2
            update(node * 2, l, mid, ql, qr, delta)
            update(node * 2 + 1, mid + 1, r, ql, qr, delta)
        if cnt[node] > 0:
            length[node] = uniq_x[r + 1] - uniq_x[l]
        else:
            if l == r:
                length[node] = 0.0
            else:
                length[node] = length[node * 2] + length[node * 2 + 1]

    segments = []  # (y_start, y_end, union_x_length)
    prev_y = events[0][0]
    i = 0
    while i < len(events):
        y = events[i][0]
        if y != prev_y:
            seg_len = length[1]
            segments.append((prev_y, y, seg_len))
            prev_y = y
        while i < len(events) and events[i][0] == y:
            _, typ, x1, x2 = events[i]
            l_idx = idx[x1]
            r_idx = idx[x2] - 1
            if l_idx <= r_idx:
                update(1, 0, n_intervals - 1, l_idx, r_idx, typ)
            i += 1

    total_area = sum((y2 - y1) * seg_len for y1, y2, seg_len in segments)
    half_area = total_area / 2.0

    accumulated = 0.0
    for y1, y2, seg_len in segments:
        if seg_len == 0:
            continue
        seg_area = seg_len * (y2 - y1)
        if accumulated + seg_area >= half_area:
            needed = half_area - accumulated
            return y1 + needed / seg_len
        accumulated += seg_area

    # Fallback (should not happen)
    return segments[-1][1]

