import heapq

def max_sum_with_at_most_k(grid: List[List[int]], limits: List[int], k: int) -> int:
    if k <= 0:
        return 0
    min_heap: List[int] = []
    for i, row in enumerate(grid):
        limit_i = limits[i] if i < len(limits) else 0
        if limit_i <= 0:
            continue
        top_vals = heapq.nlargest(limit_i, row)
        for val in top_vals:
            if len(min_heap) < k:
                heapq.heappush(min_heap, val)
            elif val > min_heap[0]:
                heapq.heapreplace(min_heap, val)
    return sum(min_heap)

from collections import defaultdict

def select_k_disjoint_special_substrings(s: str, k: int) -> bool:
    freq = defaultdict(int)
    unique = 0
    for ch in s:
        cnt = freq[ch]
        if cnt == 0:
            unique += 1
        elif cnt == 1:
            unique -= 1
        freq[ch] = cnt + 1
    return unique >= k

class Solution:
    def lenOfVDiagonal(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dirs = [1, 1, -1, -1, 1]
        memo = {}

        def dfs(i, j, k, cnt):
            key = (i, j, k, cnt)
            if key in memo:
                return memo[key]
            target = 0 if grid[i][j] == 2 else 2
            best = 0
            x, y = i + dirs[k], j + dirs[k+1]
            if 0 <= x < m and 0 <= y < n and grid[x][y] == target:
                best = dfs(x, y, k, cnt) + 1
            if cnt == 0:
                k2 = (k+1) % 4
                x2, y2 = i + dirs[k2], j + dirs[k2+1]
                if 0 <= x2 < m and 0 <= y2 < n and grid[x2][y2] == target:
                    best = max(best, dfs(x2, y2, k2, 1) + 1)
            memo[key] = best
            return best

        ans = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    for k in range(4):
                        ans = max(ans, dfs(i, j, k, 0) + 1)
        return ans

def max_min_manhattan_distance(side, points, k):
    P = 4 * side
    s = []
    for x, y in points:
        if y == 0:
            pos = x
        elif x == side:
            pos = side + y
        elif y == side:
            pos = 3 * side - x
        else:
            pos = 4 * side - y
        s.append(pos)
    s.sort()
    N = len(s)
    dup = s + [v + P for v in s]

    from bisect import bisect_left

    def feasible(d):
        nxt = [0] * (2 * N)
        for i in range(2 * N):
            j = bisect_left(dup, dup[i] + d, i + 1, 2 * N)
            nxt[i] = j if j < 2 * N else -1

        LOG = (k - 1).bit_length()
        jumps = [nxt]
        for _ in range(1, LOG):
            prev = jumps[-1]
            cur = [0] * (2 * N)
            for i in range(2 * N):
                ni = prev[i]
                cur[i] = prev[ni] if ni != -1 else -1
            jumps.append(cur)

        for i in range(N):
            pos = i
            steps = k - 1
            bit = 0
            while steps:
                if steps & 1:
                    pos = jumps[bit][pos]
                    if pos == -1:
                        break
                steps >>= 1
                bit += 1
            if pos != -1 and pos < i + N and dup[pos] - dup[i] <= P - d:
                return True
        return False

    low, high = 0, P // 2
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    return low

