def number_of_copy_arrays(original: List[int], bounds: List[List[int]]) -> int:
    if not original:
        return 0
    low = -10**18
    high = 10**18
    for o, (b_low, b_high) in zip(original, bounds):
        l = b_low - o
        r = b_high - o
        if l > low:
            low = l
        if r < high:
            high = r
        if low > high:
            return 0
    return max(0, high - low + 1)

def smallest_generated_string(str1: str, str2: str) -> str:
    n = len(str1)
    m = len(str2)
    L = n + m - 1
    word = [''] * L

    t_indices = [i for i, ch in enumerate(str1) if ch == 'T']
    for i in t_indices:
        for j, c in enumerate(str2):
            pos = i + j
            cur = word[pos]
            if cur == '':
                word[pos] = c
            elif cur != c:
                return ''

    f_indices = [i for i, ch in enumerate(str1) if ch == 'F']
    for i in f_indices:
        already_diff = False
        for j, c in enumerate(str2):
            pos = i + j
            cur = word[pos]
            if cur != '' and cur != c:
                already_diff = True
                break
        if already_diff:
            continue

        changed = False
        for j in range(m - 1, -1, -1):
            pos = i + j
            if word[pos] == '':
                word[pos] = 'b' if str2[j] == 'a' else 'a'
                changed = True
                break
        if not changed:
            return ''

    for idx in range(L):
        if word[idx] == '':
            word[idx] = 'a'

    return ''.join(word)

