def minimum_removal_cost(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for l in range(n - 2, -1, -1):
        max_idx = l
        for r in range(l + 1, n):
            if nums[r] > nums[max_idx]:
                max_idx = r
            left = dp[l][max_idx - 1] if max_idx > l else 0
            right = dp[max_idx + 1][r] if max_idx < r else 0
            dp[l][r] = nums[max_idx] + (left if left < right else right)
    return dp[0][n - 1]

import math

def permute(n: int, k: int):
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i

    odd_count = (n + 1) // 2
    even_count = n // 2

    def total_count():
        if n <= 1:
            return 1
        if abs(odd_count - even_count) > 1:
            return 0
        if odd_count == even_count:
            return 2 * fact[odd_count] * fact[even_count]
        return fact[odd_count] * fact[even_count]

    if k > total_count():
        return []

    used = [False] * (n + 1)
    result = []
    rem_odd, rem_even = odd_count, even_count
    prev_parity = None

    for pos in range(n):
        placed = False
        for v in range(1, n + 1):
            if used[v]:
                continue
            parity = v % 2
            if prev_parity is not None and parity == prev_parity:
                continue
            new_rem_odd = rem_odd - (1 if parity == 1 else 0)
            new_rem_even = rem_even - (1 if parity == 0 else 0)
            L = new_rem_odd + new_rem_even
            if L == 0:
                cnt = 1
            else:
                next_parity_odd = (parity == 0)
                needed_odd = (L + 1) // 2 if next_parity_odd else L // 2
                needed_even = L - needed_odd
                if new_rem_odd == needed_odd and new_rem_even == needed_even:
                    cnt = fact[new_rem_odd] * fact[new_rem_even]
                else:
                    cnt = 0
            if k <= cnt:
                used[v] = True
                result.append(v)
                rem_odd, rem_even, prev_parity = new_rem_odd, new_rem_even, parity
                placed = True
                break
            else:
                k -= cnt
        if not placed:
            return []
    return result

def longest_palindrome_subseq_after_operations(s: str, k: int) -> int:
    n = len(s)
    if n == 0:
        return 0
    K = k

    def dist(a: str, b: str) -> int:
        d = abs(ord(a) - ord(b))
        return d if d <= 13 else 26 - d

    prev = [[0] * (K + 1) for _ in range(n)]
    cur = [[0] * (K + 1) for _ in range(n)]

    for r in range(n):
        for l in range(r, -1, -1):
            if l == r:
                for c in range(K + 1):
                    cur[l][c] = 1
            else:
                d = dist(s[l], s[r])
                for c in range(K + 1):
                    best = cur[l + 1][c]  # dp[l+1][r][c]
                    if prev[l][c] > best:
                        best = prev[l][c]  # dp[l][r-1][c]
                    if c >= d:
                        if l + 1 <= r - 1:
                            inner = prev[l + 1][c - d]
                        else:
                            inner = 0
                        if inner + 2 > best:
                            best = inner + 2
                    cur[l][c] = best
        prev, cur = cur, prev

    ans = 0
    for c in range(K + 1):
        if prev[0][c] > ans:
            ans = prev[0][c]
    return ans

