def largest_almost_missing_integer(nums: List[int], k: int) -> int:
    n = len(nums)
    if n < k:
        return -1
    if k == 1:
        freq = Counter(nums)
        ans = -1
        for v, c in freq.items():
            if c == 1 and v > ans:
                ans = v
        return ans
    freq = Counter(nums)
    ans = -1
    if freq[nums[0]] == 1:
        ans = max(ans, nums[0])
    if freq[nums[-1]] == 1:
        ans = max(ans, nums[-1])
    return ans

from typing import List

def fruits_into_baskets(fruits: List[int], baskets: List[int]) -> int:
    fruits_sorted = sorted(fruits)
    baskets_sorted = sorted(baskets)
    i = j = placed = 0
    while i < len(fruits_sorted) and j < len(baskets_sorted):
        if baskets_sorted[j] > fruits_sorted[i]:
            placed += 1
            i += 1
            j += 1
        else:
            j += 1
    return len(fruits) - placed

