import itertools

def count_even_numbers(digits: List[int]) -> int:
    seen = [False] * 1000
    count = 0
    for a, b, c in itertools.permutations(digits, 3):
        if a == 0:
            continue
        if c % 2:
            continue
        num = a * 100 + b * 10 + c
        if not seen[num]:
            seen[num] = True
            count += 1
    return count

import re

class Spreadsheet:
    def __init__(self, rows: int):
        self.rows = rows
        self.cells = {}
    def setCell(self, cell: str, value: int) -> None:
        self.cells[cell] = value
    def resetCell(self, cell: str) -> None:
        self.cells.pop(cell, None)
    def getValue(self, formula: str) -> int:
        if formula[0] == '=':
            parts = formula[1:].split('+')
            total = 0
            for p in parts:
                if re.match(r'^[A-Z][0-9]+$', p):
                    total += self.cells.get(p, 0)
                else:
                    total += int(p)
            return total
        return self.cells.get(formula, 0)

