def closest_equal_element_queries(nums: List[int], queries: List[int]) -> List[int]:
    n = len(nums)
    positions = {}
    for i, v in enumerate(nums):
        positions.setdefault(v, []).append(i)

    precomputed = [-1] * n
    for vec in positions.values():
        sz = len(vec)
        if sz == 1:
            continue
        for i, cur in enumerate(vec):
            nxt = vec[(i + 1) % sz]
            prev = vec[(i - 1) % sz]
            forward = (nxt - cur) % n
            backward = (cur - prev) % n
            precomputed[cur] = forward if forward < backward else backward

    return [precomputed[idx] for idx in queries]

from typing import List

class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx: int, delta: int) -> None:
        i = idx + 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def prefix_sum(self, idx: int) -> int:
        i = idx + 1
        res = 0
        while i:
            res += self.bit[i]
            i -= i & -i
        return res


def minimum_queries_to_zero_array(nums: List[int], queries: List[List[int]]) -> int:
    n = len(nums)
    m = len(queries)
    targets = nums
    lo = [1] * n
    hi = [m + 1] * n
    for i, v in enumerate(targets):
        if v == 0:
            lo[i] = hi[i] = 0

    while True:
        buckets: List[List[int]] = [[] for _ in range(m + 2)]
        active = False
        for i in range(n):
            if lo[i] < hi[i]:
                active = True
                mid = (lo[i] + hi[i]) // 2
                buckets[mid].append(i)
        if not active:
            break

        bit = Fenwick(n)
        for q_idx in range(1, m + 1):
            l, r, val = queries[q_idx - 1]
            bit.add(l, val)
            if r + 1 < n:
                bit.add(r + 1, -val)
            for i in buckets[q_idx]:
                cur = bit.prefix_sum(i)
                if cur >= targets[i]:
                    hi[i] = q_idx
                else:
                    lo[i] = q_idx + 1

    max_q = 0
    for i in range(n):
        if lo[i] == m + 1:
            return -1
        max_q = max(max_q, lo[i])
    return max_q

import functools

def count_beautiful(l: int, r: int) -> int:
    def count_up_to(x: int) -> int:
        if x <= 0:
            return 0
        digits = [int(c) for c in str(x)]
        n = len(digits)
        max_sum = 9 * n
        total = 0
        for S in range(1, max_sum + 1):
            @functools.lru_cache(maxsize=None)
            def dfs(pos: int, sum_: int, prod_mod: int, started: int, tight: int) -> int:
                if pos == n:
                    return 1 if (started and sum_ == S and prod_mod == 0) else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(limit + 1):
                    n_started = started or (d != 0)
                    n_sum = sum_ + (d if n_started else 0)
                    if n_sum > S:
                        continue
                    if not n_started:
                        n_prod_mod = prod_mod
                    else:
                        if not started:
                            n_prod_mod = d % S
                        else:
                            n_prod_mod = (prod_mod * (d % S)) % S
                    res += dfs(pos + 1, n_sum, n_prod_mod, n_started, tight and d == limit)
                return res

            total += dfs(0, 0, 1 % S, 0, 1)
            dfs.cache_clear()
        return total

    return count_up_to(r) - count_up_to(l - 1)

def max_containers(n: int, w: int, max_weight: int) -> int:
    deck_capacity = n * n
    weight_limit = max_weight // w
    return min(deck_capacity, weight_limit)

