from collections import defaultdict

def number_of_components(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    if n == 0:
        return 0

    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    prop_to_nodes = defaultdict(list)
    for idx, props in enumerate(properties):
        for p in set(props):
            prop_to_nodes[p].append(idx)

    for i in range(n):
        counter = defaultdict(int)
        for p in set(properties[i]):
            for j in prop_to_nodes[p]:
                if j > i:
                    counter[j] += 1
        for j, cnt in counter.items():
            if cnt >= k:
                unite(i, j)

    roots = {find(i) for i in range(n)}
    return len(roots)

