def max_active_sections_after_trade(s: str, queries: List[List[int]]) -> List[int]:
    n = len(s)
    # prefix sum of ones
    pref_one = [0] * (n + 1)
    for i, ch in enumerate(s):
        pref_one[i + 1] = pref_one[i] + (ch == '1')
    total_ones = pref_one[n]

    # next occurrence arrays
    next_one = [n] * (n + 1)
    next_zero = [n] * (n + 1)
    for i in range(n - 1, -1, -1):
        if s[i] == '1':
            next_one[i] = i
        else:
            next_one[i] = next_one[i + 1]
        if s[i] == '0':
            next_zero[i] = i
        else:
            next_zero[i] = next_zero[i + 1]

    # previous occurrence arrays
    prev_one = [-1] * n
    prev_zero = [-1] * n
    for i in range(n):
        if s[i] == '1':
            prev_one[i] = i
        else:
            prev_one[i] = prev_one[i - 1] if i > 0 else -1
        if s[i] == '0':
            prev_zero[i] = i
        else:
            prev_zero[i] = prev_zero[i - 1] if i > 0 else -1

    ans = []
    for l, r in queries:
        # find first and last zero inside [l, r]
        first_zero = next_zero[l]
        if first_zero > r:
            ans.append(total_ones)
            continue
        last_zero = prev_zero[r]
        if first_zero >= last_zero:
            ans.append(total_ones)
            continue
        # check for a one between first_zero and last_zero
        # need a one strictly after first_zero and at most last_zero
        if first_zero + 1 > r:
            ans.append(total_ones)
            continue
        first_one = next_one[first_zero + 1]
        if first_one <= last_zero:
            zeros_inside = (r - l + 1) - (pref_one[r + 1] - pref_one[l])
            ans.append(total_ones + zeros_inside)
        else:
            ans.append(total_ones)

    return ans

