def longest_palindrome_after_substring_concatenation(s: str, t: str) -> int:
    n = len(s)
    m = len(t)
    max_len = 0
    # iterate over all substrings of s (including empty)
    for i in range(n + 1):
        for j in range(i, n + 1):
            sub_s = s[i:j]
            # iterate over all substrings of t (including empty)
            for p in range(m + 1):
                for q in range(p, m + 1):
                    sub_t = t[p:q]
                    cand = sub_s + sub_t
                    # quick length check to skip shorter candidates
                    cand_len = len(cand)
                    if cand_len <= max_len:
                        continue
                    if cand == cand[::-1]:
                        max_len = cand_len
    return max_len
# TIME: O(n^2 * m^2 * (n+m)) SPACE: O(1)

