def min_operations(nums, x, k):
    n = len(nums)
    cost = [0] * (n - x + 1)
    for i in range(n - x + 1):
        window = sorted(nums[i:i+x])
        median = window[len(window)//2]
        cost[i] = sum(abs(v - median) for v in window)

    INF = float('inf')
    m = n - x + 1
    dp = [[INF]*(k+1) for _ in range(n+1)]
    dp[0][0] = 0
    for pos in range(n):
        for t in range(k+1):
            if dp[pos][t] == INF:
                continue
            if dp[pos][t] < dp[pos+1][t]:
                dp[pos+1][t] = dp[pos][t]
            if pos < m and t < k:
                npos = pos + x
                ncost = dp[pos][t] + cost[pos]
                if ncost < dp[npos][t+1]:
                    dp[npos][t+1] = ncost
    return dp[n][k]

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        ans = i = 0
        pre, mx = float('-inf'), 0
        while i < n:
            j = i + 1
            while j < n and s[j] == s[i]:
                j += 1
            cur = j - i
            if s[i] == '1':
                ans += cur
            else:
                mx = max(mx, pre + cur)
                pre = cur
            i = j
        ans += mx
        return ans

