def max_product_alternating_sum(nums: List[int], k: int, limit: int) -> int:
    dp_even = {0: 1}  # sum -> max product for even length subsequences (including empty)
    dp_odd = {}
    for val in nums:
        next_even = dp_even.copy()
        next_odd = dp_odd.copy()
        if abs(val) <= limit:
            if val not in next_odd or val > next_odd[val]:
                next_odd[val] = val
        for s, prod in dp_even.items():
            if val == 0:
                new_prod = 0
                new_sum = s
                if new_sum not in next_odd or new_prod > next_odd[new_sum]:
                    next_odd[new_sum] = new_prod
                continue
            if abs(prod) > limit // abs(val):
                continue
            new_prod = prod * val
            new_sum = s + val
            if new_sum not in next_odd or new_prod > next_odd[new_sum]:
                next_odd[new_sum] = new_prod
        for s, prod in dp_odd.items():
            if val == 0:
                new_prod = 0
                new_sum = s
                if new_sum not in next_even or new_prod > next_even[new_sum]:
                    next_even[new_sum] = new_prod
                continue
            if abs(prod) > limit // abs(val):
                continue
            new_prod = prod * val
            new_sum = s - val
            if new_sum not in next_even or new_prod > next_even[new_sum]:
                next_even[new_sum] = new_prod
        dp_even, dp_odd = next_even, next_odd
    ans = -1
    if k in dp_even:
        ans = max(ans, dp_even[k])
    if k in dp_odd:
        ans = max(ans, dp_odd[k])
    return ans

