def count_unique_xor_triplets(nums: list[int]) -> int:
    LIMIT = 2048
    present = [0] * LIMIT
    for x in nums:
        if 0 <= x < LIMIT:
            present[x] = 1

    pair_xor = [0] * LIMIT
    for a in range(LIMIT):
        if present[a]:
            for b in range(LIMIT):
                if present[b]:
                    pair_xor[a ^ b] = 1

    result = [0] * LIMIT
    for v in range(LIMIT):
        if present[v]:
            result[v] = 1

    for p in range(LIMIT):
        if pair_xor[p]:
            for c in range(LIMIT):
                if present[c]:
                    result[p ^ c] = 1

    return sum(result)

def smallest_palindromic_permutation(s: str) -> str:
    freq = [0] * 256
    for ch in s:
        freq[ord(ch)] += 1
    left_parts = []
    middle_char = ''
    has_middle = False
    for i in range(256):
        cnt = freq[i]
        if cnt == 0:
            continue
        half = cnt >> 1
        if half:
            left_parts.append(chr(i) * half)
        if cnt & 1:
            middle_char = chr(i)
            has_middle = True
    left = ''.join(left_parts)
    result = left
    if has_middle:
        result += middle_char
    result += left[::-1]
    return result

