INF = 2000000000000000000

def _comb_capped(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    if k > n - k:
        k = n - k
    res = 1
    for i in range(1, k + 1):
        res = res * (n - k + i) // i
        if res >= INF:
            return INF
    return res

def _mul_capped(a: int, b: int) -> int:
    if a >= INF or b >= INF:
        return INF
    if a > INF // b:
        return INF
    return a * b

def smallest_palindromic_rearrangement_ii(s: str, k: int) -> str:
    if k <= 0:
        return ""
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1

    middle = []
    half_cnt = [0] * 26
    for i in range(26):
        if freq[i] % 2 == 1:
            middle.append(chr(97 + i))
        half_cnt[i] = freq[i] // 2

    half_len = sum(half_cnt)

    # compute total permutations of the half multiset
    total_perms = 1
    remaining = half_len
    for c in half_cnt:
        if c:
            total_perms = _mul_capped(total_perms, _comb_capped(remaining, c))
            if total_perms >= INF:
                total_perms = INF
                break
            remaining -= c

    if k > total_perms:
        return ""

    left = []
    for pos in range(half_len):
        N = half_len - pos
        for i in range(26):
            cnt_i = half_cnt[i]
            if cnt_i == 0:
                continue
            # permutations if we place character i now
            cnt_perm = total_perms * cnt_i // N
            if k > cnt_perm:
                k -= cnt_perm
                continue
            # choose this character
            left.append(chr(97 + i))
            half_cnt[i] -= 1
            total_perms = cnt_perm
            break

    right = list(reversed(left))
    return "".join(left) + "".join(middle) + "".join(right)

