def max_size_non_decreasing(nums: List[int]) -> int:
    stack: List[int] = []
    for cur in nums:
        while stack and stack[-1] > cur:
            cur = max(stack[-1], cur)
            stack.pop()
        stack.append(cur)
    return len(stack)

from typing import List

def find_x_value(nums: List[int], k: int, queries: List[List[int]]) -> List[int]:
    n = len(nums)
    size = 4 * n
    prod = [1] * size
    cnt = [[0] * k for _ in range(size)]

    def combine(left_prod: int, left_cnt: List[int],
                right_prod: int, right_cnt: List[int]) -> tuple:
        new_prod = (left_prod * right_prod) % k
        new_cnt = [0] * k
        for r in range(k):
            new_cnt[r] += left_cnt[r]
        for r in range(k):
            nr = (left_prod * r) % k
            new_cnt[nr] += right_cnt[r]
        return new_prod, new_cnt

    def build(node: int, l: int, r: int) -> None:
        if l == r:
            rem = nums[l] % k
            prod[node] = rem
            c = [0] * k
            c[rem] = 1
            cnt[node] = c
        else:
            mid = (l + r) // 2
            build(node * 2, l, mid)
            build(node * 2 + 1, mid + 1, r)
            prod[node], cnt[node] = combine(
                prod[node * 2], cnt[node * 2],
                prod[node * 2 + 1], cnt[node * 2 + 1]
            )

    def update(node: int, l: int, r: int, idx: int, val: int) -> None:
        if l == r:
            rem = val % k
            prod[node] = rem
            c = [0] * k
            c[rem] = 1
            cnt[node] = c
        else:
            mid = (l + r) // 2
            if idx <= mid:
                update(node * 2, l, mid, idx, val)
            else:
                update(node * 2 + 1, mid + 1, r, idx, val)
            prod[node], cnt[node] = combine(
                prod[node * 2], cnt[node * 2],
                prod[node * 2 + 1], cnt[node * 2 + 1]
            )

    def query(node: int, l: int, r: int, ql: int, qr: int) -> tuple:
        if ql > r or qr < l:
            return 1, [0] * k  # identity
        if ql <= l and r <= qr:
            return prod[node], cnt[node]
        mid = (l + r) // 2
        left_prod, left_cnt = query(node * 2, l, mid, ql, qr)
        right_prod, right_cnt = query(node * 2 + 1, mid + 1, r, ql, qr)
        return combine(left_prod, left_cnt, right_prod, right_cnt)

    build(1, 0, n - 1)

    res: List[int] = []
    for indexi, valuei, starti, xi in queries:
        update(1, 0, n - 1, indexi, valuei)

        if starti == 0:
            pre_prod = 1
        else:
            pre_prod, _ = query(1, 0, n - 1, 0, starti - 1)

        _, suffix_cnt = query(1, 0, n - 1, starti, n - 1)

        ans = 0
        for r in range(k):
            if (pre_prod * r) % k == xi:
                ans += suffix_cnt[r]
        res.append(ans)

    return res
# TIME: O((log n) * k) per query SPACE: O(n * k)

import sys

MOD = 1000000007

def decimal_to_base(s: str, b: int):
    if s == "0":
        return [0]
    cur = s
    rev = []
    while not (len(cur) == 1 and cur[0] == '0'):
        next_chars = []
        carry = 0
        for ch in cur:
            num = carry * 10 + (ord(ch) - 48)
            q = num // b
            carry = num % b
            if next_chars or q != 0:
                next_chars.append(chr(48 + q))
        rev.append(carry)
        cur = ''.join(next_chars) if next_chars else "0"
    rev.reverse()
    return rev

def decrement_string(s: str) -> str:
    res = list(s)
    i = len(res) - 1
    while i >= 0 and res[i] == '0':
        res[i] = '9'
        i -= 1
    if i >= 0:
        res[i] = chr(ord(res[i]) - 1)
    pos = 0
    while pos < len(res) and res[pos] == '0':
        pos += 1
    if pos == len(res):
        return "0"
    return ''.join(res[pos:])

def count_up_to(digits, b: int) -> int:
    n = len(digits)
    memo = [[[-1 for _ in range(2)] for _ in range(b)] for _ in range(n)]
    sys.setrecursionlimit(10000)

    def dfs(idx: int, prev: int, tight: bool, started: bool) -> int:
        if idx == n:
            return 1
        if not tight and memo[idx][prev][started] != -1:
            return memo[idx][prev][started]
        limit = digits[idx] if tight else b - 1
        total = 0
        for d in range(limit + 1):
            nstarted = started or d != 0
            ntight = tight and d == limit
            if not nstarted:
                total += dfs(idx + 1, 0, ntight, False)
            else:
                if not started:
                    total += dfs(idx + 1, d, ntight, True)
                elif d >= prev:
                    total += dfs(idx + 1, d, ntight, True)
            if total >= MOD:
                total -= MOD
        if not tight:
            memo[idx][prev][started] = total
        return total % MOD

    return dfs(0, 0, True, False) % MOD

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    l, r, b_str = data[0], data[1], data[2]
    b = int(b_str)
    r_digits = decimal_to_base(r, b)
    cnt_r = count_up_to(r_digits, b)
    cnt_l_minus = 0
    if l != "0":
        l_minus = decrement_string(l)
        l_digits = decimal_to_base(l_minus, b)
        cnt_l_minus = count_up_to(l_digits, b)
    ans = (cnt_r - cnt_l_minus) % MOD
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    solve()

from typing import List

def count_cells(grid: List[List[str]], pattern: str) -> int:
    m = len(grid)
    n = len(grid[0]) if m else 0
    M = m * n
    L = len(pattern)

    # Build row-major string
    row_str = ''.join(''.join(row) for row in grid)

    # Build column-major string
    col_chars = []
    for j in range(n):
        for i in range(m):
            col_chars.append(grid[i][j])
    col_str = ''.join(col_chars)

    def kmp_occurrences(text: str, pat: str) -> List[int]:
        n_t = len(text)
        n_p = len(pat)
        if n_p == 0:
            return list(range(n_t + 1))
        # LPS array
        lps = [0] * n_p
        length = 0
        i = 1
        while i < n_p:
            if pat[i] == pat[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        # Search
        res = []
        i = j = 0
        while i < n_t:
            if text[i] == pat[j]:
                i += 1
                j += 1
                if j == n_p:
                    res.append(i - j)
                    j = lps[j - 1]
            else:
                if j != 0:
                    j = lps[j - 1]
                else:
                    i += 1
        return res

    # Find occurrences
    row_occ = kmp_occurrences(row_str, pattern)
    col_occ = kmp_occurrences(col_str, pattern)

    # Difference arrays for coverage
    diff_hor = [0] * (M + 1)
    for p in row_occ:
        if p + L <= M:
            diff_hor[p] += 1
            diff_hor[p + L] -= 1

    diff_ver = [0] * (M + 1)
    for q in col_occ:
        if q + L <= M:
            diff_ver[q] += 1
            diff_ver[q + L] -= 1

    # Prefix sums to get boolean coverage
    hor_cov = [False] * M
    cur = 0
    for i in range(M):
        cur += diff_hor[i]
        hor_cov[i] = cur > 0

    ver_cov = [False] * M
    cur = 0
    for i in range(M):
        cur += diff_ver[i]
        ver_cov[i] = cur > 0

    # Count cells covered by both
    count = 0
    for i in range(m):
        base_row = i * n
        for j in range(n):
            idx_row = base_row + j
            idx_col = j * m + i
            if hor_cov[idx_row] and ver_cov[idx_col]:
                count += 1

    return count

