def find_x_value(nums: List[int], k: int) -> List[int]:
    if k <= 0:
        raise ValueError("k must be a positive integer")
    result = [0] * k
    dp = [0] * k
    for v in nums:
        new_dp = [0] * k
        rem = v % k
        new_dp[rem] += 1
        for r, cnt in enumerate(dp):
            if cnt:
                new_dp[(r * v) % k] += cnt
        for r, cnt in enumerate(new_dp):
            if cnt:
                result[r] += cnt
        dp = new_dp
    return result

