def path_existence_queries(
    n: int,
    nums: List[int],
    max_diff: int,
    queries: List[Tuple[int, int]],
) -> List[bool]:
    if n == 0:
        return [False] * len(queries)

    comp_id = [0] * n
    comp = 0
    for i in range(1, n):
        if nums[i] - nums[i - 1] > max_diff:
            comp += 1
        comp_id[i] = comp

    return [comp_id[u] == comp_id[v] for u, v in queries]

