from typing import List

def smallest_divisible_permutation(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    full_mask = (1 << n) - 1

    lengths = [0] * n
    pow10mod = [0] * n
    nums_mod = [0] * n
    for i, x in enumerate(nums):
        if x == 0:
            l = 1
        else:
            l = len(str(x))
        lengths[i] = l
        pow10mod[i] = pow(10, l, k)
        nums_mod[i] = x % k

    memo = [[-1] * k for _ in range(1 << n)]

    def can(mask: int, rem: int) -> int:
        if mask == full_mask:
            return 1 if rem == 0 else 0
        if memo[mask][rem] != -1:
            return memo[mask][rem]
        for i in range(n):
            if mask & (1 << i):
                continue
            new_rem = (rem * pow10mod[i] + nums_mod[i]) % k
            if can(mask | (1 << i), new_rem):
                memo[mask][rem] = 1
                return 1
        memo[mask][rem] = 0
        return 0

    if not can(0, 0):
        return []

    order = sorted(range(n), key=lambda idx: nums[idx])

    answer: List[int] = []
    mask = 0
    rem = 0
    for _ in range(n):
        for idx in order:
            if mask & (1 << idx):
                continue
            new_rem = (rem * pow10mod[idx] + nums_mod[idx]) % k
            if can(mask | (1 << idx), new_rem):
                answer.append(nums[idx])
                mask |= (1 << idx)
                rem = new_rem
                break

    return answer

