def max_profit(n: int, edges: List[Tuple[int, int]], score: List[int]) -> int:
    pre_mask = [0] * n
    for u, v in edges:
        pre_mask[v] |= 1 << u

    total_mask = (1 << n) - 1
    NEG_INF = -10**30
    dp = [NEG_INF] * (1 << n)
    dp[0] = 0

    popcnt = [0] * (1 << n)
    for mask in range(1, 1 << n):
        popcnt[mask] = popcnt[mask >> 1] + (mask & 1)

    for mask in range(total_mask + 1):
        cur = dp[mask]
        if cur == NEG_INF:
            continue
        pos = popcnt[mask] + 1
        for v in range(n):
            if mask & (1 << v):
                continue
            if pre_mask[v] & ~mask:
                continue
            next_mask = mask | (1 << v)
            profit = cur + score[v] * pos
            if profit > dp[next_mask]:
                dp[next_mask] = profit

    return dp[total_mask]

