def count_covered_buildings(n: int, buildings: List[List[int]]) -> int:
    row_min = {}
    row_max = {}
    col_min = {}
    col_max = {}
    for x, y in buildings:
        if y in row_min:
            if x < row_min[y]:
                row_min[y] = x
            elif x > row_max[y]:
                row_max[y] = x
        else:
            row_min[y] = row_max[y] = x
        if x in col_min:
            if y < col_min[x]:
                col_min[x] = y
            elif y > col_max[x]:
                col_max[x] = y
        else:
            col_min[x] = col_max[x] = y
    covered = 0
    for x, y in buildings:
        if row_min[y] < x < row_max[y] and col_min[x] < y < col_max[x]:
            covered += 1
    return covered

class Solution:
    def minTravelTime(self, l: int, n: int, k: int, position: list[int], time: list[int]) -> int:
        INF = float('inf')
        prefix = [0] * n
        for i in range(n - 1):
            prefix[i + 1] = prefix[i] + time[i]
        # dp[p+1][c][m]: min priced cost so far, last two chosen survivors were p (or -1
        # sentinel, shifted to index 0) and c, having used m merges among indices [0..c].
        dp = [[[INF] * (k + 1) for _ in range(n)] for __ in range(n + 1)]
        dp[0][0][0] = 0
        for c in range(0, n - 1):
            for pidx in range(0, n + 1):
                for m in range(0, k + 1):
                    cost0 = dp[pidx][c][m]
                    if cost0 == INF:
                        continue
                    p = pidx - 1
                    rate = prefix[c + 1] - prefix[p + 1]
                    for i2 in range(c + 1, n):
                        merges_add = i2 - c - 1
                        m2 = m + merges_add
                        if m2 > k:
                            continue
                        newcost = cost0 + rate * (position[i2] - position[c])
                        if newcost < dp[c + 1][i2][m2]:
                            dp[c + 1][i2][m2] = newcost
        return min(dp[pidx][n - 1][k] for pidx in range(0, n + 1))

import math
from typing import List, Tuple

def shortest_path_lengths(n: int, nums: List[int], max_diff: int, queries: List[Tuple[int, int]]) -> List[int]:
    if n == 0:
        return [-1] * len(queries)
    idx = list(range(n))
    idx.sort(key=lambda a: (nums[a], a))
    sorted_vals = [nums[i] for i in idx]
    pos = [0] * n
    for i, original in enumerate(idx):
        pos[original] = i
    far = [0] * n
    r = 0
    for i in range(n):
        if r < i:
            r = i
        while r + 1 < n and sorted_vals[r + 1] - sorted_vals[i] <= max_diff:
            r += 1
        far[i] = r
    LOG = int(math.ceil(math.log2(n))) + 1
    up = [far[:]]
    for _ in range(1, LOG):
        prev = up[-1]
        cur = [prev[prev[i]] for i in range(n)]
        up.append(cur)
    answers = [0] * len(queries)
    for qi, (u, v) in enumerate(queries):
        if u == v:
            answers[qi] = 0
            continue
        pu, pv = pos[u], pos[v]
        if pu > pv:
            pu, pv = pv, pu
        cur = pu
        steps = 0
        for k in range(LOG - 1, -1, -1):
            nxt = up[k][cur]
            if nxt < pv:
                cur = nxt
                steps += 1 << k
        answers[qi] = steps + 1 if far[cur] >= pv else -1
    return answers

def max_product_two_digits(n: int) -> int:
    s = str(abs(n))
    max1 = -1
    max2 = -1
    for ch in s:
        d = ord(ch) - ord('0')
        if d > max1:
            max2 = max1
            max1 = d
        elif d > max2:
            max2 = d
    return 0 if max2 == -1 else max1 * max2

