def most_frequent_vowel_consonant(s: str) -> int:
    vowel_idx = {0, 4, 8, 14, 20}
    freq = [0] * 26
    for ch in s.lower():
        o = ord(ch)
        if 97 <= o <= 122:
            freq[o - 97] += 1
    max_vowel = max((freq[i] for i in vowel_idx), default=0)
    max_consonant = max((freq[i] for i in range(26) if i not in vowel_idx), default=0)
    return max_vowel + max_consonant

