def maximum_weighted_k_edge_path(n: int, edges: List[List[int]], k: int, t: int) -> int:
    NEG_INF = -10**18

    # dp[i][v] = max weight to reach v using exactly i edges, weight must stay < t
    prev = [NEG_INF] * n
    prev[0] = 0  # start at node 0 with weight 0

    if k == 0:
        return 0 if 0 < t else -1

    for _ in range(1, k + 1):
        cur = [NEG_INF] * n
        for u, v, w in edges:
            if prev[u] != NEG_INF:
                cand = prev[u] + w
                if cand < t and cand > cur[v]:
                    cur[v] = cand
        prev = cur

    ans = max(prev)
    return ans if ans != NEG_INF else -1

