def equal_sum_grid_partition(grid: List[List[int]]) -> bool:
    if not grid or not grid[0]:
        return False
    m, n = len(grid), len(grid[0])
    col_sums = [0] * n
    total = 0
    for row in grid:
        row_sum = sum(row)
        total += row_sum
        for j, v in enumerate(row):
            col_sums[j] += v
    if total & 1:
        return False
    half = total // 2
    prefix = 0
    for i in range(m - 1):
        prefix += sum(grid[i])
        if prefix == half:
            return True
    prefix = 0
    for j in range(n - 1):
        prefix += col_sums[j]
        if prefix == half:
            return True
    return False

