def max_score(n: int, edges: List[List[int]]) -> int:
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    m = len(edges)
    is_cycle = (m == n)

    order = []
    visited = [False] * n
    if is_cycle:
        start = 0
        prev = -1
        cur = start
        while True:
            order.append(cur)
            visited[cur] = True
            nxt = None
            for nb in adj[cur]:
                if nb != prev and not visited[nb]:
                    nxt = nb
                    break
            prev, cur = cur, nxt
            if cur is None or cur == start:
                break
    else:
        start = 0
        for i in range(n):
            if len(adj[i]) <= 1:
                start = i
                break
        prev = -1
        cur = start
        while cur is not None:
            order.append(cur)
            visited[cur] = True
            nxt = None
            for nb in adj[cur]:
                if nb != prev and not visited[nb]:
                    nxt = nb
                    break
            prev, cur = cur, nxt

    k = len(order)
    vals = list(range(k, 0, -1))  # descending k, k-1, ..., 1
    arrangement = dq()
    arrangement.append(vals[0])
    for i in range(1, k):
        if i % 2 == 1:
            arrangement.append(vals[i])
        else:
            arrangement.appendleft(vals[i])
    arrangement = list(arrangement)

    value = [0] * n
    for idx, node in enumerate(order):
        value[node] = arrangement[idx]

    total = 0
    for i in range(k - 1):
        total += value[order[i]] * value[order[i + 1]]
    if is_cycle:
        total += value[order[-1]] * value[order[0]]
    return total

