from typing import List

def min_moves(matrix: List[str]) -> int:
    if not matrix:
        return -1
    m, n = len(matrix), len(matrix[0])
    if matrix[0][0] == '#' or matrix[m - 1][n - 1] == '#':
        return -1
    if m == 1 and n == 1:
        return 0

    portals = {}
    for i, row in enumerate(matrix):
        for j, ch in enumerate(row):
            if 'A' <= ch <= 'Z':
                portals.setdefault(ch, []).append((i, j))

    visited = [bytearray(n) for _ in range(m)]
    dq = deque()
    dq.append((0, 0, 0))
    visited[0][0] = 1
    used_portal = set()

    while dq:
        r, c, d = dq.popleft()
        if r == m - 1 and c == n - 1:
            return d

        ch = matrix[r][c]
        if 'A' <= ch <= 'Z' and ch not in used_portal:
            for nr, nc in portals[ch]:
                if not visited[nr][nc]:
                    visited[nr][nc] = 1
                    dq.appendleft((nr, nc, d))
            used_portal.add(ch)

        nd = d + 1
        if r > 0 and not visited[r - 1][c] and matrix[r - 1][c] != '#':
            visited[r - 1][c] = 1
            dq.append((r - 1, c, nd))
        if r + 1 < m and not visited[r + 1][c] and matrix[r + 1][c] != '#':
            visited[r + 1][c] = 1
            dq.append((r + 1, c, nd))
        if c > 0 and not visited[r][c - 1] and matrix[r][c - 1] != '#':
            visited[r][c - 1] = 1
            dq.append((r, c - 1, nd))
        if c + 1 < n and not visited[r][c + 1] and matrix[r][c + 1] != '#':
            visited[r][c + 1] = 1
            dq.append((r, c + 1, nd))

    return -1

def smallest_string_after_adjacent_removals(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    def is_consecutive(a: str, b: str) -> bool:
        diff = abs(ord(a) - ord(b))
        return diff == 1 or diff == 25
    can = [[False] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            for k in range(i + 1, j + 1):
                if (
                    is_consecutive(s[i], s[k])
                    and (i + 1 > k - 1 or can[i + 1][k - 1])
                    and (k + 1 > j or can[k + 1][j])
                ):
                    can[i][j] = True
                    break
    best = [[""] * n for _ in range(n)]
    for i in range(n):
        best[i][i] = s[i]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if can[i][j]:
                best[i][j] = ""
                continue
            cur = s[i:j + 1]
            for m in range(i, j):
                cand = best[i][m] + best[m + 1][j]
                if cand < cur:
                    cur = cand
            best[i][j] = cur
    return best[0][n - 1]

