from functools import lru_cache

def can_partition(nums: List[int], target: int) -> bool:
    n = len(nums)
    if n < 2:
        return False

    # total product must equal target squared
    total = 1
    for v in nums:
        total *= v
    if total != target * target:
        return False

    # handle zero target specially
    if target == 0:
        zero_cnt = nums.count(0)
        # need at least one zero in each subset
        return zero_cnt >= 2

    # any zero in nums makes total product zero, which cannot equal target^2 (target != 0)
    if 0 in nums:
        return False

    # quick reject: any element larger than target cannot be part of a subset product equal to target
    for v in nums:
        if v > target:
            return False

    # sort to improve pruning
    nums.sort(reverse=True)

    @lru_cache(None)
    def dfs(i: int, prod: int, cnt: int) -> bool:
        # reached target product
        if prod == target:
            # subset must be non‑empty and not all elements
            return 0 < cnt < n
        if i == n or prod > target:
            return False
        # try include nums[i]
        if dfs(i + 1, prod * nums[i], cnt + 1):
            return True
        # try exclude nums[i]
        if dfs(i + 1, prod, cnt):
            return True
        return False

    return dfs(0, 1, 0)

