from typing import List

def minimum_moves(classroom: List[str], energy: int) -> int:
    m = len(classroom)
    n = len(classroom[0])
    litter_positions = []
    start = None
    for i in range(m):
        for j in range(n):
            ch = classroom[i][j]
            if ch == 'S':
                start = (i, j)
            elif ch == 'L':
                litter_positions.append((i, j))
    if start is None:
        return -1
    L = len(litter_positions)
    idx_map = {pos: i for i, pos in enumerate(litter_positions)}
    full_mask = (1 << L) - 1
    if full_mask == 0:
        return 0

    sr, sc = start
    q = deque()
    q.append((sr, sc, energy, 0, 0))  # row, col, remaining energy, collected mask, steps
    best = {}
    best[(sr, sc, 0)] = energy
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        r, c, e, mask, steps = q.popleft()
        if mask == full_mask:
            return steps
        if e == 0 and classroom[r][c] != 'R':
            continue
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < m and 0 <= nc < n):
                continue
            cell = classroom[nr][nc]
            if cell == 'X':
                continue
            ne = e - 1
            if ne < 0:
                continue
            nmask = mask
            if cell == 'L':
                nmask = mask | (1 << idx_map[(nr, nc)])
            if cell == 'R':
                ne = energy
            key = (nr, nc, nmask)
            if best.get(key, -1) >= ne:
                continue
            best[key] = ne
            q.append((nr, nc, ne, nmask, steps + 1))
    return -1

