def maximum_good_subtree_score(vals: List[int], par: List[int]) -> int:
    n = len(vals)
    MOD = 1_000_000_007

    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[par[i]].append(i)

    node_mask = [0] * n
    for i, v in enumerate(vals):
        mask = 0
        ok = True
        while v:
            d = v % 10
            if mask >> d & 1:
                ok = False
                break
            mask |= 1 << d
            v //= 10
        node_mask[i] = mask if ok else -1

    max_score = [0] * n
    NEG = -10**18

    def dfs(u: int):
        dp = [(0, 0)]  # list of (mask, value)
        for v in children[u]:
            child_dp = dfs(v)
            # merge dp with child_dp, allowing to skip child
            merged = {}
            for m1, val1 in dp:
                # keep current state (skip child)
                if val1 > merged.get(m1, NEG):
                    merged[m1] = val1
                for m2, val2 in child_dp:
                    if m1 & m2:
                        continue
                    nm = m1 | m2
                    nv = val1 + val2
                    if nv > merged.get(nm, NEG):
                        merged[nm] = nv
            dp = list(merged.items())

        mask = node_mask[u]
        if mask != -1:
            merged = {}
            for m, val in dp:
                # keep without current node
                if val > merged.get(m, NEG):
                    merged[m] = val
                if m & mask:
                    continue
                nm = m | mask
                nv = val + vals[u]
                if nv > merged.get(nm, NEG):
                    merged[nm] = nv
            dp = list(merged.items())

        best = 0
        for _, val in dp:
            if val > best:
                best = val
        max_score[u] = best
        return dp

    dfs(0)

    total = 0
    for sc in max_score:
        total = (total + sc) % MOD
    return total

def _sieve(n):
    is_p = [True] * (n + 1)
    is_p[0] = is_p[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_p[i]:
            for j in range(i * i, n + 1, i):
                is_p[j] = False
    return is_p

_MAXV = 100000
_IS_PRIME = _sieve(_MAXV)

def maximizeDistinctPrimeCount(nums, queries):
    nums = nums[:]
    n = len(nums)
    ans = []
    for idx, val in queries:
        nums[idx] = val
        # first/last occurrence of each distinct prime value currently in nums
        positions = {}
        total_distinct = 0
        for i, v in enumerate(nums):
            if v <= _MAXV and _IS_PRIME[v]:
                if v not in positions:
                    positions[v] = [i, i]
                    total_distinct += 1
                else:
                    positions[v][1] = i
        # a prime spanning [first,last] contributes +1 EXTRA distinct-prime credit for any
        # split point p in (first, last] (so first lands in the left part, last in the right)
        diff = [0] * (n + 1)
        for v, (first, last) in positions.items():
            if last > first:
                l, r = first + 1, last
                diff[l] += 1
                diff[r + 1] -= 1
        best_overlap = 0
        cur = 0
        for p in range(1, n):
            cur += diff[p]
            best_overlap = max(best_overlap, cur)
        ans.append(total_distinct + best_overlap)
    return ans

