MOD = 10**9 + 7

def count_partitions(nums: list[int], k: int) -> int:
    n = len(nums)
    if n == 0:
        return 1
    pref = [0] * (n + 1)
    pref[0] = 1
    maxdq = deque()
    mindq = deque()
    left = 0
    dp = 0
    for i, val in enumerate(nums, 1):
        while maxdq and nums[maxdq[-1]] <= val:
            maxdq.pop()
        maxdq.append(i - 1)
        while mindq and nums[mindq[-1]] >= val:
            mindq.pop()
        mindq.append(i - 1)
        while nums[maxdq[0]] - nums[mindq[0]] > k:
            if maxdq[0] == left:
                maxdq.popleft()
            if mindq[0] == left:
                mindq.popleft()
            left += 1
        if left == 0:
            dp = pref[i - 1]
        else:
            dp = pref[i - 1] - pref[left - 1]
        dp %= MOD
        pref[i] = (pref[i - 1] + dp) % MOD
    return dp % MOD

