def min_swaps(nums: List[int]) -> int:
    n = len(nums)
    even_pos = [i for i, v in enumerate(nums) if v % 2 == 0]
    even_cnt = len(even_pos)
    odd_cnt = n - even_cnt
    if abs(even_cnt - odd_cnt) > 1:
        return -1
    ans = float('inf')
    if even_cnt >= odd_cnt:
        ans = min(ans, sum(abs(even_pos[i] - 2 * i) for i in range(even_cnt)))
