def max_triangle_area(points: List[List[int]]) -> int:
    if not points:
        return -1

    x_min_y = {}
    x_max_y = {}
    y_min_x = {}
    y_max_x = {}

    min_x = max_x = points[0][0]
    min_y = max_y = points[0][1]

    for x, y in points:
        if x < min_x:
            min_x = x
        elif x > max_x:
            max_x = x
        if y < min_y:
            min_y = y
        elif y > max_y:
            max_y = y

        if x in x_min_y:
            if y < x_min_y[x]:
                x_min_y[x] = y
            if y > x_max_y[x]:
                x_max_y[x] = y
        else:
            x_min_y[x] = x_max_y[x] = y

        if y in y_min_x:
            if x < y_min_x[y]:
                y_min_x[y] = x
            if x > y_max_x[y]:
                y_max_x[y] = x
        else:
            y_min_x[y] = y_max_x[y] = x

    best = 0

    for x, miny in x_min_y.items():
        maxy = x_max_y[x]
        if maxy > miny:
            base = maxy - miny
            height = max(abs(x - min_x), abs(x - max_x))
            area2 = base * height
            if area2 > best:
                best = area2

    for y, minx in y_min_x.items():
        maxx = y_max_x[y]
        if maxx > minx:
            base = maxx - minx
            height = max(abs(y - min_y), abs(y - max_y))
            area2 = base * height
            if area2 > best:
                best = area2

    return best if best > 0 else -1

