import sys, bisect

def kth_smallest_path_xor(par: List[int], vals: List[int], queries: List[List[int]]) -> List[int]:
    sys.setrecursionlimit(300000)
    n = len(vals)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[par[i]].append(i)

    pref = [0] * n
    stack = [(0, 0)]
    while stack:
        u, acc = stack.pop()
        pref[u] = acc ^ vals[u]
        for v in children[u]:
            stack.append((v, pref[u]))

    q_by_node = [[] for _ in range(n)]
    for idx, (u, k) in enumerate(queries):
        q_by_node[u].append((k, idx))

    ans = [-1] * len(queries)

    def dfs(u: int):
        cur_set = {pref[u]}
        cur_list = [pref[u]]
        for v in children[u]:
            child_set, child_list = dfs(v)
            if len(child_set) > len(cur_set):
                cur_set, child_set = child_set, cur_set
                cur_list, child_list = child_list, cur_list
            for val in child_set:
                if val not in cur_set:
                    cur_set.add(val)
                    bisect.insort(cur_list, val)
        for k, idx in q_by_node[u]:
            if 1 <= k <= len(cur_list):
                ans[idx] = cur_list[k - 1]
            else:
                ans[idx] = -1
        return cur_set, cur_list

    dfs(0)
    return ans

import heapq, math, itertools

class Solution:
    def minTime(self, n: int, k: int, m: int, time: list[int], mul: list[float]) -> float:
        FULL = (1 << n) - 1
        # dist[remaining][dir][stage]; remaining = bitmask of people still at the base camp
        dist = [[[float('inf')]*m for _ in range(2)] for _ in range(1 << n)]
        dist[FULL][0][0] = 0.0
        pq = [(0.0, FULL, 0, 0)]
        while pq:
            cost, remaining, direction, stage = heapq.heappop(pq)
            if cost > dist[remaining][direction][stage] + 1e-9:
                continue
            if direction == 1 and remaining == 0:
                return cost
            if direction == 0:
                people = [i for i in range(n) if remaining & (1 << i)]
                for sz in range(1, min(k, len(people)) + 1):
                    for group in itertools.combinations(people, sz):
                        gtime = max(time[i] for i in group) * mul[stage]
                        new_remaining = remaining
                        for i in group:
                            new_remaining &= ~(1 << i)
                        new_stage = (stage + int(math.floor(gtime))) % m
                        new_cost = cost + gtime
                        if new_cost < dist[new_remaining][1][new_stage] - 1e-9:
                            dist[new_remaining][1][new_stage] = new_cost
                            heapq.heappush(pq, (new_cost, new_remaining, 1, new_stage))
            else:
                arrived = [i for i in range(n) if not (remaining & (1 << i))]
                for i in arrived:
                    rtime = time[i] * mul[stage]
                    new_remaining = remaining | (1 << i)
                    new_stage = (stage + int(math.floor(rtime))) % m
                    new_cost = cost + rtime
                    if new_cost < dist[new_remaining][0][new_stage] - 1e-9:
                        dist[new_remaining][0][new_stage] = new_cost
                        heapq.heappush(pq, (new_cost, new_remaining, 0, new_stage))
        return -1.0

