_MAXV = 100000
_IS_PRIME = _sieve(_MAXV)

def primeSubarray(nums, k):
    n = len(nums)
    marks = [x if (x <= _MAXV and _IS_PRIME[x]) else 0 for x in nums]
    maxdq = deque()  # indices with marks>0, decreasing values
    mindq = deque()  # indices with marks>0, increasing values
    j1 = 0
    cnt = 0
    j2 = 0
    ans = 0
    for i in range(n):
        x = marks[i]
        if x > 0:
            cnt += 1
            while maxdq and marks[maxdq[-1]] <= x:
                maxdq.pop()
            maxdq.append(i)
            while mindq and marks[mindq[-1]] >= x:
                mindq.pop()
            mindq.append(i)
        while maxdq and mindq and marks[maxdq[0]] - marks[mindq[0]] > k:
            if maxdq[0] == j1:
                maxdq.popleft()
            if mindq[0] == j1:
                mindq.popleft()
            j1 += 1
        while cnt > 1:
            if marks[j2] > 0:
                cnt -= 1
            j2 += 1
        ans += j2 - j1
    return ans

