def inverse_coin_change(num_ways: List[int]) -> List[int]:
    n = len(num_ways)
    target = [0] + num_ways
    cur = [0] * (n + 1)
    cur[0] = 1
    denominations: List[int] = []

    for i in range(1, n + 1):
        if cur[i] > target[i]:
            return []
        if cur[i] == target[i]:
            continue
        if target[i] - cur[i] != 1:
            return []
        denominations.append(i)
        for a in range(i, n + 1):
            cur[a] += cur[a - i]

    for i in range(1, n + 1):
        if cur[i] != target[i]:
            return []
    return denominations

