def min_nodes_to_increase(n: int, edges: List[List[int]], cost: List[int]) -> int:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    parent = [-1] * n
    order = []
    stack = [0]
    parent[0] = -1
    while stack:
        node = stack.pop()
        order.append(node)
        for nb in adj[node]:
            if nb == parent[node]:
                continue
            parent[nb] = node
            stack.append(nb)

    max_sum = [0] * n
    touches = [0] * n

    for node in reversed(order):
        max_child_sum = -float('inf')
        total = 0
        has_child = False
        for nb in adj[node]:
            if nb == parent[node]:
                continue
            has_child = True
            if max_sum[nb] > max_child_sum:
                max_child_sum = max_sum[nb]
        if not has_child:
            max_sum[node] = cost[node]
            touches[node] = 0
            continue
        for nb in adj[node]:
            if nb == parent[node]:
                continue
            total += touches[nb]
            if max_sum[nb] < max_child_sum:
                total += 1
        max_sum[node] = cost[node] + max_child_sum
        touches[node] = total

    return touches[0]

