def max_stability(n: int, edges: List[List[int]], k: int) -> int:
    class DSU:
        __slots__ = ("parent", "size", "components")
        def __init__(self, n: int):
            self.parent = list(range(n))
            self.size = [1] * n
            self.components = n
        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, a: int, b: int) -> bool:
            ra, rb = self.find(a), self.find(b)
            if ra == rb:
                return False
            if self.size[ra] < self.size[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            self.size[ra] += self.size[rb]
            self.components -= 1
            return True

    if not edges:
        return -1

    max_s = max(s for _, _, s, _ in edges)
    high = max_s * 2

    def feasible(x: int) -> bool:
        dsu = DSU(n)
        upgrades = 0

        # mandatory edges (must == 1) must be taken as‑is
        for u, v, s, must in edges:
            if must == 1:
                if s < x:
                    return False
                if not dsu.union(u, v):
                    return False  # creates a cycle

        # free optional edges (must == 0, already meet threshold)
        for u, v, s, must in edges:
            if must == 0 and s >= x:
                dsu.union(u, v)

        # upgrade‑eligible optional edges
        for u, v, s, must in edges:
            if must == 0 and s < x and s * 2 >= x:
                if dsu.union(u, v):
                    upgrades += 1
                    if upgrades > k:
                        return False

        return dsu.components == 1 and upgrades <= k

    # if even the weakest possible tree cannot be built, return -1
    if not feasible(0):
        return -1

    low = 0
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    return low

