def min_max_xor(nums: List[int], k: int) -> int:
    n = len(nums)
    pref = [0] * (n + 1)
    for i, v in enumerate(nums):
        pref[i + 1] = pref[i] ^ v

    def can(limit: int) -> bool:
        # dp[i][c] = can partition first i elements into c segments with xor <= limit
        dp = [0] * (n + 1)          # bitmask of reachable segment counts for each position
        dp[0] = 1 << 0              # 0 segments reachable at position 0
        for i in range(1, n + 1):
            mask = 0
            for j in range(i):
                if (pref[i] ^ pref[j]) <= limit:
                    mask |= dp[j] << 1
            dp[i] = mask
        return (dp[n] >> k) & 1 == 1

    lo, hi = 0, (1 << 31) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution:
    def minCost(self, m: int, n: int, waitCost: list[list[int]]) -> int:
        # Every monotonic path has exactly m+n-2 moves (fixed regardless of route), and the
        # alternating move/wait pattern is entirely forced: move1 (start), then a mandatory
        # wait at every intermediate cell before the next move, with no trailing wait after
        # the final move that lands on the destination (the journey stops immediately). So
        # this reduces to a plain monotonic-path DP: total cost = sum of entry costs of every
        # visited cell + sum of waitCost at every intermediate cell (excluding start and end).
        INF = float('inf')
        f = [[0]*n for _ in range(m)]
        f[0][0] = 1
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                entry = (i+1)*(j+1)
                best = INF
                if i > 0:
                    p = f[i-1][j]
                    if not (i-1 == 0 and j == 0):
                        p += waitCost[i-1][j]
                    best = min(best, p)
                if j > 0:
                    p = f[i][j-1]
                    if not (i == 0 and j-1 == 0):
                        p += waitCost[i][j-1]
                    best = min(best, p)
                f[i][j] = entry + best
        return f[m-1][n-1]

