def minimum_time(n: int, edges: List[List[int]]) -> int:
    if n == 1:
        return 0
    adj = [[] for _ in range(n)]
    for u, v, start, end in edges:
        adj[u].append((v, start, end))
    INF = 10**18
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]
    target = n - 1
    while heap:
        cur_time, u = heapq.heappop(heap)
        if cur_time != dist[u]:
            continue
        if u == target:
            return cur_time
        for v, start, end in adj[u]:
            if cur_time > end:
                continue
            depart = start if cur_time < start else cur_time
            next_time = depart + 1
            if next_time < dist[v]:
                dist[v] = next_time
                heapq.heappush(heap, (next_time, v))
    return -1

