from typing import List

def min_stability_factor(nums: List[int], max_c: int) -> int:
    n = len(nums)
    if n == 0:
        return 0

    K = n.bit_length()
    st = [nums[:]]
    for k in range(1, K):
        step = 1 << (k - 1)
        limit = n - (1 << k) + 1
        row = [0] * n
        prev = st[-1]
        for i in range(limit):
            row[i] = math.gcd(prev[i], prev[i + step])
        st.append(row)

    def range_gcd(l: int, r: int) -> int:
        length = r - l + 1
        k = length.bit_length() - 1
        return math.gcd(st[k][l], st[k][r - (1 << k) + 1])

    def feasible(L: int) -> bool:
        w = L + 1
        if w > n:
            return True
        cnt = 0
        last = -1
        end = n - w
        for i in range(end + 1):
            if range_gcd(i, i + w - 1) >= 2:
                if last < i:
                    cnt += 1
                    if cnt > max_c:
                        return False
                    last = i + w - 1
        return cnt <= max_c

    low, high = 0, n
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1
    return low

