import bisect

def power_grid_maintenance(c: int, connections: List[Tuple[int, int]], queries: List[Tuple[int, int]]) -> List[int]:
    parent = list(range(c + 1))
    rank = [0] * (c + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    for u, v in connections:
        union(u, v)

    comp_nodes: dict[int, List[int]] = {}
    for i in range(1, c + 1):
        r = find(i)
        comp_nodes.setdefault(r, []).append(i)

    for arr in comp_nodes.values():
        arr.sort()

    online = [1] * (c + 1)
    ans: List[int] = []

    for typ, x in queries:
        if typ == 2:
            online[x] = 0
        else:
            r = find(x)
            arr = comp_nodes[r]
            idx = bisect.bisect_left(arr, x)
            while idx < len(arr) and online[arr[idx]] == 0:
                idx += 1
            ans.append(-1 if idx == len(arr) else arr[idx])

    return ans

def process_string(s: str) -> str:
    out = []
    deleted = []
    for ch in s:
        if 'a' <= ch <= 'z':
            out.append(ch)
        elif ch == '#':
            if out:
                deleted.append(out.pop())
        elif ch == '%':
            if deleted:
                out.append(deleted.pop())
        elif ch == '*':
            deleted.clear()
    return ''.join(out)

def get_kth_char(s: str, k: int) -> str:
    n = len(s)
    length = [0] * (n + 1)
    for i in range(1, n + 1):
        ch = s[i - 1]
        prev = length[i - 1]
        if 'a' <= ch <= 'z':
            length[i] = prev + 1
        elif ch == '*':
            length[i] = prev - 1 if prev > 0 else 0
        elif ch == '#':
            length[i] = prev * 2
        else:  # ch == '%'
            length[i] = prev
    if k >= length[n]:
        return '.'
    for i in range(n, 0, -1):
        ch = s[i - 1]
        prev = length[i - 1]
        if 'a' <= ch <= 'z':
            if k == prev:
                return ch
        elif ch == '#':
            if k >= prev:
                k -= prev
        elif ch == '%':
            k = prev - 1 - k
    return '.'

