def solve(n: int, edges: List[List[int]], k: int) -> int:
    if k >= n:
        return 0

    # sort edges by weight
    edges_sorted = sorted(edges, key=lambda e: e[2])

    parent = list(range(n))
    rank = [0] * n
    components = n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        nonlocal components
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        components -= 1
        return True

    last_weight = 0
    for u, v, w in edges_sorted:
        if components <= k:
            break
        if union(u, v):
            last_weight = w

    return last_weight

