def longest_palindromic_path(n: int, edges: List[List[int]], label: str) -> int:
    adj: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    max_mask = 1 << n
    pairs_by_mask: List[Set[Tuple[int, int]]] = [set() for _ in range(max_mask)]

    # single‑node palindromes
    for i in range(n):
        pairs_by_mask[1 << i].add((i, i))

    # two‑node palindromes (matching labels)
    for u, v in edges:
        if label[u] == label[v]:
            m = (1 << u) | (1 << v)
            pairs_by_mask[m].add((u, v))
            pairs_by_mask[m].add((v, u))

    ans = 1
    for mask in range(max_mask):
        for i, j in pairs_by_mask[mask]:
            bits = mask.bit_count()
            if bits > ans:
                ans = bits
            for u in adj[i]:
                if mask >> u & 1:
                    continue
                for v in adj[j]:
                    if mask >> v & 1:
                        continue
                    if u == v:          # avoid revisiting the same node on both ends
                        continue
                    if label[u] != label[v]:
                        continue
                    new_mask = mask | (1 << u) | (1 << v)
                    pairs_by_mask[new_mask].add((u, v))
    return ans

