def count_islands(grid: List[List[int]], k: int) -> int:
    if k == 0:
        return 0
    rows = len(grid)
    if rows == 0:
        return 0
    cols = len(grid[0])
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[False] * cols for _ in range(rows)]
    island_count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] > 0 and not visited[r][c]:
                total = 0
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True
                    total += grid[cr][cc]
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] > 0 and not visited[nr][nc]:
                            stack.append((nr, nc))
                if total % k == 0:
                    island_count += 1
    return island_count

