INF = 10**19

def max_path_score(edges: List[List[int]], online: List[bool], k: int) -> int:
    n = len(online)
    if not online[0] or not online[n - 1]:
        return -1

    adj: List[List[tuple[int, int]]] = [[] for _ in range(n)]
    max_cost = 0
    for u, v, c in edges:
        adj[u].append((v, c))
        if c > max_cost:
            max_cost = c

    def feasible(b: int) -> bool:
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            if d > k:
                continue
            if u == n - 1:
                return True
            for v, c in adj[u]:
                if c < b or not online[v]:
                    continue
                nd = d + c
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        return dist[n - 1] <= k

    low, high = 0, max_cost
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    return low if feasible(low) else -1

from math import comb

def number_of_integers_with_popcount_depth_equal_to_k(n: int, k: int) -> int:
    if n < 1:
        return 0
    if k == 0:
        return 1  # only the number 1

    max_bits = n.bit_length()
    max_c = max_bits  # popcount cannot exceed number of bits

    # depth[c] = popcount-depth of integer c (c >= 1)
    depth = [0] * (max_c + 1)
    depth[1] = 0
    for c in range(2, max_c + 1):
        cur = c
        d = 0
        while cur != 1:
            cur = cur.bit_count()
            d += 1
        depth[c] = d

    target_depth = k - 1
    candidates = [c for c in range(1, max_c + 1) if depth[c] == target_depth]

    def count_leq(pop: int) -> int:
        """count numbers x (1 <= x <= n) with popcount(x) == pop"""
        if pop < 0:
            return 0
        bits = max_bits
        ans = 0
        ones = 0
        for i in range(bits - 1, -1, -1):
            if (n >> i) & 1:
                need = pop - ones
                if 0 <= need <= i:
                    ans += comb(i, need)
                ones += 1
                if ones > pop:
                    break
        else:
            if ones == pop:
                ans += 1
        return ans

    total = 0
    for c in candidates:
        total += count_leq(c)

    # exclude x = 1 which has depth 0, not k (only happens when c == 1)
    if 1 in candidates:
        total -= 1

    return total

