def split_array_by_prime_indices(nums: List[int]) -> int:
    n = len(nums)
    if n < 3:
        return abs(-sum(nums))
    prime = [True] * n
    prime[0] = prime[1] = False
    i = 2
    while i * i < n:
        if prime[i]:
            j = i * i
            step = i
            while j < n:
                prime[j] = False
                j += step
        i += 1
    sum_prime = 0
    for idx, val in enumerate(nums):
        if prime[idx]:
            sum_prime += val
    total = sum(nums)
    return abs(sum_prime - (total - sum_prime))

