def min_jumps_prime_teleport(nums: List[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0

    max_val = max(nums)
    # smallest prime factor sieve
    spf = [0] * (max_val + 1)
    for i in range(2, max_val + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= max_val:
                for j in range(i * i, max_val + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

    # prime_to_indices[p] = list of indices where p divides nums[idx]
    prime_to_indices = {}
    # store distinct prime factors for each index (used only for prime numbers)
    factors: List[List[int]] = []
    for idx, val in enumerate(nums):
        x = val
        facs = []
        while x > 1:
            p = spf[x] if spf[x] != 0 else x
            facs.append(p)
            while x % p == 0:
                x //= p
        # keep unique primes
        facs = list(dict.fromkeys(facs))
        factors.append(facs)
        for p in facs:
            prime_to_indices.setdefault(p, []).append(idx)

    # helper to check primality using spf
    def is_prime(v: int) -> bool:
        return v > 1 and spf[v] == v

    dist = [-1] * n
    q = deque([0])
    dist[0] = 0

    while q:
        cur = q.popleft()
        cur_dist = dist[cur]
        if cur == n - 1:
            return cur_dist

        # adjacent moves
        for nxt in (cur - 1, cur + 1):
            if 0 <= nxt < n and dist[nxt] == -1:
                dist[nxt] = cur_dist + 1
                q.append(nxt)

        # teleport only if current value is prime
        if is_prime(nums[cur]):
            p = nums[cur]  # the prime itself
            lst = prime_to_indices.get(p, [])
            for nxt in lst:
                if dist[nxt] == -1:
                    dist[nxt] = cur_dist + 1
                    q.append(nxt)
            # clear to avoid future redundant processing
            prime_to_indices[p] = []

    return -1

