def min_removals_to_balance_array(nums: List[int], k: int) -> int:
    nums.sort()
    n = len(nums)
    left = 0
    best = 0
    for right in range(n):
        while nums[right] > k * nums[left]:
            left += 1
        window_size = right - left + 1
        if window_size > best:
            best = window_size
    return n - best

