def threshold_majority_queries(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    uniq = sorted(set(nums))
    comp = {v: i for i, v in enumerate(uniq)}
    comp_nums = [comp[v] for v in nums]
    m = len(uniq)

    block = int(n ** 0.5) or 1
    qinfo = [(l, r, thr, idx) for idx, (l, r, thr) in enumerate(queries)]

    def mo_key(item):
        l, r, _, _ = item
        block_id = l // block
        return (block_id, r if block_id % 2 == 0 else -r)

    qinfo.sort(key=mo_key)

    freq = [0] * m
    freq_vals = [set() for _ in range(n + 1)]
    max_freq = 0

    def add(pos: int):
        nonlocal max_freq
        idx = comp_nums[pos]
        old = freq[idx]
        new = old + 1
        freq[idx] = new
        if old:
            freq_vals[old].remove(idx)
        freq_vals[new].add(idx)
        if new > max_freq:
            max_freq = new

    def remove(pos: int):
        nonlocal max_freq
        idx = comp_nums[pos]
        old = freq[idx]
        new = old - 1
        freq[idx] = new
        freq_vals[old].remove(idx)
        if new:
            freq_vals[new].add(idx)
        if not freq_vals[max_freq]:
            while max_freq > 0 and not freq_vals[max_freq]:
                max_freq -= 1

    ans = [-1] * len(queries)
    cur_l, cur_r = 0, -1
    for l, r, thr, qi in qinfo:
        while cur_l > l:
            cur_l -= 1
            add(cur_l)
        while cur_r < r:
            cur_r += 1
            add(cur_r)
        while cur_l < l:
            remove(cur_l)
            cur_l += 1
        while cur_r > r:
            remove(cur_r)
            cur_r -= 1

        if max_freq >= thr:
            ans[qi] = uniq[min(freq_vals[max_freq])]
        else:
            ans[qi] = -1

    return ans

