def minimum_time_to_activate_string(s: str, order: List[int], k: int) -> int:
    n = len(s)
    total_substrings = n * (n + 1) // 2
    if k <= 0:
        return 0
    if k > total_substrings:
        return -1

    times = [n] * n
    for t, idx in enumerate(order):
        times[idx] = t

    def good_substrings(t: int) -> int:
        bad = 0
        cur = 0
        for i in range(n):
            if times[i] > t:
                cur += 1
            else:
                if cur:
                    bad += cur * (cur + 1) // 2
                    cur = 0
        if cur:
            bad += cur * (cur + 1) // 2
        return total_substrings - bad

    lo, hi = 0, n - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if good_substrings(mid) >= k:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

