def min_cost_reversal(n: int, edges: List[List[int]]) -> int:
    adj: List[List[tuple]] = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, 2 * w))

    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1 if dist[n - 1] == INF else dist[n - 1]

class Solution:
    def xorAfterQueries(self, nums: list[int], queries: list[list[int]]) -> int:
        MOD = 1_000_000_007
        nums = nums[:]
        for l, r, k, v in queries:
            idx = l
            while idx <= r:
                nums[idx] = nums[idx] * v % MOD
                idx += k
        x = 0
        for n in nums:
            x ^= n
        return x

