def minimum_sum_after_deletions(nums: List[int], k: int) -> int:
    total = sum(nums)
    pref = 0
    dp = 0
    best: Dict[int, int] = {0: 0}
    neg_inf = -10**30
    for x in nums:
        pref += x
        r = pref % k
        cand = pref + best.get(r, neg_inf)
        if cand > dp:
            dp = cand
        val = dp - pref
        if r in best:
            if val > best[r]:
                best[r] = val
        else:
            best[r] = val
    return total - dp

