def unique_paths(grid):
    MOD = 10**9 + 7
    n, m = len(grid), len(grid[0])
    memo = {}

    def dp(i, j, direction):
        while 0 <= i < n and 0 <= j < m and grid[i][j] == 1:
            direction = 1 - direction
            if direction == 0:
                i += 1
            else:
                j += 1
        if i < 0 or i >= n or j < 0 or j >= m:
            return 0
        if i == n - 1 and j == m - 1:
            return 1
        if grid[i][j] == 0:
            key = (i, j)
            if key in memo:
                return memo[key]
            res = (dp(i + 1, j, 0) + dp(i, j + 1, 1)) % MOD
            memo[key] = res
            return res
        return 0

    return dp(0, 0, 0) % MOD

def maxScore(cards, x):
