    Q = {}
    Z = 0
    for c in cards:
        if x not in c:
            continue
        a, b = c[0], c[1]
        if a == x and b == x:
            Z += 1
        elif a == x:
            P[b] = P.get(b, 0) + 1
        elif b == x:
            Q[a] = Q.get(a, 0) + 1
    totalP = sum(P.values())
    totalQ = sum(Q.values())
    maxP = max(P.values()) if P else 0
    maxQ = max(Q.values()) if Q else 0
    total = totalP + totalQ + Z
    bottleneck = max(maxP + maxQ, Z)
    return min(total // 2, total - bottleneck)

def find_least_frequent_digit(num: int) -> int:
    n = abs(num)
    freq = [0] * 10
    if n == 0:
        freq[0] = 1
    else:
        while n:
            d = n % 10
            freq[d] += 1
            n //= 10
    min_count = float('inf')
    answer = -1
    for d in range(10):
        cnt = freq[d]
        if cnt and cnt < min_count:
            min_count = cnt
            answer = d
    return answer

