def max_product_no_common_bits(arr: List[int]) -> int:
    n = len(arr)
    if n < 2:
        return 0

    max_val = max(arr)
    bits = max_val.bit_length()
    if bits == 0:
        bits = 1
    size = 1 << bits
    full_mask = size - 1

    best = [-1] * size
    cnt = [0] * size
    for v in arr:
        cnt[v] += 1
        if v > best[v]:
            best[v] = v

    for i in range(bits):
        step = 1 << i
        for mask in range(size):
            if mask & step:
                sub = mask ^ step
                b = best[sub]
                if b > best[mask]:
                    best[mask] = b

    ans = 0
    for v in arr:
        partner = best[full_mask ^ v]
        if partner == -1:
            continue
        if partner == v and cnt[v] < 2:
            continue
        prod = v * partner
        if prod > ans:
            ans = prod

    return ans

def sum_of_beautiful_subsequences_optimal(nums):
    MOD = 10**9 + 7
    n = len(nums)
    max_v = max(nums)

    divisors_cache = {}
    def divisors_of(v):
        if v in divisors_cache:
            return divisors_cache[v]
        res = []
        d = 1
        while d * d <= v:
            if v % d == 0:
                res.append(d)
                if d != v // d:
                    res.append(v // d)
            d += 1
        divisors_cache[v] = res
        return res

    fenwicks = {}
    def get_fenwick(d):
        if d not in fenwicks:
            fenwicks[d] = [0] * (max_v + 2)
        return fenwicks[d]

    def fen_update(tree, i, val):
        while i <= max_v:
            tree[i] = (tree[i] + val) % MOD
            i += i & (-i)

    def fen_query(tree, i):
        s = 0
        while i > 0:
            s = (s + tree[i]) % MOD
            i -= i & (-i)
        return s

    dp_multiple = {}
    for v in nums:
        divs = divisors_of(v)
        dp_for_this = {}
        for d in divs:
            tree = get_fenwick(d)
            sum_less = fen_query(tree, v - 1)
            val = (sum_less + 1) % MOD
            dp_for_this[d] = val
        for d, val in dp_for_this.items():
            tree = get_fenwick(d)
            fen_update(tree, v, val)
            dp_multiple[d] = (dp_multiple.get(d, 0) + val) % MOD

    exact = {}
    for g in sorted(dp_multiple.keys(), reverse=True):
        val = dp_multiple.get(g, 0)
        k = 2 * g
        while k <= max_v:
            if k in exact:
                val = (val - exact[k]) % MOD
            k += g
        exact[g] = val % MOD

    ans = 0
    for g, cnt in exact.items():
        ans = (ans + g * cnt) % MOD
    return ans

