def balanced_k_factor_decomposition(n, k):
    def get_divisors(x):
        divs = []
        i = 1
        while i * i <= x:
            if x % i == 0:
                divs.append(i)
                if i != x // i:
                    divs.append(x // i)
            i += 1
        return divs
    best = [None]
    path = [0] * k
    def dfs(i, x, mi, mx):
        if i == 0:
            d = max(mx, x) - min(mi, x)
            if best[0] is None or d < best[0][0]:
                path[i] = x
                best[0] = (d, path[:])
            return
        for y in get_divisors(x):
            path[i] = y
            dfs(i - 1, x // y, min(mi, y), max(mx, y))
    dfs(k - 1, n, inf, 0)
    return best[0][1]

