class Solution:
    def minArrivalsToDiscard(self, arrivals: list[int], w: int, m: int) -> int:
        n = len(arrivals)
        kept = [False] * n
        cnt = defaultdict(int)
        discards = 0
        for i in range(n):
            x = arrivals[i]
            left = i - w
            if left >= 0 and kept[left]:
                cnt[arrivals[left]] -= 1
            if cnt[x] >= m:
                discards += 1
                kept[i] = False
            else:
                cnt[x] += 1
                kept[i] = True
        return discards

class Solution:
    def generateSchedule(self, n: int) -> list[list[int]]:
        if n <= 4:
            return []
        remaining = {}
        deg = [0]*n
        for a in range(n):
            for b in range(n):
                if a != b:
                    remaining[(a, b)] = True
                    deg[a] += 1
                    deg[b] += 1

        seq = []
        last = None
        total = n*(n-1)
        for _ in range(total):
            best, best_score = None, -1
            for (a, b), avail in remaining.items():
                if not avail:
                    continue
                if last is not None and (a in last or b in last):
                    continue
                score = deg[a] + deg[b]
                if score > best_score:
                    best_score, best = score, (a, b)
            if best is None:
                return []  # shouldn't happen for n >= 5, kept as a safety net
            a, b = best
            remaining[(a, b)] = False
            deg[a] -= 1
            deg[b] -= 1
            seq.append([a, b])
            last = (a, b)
        return seq

