def minSplitMerge(nums1, nums2):
    n = len(nums1)
    start = tuple(nums1)
    target = tuple(nums2)
    if start == target:
        return 0
    # n <= 6 (per constraints), so BFS over the full state space of array configurations is feasible
    visited = {start}
    q = deque([start])
    steps = 0
    while q:
        steps += 1
        for _ in range(len(q)):
            cur = q.popleft()
            for l in range(n):
                for r in range(l, n):
                    sub = cur[l:r + 1]
                    rest = cur[:l] + cur[r + 1:]
                    for pos in range(len(rest) + 1):
                        new_state = rest[:pos] + sub + rest[pos:]
                        if new_state == target:
                            return steps
                        if new_state not in visited:
                            visited.add(new_state)
                            q.append(new_state)
    return -1

