def count_distinct(s: str, k: int) -> int:
    n = len(s)
    dx = {'L': -1, 'R': 1, 'U': 0, 'D': 0}
    dy = {'L': 0, 'R': 0, 'U': 1, 'D': -1}
    pref: list[Tuple[int, int]] = [(0, 0)]
    x = y = 0
    for ch in s:
        x += dx[ch]
        y += dy[ch]
        pref.append((x, y))
    total = pref[n]
    reachable: Set[Tuple[int, int]] = set()
    for i in range(0, n - k + 1):
        xi, yi = pref[i]
        xj, yj = pref[i + k]
        point = (xi + (total[0] - xj), yi + (total[1] - yj))
        reachable.add(point)
    return len(reachable)

