def max_alternating_sum(arr: List[int], swaps: List[Tuple[int, int]]) -> int:
    n = len(arr)
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for u, v in swaps:
        union(u, v)

    comp_vals: dict[int, List[int]] = {}
    comp_pos_cnt: dict[int, int] = {}
    for i, val in enumerate(arr):
        r = find(i)
        comp_vals.setdefault(r, []).append(val)
        if i & 1 == 0:
            comp_pos_cnt[r] = comp_pos_cnt.get(r, 0) + 1

    total = 0
    for r, values in comp_vals.items():
        values.sort(reverse=True)
        pos_cnt = comp_pos_cnt.get(r, 0)
        pos_sum = sum(values[:pos_cnt])
        neg_sum = sum(values[pos_cnt:])
        total += pos_sum - neg_sum

    return total

def climbStairs(n, costs):
    INF = float('inf')
    f = [INF] * (n + 1)
    f[0] = 0
    for i in range(1, n + 1):
        x = costs[i - 1]
        for j in range(max(0, i - 3), i):
            f[i] = min(f[i], f[j] + x + (i - j) ** 2)
    return f[n]

