def split_array(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return -1
    s = [0] * n
    s[0] = nums[0]
    f = [True] * n   # f[i]: nums[0..i] strictly increasing
    g = [True] * n   # g[i]: nums[i..n-1] strictly decreasing
    for i in range(1, n):
        s[i] = s[i - 1] + nums[i]
        f[i] = f[i - 1] and nums[i] > nums[i - 1]
    for i in range(n - 2, -1, -1):
        g[i] = g[i + 1] and nums[i] > nums[i + 1]
    ans = None
    for i in range(n - 1):
        if f[i] and g[i + 1]:
            left_sum = s[i]
            right_sum = s[n - 1] - s[i]
            diff = abs(left_sum - right_sum)
            if ans is None or diff < ans:
                ans = diff
    return -1 if ans is None else ans

