MOD = 10**9 + 7

class Solution:
    def zigZagArrays(self, n: int, l: int, r: int) -> int:
        d = r - l + 1
        if n == 1:
            return d % MOD
        if n == 2:
            return (d * (d - 1)) % MOD

        size = 2 * d
        # State (v, 0..d-1) = "last move was up, currently at value v" (value v mapped to 0-indexed).
        # State (d+v) = "last move was down, currently at value v".
        vec = [0] * size
        for v in range(d):
            vec[v] = v            # up-state at v: number of valid smaller starting values v0<v
            vec[d + v] = d - 1 - v  # down-state at v: number of valid larger starting values v0>v

        M = [[0] * size for _ in range(size)]
        for v0 in range(d):
            for v1 in range(v0):        # from up-state at v0, next must go down: v1 < v0
                M[d + v1][v0] += 1
            for v1 in range(v0 + 1, d): # from down-state at v0, next must go up: v1 > v0
                M[v1][d + v0] += 1

        def mat_mult(A, B):
            n_, k_, m_ = len(A), len(B), len(B[0])
            C = [[0] * m_ for _ in range(n_)]
            for i in range(n_):
                Ai = A[i]
                for t in range(k_):
                    a = Ai[t]
                    if a == 0:
                        continue
                    bt = B[t]
                    Ci = C[i]
                    for j in range(m_):
                        if bt[j]:
                            Ci[j] = (Ci[j] + a * bt[j]) % MOD
            return C

        def mat_vec(A, v):
            res = [0] * len(A)
            for i, Ai in enumerate(A):
                s = 0
                for j, x in enumerate(v):
                    if Ai[j] and x:
                        s += Ai[j] * x
                res[i] = s % MOD
            return res

        def mat_pow(A, p):
            n_ = len(A)
            R = [[1 if i == j else 0 for j in range(n_)] for i in range(n_)]
            while p:
                if p & 1:
                    R = mat_mult(R, A)
                A = mat_mult(A, A)
                p >>= 1
            return R

        Mp = mat_pow(M, n - 2)
        return sum(mat_vec(Mp, vec)) % MOD

class Solution:
    def countNoZeroPairs(self, n: int) -> int:
        digits = list(map(int, str(n)))[::-1]
        digits.append(0)
        L = len(digits)
        dp = [[[0]*2 for _ in range(2)] for _ in range(2)]
        dp[0][1][1] = 1
        for pos in range(L):
            ndp = [[[0]*2 for _ in range(2)] for _ in range(2)]
            target = digits[pos]
            for carry in range(2):
                for aliveA in range(2):
                    for aliveB in range(2):
                        ways = dp[carry][aliveA][aliveB]
                        if ways == 0: continue
                        if aliveA:
                            A = [(d,1) for d in range(1,10)]
                            if pos > 0: A.append((0,0))
                        else:
                            A = [(0,0)]
                        if aliveB:
                            B = [(d,1) for d in range(1,10)]
                            if pos > 0: B.append((0,0))
                        else:
                            B = [(0,0)]
                        for da, na in A:
                            for db, nb in B:
                                sm = da+db+carry
                                if sm % 10 != target: continue
                                ndp[sm//10][na][nb] += ways
            dp = ndp
        return dp[0][0][0]

