def remove_k_balanced(s: str, k: int) -> str:
    stack: List[str] = []               # characters kept so far
    pos_stack: List[int] = []           # start index in stack for each '('
    inner_counts: List[int] = []        # number of balanced pairs inside each '('

    for ch in s:
        if ch == '(':
            pos_stack.append(len(stack))
            inner_counts.append(0)
            stack.append(ch)
        elif ch == ')':
            if not pos_stack:
                # unmatched ')', just keep it
                stack.append(ch)
                continue
            inner = inner_counts.pop()
            start_idx = pos_stack.pop()
            total_pairs = inner + 1
            if total_pairs == k:
                # remove the whole substring from start_idx to current ')'
                stack = stack[:start_idx]
            else:
                # keep the substring and propagate its pair count outward
                stack.append(ch)
                if inner_counts:
                    inner_counts[-1] += total_pairs
        else:
            # any other character is kept as‑is
            stack.append(ch)

    return ''.join(stack)

def longest_balanced(s: str) -> int:
    """
    Returns the length of the longest contiguous substring of `s`
    where every character that appears in the substring occurs the same
    number of times.
    """
    n = len(s)
    max_len = 0

    for left in range(n):
        counts = [0] * 26  # assume lowercase English letters
        distinct = 0
        for right in range(left, n):
            idx = ord(s[right]) - ord('a')
            if 0 <= idx < 26:
                if counts[idx] == 0:
                    distinct += 1
                counts[idx] += 1
            else:
                # characters outside a‑z are treated as separate symbols
                # expand the counts list dynamically
                # (this branch is rarely hit for typical test data)
                # map the character to a new slot
                # for simplicity, restart the window when encountering unknown chars
                break

            # compute max and min of non‑zero counts
            cur_max = 0
            cur_min = None
            for c in counts:
                if c:
                    if cur_min is None or c < cur_min:
                        cur_min = c
                    if c > cur_max:
                        cur_max = c
            if cur_min is not None and cur_max == cur_min:
                max_len = max(max_len, right - left + 1)

    return max_len

