def equal_score_substring(s: str) -> bool:
    n: int = len(s)
    if n < 2:
        return False
    vals: List[int] = [ord(ch) - ord('a') + 1 for ch in s]
    for length in range(1, n):
        sum_to_first = {}
        cur_sum = sum(vals[:length])
        sum_to_first[cur_sum] = 0
        for start in range(1, n - length + 1):
            cur_sum += vals[start + length - 1] - vals[start - 1]
            if cur_sum in sum_to_first:
                prev_start = sum_to_first[cur_sum]
                if start >= prev_start + length:
                    return True
            else:
                sum_to_first[cur_sum] = start
    return False

