        return 0
    max_sum = min_sum = points[0][0] + points[0][1]
    max_diff = min_diff = points[0][0] - points[0][1]
    for x, y in points[1:]:
        s = x + y
        d = x - y
        if s > max_sum:
            max_sum = s
        if s < min_sum:
            min_sum = s
        if d > max_diff:
            max_diff = d
        if d < min_diff:
            min_diff = d
    return max(max_sum - min_sum, max_diff - min_diff)

