from typing import List

def smallest_permutation_greater(source: str, target: str) -> str:
    if len(source) != len(target):
        return ""
    cnt: Counter = Counter(source)
    n: int = len(source)
    result: List[str] = []

    def dfs(pos: int, tight: bool) -> bool:
        if pos == n:
            # succeed only if we have already placed a larger character
            return not tight
        for ch in sorted(cnt.keys()):
            if cnt[ch] == 0:
                continue
            if tight:
                if ch < target[pos]:
                    continue
                cnt[ch] -= 1
                result.append(ch)
                if ch == target[pos]:
                    if dfs(pos + 1, True):
                        return True
                else:  # ch > target[pos]
                    # fill the rest with the smallest remaining characters
                    for k in sorted(cnt.elements()):
                        result.append(k)
                    return True
                # backtrack
                result.pop()
                cnt[ch] += 1
            else:
                # already greater, just fill smallest possible
                cnt[ch] -= 1
                result.append(ch)
                if dfs(pos + 1, False):
                    return True
                result.pop()
                cnt[ch] += 1
        return False

