class Solution:
    def longestBalancedSubstring(self, s: str) -> int:
        x = self._calc1(s)
        y = max(self._calc2(s, 'a', 'b'), self._calc2(s, 'b', 'c'), self._calc2(s, 'a', 'c'))
        z = self._calc3(s)
        return max(x, y, z)

    def _calc1(self, s):
        # Case: only one distinct character - longest run of identical characters.
        res = 0
        i, n = 0, len(s)
        while i < n:
            j = i + 1
            while j < n and s[j] == s[i]:
                j += 1
            res = max(res, j - i)
            i = j
        return res

    def _calc2(self, s, a, b):
        # Case: exactly two distinct characters a,b in equal counts. Substring must not
        # contain the third character at all, so reset the running diff/hashmap whenever
        # it's seen (a substring spanning the third char can't be valid for this pair).
        n = len(s)
        res = 0
        pos = {0: -1}
        d = 0
        for i in range(n):
            c = s[i]
            if c != a and c != b:
                pos = {0: i}
                d = 0
                continue
            d += 1 if c == a else -1
            if d in pos:
                res = max(res, i - pos[d])
            else:
                pos[d] = i
        return res

    def _calc3(self, s):
        # Case: all three characters present in equal counts. Track the running
        # (count_a - count_b, count_b - count_c) pair; a repeat means equal a/b/c counts
        # in between (no need to exclude anything here - all three chars are allowed).
        n = len(s)
        res = 0
        pos = {(0, 0): -1}
        da = db = dc = 0
        for i in range(n):
            c = s[i]
            if c == 'a':
                da += 1
            elif c == 'b':
                db += 1
            else:
                dc += 1
            key = (da - db, db - dc)
            if key in pos:
                res = max(res, i - pos[key])
            else:
                pos[key] = i
        return res

