def count_ways(rows: List[List[int]]) -> int:
    MOD = 10**9 + 7
    if not rows:
        return 0

    max_val = 0
    for row in rows:
        if row:
            max_val = max(max_val, max(row))
    if max_val == 0:
        return 0

    # Möbius function up to max_val
    mu = [1] * (max_val + 1)
    mu[0] = 0
    is_prime = [True] * (max_val + 1)
    primes: List[int] = []
    for i in range(2, max_val + 1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            ip = i * p
            if ip > max_val:
                break
            is_prime[ip] = False
            if i % p == 0:
                mu[ip] = 0
                break
            else:
                mu[ip] = -mu[i]

    # Pre‑compute divisors for every number up to max_val
    divisors: List[List[int]] = [[] for _ in range(max_val + 1)]
    for d in range(1, max_val + 1):
        for mult in range(d, max_val + 1, d):
            divisors[mult].append(d)

    # ways[d] = product over rows of (count of numbers divisible by d)
    ways = [1] * (max_val + 1)
    for row in rows:
        cnt = [0] * (max_val + 1)
        for v in row:
            for d in divisors[v]:
                cnt[d] += 1
        for d in range(1, max_val + 1):
            ways[d] = ways[d] * cnt[d] % MOD

    # Inclusion‑exclusion using Möbius inversion
    ans = 0
    for d in range(1, max_val + 1):
        ans = (ans + mu[d] * ways[d]) % MOD
    return ans % MOD

