import math
class Solution:
    def minTime(self, d: list[int], r: list[int]) -> int:
        d1, d2 = d
        r1, r2 = r
        lcm = r1 * r2 // math.gcd(r1, r2)
        def feasible(T):
            a1 = T - T // r1
            a2 = T - T // r2
            atotal = T - T // lcm
            return a1 >= d1 and a2 >= d2 and atotal >= d1 + d2
        lo, hi = 1, 4_000_000_000
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

NEG = float('-inf')
def max_cyclic_partition_score(nums, k):
    n = len(nums)
    def linear(a):
        f = [[NEG] * 3 for _ in range(k + 1)]
        f[0][1] = 0
        for x in a:
            g = [row[:] for row in f]
            for c in range(k + 1):
                for bi in range(3):
                    cur = f[c][bi]
                    if cur == NEG:
                        continue
                    b = bi - 1
                    for sign in (1, -1):
                        nb = b + sign
                        if nb < -1 or nb > 1:
                            continue
                        nc = c + (1 if nb == 0 else 0)
                        if nc > k:
                            continue
                        val = cur + sign * x
                        if val > g[nc][nb + 1]:
                            g[nc][nb + 1] = val
            f = g
        return max(f[c][1] for c in range(k + 1))
    return max(linear(nums[r:] + nums[:r]) for r in range(n))

