def longest_non_decreasing_after_one_replace(arr: List[int]) -> int:
    n = len(arr)
    if n <= 2:
        return n

    left = [0] * n
    left[0] = 1
    for i in range(1, n):
        left[i] = left[i - 1] + 1 if arr[i] >= arr[i - 1] else 1

    best = max(left)

    next_right_len = 0  # corresponds to right[i+1] for the current i
    right_len = 0
    for i in range(n - 1, -1, -1):
        if i == n - 1:
            right_len = 1
        else:
            right_len = right_len + 1 if arr[i] <= arr[i + 1] else 1

        if i > 0:
            best = max(best, left[i - 1] + 1)
        if i < n - 1:
            best = max(best, next_right_len + 1)
        if 0 < i < n - 1 and arr[i - 1] <= arr[i + 1]:
            best = max(best, left[i - 1] + 1 + next_right_len)

        next_right_len = right_len

    return min(best, n)

