def smallest_negated_permutation(n: int, target: int) -> List[int]:
    total = n * (n + 1) // 2
    # feasibility check
    if abs(target) > total or (total - target) & 1:
        return []
    need = (total - target) // 2  # sum of numbers that must be negated
    negated: List[int] = []
    # pick largest numbers first to obtain lexicographically smallest sequence
    for i in range(n, 0, -1):
        if need >= i:
            negated.append(i)
            need -= i
    # construct result: negatives in descending order, then positives in ascending order
    result: List[int] = [-i for i in negated]
    negated_set = set(negated)
    for i in range(1, n + 1):
        if i not in negated_set:
            result.append(i)
    return result

