def total_waviness(L: int, R: int) -> int:
    def up_to(N):
        if N < 0:
            return 0
        digits = list(map(int, str(N)))
        n = len(digits)
        @lru_cache(maxsize=None)
        def go(pos, prev, tight, started):
            if pos == n:
                return (1, 0)
            cnt = 0
            tot = 0
            hi = digits[pos] if tight else 9
            for d in range(0, hi + 1):
                ntight = tight and (d == hi)
                nstarted = started or d > 0
                add = abs(prev - d) if started else 0
                c, s = go(pos + 1, d if nstarted else -1, ntight, nstarted)
                cnt += c
                tot += s + add * c
            return (cnt, tot)
        res = go(0, -1, True, False)[1]
        go.cache_clear()
        return res
    return up_to(R) - up_to(L - 1)

