MOD = 1_000_000_007

def numberOfEffectiveSubsequences(nums):
    n = len(nums)
    max_val = max(nums)
    B = 1
    while (1 << B) <= max_val:
        B += 1
    size = 1 << B
    fullmask = size - 1

    subset_sum = [0] * size
    for v in nums:
        subset_sum[v] += 1
    for bit in range(B):
        for mask in range(size):
            if mask & (1 << bit):
                subset_sum[mask] += subset_sum[mask ^ (1 << bit)]

    active_bits = 0
    for v in nums:
        active_bits |= v

    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i - 1] * 2) % MOD

    answer = 0
    submask = active_bits
    while submask > 0:
        bits_set = bin(submask).count('1')
        elements_with_none = subset_sum[fullmask ^ submask]
        forced = n - elements_with_none
        ways = pow2[n - forced]
        if bits_set % 2 == 1:
            answer = (answer + ways) % MOD
        else:
            answer = (answer - ways + MOD) % MOD
        submask = (submask - 1) & active_bits

    return answer % MOD

