def min_deletions_to_make_alternating_substring(s: str, queries: List[List[int]]) -> List[int]:
    n = len(s)
    if n == 0:
        return []

    s_list = list(s)
    diff = [0] * n  # diff[i] = 1 if s[i] != s[i-1] for i > 0 else 0

    class BIT:
        __slots__ = ("n", "tree")
        def __init__(self, n: int):
            self.n = n
            self.tree = [0] * (n + 1)

        def add(self, i: int, delta: int) -> None:
            while i <= self.n:
                self.tree[i] += delta
                i += i & -i

        def sum(self, i: int) -> int:
            res = 0
            while i:
                res += self.tree[i]
                i -= i & -i
            return res

        def range_sum(self, l: int, r: int) -> int:
            if l > r:
                return 0
            return self.sum(r) - self.sum(l - 1)

    bit = BIT(n)
    for i in range(1, n):
        d = 1 if s_list[i] != s_list[i - 1] else 0
        diff[i] = d
        if d:
            bit.add(i, d)

    out: List[int] = []
    for q in queries:
        typ = q[0]
        if typ == 1:
            pos = q[1]  # 0‑based index
            # flip character assuming only 'A' and 'B'
            s_list[pos] = 'B' if s_list[pos] == 'A' else 'A'
            if pos > 0:
                i = pos
                new = 1 if s_list[i] != s_list[i - 1] else 0
                delta = new - diff[i]
                if delta:
                    diff[i] = new
                    bit.add(i, delta)
            if pos + 1 < n:
                i = pos + 1
                new = 1 if s_list[i] != s_list[i - 1] else 0
                delta = new - diff[i]
                if delta:
                    diff[i] = new
                    bit.add(i, delta)
        else:
            l = q[1]
            r = q[2]
            if l == r:
                out.append(0)
            else:
                sum_diff = bit.range_sum(l + 1, r)
                deletions = (r - l) - sum_diff
                out.append(deletions)
    return out
# TIME: O((n+q) log n) SPACE: O(n)

def mirror_distance(n: int) -> int:
    original = abs(n)
    rev = 0
    temp = original
    while temp:
        rev = rev * 10 + (temp % 10)
        temp //= 10
    return abs(original - rev)

