def max_sum_divisible_by_three(nums: list[int]) -> int:
    top = {0: [], 1: [], 2: []}
    for v in nums:
        r = v % 3
        lst = top[r]
        if len(lst) < 3:
            lst.append(v)
            i = len(lst) - 1
            while i and lst[i] > lst[i - 1]:
                lst[i], lst[i - 1] = lst[i - 1], lst[i]
                i -= 1
        elif v > lst[-1]:
            lst[-1] = v
            i = 2
            while i and lst[i] > lst[i - 1]:
                lst[i], lst[i - 1] = lst[i - 1], lst[i]
                i -= 1
    candidates = []
    r0, r1, r2 = top[0], top[1], top[2]
    if len(r0) >= 3:
        candidates.append(r0[0] + r0[1] + r0[2])
    if len(r1) >= 3:
        candidates.append(r1[0] + r1[1] + r1[2])
    if len(r2) >= 3:
        candidates.append(r2[0] + r2[1] + r2[2])
    if r0 and r1 and r2:
        candidates.append(r0[0] + r1[0] + r2[0])
    return max(candidates) if candidates else 0

