def total_interaction_cost(n: int, edges: List[Tuple[int, int]], values: List[int]) -> int:
    if n <= 1:
        return 0

    adj: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # total frequency of each value in the whole tree
    total_freq: Dict[int, int] = {}
    for val in values:
        total_freq[val] = total_freq.get(val, 0) + 1

    import sys
    sys.setrecursionlimit(10 ** 6)

    total_cost = 0

    def dfs(node: int, parent: int) -> Dict[int, int]:
        nonlocal total_cost
        # counter for the subtree rooted at node
        cnt: Dict[int, int] = {values[node]: 1}
        for nb in adj[node]:
            if nb == parent:
                continue
            child_cnt = dfs(nb, node)

            # contribution of edge (node, nb)
            for val, c in child_cnt.items():
                total_cost += c * (total_freq[val] - c)

            # merge child_cnt into cnt (small-to-large)
            if len(child_cnt) > len(cnt):
                cnt, child_cnt = child_cnt, cnt
            for val, c in child_cnt.items():
                cnt[val] = cnt.get(val, 0) + c
        return cnt

    dfs(0, -1)
    return total_cost

def number_of_balanced_integers_optimal(low, high):
    def count_up_to(n):
        if n < 11:
            return 0
        s = str(n)
        length = len(s)
        memo = {}
        def dfs(pos, diff, tight, started, parity_odd):
            if pos == length:
                return 1 if (started and diff == 0) else 0
            key = (pos, diff, started, parity_odd)
            if not tight and key in memo:
                return memo[key]
            limit = int(s[pos]) if tight else 9
            res = 0
            for d in range(limit + 1):
                if not started and d == 0:
                    res += dfs(pos + 1, diff, tight and d == limit, False, True)
                else:
                    delta = -d if parity_odd else d
                    res += dfs(pos + 1, diff + delta, tight and d == limit, True, not parity_odd)
            if not tight:
                memo[key] = res
            return res
        return dfs(0, 0, True, False, True)

    if high < 11:
        return 0
    low = max(low, 11)
    return count_up_to(high) - count_up_to(low - 1)

