class Solution:
    def maxCapacity(self, costs: list[int], capacity: list[int], budget: int) -> int:
        n = len(costs)
        arr = [(costs[i], capacity[i]) for i in range(n) if costs[i] < budget]
        if not arr:
            return 0
        arr.sort()
        m = len(arr)
        ans = max(cap for _, cap in arr)

        # sparse table for O(1) range-max of capacity over the sorted-by-cost array
        LOG = max(1, m.bit_length())
        sparse = [[0]*m for _ in range(LOG)]
        for i in range(m):
            sparse[0][i] = arr[i][1]
        j = 1
        while (1 << j) <= m:
            half = 1 << (j-1)
            for i in range(m - (1<<j) + 1):
                sparse[j][i] = max(sparse[j-1][i], sparse[j-1][i+half])
            j += 1

        def query(l, r):
            if l > r:
                return float('-inf')
            length = r - l + 1
            k = length.bit_length() - 1
            return max(sparse[k][l], sparse[k][r - (1<<k) + 1])

        # Two-pointer: as i increases (sorted ascending), the largest valid partner index
        # only shrinks - hi must never reset, or the pointer degrades to O(n^2).
        hi = m - 1
        for i in range(m):
            if hi < i:
                hi = i
            while hi > i and arr[i][0] + arr[hi][0] >= budget:
                hi -= 1
            if hi > i:
                best_partner_cap = query(i+1, hi)
                if best_partner_cap != float('-inf'):
                    ans = max(ans, arr[i][1] + best_partner_cap)
        return ans

