def count_pythagorean_nodes(n: int, edges: List[Tuple[int, int]], a: int, b: int, c: int) -> int:
    adj: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start: int) -> List[int]:
        dist = [-1] * n
        q = deque([start])
        dist[start] = 0
        while q:
            cur = q.popleft()
            dcur = dist[cur]
            for nb in adj[cur]:
                if dist[nb] == -1:
                    dist[nb] = dcur + 1
                    q.append(nb)
        return dist

    da = bfs(a)
    db = bfs(b)
    dc = bfs(c)

    def is_pythagorean(x: int, y: int, z: int) -> bool:
        # check any ordering satisfies x^2 + y^2 == z^2
        return x * x + y * y == z * z or x * x + z * z == y * y or y * y + z * z == x * x

    count = 0
    for i in range(n):
        if is_pythagorean(da[i], db[i], dc[i]):
            count += 1
    return count

