import math

def nth_smallest_with_k_ones(n: int, k: int) -> int:
    if n < 1 or k < 0:
        raise ValueError("Invalid arguments")
    if k == 0:
        if n == 1:
            return 0
        raise ValueError("n exceeds number of possible integers")
    # Find the smallest highest bit position such that there are at least n numbers
    # with k set bits using positions 0..pos.
    pos = k - 1
    while math.comb(pos + 1, k) < n:
        pos += 1

    remaining = n - 1  # zero‑based rank
    bits_left = k
    result = 0

    for p in range(pos, -1, -1):
        if bits_left == 0:
            break
        count = math.comb(p, bits_left) if p >= bits_left else 0
        if remaining >= count:
            result |= 1 << p
            remaining -= count
            bits_left -= 1
    return result

