    return ''.join(chars)

def min_k(nums, limit):
    total = sum(nums)
    max_val = max(nums) if nums else 0
    if total <= limit:
        return 0
    low, high = 0, max_val
    while low < high:
        mid = (low + high) // 2
        reduced_sum = sum(v - mid for v in nums if v > mid)
        if reduced_sum <= limit:
            high = mid
        else:
            low = mid + 1
    return low

