class RideSharingSystem:
    def __init__(self):
        self.riders = deque()
        self.drivers = deque()
        self.cancelled = set()

    def addRider(self, riderId: int) -> None:
        self.riders.append(riderId)

    def addDriver(self, driverId: int) -> None:
        self.drivers.append(driverId)

    def matchDriverWithRider(self):
        while self.riders and self.riders[0] in self.cancelled:
            self.cancelled.discard(self.riders.popleft())
        if not self.riders or not self.drivers:
            return [-1, -1]
        riderId = self.riders.popleft()
        driverId = self.drivers.popleft()
        return [driverId, riderId]

    def cancelRider(self, riderId: int) -> None:
        if riderId in self.riders:
            self.cancelled.add(riderId)

