def max_score(nums1: List[int], nums2: List[int], k: int) -> int:
    n, m = len(nums1), len(nums2)
    if k == 0 or k > min(n, m):
        return 0
    neg_inf = float('-inf')
    # dp_prev[j][t] = best score using first i-1 elements of nums1 and first j elements of nums2
    dp_prev = [[neg_inf] * (k + 1) for _ in range(m + 1)]
    for j in range(m + 1):
        dp_prev[j][0] = 0

    for i in range(1, n + 1):
        dp_cur = [[neg_inf] * (k + 1) for _ in range(m + 1)]
        dp_cur[0][0] = 0
        for j in range(1, m + 1):
            for t in range(0, k + 1):
                # skip nums1[i-1] or nums2[j-1]
                best = dp_prev[j][t]
                if dp_cur[j - 1][t] > best:
                    best = dp_cur[j - 1][t]
                # pair them
                if t > 0:
                    cand = dp_prev[j - 1][t - 1] + nums1[i - 1] * nums2[j - 1]
                    if cand > best:
                        best = cand
                dp_cur[j][t] = best
        dp_prev = dp_cur

    return int(dp_prev[m][k])

def longest_alternating_subarray(nums):
    n = len(nums)
    if n == 0:
        return 0
    l1 = [1] * n  # ends at i, last comparison was "up" (nums[i-1] < nums[i])
    l2 = [1] * n  # ends at i, last comparison was "down" (nums[i-1] > nums[i])
    r1 = [1] * n  # starts at i, next comparison is "up" (nums[i] < nums[i+1])
    r2 = [1] * n  # starts at i, next comparison is "down" (nums[i] > nums[i+1])
    ans = 1 if n > 0 else 0
    for i in range(1, n):
        if nums[i-1] < nums[i]:
            l1[i] = l2[i-1] + 1
        elif nums[i-1] > nums[i]:
            l2[i] = l1[i-1] + 1
        ans = max(ans, l1[i], l2[i])
    for i in range(n-2, -1, -1):
        if nums[i+1] > nums[i]:
            r1[i] = r2[i+1] + 1
        elif nums[i+1] < nums[i]:
            r2[i] = r1[i+1] + 1
    for i in range(1, n-1):
        if nums[i-1] < nums[i+1]:
            ans = max(ans, l2[i-1] + r2[i+1])
        elif nums[i-1] > nums[i+1]:
            ans = max(ans, l1[i-1] + r1[i+1])
    return ans

def house_robber_v(root):
