        return 0
    delp = [[2]*n for _ in range(n)]
    best = 1
    for i in range(n):
        delp[i][i] = 0
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if s[i] == s[j]:
                delp[i][j] = 0 if length == 2 else delp[i+1][j-1]
            else:
                a = delp[i+1][j]
                b = delp[i][j-1]
                delp[i][j] = min(1+min(a,b), 2)
            if delp[i][j] <= 1:
                best = max(best, length)
    return best

