def max_subarray_xor_bounded(nums: List[int], k: int) -> int:
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] ^ nums[i]
    maxbit = max(1, max(prefix).bit_length())
    trie = [[-1, -1, 0]]
    def insert(val, delta):
        node = 0
        trie[node][2] += delta
        for b in range(maxbit - 1, -1, -1):
            bit = (val >> b) & 1
            if trie[node][bit] == -1:
                trie.append([-1, -1, 0])
                trie[node][bit] = len(trie) - 1
            node = trie[node][bit]
            trie[node][2] += delta
    def query(val):
        node = 0
        res = 0
        for b in range(maxbit - 1, -1, -1):
            bit = (val >> b) & 1
            want = 1 - bit
            if trie[node][want] != -1 and trie[trie[node][want]][2] > 0:
                res |= (1 << b)
                node = trie[node][want]
            else:
                node = trie[node][bit]
        return res
    maxdq, mindq = deque(), deque()
    l, ans = 0, 0
    inserted = [False] * (n + 1)
    for r in range(n):
        while maxdq and nums[maxdq[-1]] <= nums[r]: maxdq.pop()
        maxdq.append(r)
        while mindq and nums[mindq[-1]] >= nums[r]: mindq.pop()
        mindq.append(r)
        while nums[maxdq[0]] - nums[mindq[0]] > k:
            if inserted[l]:
                insert(prefix[l], -1)
                inserted[l] = False
            if maxdq[0] == l: maxdq.popleft()
            if mindq[0] == l: mindq.popleft()
            l += 1
        insert(prefix[r], 1)
        inserted[r] = True
        ans = max(ans, query(prefix[r + 1]))
    return ans

def mergeCharacters(s: str, k: int) -> str:
    last = {}
    ans = []
    for c in s:
        cur = len(ans)
        if c in last and cur - last[c] <= k:
