        ans.append(c)
        last[c] = cur
    return ''.join(ans)

def max_xor_after_rearrangement(a: str, b: str) -> str:
    """
    Rearrange the bits of string `a` to maximize the XOR with string `b`.
    Both strings have the same length and consist only of '0' and '1'.
    Returns the resulting XOR string.
    """
    zeros = a.count('0')
    ones = len(a) - zeros
    xor_bits = []

    for ch in b:
        if ch == '1':
            if zeros:
                zeros -= 1
                xor_bits.append('1')
            else:
                ones -= 1
                xor_bits.append('0')
        else:  # ch == '0'
            if ones:
                ones -= 1
                xor_bits.append('1')
            else:
                zeros -= 1
                xor_bits.append('0')

    return ''.join(xor_bits)

