def subarrays_with_k_distinct(nums: List[int], k: int) -> int:
    def at_most(m: int) -> int:
        left = 0
        result = 0
        freq = {}
        for right, val in enumerate(nums):
            freq[val] = freq.get(val, 0) + 1
            while len(freq) > m:
                left_val = nums[left]
                freq[left_val] -= 1
                if freq[left_val] == 0:
                    del freq[left_val]
                left += 1
            result += right - left + 1
        return result
    return at_most(k) - at_most(k - 1)

