def min_bitwise_or(grid: List[List[int]]) -> int:
    n = len(grid)
    if n == 0:
        return 0
    m = len(grid[0])
    max_val = 0
    for row in grid:
        for v in row:
            if v > max_val:
                max_val = v
    highest_bit = max_val.bit_length() - 1
    answer = 0
    for bit in range(highest_bit, -1, -1):
        mask = answer | ((1 << bit) - 1)
        ok = True
        for i in range(n):
            row_ok = False
            row = grid[i]
            for v in row:
