def _count_digit_sum_good_up_to(n: int) -> int:
    if n < 0:
        return 0
    s = str(n)
    length = len(s)

    @lru_cache(maxsize=None)
    def dp(pos, tight, total):
        if pos == length:
            return 1 if total in _GOOD_SUMS else 0
        limit = int(s[pos]) if tight else 9
        res = 0
        for dgt in range(limit + 1):
            res += dp(pos + 1, tight and dgt == limit, total + dgt)
        return res

    result = dp(0, True, 0)
    dp.cache_clear()
    return result


def _count_both_up_to(n: int) -> int:
    if n < 0:
        return 0
    cnt = 0
    for x in _GOOD_SORTED:
        if x > n:
            break
        if _digit_sum(x) in _GOOD_SUMS:
            cnt += 1
    return cnt


def _fancy_count_up_to(n: int) -> int:
    if n < 0:
        return 0
    return _count_good_up_to(n) + _count_digit_sum_good_up_to(n) - _count_both_up_to(n)


