def minCost(s, encCost, flatCost):
    n = len(s)
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + (1 if s[i] == '1' else 0)

    def seg_cost(x, y):
        L = y - x
        X = pre[y] - pre[x]
        if X == 0:
            return flatCost
        return L * X * encCost

    memo = {}
    def dfs(x, y):
        if (x, y) in memo:
            return memo[(x, y)]
        # dfs(x,y): min cost to partition s[x..y-1], choosing between keeping it whole
        # or (only if length is even) splitting into two equal halves recursively
        whole = seg_cost(x, y)
        L = y - x
        if L % 2 == 0:
            mid = x + L // 2
            split = dfs(x, mid) + dfs(mid, y)
            res = min(whole, split)
        else:
            res = whole
        memo[(x, y)] = res
        return res

    return dfs(0, n)

def longest_arithmetic_optimal(nums):
    n = len(nums)
    if n <= 2:
        return n
    left = [2] * n
    right = [2] * n
    left[0] = 1
    right[n-1] = 1
    for i in range(2, n):
        if nums[i] - nums[i-1] == nums[i-1] - nums[i-2]:
            left[i] = left[i-1] + 1
    for i in range(n-3, -1, -1):
        if nums[i+1] - nums[i] == nums[i+2] - nums[i+1]:
            right[i] = right[i+1] + 1
    ans = 2
    for i in range(n):
        ans = max(ans, left[i], right[i])
        if i > 0:
            ans = max(ans, left[i-1] + 1)
        if i + 1 < n:
            ans = max(ans, right[i+1] + 1)
        if 0 < i < n - 1:
            diff_sum = nums[i+1] - nums[i-1]
            if diff_sum % 2 == 0:
                diff = diff_sum // 2
                k = 3
                if i > 1 and diff == (nums[i-1] - nums[i-2]):
                    k += left[i-1] - 1
                if i < n - 2 and diff == (nums[i+2] - nums[i+1]):
                    k += right[i+1] - 1
                ans = max(ans, k)
    return ans

def max_points_activated(points):
    parent = {}
    size = {}
    def find(x):
        if x not in parent:
            parent[x] = x
            size[x] = 1
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    M = 3_000_000_000
    for x, y in points:
        union(x, y + M)
    cnt = {}
    for x, y in points:
        r = find(x)
        cnt[r] = cnt.get(r, 0) + 1
    mx1 = mx2 = 0
    for v in cnt.values():
        if v > mx1:
            mx2 = mx1
            mx1 = v
        elif v > mx2:
            mx2 = v
    return mx1 + mx2 + 1

