def solve(A: List[int], B: List[int]) -> int:
    if len(A) != len(B):
        return -1

    diff = {}
    for v in A:
        diff[v] = diff.get(v, 0) + 1
    for v in B:
        diff[v] = diff.get(v, 0) - 1

    swaps_needed = 0
    for d in diff.values():
        if d % 2 != 0:
            return -1
        swaps_needed += abs(d) // 2

    # each swap fixes two mismatched positions, so divide by 2
    return swaps_needed // 2

def count_commas(L: int, R: int) -> int:
    """
    Returns the total number of commas that would appear when writing all
    integers from L to R inclusive with standard thousand-separator commas.
    """
    def total_up_to(limit: int) -> int:
        if limit < 1:
            return 0
        total = 0
        max_len = len(str(limit))
        for d in range(1, max_len + 1):
            start = 1 if d == 1 else 10 ** (d - 1)
            end = min(limit, (10 ** d) - 1)
            if start > end:
                continue
            count = end - start + 1
            commas = (d - 1) // 3
            total += count * commas
        return total

    return total_up_to(R) - total_up_to(L - 1)

MOD = 10**9 + 7

class Solution:
    def countVisiblePeople(self, n: int, pos: int, k: int) -> int:
        l = pos
        r = n - pos - 1
        maxN = max(l, r) + 1
        fact = [1] * (maxN + 1)
        for i in range(1, maxN + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (maxN + 1)
        inv_fact[maxN] = pow(fact[maxN], MOD - 2, MOD)
        for i in range(maxN, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def comb(nn, kk):
            if kk < 0 or kk > nn:
                return 0
            return fact[nn] * inv_fact[kk] % MOD * inv_fact[nn - kk] % MOD

        ans = 0
        for a in range(0, min(k, l) + 1):
            b = k - a
            if b <= r:
                ans = (ans + 2 * comb(l, a) % MOD * comb(r, b)) % MOD
        return ans

