def min_removals_to_target_xor(arr: List[int], target: int) -> int:
    n = len(arr)
    dp = {0: 0}
    for v in arr:
        next_dp = dict(dp)
        for xor_val, size in dp.items():
            new_xor = xor_val ^ v
            new_size = size + 1
            existing = next_dp.get(new_xor)
            if existing is None or new_size > existing:
                next_dp[new_xor] = new_size
        dp = next_dp
    best = dp.get(target)
    if best is None:
        return -1
    return n - best

