def min_xor_path(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    if m == 1 and n == 1:
        return grid[0][0]

    total_steps = m + n - 2
    half = total_steps // 2

    start_map: Dict[Tuple[int, int], List[int]] = {}
    end_map: Dict[Tuple[int, int], List[int]] = {}

    # DFS from start to the middle diagonal
    stack = [(0, 0, grid[0][0])]
    while stack:
        i, j, cur = stack.pop()
        if i + j == half:
            start_map.setdefault((i, j), []).append(cur)
            continue
        if i + 1 < m:
            stack.append((i + 1, j, cur ^ grid[i + 1][j]))
        if j + 1 < n:
            stack.append((i, j + 1, cur ^ grid[i][j + 1]))

    # DFS from end to the middle diagonal (moving up/left)
    stack = [(m - 1, n - 1, grid[m - 1][n - 1])]
    while stack:
        i, j, cur = stack.pop()
        if i + j == half:
            end_map.setdefault((i, j), []).append(cur)
            continue
        if i - 1 >= 0:
            stack.append((i - 1, j, cur ^ grid[i - 1][j]))
        if j - 1 >= 0:
            stack.append((i, j - 1, cur ^ grid[i][j - 1]))

    class TrieNode:
        __slots__ = ("child",)
        def __init__(self):
            self.child = [None, None]

    def insert(root: TrieNode, num: int) -> None:
        node = root
        for b in range(31, -1, -1):
            bit = (num >> b) & 1
            if node.child[bit] is None:
                node.child[bit] = TrieNode()
            node = node.child[bit]

    def query_min_xor(root: TrieNode, num: int) -> int:
        node = root
        xor_val = 0
        for b in range(31, -1, -1):
            bit = (num >> b) & 1
            if node.child[bit] is not None:
                node = node.child[bit]
            else:
                node = node.child[1 - bit]
                xor_val |= (1 << b)
        return xor_val

    answer = (1 << 62) - 1
    for (i, j), start_vals in start_map.items():
        end_vals = end_map.get((i, j), [])
        if not end_vals:
            continue
        root = TrieNode()
        for ev in end_vals:
            insert(root, ev)
        mid_val = grid[i][j]
        for sv in start_vals:
            target = sv ^ mid_val
            candidate = query_min_xor(root, target)
            if candidate < answer:
                answer = candidate

    return answer
# TIME: O(2^{(m+n)/2} * 32) SPACE: O(2^{(m+n)/2})

