def integers_with_multiple_sum_of_two_cubes(n: int) -> List[int]:
    if n < 2:
        return []
    limit = int(n ** (1 / 3))
    while (limit + 1) ** 3 <= n:
        limit += 1
    while limit ** 3 > n:
        limit -= 1
    cubes = [i * i * i for i in range(limit + 1)]
    count_map: dict[int, int] = {}
    for a in range(1, limit + 1):
        a_cubed = cubes[a]
        for b in range(a, limit + 1):
            s = a_cubed + cubes[b]
            if s > n:
                break
            count_map[s] = count_map.get(s, 0) + 1
    result = [s for s, cnt in count_map.items() if cnt > 1]
    result.sort()
    return result

class Solution:
    def numberOfGoodEdges(self, n: int, edges: list[list[int]]) -> int:
        parent = list(range(n))
        parity = [0] * n
        def find(x):
