                return x, 0
            root, p = find(parent[x])
            parity[x] ^= p
            parent[x] = root
            return root, parity[x]
        count = 0
        for u, v, w in edges:
            ru, pu = find(u)
            rv, pv = find(v)
            if ru != rv:
                parent[ru] = rv
                parity[ru] = pu ^ pv ^ w
                count += 1
            else:
                if (pu ^ pv) == w:
                    count += 1
        return count

