MOD = 10**9 + 7

def max_binary_concat(ones: List[int], zeros: List[int]) -> int:
    def cmp(x: str, y: str) -> int:
        if x + y > y + x:
            return -1
        if x + y < y + x:
            return 1
        return 0
    segments = [("1" * o) + ("0" * z) for o, z in zip(ones, zeros)]
    segments.sort(key=functools.cmp_to_key(cmp))
    if not segments:
        return 0
    binary_str = "".join(segments)
    if binary_str.lstrip('0') == "":
        return 0
    return int(binary_str, 2) % MOD

