def smallestStableIndex(nums, k):
    n = len(nums)
    prefix_max = [0] * n
    prefix_max[0] = nums[0]
    for i in range(1, n):
        prefix_max[i] = max(prefix_max[i - 1], nums[i])
    suffix_min = [0] * n
    suffix_min[n - 1] = nums[n - 1]
    for i in range(n - 2, -1, -1):
        suffix_min[i] = min(suffix_min[i + 1], nums[i])
    for i in range(n):
        if prefix_max[i] - suffix_min[i] <= k:
            return i
    return -1

from functools import lru_cache

def count_good_paths(l: int, r: int, directions: str) -> int:
    key = [False] * 16
    row, col = 0, 0
    key[0] = True
    for c in directions:
        if c == "D":
            row += 1
        else:
            col += 1
        key[row * 4 + col] = True

    def calc(x: int) -> int:
        if x < 0:
            return 0
        s = str(x).zfill(16)

        @lru_cache(maxsize=None)
        def dfs(pos, last, lim):
            if pos == 16:
                return 1
            res = 0
            start = last if key[pos] else 0
            end = int(s[pos]) if lim else 9
            for i in range(start, end + 1):
                res += dfs(pos + 1, i if key[pos] else last, lim and (i == end))
            return res

        result = dfs(0, 0, True)
        dfs.cache_clear()
        return result

    return calc(r) - calc(l - 1)

