import bisect

def kth_smallest_even(arr: List[int], queries: List[List[int]]) -> List[int]:
    n = len(arr)
    size = 4 * n
    seg: List[List[int]] = [[] for _ in range(size)]

    def merge(a: List[int], b: List[int]) -> List[int]:
        i = j = 0
        res = []
        while i < len(a) and j < len(b):
            if a[i] <= b[j]:
                res.append(a[i])
                i += 1
            else:
                res.append(b[j])
                j += 1
        if i < len(a):
            res.extend(a[i:])
        if j < len(b):
            res.extend(b[j:])
        return res

    def build(node: int, l: int, r: int) -> None:
        if l == r:
            if arr[l] % 2 == 0:
                seg[node] = [arr[l]]
            return
        mid = (l + r) // 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        seg[node] = merge(seg[node * 2], seg[node * 2 + 1])

    def count_leq(node: int, l: int, r: int, ql: int, qr: int, val: int) -> int:
        if ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return bisect.bisect_right(seg[node], val)
        mid = (l + r) // 2
        return (count_leq(node * 2, l, mid, ql, qr, val) +
                count_leq(node * 2 + 1, mid + 1, r, ql, qr, val))

    build(1, 0, n - 1)

    # global maximum even in the whole array (0 if none)
    max_even = 0
    for v in arr:
        if v % 2 == 0 and v > max_even:
            max_even = v

    results: List[int] = []
    for l, r, k in queries:
        # binary search for smallest even x with missing >= k
        lo = 2
        hi = max(max_even, 2 * k) + 2 * k  # safe upper bound
        while lo < hi:
            mid = (lo + hi) // 2
            present = count_leq(1, 0, n - 1, l, r, mid)
            missing = mid // 2 - present
            if missing >= k:
                hi = mid
            else:
                lo = mid + 1
        # ensure answer is even
        ans = lo if lo % 2 == 0 else lo + 1
        results.append(ans)
    return results
