def sort_vowels(s: str) -> str:
    vowels = set('aeiou')
    freq = {}
    first_occ = {}
    positions = []
    arr = list(s)
    for i, c in enumerate(arr):
        if c in vowels:
            positions.append(i)
            freq[c] = freq.get(c, 0) + 1
            if c not in first_occ:
                first_occ[c] = i
    letters = list(freq.keys())
    letters.sort(key=lambda c: (-freq[c], first_occ[c]))
    sorted_vowels = []
    for c in letters:
