def max_fixed_points(nums: List[int]) -> int:
    n = len(nums)
    req = [i - nums[i] for i in range(n)]
    dp = [0] * n
    for i in range(n):
        if req[i] < 0:
            dp[i] = 0
            continue
        dp[i] = 1
        for j in range(i):
            if dp[j] > 0 and nums[j] < nums[i] and req[j] <= req[i]:
