def count_local_maximums(matrix: List[List[int]]) -> int:
    n, m = len(matrix), len(matrix[0])
    count = 0
    for r in range(n):
        for c in range(m):
            x = matrix[r][c]
            if x == 0:
                continue
            is_max = True
            # the cell's own value x is the neighbourhood radius
            for dr in range(-x, x + 1):
                if not is_max:
                    break
                for dc in range(-x, x + 1):
                    if abs(dr) == x and abs(dc) == x:
                        continue  # corner exclusion
                    rr, cc = r + dr, c + dc
                    if rr < 0 or rr >= n or cc < 0 or cc >= m:
                        continue
                    if matrix[rr][cc] > x:
                        is_max = False
                        break
            if is_max:
                count += 1
    return count

