def union_sorted_arrays(arr1: List[int], arr2: List[int]) -> List[int]:
    result: List[int] = []
    i = j = 0
    last: int | None = None
    len1, len2 = len(arr1), len(arr2)
    while i < len1 and j < len2:
        if arr1[i] < arr2[j]:
            val = arr1[i]
            i += 1
        elif arr1[i] > arr2[j]:
            val = arr2[j]
            j += 1
        else:
            val = arr1[i]
            i += 1
            j += 1
        if val != last:
            result.append(val)
            last = val
    while i < len1:
        val = arr1[i]
        i += 1
        if val != last:
            result.append(val)
            last = val
    while j < len2:
        val = arr2[j]
        j += 1
        if val != last:
            result.append(val)
            last = val
    return result

