def longest_subarray_with_sum_k(nums: List[int], k: int) -> int:
    left = 0
    current_sum = 0
    max_len = 0
    for right, val in enumerate(nums):
        current_sum += val
        while current_sum > k and left <= right:
            current_sum -= nums[left]
            left += 1
        if current_sum == k:
