def my_pow(x: float, n: int) -> float:
    if n == 0:
        return 1.0
    if n < 0:
        x = 1.0 / x
        n = -n
    result = 1.0
    while n:
        if n & 1:
            result *= x
        x *= x
        n >>= 1
    return result

