def kth_smallest(matrix: List[List[int]], k: int) -> int:
    n = len(matrix)
    low, high = matrix[0][0], matrix[-1][-1]
    while low < high:
        mid = low + (high - low) // 2
        count = 0
        row, col = n - 1, 0
        while row >= 0 and col < n:
            if matrix[row][col] <= mid:
                count += row + 1
                col += 1
            else:
                row -= 1
        if count < k:
            low = mid + 1
        else:
            high = mid
    return low

