def preorder_traversal(root: Optional[TreeNode]) -> List[int]:
    result: List[int] = []
    if not root:
        return result
    stack = [root]
    while stack:
        node = stack.pop()
        result.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
    return result

