def inorder_traversal(root: Optional["TreeNode"]) -> List[int]:
    result: List[int] = []
    cur = root
    while cur:
        if cur.left is None:
            result.append(cur.val)
            cur = cur.right
        else:
            pred = cur.left
            while pred.right and pred.right is not cur:
                pred = pred.right
            if pred.right is None:
                pred.right = cur
                cur = cur.left
            else:
                pred.right = None
                result.append(cur.val)
                cur = cur.right
    return result

def trie():
    class _Node:
        __slots__ = ("children", "is_end")
        def __init__(self):
            self.children = [None] * 26
            self.is_end = False

    root = _Node()

    def insert(word: str) -> None:
        node = root
        for ch in word:
            idx = ord(ch) - 97
            if node.children[idx] is None:
                node.children[idx] = _Node()
            node = node.children[idx]
        node.is_end = True

    def search(word: str) -> bool:
        node = root
        for ch in word:
            idx = ord(ch) - 97
            if node.children[idx] is None:
                return False
            node = node.children[idx]
        return node.is_end

    def starts_with(prefix: str) -> bool:
        node = root
        for ch in prefix:
            idx = ord(ch) - 97
            if node.children[idx] is None:
                return False
            node = node.children[idx]
        return True

    return {"insert": insert, "search": search, "startsWith": starts_with}

def lowest_common_ancestor(root, p, q):
    node = root
    while node:
        if p.val < node.val and q.val < node.val:
            node = node.left
        elif p.val > node.val and q.val > node.val:
            node = node.right
        else:
            return node
    return None

