def range_sum_query(nums: List[int], queries: List[Tuple[Any, ...]]) -> List[int]:
    n = len(nums)
    if n == 0:
        return []
    bit = [0] * (n + 1)

    def add(idx: int, delta: int) -> None:
        i = idx + 1
        while i <= n:
            bit[i] += delta
            i += i & -i

    def prefix(idx: int) -> int:
        i = idx + 1
        s = 0
        while i:
            s += bit[i]
            i -= i & -i
        return s

    for i, v in enumerate(nums):
        add(i, v)

    answers: List[int] = []
    for q in queries:
        if q[0] == 'update':
            idx, val = q[1], q[2]
            delta = val - nums[idx]
            nums[idx] = val
            add(idx, delta)
        else:
            left, right = q[1], q[2]
            total = prefix(right) - (prefix(left - 1) if left > 0 else 0)
            answers.append(total)
    return answers

