def count_houses(n, x, y):
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        adj[i].append(i + 1)
        adj[i + 1].append(i)
    if x != y:
        adj[x].append(y)
        adj[y].append(x)
    result = [0] * n
    for src in range(1, n + 1):
        dist = [-1] * (n + 1)
        dist[src] = 0
        queue = [src]
        head = 0
        while head < len(queue):
            cur = queue[head]; head += 1
            for nxt in adj[cur]:
                if dist[nxt] == -1:
                    dist[nxt] = dist[cur] + 1
                    queue.append(nxt)
        for dest in range(1, n + 1):
            if dest == src: continue
            d = dist[dest]
            if 1 <= d <= n - 1:
                result[d - 1] += 1
    return result

