def maximum_good_subarray_sum(nums: List[int], k: int) -> int:
    max_sum = float('-inf')
    prefix = 0
    min_prefix_by_val = {}
    for num in nums:
        prefix_before = prefix
        prefix += num
        # check previous positions where the first element differs by k
        for target in (num + k, num - k):
            if target in min_prefix_by_val:
                cand = prefix - min_prefix_by_val[target]
                if cand > max_sum:
                    max_sum = cand
        # for k == 0, a single element subarray is also valid
        if k == 0 and num > max_sum:
            max_sum = num
        # store the smallest prefix sum seen before this value
        if num not in min_prefix_by_val or prefix_before < min_prefix_by_val[num]:
            min_prefix_by_val[num] = prefix_before
    return int(max_sum)  # type: ignore

def minimum_pushes(word: str) -> int:
    # Count frequencies (all will be 1 due to distinct letters, but keep generic)
    freq = {}
    for ch in word:
        freq[ch] = freq.get(ch, 0) + 1
    # Sort frequencies descending
    freqs = sorted(freq.values(), reverse=True)
    total = 0
    for i, f in enumerate(freqs):
        pushes = i // 8 + 1
        total += pushes * f
    return total

def min_cost(nums, k, dist):
    n = len(nums)
    INF = float('inf')
    answer = INF
    for i1 in range(1, n):
        max_last = min(n - 1, i1 + dist)
        min_last = i1 + (k - 2) - 1
        if min_last > max_last:
            continue
        for i_last in range(min_last, max_last + 1):
            interior_len = i_last - i1 - 1
            need = max(k - 3, 0)
            if interior_len < need:
                continue
            interior_vals = sorted(nums[i1+1:i_last])
            sum_smallest = sum(interior_vals[:need])
            total = nums[0] + nums[i1] + nums[i_last] + sum_smallest
            if total < answer:
                answer = total
    return -1 if answer == INF else answer

